// Nuvemath — 4-sinf, I qism nazariyasi. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t1. O‘rganilganlarni takrorlash ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Yangi o‘quv yili — eski do‘stlar bilan', 'Новый учебный год — со старыми друзьями', 'A new school year with old friends'), p: [
      L('Salom, to‘rtinchi sinf o‘quvchisi! Yozgi ta’tildan keyin sonlar bilan yana uchrashdik. Avval 3-sinfda o‘rgangan narsalarimizni eslaymiz: besh xonali sonlar, xonalar, ustunda qo‘shish va ayirish, bir xonali songa ko‘paytirish va bo‘lish. Bu takrorlash — bo‘sh vaqt emas. Uy qurishdan oldin poydevor tekshirilganidek, biz ham bilimlarimizni tekshirib olamiz.', 'Привет, четвероклассник! После летних каникул мы снова встречаемся с числами. Сначала вспомним то, что учили в 3 классе: пятизначные числа, разряды, сложение и вычитание столбиком, умножение и деление на однозначное число. Повторение — не потерянное время. Как перед стройкой проверяют фундамент, так и мы проверяем свои знания.', 'Hello, fourth-grader! After the summer holidays we meet the numbers again. First we recall what we learned in Grade 3: five-digit numbers, places, column addition and subtraction, multiplying and dividing by a one-digit number. Review is not wasted time. Just as builders check the foundation before building a house, we check our knowledge.'),
      L('Tasavvur qiling: Toshkentdan Samarqandgacha 300 kilometr, lekin bir yilda yo‘lovchi poyezd 52 647 kilometr yo‘l bosdi. Bu sonni o‘qiy olasizmi? Unda nechta minglik bor? Agar poyezd yana 8 353 kilometr yursa, jami qancha bo‘ladi? Mana shu savollarga javob berish uchun bizga 3-sinf bilimlari kerak.', 'Представь: от Ташкента до Самарканда 300 километров, а за год пассажирский поезд проехал 52 647 километров. Можешь прочитать это число? Сколько в нём тысяч? Если поезд проедет ещё 8 353 километра, сколько получится всего? Чтобы ответить, нам нужны знания 3 класса.', 'Imagine: from Tashkent to Samarkand is 300 kilometres, but in one year a passenger train travelled 52 647 kilometres. Can you read this number? How many thousands are in it? If the train goes another 8 353 kilometres, what is the total? To answer, we need our Grade 3 knowledge.'),
      L('Bu mavzuda biz sonni xona qo‘shiluvchilari yig‘indisi ko‘rinishida yozishni, ustunda hisoblashni va masalalarni qisqa yozuv bilan yechishni eslaymiz. Tayyormisiz? Boshladik!', 'В этой теме мы вспомним, как записать число суммой разрядных слагаемых, как считать столбиком и как решать задачи с краткой записью. Готовы? Начали!', 'In this topic we recall how to write a number as a sum of place values, how to calculate in columns and how to solve problems with a short record. Ready? Let’s go!')
    ] },
    { kind: 'def', h: L('Xonalar va xona qo‘shiluvchilari', 'Разряды и разрядные слагаемые', 'Places and place values'), p: [
      L('Har bir raqam sonda o‘z <b>xonasida</b> turadi. O‘ngdan chapga: birliklar, o‘nliklar, yuzliklar, minglar, o‘n minglar. 52 647 sonida 7 — birliklar xonasida, 4 — o‘nliklar, 6 — yuzliklar, 2 — minglar, 5 — o‘n minglar xonasida.', 'Каждая цифра стоит в своём <b>разряде</b>. Справа налево: единицы, десятки, сотни, тысячи, десятки тысяч. В числе 52 647 цифра 7 стоит в разряде единиц, 4 — десятков, 6 — сотен, 2 — тысяч, 5 — десятков тысяч.', 'Every digit stands in its own <b>place</b>. From right to left: ones, tens, hundreds, thousands, ten-thousands. In 52 647 the digit 7 is in the ones place, 4 in the tens, 6 in the hundreds, 2 in the thousands and 5 in the ten-thousands.'),
      L('<b>Xona qo‘shiluvchilari</b> — bu har bir raqamning haqiqiy qiymati. 5 raqami o‘n minglar xonasida turgani uchun uning qiymati 50 000. Sonni xona qo‘shiluvchilari yig‘indisi ko‘rinishida yozamiz: 52 647 = 50 000 + 2 000 + 600 + 40 + 7.', '<b>Разрядные слагаемые</b> — это настоящее значение каждой цифры. Цифра 5 стоит в разряде десятков тысяч, поэтому её значение 50 000. Записываем число суммой разрядных слагаемых: 52 647 = 50 000 + 2 000 + 600 + 40 + 7.', '<b>Place values</b> are the true value of each digit. The digit 5 is in the ten-thousands place, so its value is 50 000. We write the number in expanded form: 52 647 = 50 000 + 2 000 + 600 + 40 + 7.')
    ], list: [
      L('<b>Birliklar sinfi</b>: birliklar, o‘nliklar, yuzliklar — sonning oxirgi uchta raqami.', '<b>Класс единиц</b>: единицы, десятки, сотни — последние три цифры числа.', '<b>Ones period</b>: ones, tens, hundreds — the last three digits.'),
      L('<b>Minglar sinfi</b>: minglar, o‘n minglar, yuz minglar — undan oldingi uchta raqam.', '<b>Класс тысяч</b>: тысячи, десятки тысяч, сотни тысяч — три цифры перед ними.', '<b>Thousands period</b>: thousands, ten-thousands, hundred-thousands — the three digits before them.'),
      L('Sonni yozganda sinflar orasida kichik bo‘sh joy qoldiramiz: 52 647, 7 005, 120 300.', 'При записи между классами оставляем небольшой пробел: 52 647, 7 005, 120 300.', 'When writing, we leave a small gap between periods: 52 647, 7 005, 120 300.')
    ] },
    { kind: 'history', h: L('Raqamlar va algoritm so‘zi qayerdan kelgan?', 'Откуда пришли цифры и слово «алгоритм»?', 'Where did the digits and the word “algorithm” come from?'), p: [
      L('Biz hozir ishlatayotgan raqamlar — 0, 1, 2, …, 9 — Hindistonda paydo bo‘lgan. Lekin ularni butun dunyoga tanitgan olim bizning yurtdoshimiz — <b>Muhammad ibn Muso al-Xorazmiy</b> (taxminan 783–850). U Xorazmda tug‘ilgan va Bag‘doddagi «Bayt ul-hikma» (Donishmandlik uyi)da ishlagan.', 'Цифры, которыми мы пользуемся сейчас — 0, 1, 2, …, 9 — появились в Индии. Но познакомил с ними весь мир наш земляк — <b>Мухаммад ибн Муса аль-Хорезми</b> (около 783–850). Он родился в Хорезме и работал в багдадском «Доме мудрости».', 'The digits we use today — 0, 1, 2, …, 9 — appeared in India. But the scholar who introduced them to the whole world was our countryman <b>Muhammad ibn Musa al-Khwarizmi</b> (about 783–850). He was born in Khwarezm and worked at the House of Wisdom in Baghdad.'),
      L('Xorazmiy «Hind hisobi haqida kitob» asarida xonali yozuvni va ustunda hisoblash usullarini tushuntirgan. Bu kitob lotin tiliga tarjima qilinganda, uning nomi «Algoritmi» deb yozilgan. Shundan «<b>algoritm</b>» so‘zi kelib chiqqan — aniq bosqichlar ketma-ketligi. Siz ustunda qo‘shganingizda Xorazmiy algoritmini ishlatasiz!', 'В книге «Об индийском счёте» аль-Хорезми объяснил позиционную запись и приёмы вычисления в столбик. Когда книгу перевели на латынь, его имя записали как «Algoritmi». Отсюда произошло слово «<b>алгоритм</b>» — точная последовательность шагов. Складывая столбиком, ты используешь алгоритм аль-Хорезми!', 'In his book on Indian reckoning, al-Khwarizmi explained place-value notation and column methods. When the book was translated into Latin, his name was written “Algoritmi”. That is where the word “<b>algorithm</b>” comes from — an exact sequence of steps. When you add in columns, you use al-Khwarizmi’s algorithm!'),
      L('Xona tizimining eng muhim ixtirosi — <b>nol</b>. Nol xonaning bo‘shligini ko‘rsatadi: 7 005 da ikkita nol bo‘lmasa, 75 bo‘lib qolardi. Qadimgi rimliklarda nol bo‘lmagan, shuning uchun ular katta sonlar bilan ustunda hisoblay olmagan.', 'Самое важное изобретение позиционной системы — <b>нуль</b>. Нуль показывает, что разряд пуст: без двух нулей в 7 005 получилось бы 75. У древних римлян нуля не было, поэтому они не могли считать столбиком с большими числами.', 'The most important invention of the place-value system is <b>zero</b>. Zero shows that a place is empty: without the two zeros in 7 005 we would get 75. The ancient Romans had no zero, so they could not do column arithmetic with big numbers.')
    ] },
    { kind: 'rule', h: L('Ustunda qo‘shish va ayirish qoidasi', 'Правило сложения и вычитания столбиком', 'The rule for column addition and subtraction'), p: [
      L('Ustunda hisoblashning asosiy qoidasi: <b>xona ostiga xona</b>. Birliklar birliklar ostida, o‘nliklar o‘nliklar ostida turishi shart. Hisobni har doim o‘ngdan, birliklardan boshlaymiz.', 'Главное правило вычисления столбиком: <b>разряд под разрядом</b>. Единицы должны стоять под единицами, десятки под десятками. Считаем всегда справа, с единиц.', 'The main rule of column work: <b>place under place</b>. Ones must sit under ones, tens under tens. We always start from the right, with the ones.'),
      L('Qo‘shishda xonadagi yig‘indi 10 yoki undan katta bo‘lsa, birlikni yozib, o‘nlikni keyingi xonaga <b>o‘tkazamiz</b>. Ayirishda yuqoridagi raqam kichik bo‘lsa, keyingi xonadan <b>1 ni qarz olamiz</b> — u 10 ta kichik birlikka aylanadi.', 'При сложении, если сумма в разряде 10 или больше, записываем единицы, а десяток <b>переносим</b> в следующий разряд. При вычитании, если верхняя цифра меньше, <b>занимаем 1</b> у следующего разряда — она превращается в 10 единиц этого разряда.', 'In addition, if the sum in a place is 10 or more, write the ones and <b>carry</b> the ten into the next place. In subtraction, if the top digit is smaller, <b>borrow 1</b> from the next place — it becomes 10 units of this place.'),
      L('Tekshirish qoidasi: qo‘shishni ayirish bilan, ayirishni qo‘shish bilan tekshiramiz. 4 245 − 2 899 = 1 346 bo‘lsa, 1 346 + 2 899 = 4 245 chiqishi kerak.', 'Правило проверки: сложение проверяем вычитанием, вычитание — сложением. Если 4 245 − 2 899 = 1 346, то должно получиться 1 346 + 2 899 = 4 245.', 'Checking rule: check addition by subtraction and subtraction by addition. If 4 245 − 2 899 = 1 346, then 1 346 + 2 899 must give 4 245.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 4 245 − 2 899', 'Пошагово: 4 245 − 2 899', 'Step by step: 4 245 − 2 899'), p: [
      L('Bu misolda uch marta qarz olishga to‘g‘ri keladi. Diqqat bilan kuzating.', 'В этом примере придётся занимать три раза. Следи внимательно.', 'In this example we have to borrow three times. Watch carefully.')
    ], list: [
      L('<b>Birliklar:</b> 5 dan 9 ni ayirib bo‘lmaydi. O‘nliklardan 1 qarz olamiz: 15 − 9 = 6. Yozamiz 6.', '<b>Единицы:</b> из 5 нельзя вычесть 9. Занимаем 1 у десятков: 15 − 9 = 6. Пишем 6.', '<b>Ones:</b> we cannot take 9 from 5. Borrow 1 from the tens: 15 − 9 = 6. Write 6.'),
      L('<b>O‘nliklar:</b> 4 edi, 1 ni berdik — 3 qoldi. 3 dan 9 ni ayirib bo‘lmaydi, yuzliklardan qarz olamiz: 13 − 9 = 4. Yozamiz 4.', '<b>Десятки:</b> было 4, одну отдали — осталось 3. Из 3 нельзя вычесть 9, занимаем у сотен: 13 − 9 = 4. Пишем 4.', '<b>Tens:</b> there were 4, we gave 1 — 3 left. We cannot take 9 from 3, borrow from the hundreds: 13 − 9 = 4. Write 4.'),
      L('<b>Yuzliklar:</b> 2 edi, 1 qoldi. 1 dan 8 ni ayirib bo‘lmaydi, minglardan qarz olamiz: 11 − 8 = 3. Yozamiz 3.', '<b>Сотни:</b> было 2, осталась 1. Из 1 нельзя вычесть 8, занимаем у тысяч: 11 − 8 = 3. Пишем 3.', '<b>Hundreds:</b> there were 2, 1 left. We cannot take 8 from 1, borrow from the thousands: 11 − 8 = 3. Write 3.'),
      L('<b>Minglar:</b> 4 edi, 3 qoldi. 3 − 2 = 1. Yozamiz 1. Javob: <b>1 346</b>.', '<b>Тысячи:</b> было 4, осталось 3. 3 − 2 = 1. Пишем 1. Ответ: <b>1 346</b>.', '<b>Thousands:</b> there were 4, 3 left. 3 − 2 = 1. Write 1. Answer: <b>1 346</b>.'),
      L('<b>Tekshiramiz:</b> 1 346 + 2 899 = 4 245. To‘g‘ri!', '<b>Проверяем:</b> 1 346 + 2 899 = 4 245. Верно!', '<b>Check:</b> 1 346 + 2 899 = 4 245. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir namunani avval o‘zingiz yechib, so‘ng javob bilan solishtiring.', 'Сначала реши каждый пример сам, потом сравни с ответом.', 'Try each example yourself first, then compare with the answer.')
    ], ex: [
      { q: L('30 000 + 7 000 + 200 + 9 — qanday son?', '30 000 + 7 000 + 200 + 9 — какое это число?', '30 000 + 7 000 + 200 + 9 — which number is it?'), s: L('O‘n minglar — 3, minglar — 7, yuzliklar — 2, o‘nliklar yo‘q — 0, birliklar — 9. Javob: <b>37 209</b>. O‘nliklar xonasiga nol yozishni unutmang!', 'Десятков тысяч — 3, тысяч — 7, сотен — 2, десятков нет — 0, единиц — 9. Ответ: <b>37 209</b>. Не забудь нуль в разряде десятков!', 'Ten-thousands 3, thousands 7, hundreds 2, no tens — 0, ones 9. Answer: <b>37 209</b>. Do not forget the zero in the tens place!') },
      { q: L('23 007 sonida nechta minglik bor?', 'Сколько тысяч в числе 23 007?', 'How many thousands are in 23 007?'), s: L('Minglar sinfi — 23. Demak, sonda 23 ta minglik va 7 ta birlik bor. Agar «minglar xonasidagi raqam» so‘ralsa, javob 3 bo‘lardi, lekin «nechta minglik» — bu 23.', 'Класс тысяч — 23. Значит, в числе 23 тысячи и 7 единиц. Если спросят «цифра в разряде тысяч», ответ 3, но «сколько тысяч» — это 23.', 'The thousands period is 23. So the number has 23 thousands and 7 ones. If asked for “the digit in the thousands place”, the answer would be 3, but “how many thousands” is 23.') },
      { q: L('Ustunda qo‘shing: 5 678 + 1 845.', 'Сложи столбиком: 5 678 + 1 845.', 'Add in a column: 5 678 + 1 845.'), s: L('Birliklar: 8 + 5 = 13 — 3 yozamiz, 1 o‘tkazamiz. O‘nliklar: 7 + 4 + 1 = 12 — 2 yozamiz, 1 o‘tkazamiz. Yuzliklar: 6 + 8 + 1 = 15 — 5 yozamiz, 1 o‘tkazamiz. Minglar: 5 + 1 + 1 = 7. Javob: <b>7 523</b>.', 'Единицы: 8 + 5 = 13 — пишем 3, переносим 1. Десятки: 7 + 4 + 1 = 12 — пишем 2, переносим 1. Сотни: 6 + 8 + 1 = 15 — пишем 5, переносим 1. Тысячи: 5 + 1 + 1 = 7. Ответ: <b>7 523</b>.', 'Ones: 8 + 5 = 13 — write 3, carry 1. Tens: 7 + 4 + 1 = 12 — write 2, carry 1. Hundreds: 6 + 8 + 1 = 15 — write 5, carry 1. Thousands: 5 + 1 + 1 = 7. Answer: <b>7 523</b>.') },
      { q: L('Maktab bog‘iga 7 qator daraxt ekildi, har qatorda 18 tadan. Jami nechta daraxt?', 'В школьном саду посадили 7 рядов деревьев, по 18 в каждом. Сколько всего деревьев?', '7 rows of 18 trees were planted in the school garden. How many trees in all?'), s: L('Bir xil sonlarni qo‘shish — bu ko‘paytirish: 18 · 7. Hisoblaymiz: 10 · 7 = 70, 8 · 7 = 56, 70 + 56 = 126. Javob: <b>126 ta daraxt</b>.', 'Сложение одинаковых чисел — это умножение: 18 · 7. Считаем: 10 · 7 = 70, 8 · 7 = 56, 70 + 56 = 126. Ответ: <b>126 деревьев</b>.', 'Adding equal numbers is multiplication: 18 · 7. Work it out: 10 · 7 = 70, 8 · 7 = 56, 70 + 56 = 126. Answer: <b>126 trees</b>.') }
    ] },
    { kind: 'table', h: L('Xonalar jadvali', 'Таблица разрядов', 'Place-value table'), p: [
      L('Jadval sonning tuzilishini ko‘rsatadi. Har bir ustun — bitta xona. Sonni jadvalga yozganda bo‘sh xonaga 0 qo‘yiladi.', 'Таблица показывает строение числа. Каждый столбец — один разряд. Если разряд пуст, в таблицу пишем 0.', 'The table shows how a number is built. Each column is one place. An empty place gets a 0.')
    ], table: { head: [L('Son', 'Число', 'Number'), L('O‘n ming', 'Дес. тыс.', 'Ten-th.'), L('Ming', 'Тыс.', 'Th.'), L('Yuz', 'Сот.', 'H.'), L('O‘n', 'Дес.', 'T.'), L('Bir', 'Ед.', 'O.')], rows: [
      ['52 647', '5', '2', '6', '4', '7'],
      ['37 209', '3', '7', '2', '0', '9'],
      ['7 005', '0', '7', '0', '0', '5'],
      ['90 100', '9', '0', '1', '0', '0']
    ] }, after: [
      L('Jadvaldagi 7 005 sonida o‘n minglar xonasi bo‘sh — sonni yozganda oldidagi nol yozilmaydi. Lekin ichkaridagi nollar (yuzliklar va o‘nliklar) albatta yoziladi.', 'У числа 7 005 разряд десятков тысяч пуст — при записи числа нуль впереди не пишут. А вот нули внутри (сотни и десятки) обязательно пишутся.', 'In 7 005 the ten-thousands place is empty — a leading zero is not written. But the zeros inside (hundreds and tens) must be written.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), p: [
      L('Takrorlashda eng ko‘p uchraydigan xatolarni bilib oling — shunda ularni qilmaysiz.', 'Узнай самые частые ошибки при повторении — и ты их не сделаешь.', 'Learn the most common mistakes — then you will not make them.')
    ], list: [
      L('<b>Nolni tashlab ketish.</b> 30 000 + 7 000 + 9 ni 379 deb yozish xato. To‘g‘risi — 37 009: yuzliklar va o‘nliklar xonasiga nol qo‘yiladi.', '<b>Пропуск нуля.</b> Записать 30 000 + 7 000 + 9 как 379 — ошибка. Верно — 37 009: в разряды сотен и десятков ставим нули.', '<b>Dropping a zero.</b> Writing 30 000 + 7 000 + 9 as 379 is wrong. Correct: 37 009 — zeros go in the hundreds and tens places.'),
      L('<b>Noto‘g‘ri yozish.</b> Ustunda 5 678 va 845 ni chap tomondan tekislab yozish xato. Birliklar birliklar ostida turishi kerak — sonlarni o‘ng tomondan tekislaymiz.', '<b>Неверная запись.</b> Выравнивать 5 678 и 845 в столбике по левому краю — ошибка. Единицы должны стоять под единицами — выравниваем по правому краю.', '<b>Wrong alignment.</b> Lining up 5 678 and 845 from the left is wrong. Ones must sit under ones — align from the right.'),
      L('<b>O‘tkazishni unutish.</b> 8 + 5 = 13 da 3 ni yozib, 1 ni keyingi xonaga qo‘shmaslik. Yechim: o‘tkazilgan 1 ni ustun tepasiga kichik qilib yozib qo‘ying.', '<b>Забытый перенос.</b> Написать 3 из 8 + 5 = 13 и не прибавить 1 к следующему разряду. Решение: записывай перенесённую 1 маленькой цифрой над столбиком.', '<b>Forgetting the carry.</b> Writing 3 from 8 + 5 = 13 and not adding 1 to the next place. Fix: write the carried 1 as a small digit above the column.'),
      L('<b>Qarzni unutish.</b> Ayirishda 1 ni qarz olib, yuqori raqamni kamaytirmaslik. 4 245 − 2 899 da o‘nliklar 4 emas, 3 bo‘lib qoladi!', '<b>Забытый заём.</b> Занять 1 при вычитании и не уменьшить верхнюю цифру. В 4 245 − 2 899 десятков остаётся не 4, а 3!', '<b>Forgetting the borrow.</b> Borrowing 1 and not reducing the top digit. In 4 245 − 2 899 the tens become 3, not 4!'),
      L('<b>«Minglik» va «minglar xonasi»ni aralashtirish.</b> 23 007 da minglar xonasida 3 turadi, lekin minglik 23 ta.', '<b>Путать «тысячи» и «разряд тысяч».</b> В 23 007 в разряде тысяч стоит 3, но тысяч в числе 23.', '<b>Mixing up “thousands” and “thousands place”.</b> In 23 007 the thousands place holds 3, but there are 23 thousands.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('Besh xonali sonlar atrofimizda juda ko‘p. Do‘kondagi narxlar: daftar 3 500 so‘m, kitob 45 000 so‘m, velosiped 1 250 000 so‘m. Xaridni hisoblash uchun ustunda qo‘shish kerak: 45 000 + 3 500 = 48 500 so‘m.', 'Пятизначные числа окружают нас повсюду. Цены в магазине: тетрадь 3 500 сум, книга 45 000 сум, велосипед 1 250 000 сум. Чтобы посчитать покупку, нужно сложить столбиком: 45 000 + 3 500 = 48 500 сум.', 'Five-digit numbers are everywhere around us. Shop prices: a notebook 3 500 sum, a book 45 000 sum, a bicycle 1 250 000 sum. To total a purchase you add in columns: 45 000 + 3 500 = 48 500 sum.'),
      L('Geografiya darsida: Orol dengizining uzunligi bir vaqtlar 428 km edi. O‘zbekistonning maydoni — 448 978 kvadrat kilometr. Bu sonlarni o‘qish va taqqoslash uchun xonalarni bilish zarur.', 'На уроке географии: длина Аральского моря когда-то была 428 км. Площадь Узбекистана — 448 978 квадратных километров. Чтобы читать и сравнивать такие числа, нужно знать разряды.', 'In geography: the Aral Sea was once 428 km long. The area of Uzbekistan is 448 978 square kilometres. To read and compare such numbers you need to know the places.'),
      L('Sportda: futbol stadionida 34 000 ishqiboz sig‘adi. Agar o‘yinga 28 750 kishi kelgan bo‘lsa, nechta o‘rin bo‘sh qoldi? 34 000 − 28 750 = 5 250. Ustunda ayirish shu yerda ham kerak bo‘ldi!', 'В спорте: футбольный стадион вмещает 34 000 болельщиков. Если на матч пришли 28 750 человек, сколько мест осталось свободными? 34 000 − 28 750 = 5 250. Вычитание столбиком пригодилось и здесь!', 'In sport: a football stadium holds 34 000 fans. If 28 750 people came to the match, how many seats stayed empty? 34 000 − 28 750 = 5 250. Column subtraction is needed here too!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Agar siz har soniyada bitta sondan sanasangiz, 1 dan 100 000 gacha sanash uchun qariyb 28 soat kerak bo‘ladi — bir sutkadan ko‘p, uxlamasdan!', 'Если считать по одному числу в секунду, чтобы досчитать от 1 до 100 000, понадобится почти 28 часов — больше суток, без сна!', 'If you count one number per second, counting from 1 to 100 000 takes almost 28 hours — more than a day without sleep!'),
      L('Eng katta besh xonali son — 99 999. Unga 1 ni qo‘shsak, olti xonali son 100 000 — yuz ming hosil bo‘ladi.', 'Самое большое пятизначное число — 99 999. Прибавим 1 — получим шестизначное число 100 000 — сто тысяч.', 'The largest five-digit number is 99 999. Add 1 and you get the six-digit number 100 000 — one hundred thousand.'),
      L('12 345 soni «ketma-ket raqamli son» deyiladi. Uni teskari yozsak — 54 321. Ikkalasining farqi 41 976 ga teng.', 'Число 12 345 называют «числом из последовательных цифр». Запишем его наоборот — 54 321. Их разность равна 41 976.', '12 345 is a “consecutive-digit number”. Written backwards it is 54 321. The difference between them is 41 976.'),
      L('Xorazmiyning kitobi Yevropada 300 yildan ortiq vaqt davomida arifmetika darsligi bo‘lib xizmat qilgan.', 'Книга аль-Хорезми более 300 лет служила в Европе учебником арифметики.', 'Al-Khwarizmi’s book served as the arithmetic textbook in Europe for more than 300 years.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), p: [
      L('Bu savollarga og‘zaki yoki daftarda javob bering. Javoblar pastda.', 'Ответь на вопросы устно или в тетради. Ответы ниже.', 'Answer these questions aloud or in your notebook. The answers are below.')
    ], list: [
      L('Raqamlari 4, 0, 7, 2, 1 bo‘lgan eng katta va eng kichik besh xonali sonlarni yozing.', 'Запиши самое большое и самое маленькое пятизначные числа из цифр 4, 0, 7, 2, 1.', 'Write the largest and the smallest five-digit numbers using the digits 4, 0, 7, 2, 1.'),
      L('60 000 + 500 + 3 sonida nechta o‘nlik bor?', 'Сколько десятков в числе 60 000 + 500 + 3?', 'How many tens are in 60 000 + 500 + 3?'),
      L('10 000 − 1 nechaga teng? 10 000 − 999 chi?', 'Чему равно 10 000 − 1? А 10 000 − 999?', 'What is 10 000 − 1? And 10 000 − 999?')
    ], after: [
      L('Javoblar: 1) 74 210 va 10 247 (nol boshida tura olmaydi); 2) 60 503 da 6 050 ta o‘nlik bor (so‘nggi raqamni tashlab); 3) 9 999 va 9 001.', 'Ответы: 1) 74 210 и 10 247 (нуль не может стоять впереди); 2) в 60 503 — 6 050 десятков (отбрасываем последнюю цифру); 3) 9 999 и 9 001.', 'Answers: 1) 74 210 and 10 247 (zero cannot be first); 2) 60 503 has 6 050 tens (drop the last digit); 3) 9 999 and 9 001.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Har bir raqam o‘z xonasida turadi: birliklar, o‘nliklar, yuzliklar, minglar, o‘n minglar.', 'Каждая цифра стоит в своём разряде: единицы, десятки, сотни, тысячи, десятки тысяч.', 'Each digit stands in its place: ones, tens, hundreds, thousands, ten-thousands.'),
      L('Xona qo‘shiluvchilari yig‘indisi: 52 647 = 50 000 + 2 000 + 600 + 40 + 7.', 'Сумма разрядных слагаемых: 52 647 = 50 000 + 2 000 + 600 + 40 + 7.', 'Expanded form: 52 647 = 50 000 + 2 000 + 600 + 40 + 7.'),
      L('Ustunda hisoblashda xona ostiga xona yoziladi, hisob o‘ngdan boshlanadi.', 'В столбике разряд пишется под разрядом, счёт начинается справа.', 'In columns, place goes under place and work starts from the right.'),
      L('Qo‘shishda 10 dan oshsa — o‘tkazamiz, ayirishda yetmasa — qarz olamiz.', 'При сложении через десяток — переносим, при вычитании, если не хватает — занимаем.', 'When adding past ten — carry; when subtracting and short — borrow.'),
      L('Har bir natijani teskari amal bilan tekshiramiz.', 'Каждый результат проверяем обратным действием.', 'Check every result with the inverse operation.'),
      L('Xorazmiy — hind raqamlarini dunyoga tanitgan olim; «algoritm» so‘zi uning nomidan.', 'Аль-Хорезми познакомил мир с индийскими цифрами; слово «алгоритм» — от его имени.', 'Al-Khwarizmi introduced Indian numerals to the world; the word “algorithm” comes from his name.')
    ] }
  ] });

  // ---------- t2. Qavssiz ifodalarda amallar tartibi ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Kim birinchi?', 'Кто первый?', 'Who goes first?'), p: [
      L('Ikki do‘st bitta misolni yechdi: 20 + 30 · 2. Aziz 100 dedi, Malika 80 dedi. Kim haq? Aziz chapdan o‘ngga hisobladi: 20 + 30 = 50, 50 · 2 = 100. Malika avval ko‘paytirdi: 30 · 2 = 60, 20 + 60 = 80. Matematikada bitta misolning bitta javobi bo‘lishi kerak. Shuning uchun olimlar kelishib olishgan: <b>amallar tartibi</b> degan qoida bor.', 'Двое друзей решали один пример: 20 + 30 · 2. Азиз сказал 100, Малика — 80. Кто прав? Азиз считал слева направо: 20 + 30 = 50, 50 · 2 = 100. Малика сначала умножила: 30 · 2 = 60, 20 + 60 = 80. В математике у одного примера должен быть один ответ. Поэтому учёные договорились: есть правило <b>порядка действий</b>.', 'Two friends solved the same example: 20 + 30 · 2. Aziz said 100, Malika said 80. Who is right? Aziz went left to right: 20 + 30 = 50, 50 · 2 = 100. Malika multiplied first: 30 · 2 = 60, 20 + 60 = 80. In maths one example must have one answer. So mathematicians agreed on a rule: the <b>order of operations</b>.'),
      L('To‘g‘ri javob — 80. Malika haq, chunki ko‘paytirish qo‘shishdan «kuchliroq» va u birinchi bajariladi. Bu mavzuda biz qavssiz ifodalarda amallar qaysi tartibda bajarilishini o‘rganamiz va uni pul, valyuta kursi bilan bog‘liq masalalarda qo‘llaymiz.', 'Правильный ответ — 80. Малика права, потому что умножение «сильнее» сложения и выполняется первым. В этой теме мы узнаем, в каком порядке выполняются действия в выражениях без скобок, и применим это в задачах о деньгах и курсе валют.', 'The right answer is 80. Malika is right, because multiplication is “stronger” than addition and is done first. In this topic we learn the order of operations in expressions without brackets and apply it to problems about money and exchange rates.'),
      L('Nega aynan shunday? Chunki 30 · 2 aslida «30 + 30» degani. 20 + 30 · 2 = 20 + 30 + 30 = 80. Ko‘paytirish — bu qisqartirilgan qo‘shish, shuning uchun uni avval ochib olamiz.', 'Почему именно так? Потому что 30 · 2 на самом деле значит «30 + 30». 20 + 30 · 2 = 20 + 30 + 30 = 80. Умножение — это сокращённое сложение, поэтому его раскрываем первым.', 'Why this way? Because 30 · 2 really means “30 + 30”. So 20 + 30 · 2 = 20 + 30 + 30 = 80. Multiplication is shortened addition, so we unpack it first.')
    ] },
    { kind: 'def', h: L('Amallar darajasi', 'Ступени действий', 'Levels of operations'), p: [
      L('To‘rt arifmetik amal ikki guruhga bo‘linadi. <b>Birinchi daraja</b> — qo‘shish va ayirish. <b>Ikkinchi daraja</b> — ko‘paytirish va bo‘lish. Ikkinchi daraja amallari kuchliroq va birinchi bajariladi.', 'Четыре арифметических действия делятся на две группы. <b>Первая ступень</b> — сложение и вычитание. <b>Вторая ступень</b> — умножение и деление. Действия второй ступени сильнее и выполняются первыми.', 'The four arithmetic operations fall into two groups. <b>First level</b>: addition and subtraction. <b>Second level</b>: multiplication and division. Second-level operations are stronger and are done first.'),
      L('<b>Ifoda</b> — bu sonlar va amal belgilaridan tuzilgan yozuv, masalan 100 − 40 : 4 + 6. <b>Ifodaning qiymati</b> — barcha amallarni bajargandan keyin chiqadigan son. Bu ifodaning qiymati 96.', '<b>Выражение</b> — это запись из чисел и знаков действий, например 100 − 40 : 4 + 6. <b>Значение выражения</b> — число, которое получается после выполнения всех действий. Значение этого выражения — 96.', 'An <b>expression</b> is a record made of numbers and operation signs, e.g. 100 − 40 : 4 + 6. The <b>value of the expression</b> is the number you get after doing all operations. The value here is 96.'),
      L('<b>Valyuta kursi</b> — bir davlat pulining boshqa davlat pulidagi narxi. Masalan, 1 dollar = 12 500 so‘m degani: bitta dollarni olish uchun 12 500 so‘m berish kerak.', '<b>Курс валюты</b> — цена денег одной страны в деньгах другой. Например, 1 доллар = 12 500 сум означает: чтобы получить один доллар, нужно отдать 12 500 сум.', 'An <b>exchange rate</b> is the price of one country’s money in another’s. For example, 1 dollar = 12 500 sum means you give 12 500 sum to get one dollar.')
    ] },
    { kind: 'history', h: L('Qoida qanday paydo bo‘lgan?', 'Как появилось правило?', 'How did the rule appear?'), p: [
      L('Amal belgilari juda yosh. «+» va «−» belgilari birinchi marta 1489-yilda nemis olimi Yohann Vidman kitobida bosilgan. Ko‘paytirish uchun «×» belgisini ingliz Uilyam Otred 1631-yilda, nuqta «·» ni esa nemis olimi Leybnits 1698-yilda taklif qilgan. Bo‘lish uchun «:» belgisini ham Leybnits ishlatgan.', 'Знаки действий совсем молодые. Знаки «+» и «−» впервые напечатаны в 1489 году в книге немецкого учёного Иоганна Видмана. Знак «×» для умножения предложил англичанин Уильям Отред в 1631 году, а точку «·» — немецкий учёный Лейбниц в 1698 году. Знак «:» для деления тоже ввёл Лейбниц.', 'The operation signs are quite young. “+” and “−” were first printed in 1489 in a book by the German scholar Johannes Widmann. The “×” sign for multiplication was suggested by the Englishman William Oughtred in 1631, and the dot “·” by the German scholar Leibniz in 1698. Leibniz also used “:” for division.'),
      L('Undan oldin odamlar amallarni so‘z bilan yozgan: «yigirmaga o‘ttizning ikki karrasini qo‘sh». Bunday yozuvda tartib so‘zlardan tushunarli edi. Belgilar paydo bo‘lgach, kelishuv kerak bo‘ldi — va «avval ko‘paytirish» qoidasi barcha mamlakatlar uchun umumiy bo‘lib qoldi.', 'До этого действия записывали словами: «к двадцати прибавь дважды по тридцать». В такой записи порядок был ясен из слов. Когда появились знаки, понадобилось соглашение — и правило «сначала умножение» стало общим для всех стран.', 'Before that, people wrote operations in words: “to twenty add thirty taken twice”. There the order was clear from the words. When signs appeared, an agreement was needed — and the rule “multiplication first” became common to all countries.'),
      L('Bugun bu qoida dunyodagi barcha kalkulyator va kompyuterlarga «o‘rnatilgan». Muhandislik kalkulyatoriga 20 + 30 · 2 tersangiz, u 80 ni ko‘rsatadi.', 'Сегодня это правило «встроено» во все калькуляторы и компьютеры мира. Наберите на инженерном калькуляторе 20 + 30 · 2 — он покажет 80.', 'Today this rule is built into every calculator and computer in the world. Type 20 + 30 · 2 on a scientific calculator and it shows 80.')
    ] },
    { kind: 'rule', h: L('Qoida', 'Правило', 'The rule'), p: [
      L('Qavssiz ifodada amallar quyidagi tartibda bajariladi:', 'В выражении без скобок действия выполняются в таком порядке:', 'In an expression without brackets, operations are done in this order:')
    ], list: [
      L('<b>1-qadam.</b> Ko‘paytirish va bo‘lish — chapdan o‘ngga, qaysi oldin kelsa.', '<b>Шаг 1.</b> Умножение и деление — слева направо, в порядке следования.', '<b>Step 1.</b> Multiplication and division — left to right, in the order they appear.'),
      L('<b>2-qadam.</b> Qo‘shish va ayirish — chapdan o‘ngga, qaysi oldin kelsa.', '<b>Шаг 2.</b> Сложение и вычитание — слева направо, в порядке следования.', '<b>Step 2.</b> Addition and subtraction — left to right, in the order they appear.')
    ], after: [
      L('Qisqacha: <b>· : → + −</b>. Agar ifodada faqat bir daraja amallari bo‘lsa (masalan, faqat qo‘shish va ayirish), ular oddiy tartibda, chapdan o‘ngga bajariladi: 100 − 30 + 20 = 70 + 20 = 90, 100 − 50 emas!', 'Кратко: <b>· : → + −</b>. Если в выражении только действия одной ступени (например, только сложение и вычитание), они выполняются просто слева направо: 100 − 30 + 20 = 70 + 20 = 90, а не 100 − 50!', 'In short: <b>· : → + −</b>. If the expression has only one level (e.g. only addition and subtraction), do them simply left to right: 100 − 30 + 20 = 70 + 20 = 90, not 100 − 50!'),
      L('Ko‘paytirish va bo‘lish o‘zaro teng kuchli: 60 : 3 · 2 = 20 · 2 = 40. Chapdagi bo‘lish avval bajarildi.', 'Умножение и деление равны по силе: 60 : 3 · 2 = 20 · 2 = 40. Деление слева выполняется раньше.', 'Multiplication and division are equally strong: 60 : 3 · 2 = 20 · 2 = 40. The division on the left comes first.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 100 − 40 : 4 + 6 · 3', 'Пошагово: 100 − 40 : 4 + 6 · 3', 'Step by step: 100 − 40 : 4 + 6 · 3'), p: [
      L('Yechishdan oldin har bir amal ustiga tartib raqamini yozib chiqing. Bu kichik odat juda ko‘p xatodan saqlaydi.', 'Перед решением надпиши над каждым действием его номер. Эта маленькая привычка спасает от множества ошибок.', 'Before solving, write the order number above each operation. This small habit prevents many mistakes.')
    ], list: [
      L('Ifodada to‘rtta amal bor: −, :, +, ·. Ikkinchi daraja amallari: «:» va «·». Ularni 1 va 2 deb belgilaymiz (chapdan o‘ngga).', 'В выражении четыре действия: −, :, +, ·. Действия второй ступени: «:» и «·». Отмечаем их 1 и 2 (слева направо).', 'The expression has four operations: −, :, +, ·. Second-level ones are “:” and “·”. Number them 1 and 2 (left to right).'),
      L('Birinchi daraja amallari: «−» va «+». Ularni 3 va 4 deb belgilaymiz.', 'Действия первой ступени: «−» и «+». Отмечаем их 3 и 4.', 'First-level ones are “−” and “+”. Number them 3 and 4.'),
      L('1) 40 : 4 = 10.  2) 6 · 3 = 18. Endi ifoda: 100 − 10 + 18.', '1) 40 : 4 = 10.  2) 6 · 3 = 18. Теперь выражение: 100 − 10 + 18.', '1) 40 : 4 = 10.  2) 6 · 3 = 18. Now the expression is 100 − 10 + 18.'),
      L('3) 100 − 10 = 90.  4) 90 + 18 = 108. Javob: <b>108</b>.', '3) 100 − 10 = 90.  4) 90 + 18 = 108. Ответ: <b>108</b>.', '3) 100 − 10 = 90.  4) 90 + 18 = 108. Answer: <b>108</b>.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('20 + 30 · 2', '20 + 30 · 2', '20 + 30 · 2'), s: L('Avval ko‘paytirish: 30 · 2 = 60. Keyin qo‘shish: 20 + 60 = <b>80</b>.', 'Сначала умножение: 30 · 2 = 60. Потом сложение: 20 + 60 = <b>80</b>.', 'Multiplication first: 30 · 2 = 60. Then addition: 20 + 60 = <b>80</b>.') },
      { q: L('100 − 40 : 4', '100 − 40 : 4', '100 − 40 : 4'), s: L('Avval bo‘lish: 40 : 4 = 10. Keyin ayirish: 100 − 10 = <b>90</b>. (60 : 4 = 15 deb hisoblash xato!)', 'Сначала деление: 40 : 4 = 10. Потом вычитание: 100 − 10 = <b>90</b>. (Считать 60 : 4 = 15 — ошибка!)', 'Division first: 40 : 4 = 10. Then subtraction: 100 − 10 = <b>90</b>. (Working out 60 : 4 = 15 is wrong!)') },
      { q: L('48 : 6 · 5 − 12', '48 : 6 · 5 − 12', '48 : 6 · 5 − 12'), s: L('Bo‘lish va ko‘paytirish chapdan o‘ngga: 48 : 6 = 8, 8 · 5 = 40. So‘ng: 40 − 12 = <b>28</b>.', 'Деление и умножение слева направо: 48 : 6 = 8, 8 · 5 = 40. Затем: 40 − 12 = <b>28</b>.', 'Division and multiplication left to right: 48 : 6 = 8, 8 · 5 = 40. Then 40 − 12 = <b>28</b>.') },
      { q: L('1 dollar = 12 500 so‘m. Narxi 20 dollar bo‘lgan fleshka necha so‘m turadi?', '1 доллар = 12 500 сум. Сколько сумов стоит флешка за 20 долларов?', '1 dollar = 12 500 sum. How many sum does a 20-dollar flash drive cost?'), s: L('Bitta dollar 12 500 so‘m, 20 ta dollar — 20 marta ko‘p: 12 500 · 20 = 250 000. Javob: <b>250 000 so‘m</b>.', 'Один доллар — 12 500 сум, 20 долларов — в 20 раз больше: 12 500 · 20 = 250 000. Ответ: <b>250 000 сум</b>.', 'One dollar is 12 500 sum, 20 dollars is 20 times more: 12 500 · 20 = 250 000. Answer: <b>250 000 sum</b>.') },
      { q: L('Onam 3 ta non 4 000 so‘mdan va 2 kg olma 15 000 so‘mdan oldi. Jami qancha to‘ladi? Ifoda tuzing.', 'Мама купила 3 лепёшки по 4 000 сум и 2 кг яблок по 15 000 сум. Сколько заплатила? Составь выражение.', 'Mum bought 3 loaves at 4 000 sum and 2 kg of apples at 15 000 sum. How much did she pay? Write an expression.'), s: L('Ifoda: 4 000 · 3 + 15 000 · 2. Avval ikkala ko‘paytirish: 12 000 va 30 000. Keyin qo‘shish: 12 000 + 30 000 = <b>42 000 so‘m</b>.', 'Выражение: 4 000 · 3 + 15 000 · 2. Сначала оба умножения: 12 000 и 30 000. Потом сложение: 12 000 + 30 000 = <b>42 000 сум</b>.', 'Expression: 4 000 · 3 + 15 000 · 2. Both multiplications first: 12 000 and 30 000. Then add: 12 000 + 30 000 = <b>42 000 sum</b>.') }
    ] },
    { kind: 'table', h: L('Valyuta kursi jadvali', 'Таблица курса валют', 'Exchange-rate table'), p: [
      L('Kurs har kuni ozgina o‘zgaradi. Quyida taxminiy, yaxlitlangan kurslar berilgan — ular bilan hisoblash oson. Haqiqiy kursni Markaziy bank e’lon qiladi.', 'Курс каждый день немного меняется. Ниже даны примерные, округлённые курсы — с ними легко считать. Настоящий курс объявляет Центральный банк.', 'Rates change slightly every day. Below are approximate, rounded rates that are easy to calculate with. The real rate is announced by the Central Bank.')
    ], table: { head: [L('Valyuta', 'Валюта', 'Currency'), L('1 birlik ≈ so‘m', '1 единица ≈ сум', '1 unit ≈ sum'), L('10 birlik', '10 единиц', '10 units')], rows: [
      [L('AQSH dollari', 'Доллар США', 'US dollar'), '12 500', '125 000'],
      [L('Yevro', 'Евро', 'Euro'), '14 000', '140 000'],
      [L('Rossiya rubli', 'Российский рубль', 'Russian rouble'), '150', '1 500'],
      [L('Xitoy yuani', 'Китайский юань', 'Chinese yuan'), '1 750', '17 500']
    ] }, after: [
      L('Dollarni so‘mga aylantirish — ko‘paytirish: 15 dollar = 15 · 12 500 = 187 500 so‘m. So‘mni dollarga aylantirish — bo‘lish: 250 000 so‘m = 250 000 : 12 500 = 20 dollar.', 'Перевод долларов в сумы — умножение: 15 долларов = 15 · 12 500 = 187 500 сум. Перевод сумов в доллары — деление: 250 000 сум = 250 000 : 12 500 = 20 долларов.', 'Dollars to sum is multiplication: 15 dollars = 15 · 12 500 = 187 500 sum. Sum to dollars is division: 250 000 sum = 250 000 : 12 500 = 20 dollars.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Chapdan o‘ngga «yugurish».</b> 20 + 30 · 2 da avval 20 + 30 ni hisoblash. Yechim: ifodani o‘qishdan oldin «·» va «:» belgilarini qidiring va ularni belgilang.', '<b>«Бег» слева направо.</b> В 20 + 30 · 2 сначала считать 20 + 30. Решение: прежде чем читать выражение, найди знаки «·» и «:» и отметь их.', '<b>“Running” left to right.</b> Working out 20 + 30 first in 20 + 30 · 2. Fix: before reading the expression, find the “·” and “:” signs and mark them.'),
      L('<b>Ko‘paytirishni bo‘lishdan «kuchli» deb o‘ylash.</b> 60 : 3 · 2 da 3 · 2 = 6 ni avval hisoblab, 60 : 6 = 10 deyish xato. Ular teng kuchli: 60 : 3 = 20, 20 · 2 = 40.', '<b>Считать умножение «сильнее» деления.</b> В 60 : 3 · 2 сначала посчитать 3 · 2 = 6 и сказать 60 : 6 = 10 — ошибка. Они равны по силе: 60 : 3 = 20, 20 · 2 = 40.', '<b>Thinking multiplication beats division.</b> In 60 : 3 · 2, doing 3 · 2 = 6 first and saying 60 : 6 = 10 is wrong. They are equal: 60 : 3 = 20, 20 · 2 = 40.'),
      L('<b>Ayirish va qo‘shishni almashtirish.</b> 100 − 30 + 20 ni 100 − 50 = 50 deb yechish xato. Chapdan o‘ngga: 70 + 20 = 90.', '<b>Менять местами вычитание и сложение.</b> Решать 100 − 30 + 20 как 100 − 50 = 50 — ошибка. Слева направо: 70 + 20 = 90.', '<b>Swapping subtraction and addition.</b> Solving 100 − 30 + 20 as 100 − 50 = 50 is wrong. Left to right: 70 + 20 = 90.'),
      L('<b>Oraliq natijani yo‘qotish.</b> Uzun ifodada hisoblab bo‘lingan sonni yozmay, boshqasini boshlash. Yechim: har qadamdan keyin yangi, qisqaroq ifodani to‘liq yozing.', '<b>Потерять промежуточный результат.</b> В длинном выражении не записать посчитанное число и начать другое. Решение: после каждого шага записывай новое, более короткое выражение целиком.', '<b>Losing an intermediate result.</b> In a long expression, not writing a computed number before starting the next. Fix: after each step write the new, shorter expression in full.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Bozorda.</b> 2 kg uzum 20 000 so‘mdan va 1 ta tarvuz 25 000 so‘m. Jami: 20 000 · 2 + 25 000 = 65 000. Agar amallar tartibini bilmasangiz, (20 000 · 2 + 25 000 o‘rniga) 20 000 · (2 + 25 000) deb hisoblab, aqlga sig‘maydigan narxga duch kelasiz.', '<b>На базаре.</b> 2 кг винограда по 20 000 сум и 1 арбуз за 25 000 сум. Итого: 20 000 · 2 + 25 000 = 65 000. Если не знать порядок действий и посчитать 20 000 · (2 + 25 000), получится невообразимая цена.', '<b>At the market.</b> 2 kg of grapes at 20 000 sum and one watermelon at 25 000 sum. Total: 20 000 · 2 + 25 000 = 65 000. Without the order of operations you might compute 20 000 · (2 + 25 000) and get an unbelievable price.'),
      L('<b>Sayohatda.</b> Oila 300 dollar bilan chet elga bordi va 120 dollar sarfladi. Qolgan pul so‘mda qancha? (300 − 120) · 12 500 — bu yerda qavs kerak, lekin qavssiz yozsak — 300 · 12 500 − 120 · 12 500 = 3 750 000 − 1 500 000 = 2 250 000 so‘m.', '<b>В путешествии.</b> Семья поехала за границу с 300 долларами и потратила 120. Сколько осталось в сумах? (300 − 120) · 12 500 — здесь нужны скобки, а без скобок — 300 · 12 500 − 120 · 12 500 = 3 750 000 − 1 500 000 = 2 250 000 сум.', '<b>Travelling.</b> A family went abroad with 300 dollars and spent 120. How much is left in sum? (300 − 120) · 12 500 — here brackets are needed, but without them: 300 · 12 500 − 120 · 12 500 = 3 750 000 − 1 500 000 = 2 250 000 sum.'),
      L('<b>Sportda.</b> Futbol jadvalida g‘alaba 3 ochko, durang 1 ochko. Jamoa 5 marta yutdi, 2 marta durang qildi: 3 · 5 + 1 · 2 = 15 + 2 = 17 ochko. Jadvallar aynan shu formula bilan tuziladi.', '<b>В спорте.</b> В футбольной таблице победа — 3 очка, ничья — 1 очко. Команда 5 раз выиграла и 2 раза сыграла вничью: 3 · 5 + 1 · 2 = 15 + 2 = 17 очков. Таблицы составляют именно по этой формуле.', '<b>In sport.</b> In a football table a win is 3 points, a draw 1 point. A team won 5 and drew 2: 3 · 5 + 1 · 2 = 15 + 2 = 17 points. League tables are built with exactly this formula.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Ingliz tilida bolalar amallar tartibini eslab qolish uchun «PEMDAS» so‘zini yodlaydi: qavs, daraja, ko‘paytirish-bo‘lish, qo‘shish-ayirish.', 'В английских школах дети запоминают порядок действий по слову «PEMDAS»: скобки, степень, умножение-деление, сложение-вычитание.', 'In English-speaking schools children memorise the order with the word “PEMDAS”: parentheses, exponents, multiplication-division, addition-subtraction.'),
      L('2019-yilda internetda 8 : 2 · (2 + 2) misoli millionlab odamni bahslashtirdi. To‘g‘ri javob — 16: chapdan o‘ngga 8 : 2 = 4, 4 · 4 = 16.', 'В 2019 году пример 8 : 2 · (2 + 2) заставил спорить миллионы людей в интернете. Правильный ответ — 16: слева направо 8 : 2 = 4, 4 · 4 = 16.', 'In 2019 the example 8 : 2 · (2 + 2) made millions of people argue online. The correct answer is 16: left to right 8 : 2 = 4, then 4 · 4 = 16.'),
      L('O‘zbekiston so‘mi 1994-yil 1-iyulda muomalaga kiritilgan. O‘shanda 1 dollar taxminan 7 so‘m turardi!', 'Узбекский сум введён в обращение 1 июля 1994 года. Тогда 1 доллар стоил около 7 сумов!', 'The Uzbek sum entered circulation on 1 July 1994. Back then one dollar cost about 7 sum!'),
      L('Nuqta «·» va xoch «×» — ikkalasi ham ko‘paytirish belgisi. Kompyuterda esa yulduzcha «*» ishlatiladi: 3*4 = 12.', 'Точка «·» и крестик «×» — оба знаки умножения. В компьютере же используют звёздочку «*»: 3*4 = 12.', 'The dot “·” and the cross “×” are both multiplication signs. Computers use the asterisk “*”: 3*4 = 12.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('7 + 7 · 7 − 7 : 7 ifodasining qiymatini toping.', 'Найди значение выражения 7 + 7 · 7 − 7 : 7.', 'Find the value of 7 + 7 · 7 − 7 : 7.'),
      L('5 ta bir xil ruchka 3 000 so‘mdan va 1 ta daftar 2 500 so‘m. Jami narx ifodasini yozing va hisoblang.', '5 одинаковых ручек по 3 000 сум и 1 тетрадь за 2 500 сум. Запиши выражение для общей цены и вычисли.', '5 identical pens at 3 000 sum and 1 notebook at 2 500 sum. Write the expression for the total and work it out.'),
      L('1 yevro = 14 000 so‘m. 70 000 so‘mga necha yevro olish mumkin?', '1 евро = 14 000 сум. Сколько евро можно купить на 70 000 сум?', '1 euro = 14 000 sum. How many euros can you buy with 70 000 sum?')
    ], after: [
      L('Javoblar: 1) 7 · 7 = 49, 7 : 7 = 1, 7 + 49 − 1 = 55; 2) 3 000 · 5 + 2 500 = 17 500 so‘m; 3) 70 000 : 14 000 = 5 yevro.', 'Ответы: 1) 7 · 7 = 49, 7 : 7 = 1, 7 + 49 − 1 = 55; 2) 3 000 · 5 + 2 500 = 17 500 сум; 3) 70 000 : 14 000 = 5 евро.', 'Answers: 1) 7 · 7 = 49, 7 : 7 = 1, 7 + 49 − 1 = 55; 2) 3 000 · 5 + 2 500 = 17 500 sum; 3) 70 000 : 14 000 = 5 euros.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Qavssiz ifodada avval ko‘paytirish va bo‘lish, keyin qo‘shish va ayirish bajariladi.', 'В выражении без скобок сначала умножение и деление, потом сложение и вычитание.', 'Without brackets: multiplication and division first, then addition and subtraction.'),
      L('Bir darajadagi amallar chapdan o‘ngga bajariladi.', 'Действия одной ступени выполняются слева направо.', 'Operations of the same level go left to right.'),
      L('Ko‘paytirish va bo‘lish teng kuchli; qo‘shish va ayirish ham teng kuchli.', 'Умножение и деление равны по силе; сложение и вычитание тоже.', 'Multiplication and division are equal; so are addition and subtraction.'),
      L('Yechishdan oldin amallar ustiga tartib raqamlarini yozing.', 'Перед решением надпиши над действиями их номера.', 'Number the operations before solving.'),
      L('Valyuta kursi — bir pulning boshqa puldagi narxi: dollar → so‘m — ko‘paytirish, so‘m → dollar — bo‘lish.', 'Курс валюты — цена одних денег в других: доллар → сум — умножение, сум → доллар — деление.', 'An exchange rate is the price of one currency in another: dollars → sum is multiplication, sum → dollars is division.'),
      L('20 + 30 · 2 = 80, 100 − 40 : 4 = 90 — buni yodda tuting!', '20 + 30 · 2 = 80, 100 − 40 : 4 = 90 — запомни это!', 'Remember: 20 + 30 · 2 = 80 and 100 − 40 : 4 = 90!')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t3. Qavsli ifodalarda amallar tartibi ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Qavs — «avval meni hisobla!»', 'Скобки — «сначала посчитай меня!»', 'Brackets: “work me out first!”'), p: [
      L('O‘tgan mavzuda bilib oldik: 20 + 30 · 2 = 80, chunki ko‘paytirish birinchi bajariladi. Lekin ba’zan bizga aynan qo‘shishni birinchi bajarish kerak bo‘ladi. Masalan: «Aziz 20 ta, Malika 30 ta yong‘oq terdi. Ularning hammasini 2 baravar ko‘paytirishsa, qancha bo‘ladi?» Bu yerda avval umumiy son topiladi: 20 + 30 = 50, keyin 50 · 2 = 100.', 'В прошлой теме мы узнали: 20 + 30 · 2 = 80, потому что умножение выполняется первым. Но иногда нам нужно сначала выполнить именно сложение. Например: «Азиз собрал 20 орехов, Малика — 30. Если всё увеличить в 2 раза, сколько получится?» Здесь сначала находим общее число: 20 + 30 = 50, потом 50 · 2 = 100.', 'In the last topic we learned that 20 + 30 · 2 = 80, because multiplication comes first. But sometimes we need the addition to come first. For example: “Aziz gathered 20 walnuts, Malika 30. If all of them are doubled, how many will there be?” Here we first find the total: 20 + 30 = 50, then 50 · 2 = 100.'),
      L('Buni qanday yozamiz? Matematiklar maxsus belgini o‘ylab topishgan — <b>qavs</b>: (20 + 30) · 2. Qavs ichidagi amal har qanday boshqa amaldan oldin bajariladi. Qavs — xuddi navbatsiz o‘tish chiptasi: unda turgan amal hammadan oldin xizmat ko‘radi.', 'Как это записать? Математики придумали особый знак — <b>скобки</b>: (20 + 30) · 2. Действие в скобках выполняется раньше любого другого. Скобки — как билет без очереди: действие в них обслуживается первым.', 'How do we write that? Mathematicians invented a special sign — <b>brackets</b>: (20 + 30) · 2. The operation inside brackets is done before any other. Brackets are like a skip-the-queue ticket: the operation inside is served first.'),
      L('Bu mavzuda biz qavsli ifodalarni yechishni, qavs qo‘yish orqali natijani o‘zgartirishni va masala shartiga qarab o‘zimiz qavsli ifoda tuzishni o‘rganamiz.', 'В этой теме мы научимся решать выражения со скобками, менять результат с помощью скобок и сами составлять выражения со скобками по условию задачи.', 'In this topic we learn to solve expressions with brackets, change a result by placing brackets and write bracketed expressions from a problem ourselves.')
    ] },
    { kind: 'def', h: L('Qavslar va ularning turlari', 'Скобки и их виды', 'Brackets and their kinds'), p: [
      L('<b>Qavs</b> — ifodaning bir qismini ajratib ko‘rsatadigan belgi. Ochiluvchi qavs «(» va yopiluvchi qavs «)» doimo juft bo‘ladi. Ular orasidagi qism yaxlit bitta son kabi qaraladi: avval uni hisoblaymiz, so‘ng natijani ifodaga qo‘yamiz.', '<b>Скобки</b> — знак, который выделяет часть выражения. Открывающая «(» и закрывающая «)» скобки всегда идут парой. Часть между ними рассматривается как одно число: сначала её вычисляем, потом подставляем результат в выражение.', '<b>Brackets</b> are a sign that marks off part of an expression. An opening “(” and a closing “)” bracket always come as a pair. The part between them is treated as a single number: we compute it first and then put the result back into the expression.'),
      L('Ba’zan bitta ifodada bir necha qavs bo‘ladi: (60 − 20) : (2 + 3). Bunda ikkala qavs ham birinchi hisoblanadi, chapdan o‘ngga: 40 va 5, keyin 40 : 5 = 8.', 'Иногда в одном выражении несколько скобок: (60 − 20) : (2 + 3). Тогда обе скобки считаются первыми, слева направо: 40 и 5, затем 40 : 5 = 8.', 'Sometimes one expression has several brackets: (60 − 20) : (2 + 3). Then both brackets come first, left to right: 40 and 5, then 40 : 5 = 8.'),
      L('Qavs ichida qavs ham bo‘lishi mumkin. Katta sinflarda kvadrat qavslar ishlatiladi: [ ]. Bunda <b>eng ichki</b> qavs birinchi hisoblanadi: 2 · [100 − (30 + 20)] = 2 · [100 − 50] = 2 · 50 = 100.', 'Бывают и скобки внутри скобок. В старших классах используют квадратные скобки: [ ]. Тогда первой считается <b>самая внутренняя</b> скобка: 2 · [100 − (30 + 20)] = 2 · [100 − 50] = 2 · 50 = 100.', 'There can also be brackets inside brackets. Older pupils use square brackets [ ]. Then the <b>innermost</b> bracket is computed first: 2 · [100 − (30 + 20)] = 2 · [100 − 50] = 2 · 50 = 100.')
    ] },
    { kind: 'history', h: L('Qavslar tarixi', 'История скобок', 'A history of brackets'), p: [
      L('Qadimgi olimlar qavs ishlatmagan. Ular ifodaning bir qismini ustiga chiziq tortib ajratishgan: chiziq ostidagi narsa birinchi hisoblangan. Bu «vinkulum» deb ataladi. Bunday chiziq bugun ham ildiz belgisi √ ning ustida saqlanib qolgan.', 'Древние учёные скобками не пользовались. Часть выражения выделяли чертой сверху: то, что под чертой, считалось первым. Это называется «винкулум». Такая черта и сегодня сохранилась над знаком корня √.', 'Ancient scholars did not use brackets. They marked part of an expression with a line drawn over it: whatever was under the line was computed first. This is called a “vinculum”. Such a line still survives today over the root sign √.'),
      L('Dumaloq qavslarni XVI asrda italyan matematiklari ishlata boshlagan. Ularni keng tarqatgan olimlar orasida Rene Dekart va Leonard Eyler bor. Eyler XVIII asrda o‘z darsliklarida qavslarni hozirgi ko‘rinishida doimiy ishlatgan va shundan keyin ular hamma joyda qabul qilingan.', 'Круглые скобки начали использовать итальянские математики в XVI веке. Среди учёных, распространивших их, — Рене Декарт и Леонард Эйлер. Эйлер в XVIII веке постоянно применял скобки в нынешнем виде в своих учебниках, и после этого их приняли повсюду.', 'Round brackets began to be used by Italian mathematicians in the 16th century. Among those who spread them were René Descartes and Leonhard Euler. In the 18th century Euler used brackets in today’s form throughout his textbooks, and after that they were accepted everywhere.'),
      L('Xorazmiy esa o‘z masalalarini butunlay so‘z bilan yozgan: «molni ikkiga ko‘paytir, so‘ng unga o‘nni qo‘sh». Bunday yozuvda tartib gapdagi so‘zlar ketma-ketligidan aniq bo‘lgan. Belgilar va qavslar yozuvni qisqa qildi — bir qatorda butun bir sahifalik fikrni ifodalash mumkin bo‘ldi.', 'Аль-Хорезми записывал свои задачи целиком словами: «умножь имущество на два, затем прибавь к нему десять». В такой записи порядок был ясен из последовательности слов. Знаки и скобки сделали запись короткой — в одну строку стало можно уложить мысль на целую страницу.', 'Al-Khwarizmi wrote his problems entirely in words: “multiply the wealth by two, then add ten to it”. In such writing the order was clear from the word sequence. Signs and brackets made writing short — a page-long idea could now fit on one line.')
    ] },
    { kind: 'rule', h: L('To‘liq qoida', 'Полное правило', 'The full rule'), p: [
      L('Endi amallar tartibining to‘liq qoidasini bilamiz:', 'Теперь мы знаем полное правило порядка действий:', 'Now we know the full rule for the order of operations:')
    ], list: [
      L('<b>1.</b> Avval qavs ichidagi amallar bajariladi. Qavs ichida ham shu qoida amal qiladi: avval · va :, keyin + va −.', '<b>1.</b> Сначала выполняются действия в скобках. Внутри скобок действует то же правило: сначала · и :, потом + и −.', '<b>1.</b> First, the operations inside brackets. Inside the brackets the same rule applies: · and : first, then + and −.'),
      L('<b>2.</b> Keyin ko‘paytirish va bo‘lish — chapdan o‘ngga.', '<b>2.</b> Затем умножение и деление — слева направо.', '<b>2.</b> Then multiplication and division — left to right.'),
      L('<b>3.</b> Oxirida qo‘shish va ayirish — chapdan o‘ngga.', '<b>3.</b> В конце сложение и вычитание — слева направо.', '<b>3.</b> Finally addition and subtraction — left to right.')
    ], after: [
      L('Qisqacha: <b>( ) → · : → + −</b>. Qavs qo‘yish natijani o‘zgartirishi mumkin: 20 + 30 · 2 = 80, (20 + 30) · 2 = 100. Lekin har doim emas: 20 + (30 · 2) = 80 — bu qavs ortiqcha, chunki ko‘paytirish baribir birinchi bajariladi.', 'Кратко: <b>( ) → · : → + −</b>. Скобки могут изменить результат: 20 + 30 · 2 = 80, (20 + 30) · 2 = 100. Но не всегда: 20 + (30 · 2) = 80 — эти скобки лишние, ведь умножение и так выполняется первым.', 'In short: <b>( ) → · : → + −</b>. Brackets can change the result: 20 + 30 · 2 = 80, (20 + 30) · 2 = 100. But not always: 20 + (30 · 2) = 80 — these brackets are unnecessary because multiplication comes first anyway.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 120 − (14 + 6) · 5 : 10', 'Пошагово: 120 − (14 + 6) · 5 : 10', 'Step by step: 120 − (14 + 6) · 5 : 10'), list: [
      L('<b>Tartibni belgilaymiz.</b> Qavs ichidagi «+» — 1. Keyin «·» — 2, «:» — 3 (chapdan o‘ngga). Oxirida «−» — 4.', '<b>Отмечаем порядок.</b> «+» в скобках — 1. Затем «·» — 2, «:» — 3 (слева направо). В конце «−» — 4.', '<b>Mark the order.</b> The “+” in brackets is 1. Then “·” is 2 and “:” is 3 (left to right). Last, “−” is 4.'),
      L('<b>1)</b> 14 + 6 = 20. Ifoda: 120 − 20 · 5 : 10.', '<b>1)</b> 14 + 6 = 20. Выражение: 120 − 20 · 5 : 10.', '<b>1)</b> 14 + 6 = 20. Expression: 120 − 20 · 5 : 10.'),
      L('<b>2)</b> 20 · 5 = 100. Ifoda: 120 − 100 : 10.', '<b>2)</b> 20 · 5 = 100. Выражение: 120 − 100 : 10.', '<b>2)</b> 20 · 5 = 100. Expression: 120 − 100 : 10.'),
      L('<b>3)</b> 100 : 10 = 10. Ifoda: 120 − 10.', '<b>3)</b> 100 : 10 = 10. Выражение: 120 − 10.', '<b>3)</b> 100 : 10 = 10. Expression: 120 − 10.'),
      L('<b>4)</b> 120 − 10 = 110. Javob: <b>110</b>. Har qadamda qolgan ifodani to‘liq qayta yozish xatolardan saqlaydi.', '<b>4)</b> 120 − 10 = 110. Ответ: <b>110</b>. Переписывать оставшееся выражение после каждого шага — защита от ошибок.', '<b>4)</b> 120 − 10 = 110. Answer: <b>110</b>. Rewriting the remaining expression after every step protects you from mistakes.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '(90 − 30) : 6', s: L('Qavs: 90 − 30 = 60. Keyin 60 : 6 = <b>10</b>. Qavssiz bo‘lsa: 90 − 30 : 6 = 90 − 5 = 85 — butunlay boshqa javob!', 'Скобки: 90 − 30 = 60. Затем 60 : 6 = <b>10</b>. Без скобок: 90 − 30 : 6 = 90 − 5 = 85 — совсем другой ответ!', 'Brackets: 90 − 30 = 60. Then 60 : 6 = <b>10</b>. Without brackets: 90 − 30 : 6 = 90 − 5 = 85 — a totally different answer!') },
      { q: '(48 + 12) : (7 − 4)', s: L('Ikkala qavs: 48 + 12 = 60, 7 − 4 = 3. Keyin 60 : 3 = <b>20</b>.', 'Обе скобки: 48 + 12 = 60, 7 − 4 = 3. Затем 60 : 3 = <b>20</b>.', 'Both brackets: 48 + 12 = 60, 7 − 4 = 3. Then 60 : 3 = <b>20</b>.') },
      { q: L('Qavs qo‘yib, to‘g‘ri tenglik hosil qiling: 6 + 4 · 5 − 2 = 48', 'Расставь скобки, чтобы получилось верное равенство: 6 + 4 · 5 − 2 = 48', 'Place brackets to make the equality true: 6 + 4 · 5 − 2 = 48'), s: L('Qavssiz: 6 + 20 − 2 = 24 — kam. Qo‘shishni oldinga chiqarib sinab ko‘ramiz: (6 + 4) · 5 − 2 = 50 − 2 = 48. To‘g‘ri! Javob: <b>(6 + 4) · 5 − 2 = 48</b>.', 'Без скобок: 6 + 20 − 2 = 24. Пробуем: (6 + 4) · 5 − 2 = 50 − 2 = 48. Верно! Ответ: <b>(6 + 4) · 5 − 2 = 48</b>.', 'Without brackets: 6 + 20 − 2 = 24. Try: (6 + 4) · 5 − 2 = 50 − 2 = 48. Correct! Answer: <b>(6 + 4) · 5 − 2 = 48</b>.') },
      { q: L('Do‘konga 3 ta qutida 25 tadan va 5 ta qutida 25 tadan daftar keltirildi. Jami nechta daftar? Ikki usulda yeching.', 'В магазин привезли 3 коробки по 25 тетрадей и 5 коробок по 25 тетрадей. Сколько всего тетрадей? Реши двумя способами.', 'A shop received 3 boxes of 25 notebooks and 5 boxes of 25 notebooks. How many notebooks in all? Solve in two ways.'), s: L('1-usul: 25 · 3 + 25 · 5 = 75 + 125 = 200. 2-usul: avval qutilar soni: 25 · (3 + 5) = 25 · 8 = 200. Javob: <b>200 ta</b>. Ikkinchi usul tezroq — qavs yordam berdi.', 'Способ 1: 25 · 3 + 25 · 5 = 75 + 125 = 200. Способ 2: сначала число коробок: 25 · (3 + 5) = 25 · 8 = 200. Ответ: <b>200 тетрадей</b>. Второй способ быстрее — помогли скобки.', 'Way 1: 25 · 3 + 25 · 5 = 75 + 125 = 200. Way 2: first the number of boxes: 25 · (3 + 5) = 25 · 8 = 200. Answer: <b>200 notebooks</b>. The second way is faster — the brackets helped.') }
    ] },
    { kind: 'table', h: L('Qavs natijani qanday o‘zgartiradi', 'Как скобки меняют результат', 'How brackets change the result'), p: [
      L('Bir xil sonlar va bir xil belgilar, lekin qavslar turli joyda. Natijalarni solishtiring.', 'Одни и те же числа и знаки, но скобки в разных местах. Сравни результаты.', 'The same numbers and signs, but brackets in different places. Compare the results.')
    ], table: { head: [L('Ifoda', 'Выражение', 'Expression'), L('Hisob', 'Вычисление', 'Working'), L('Qiymat', 'Значение', 'Value')], rows: [
      ['24 + 16 : 4 − 2', '24 + 4 − 2', '26'],
      ['(24 + 16) : 4 − 2', '40 : 4 − 2', '8'],
      ['(24 + 16) : (4 − 2)', '40 : 2', '20'],
      ['24 + 16 : (4 − 2)', '24 + 8', '32']
    ] }, after: [
      L('To‘rtta ifoda — to‘rtta turli javob! Shuning uchun qavsni ko‘zdan qochirish jiddiy xatoga olib keladi.', 'Четыре выражения — четыре разных ответа! Поэтому пропустить скобки — серьёзная ошибка.', 'Four expressions — four different answers! That is why overlooking brackets leads to serious mistakes.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Qavsni e’tiborsiz qoldirish.</b> (20 + 30) · 2 ni 20 + 60 = 80 deb yechish. Yechim: misolni o‘qiganda avval qavslarni topib, ularni rangli qalam bilan aylantiring.', '<b>Не заметить скобки.</b> Решить (20 + 30) · 2 как 20 + 60 = 80. Решение: читая пример, сначала найди скобки и обведи их цветным карандашом.', '<b>Ignoring the brackets.</b> Solving (20 + 30) · 2 as 20 + 60 = 80. Fix: when reading, find the brackets first and circle them in colour.'),
      L('<b>Qavs ichida tartibni buzish.</b> (5 + 3 · 4) da avval 5 + 3 ni hisoblash. Qavs ichida ham ko‘paytirish birinchi: 5 + 12 = 17.', '<b>Нарушить порядок внутри скобок.</b> В (5 + 3 · 4) сначала посчитать 5 + 3. Внутри скобок тоже сначала умножение: 5 + 12 = 17.', '<b>Breaking the order inside brackets.</b> Doing 5 + 3 first in (5 + 3 · 4). Inside brackets multiplication still comes first: 5 + 12 = 17.'),
      L('<b>Qavsdan keyin tartibni unutish.</b> 100 − (20 + 10) · 2 da qavsdan keyin 100 − 30 = 70, 70 · 2 = 140 deyish xato. Qavsdan so‘ng ham ko‘paytirish oldin: 30 · 2 = 60, 100 − 60 = 40.', '<b>Забыть порядок после скобок.</b> В 100 − (20 + 10) · 2 после скобок сказать 100 − 30 = 70, 70 · 2 = 140 — ошибка. После скобок умножение тоже раньше: 30 · 2 = 60, 100 − 60 = 40.', '<b>Forgetting the order after brackets.</b> In 100 − (20 + 10) · 2, doing 100 − 30 = 70, 70 · 2 = 140 is wrong. After the brackets, multiplication still comes first: 30 · 2 = 60, 100 − 60 = 40.'),
      L('<b>Juftsiz qavs.</b> O‘zingiz ifoda yozganda yopiluvchi qavsni unutish: (20 + 30 · 2. Har bir «(» uchun «)» bo‘lishini tekshiring.', '<b>Непарная скобка.</b> Записывая выражение, забыть закрывающую скобку: (20 + 30 · 2. Проверь, что на каждую «(» есть «)».', '<b>An unpaired bracket.</b> Forgetting the closing bracket when writing: (20 + 30 · 2. Check that every “(” has a “)”.')
    ] },
    { kind: 'life', h: L('Hayotda qavslar', 'Скобки в жизни', 'Brackets in life'), p: [
      L('<b>Sinf sayohati.</b> Sinfda 18 qiz va 14 o‘g‘il bola bor. Har biri muzeyga 5 000 so‘mdan to‘laydi. Jami: (18 + 14) · 5 000 = 32 · 5 000 = 160 000 so‘m. Qavssiz yozsak, faqat o‘g‘il bolalar to‘lagandek chiqib qoladi!', '<b>Экскурсия класса.</b> В классе 18 девочек и 14 мальчиков. Каждый платит за музей 5 000 сум. Всего: (18 + 14) · 5 000 = 32 · 5 000 = 160 000 сум. Без скобок получится, будто платили только мальчики!', '<b>A class trip.</b> A class has 18 girls and 14 boys. Each pays 5 000 sum for the museum. Total: (18 + 14) · 5 000 = 32 · 5 000 = 160 000 sum. Without brackets it would look as if only the boys paid!'),
      L('<b>Qaytim.</b> Siz 50 000 so‘m berdingiz va 12 000 hamda 9 000 so‘mlik ikki narsa oldingiz. Qaytim: 50 000 − (12 000 + 9 000) = 29 000 so‘m. Kassa apparati ham aynan shunday hisoblaydi.', '<b>Сдача.</b> Ты дал 50 000 сум и купил две вещи за 12 000 и 9 000 сум. Сдача: 50 000 − (12 000 + 9 000) = 29 000 сум. Кассовый аппарат считает точно так же.', '<b>Change.</b> You paid 50 000 sum for two things costing 12 000 and 9 000. Change: 50 000 − (12 000 + 9 000) = 29 000 sum. A cash register works it out the same way.'),
      L('<b>Dasturlash.</b> Excel jadvallari va kompyuter dasturlarida formulalar qavslar bilan yoziladi: =(A1+B1)*2. Qavsni noto‘g‘ri qo‘ygan dasturchi xato natija oladi — shuning uchun qavslar professional ishda ham muhim.', '<b>Программирование.</b> В таблицах Excel и компьютерных программах формулы пишут со скобками: =(A1+B1)*2. Программист, неверно поставивший скобки, получит неверный результат — поэтому скобки важны и в профессиональной работе.', '<b>Programming.</b> In Excel and computer programs formulas are written with brackets: =(A1+B1)*2. A programmer who misplaces brackets gets a wrong result — so brackets matter in professional work too.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«To‘rtta to‘rtlik» o‘yini: faqat to‘rtta 4 raqami, amallar va qavslar bilan sonlar hosil qiling. Masalan, (4 + 4) : (4 + 4) = 1, 4 : 4 + 4 : 4 = 2, (4 + 4 + 4) : 4 = 3.', 'Игра «четыре четвёрки»: составь числа только из четырёх цифр 4, знаков и скобок. Например, (4 + 4) : (4 + 4) = 1, 4 : 4 + 4 : 4 = 2, (4 + 4 + 4) : 4 = 3.', 'The “four fours” game: make numbers using only four 4s, signs and brackets. E.g. (4 + 4) : (4 + 4) = 1, 4 : 4 + 4 : 4 = 2, (4 + 4 + 4) : 4 = 3.'),
      L('Polshalik olim Yan Lukasevich 1924-yilda qavssiz yozuvni ixtiro qildi: amal belgisi sonlardan oldin yoziladi. Bu usul ba’zi kalkulyatorlar va dasturlash tillarida ishlatiladi.', 'Польский учёный Ян Лукасевич в 1924 году придумал запись без скобок: знак действия пишется перед числами. Этот способ используют некоторые калькуляторы и языки программирования.', 'The Polish scholar Jan Łukasiewicz invented a bracket-free notation in 1924: the operation sign is written before the numbers. Some calculators and programming languages use it.'),
      L('Bitta ifodaga qavslarni turli usulda qo‘yish mumkin. 1 + 2 · 3 + 4 · 5 ifodasida qavs qo‘yib 27, 29, 47, 55, 65, 71, 105 kabi javoblarni olish mumkin. Sinab ko‘ring!', 'В одно выражение скобки можно расставить по-разному. В 1 + 2 · 3 + 4 · 5 можно получить 27, 29, 47, 55, 65, 71, 105 и другие ответы. Попробуй!', 'Brackets can be placed in one expression in different ways. In 1 + 2 · 3 + 4 · 5 you can get 27, 29, 47, 55, 65, 71, 105 and more. Try it!')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 5 · (40 − 8 · 3).', 'Вычисли: 5 · (40 − 8 · 3).', 'Work out: 5 · (40 − 8 · 3).'),
      L('Qavs qo‘ying: 36 : 6 − 2 = 9.', 'Расставь скобки: 36 : 6 − 2 = 9.', 'Place brackets: 36 : 6 − 2 = 9.'),
      L('Masala: Bog‘da 45 tup olma va 35 tup o‘rik bor. Ular 8 qatorga teng ekilgan. Har qatorda nechta daraxt? Ifoda yozing.', 'Задача: в саду 45 яблонь и 35 абрикосов, посаженных поровну в 8 рядов. Сколько деревьев в каждом ряду? Запиши выражение.', 'Problem: an orchard has 45 apple and 35 apricot trees planted equally in 8 rows. How many trees per row? Write the expression.')
    ], after: [
      L('Javoblar: 1) 8 · 3 = 24, 40 − 24 = 16, 5 · 16 = 80; 2) 36 : (6 − 2) = 36 : 4 = 9; 3) (45 + 35) : 8 = 80 : 8 = 10 ta.', 'Ответы: 1) 8 · 3 = 24, 40 − 24 = 16, 5 · 16 = 80; 2) 36 : (6 − 2) = 36 : 4 = 9; 3) (45 + 35) : 8 = 80 : 8 = 10 деревьев.', 'Answers: 1) 8 · 3 = 24, 40 − 24 = 16, 5 · 16 = 80; 2) 36 : (6 − 2) = 36 : 4 = 9; 3) (45 + 35) : 8 = 80 : 8 = 10 trees.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Qavs ichidagi amallar birinchi bajariladi.', 'Действия в скобках выполняются первыми.', 'Operations in brackets come first.'),
      L('Qavs ichida ham, undan tashqarida ham · va : oldin, + va − keyin.', 'И в скобках, и вне их · и : раньше, + и − позже.', 'Inside and outside brackets, · and : come before + and −.'),
      L('Bir nechta qavs bo‘lsa, ular chapdan o‘ngga, ichma-ich bo‘lsa — ichkaridan tashqariga hisoblanadi.', 'Несколько скобок считаем слева направо, вложенные — изнутри наружу.', 'Several brackets go left to right; nested ones go from the inside out.'),
      L('Qavs natijani o‘zgartirishi mumkin: 20 + 30 · 2 = 80, (20 + 30) · 2 = 100.', 'Скобки могут изменить результат: 20 + 30 · 2 = 80, (20 + 30) · 2 = 100.', 'Brackets can change the result: 20 + 30 · 2 = 80, (20 + 30) · 2 = 100.'),
      L('Masalada «avval umumiy sonni top» degan joyda qavs kerak bo‘ladi.', 'Если в задаче нужно «сначала найти общее число» — нужны скобки.', 'When a problem says “first find the total”, you need brackets.'),
      L('Har qadamdan keyin qolgan ifodani qayta yozing.', 'После каждого шага переписывай оставшееся выражение.', 'Rewrite the remaining expression after every step.')
    ] }
  ] });

  // ---------- t4. Misol va masalalar: harakat va massa ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Ikki poyezd uchrashganda', 'Когда встречаются два поезда', 'When two trains meet'), p: [
      L('Ertalab Toshkentdan Samarqandga qarab bir poyezd, xuddi shu paytda Samarqanddan Toshkentga qarab ikkinchi poyezd yo‘lga chiqdi. Ular qayerda va qachon uchrashadi? Bu savol faqat matematik masala emas — temir yo‘l dispetcherlari har kuni shunday hisob-kitob qilishadi, chunki bitta yo‘lda poyezdlar to‘qnashmasligi kerak.', 'Утром из Ташкента в Самарканд вышел поезд, а в то же время из Самарканда в Ташкент — второй поезд. Где и когда они встретятся? Это не просто школьная задача — диспетчеры железной дороги считают такое каждый день, ведь поезда на одном пути не должны столкнуться.', 'In the morning one train left Tashkent for Samarkand and at the same time another left Samarkand for Tashkent. Where and when will they meet? This is not just a school problem — railway dispatchers do such calculations every day, because trains on one line must never collide.'),
      L('Bu mavzuda biz <b>qarama-qarshi harakat</b> masalalarini yechamiz, tezlik, vaqt va masofa orasidagi bog‘lanishni takrorlaymiz. Shuningdek, katta massalarni o‘lchash birliklari — <b>tonna</b> va <b>sentner</b> bilan ishlaymiz: yuk mashinalari, vagonlar va hosil haqidagi masalalar bunga misol.', 'В этой теме мы решаем задачи на <b>встречное движение</b>, повторяем связь скорости, времени и расстояния. А ещё работаем с единицами больших масс — <b>тонной</b> и <b>центнером</b>: задачи о грузовиках, вагонах и урожае.', 'In this topic we solve problems on <b>moving towards each other</b> and review how speed, time and distance are linked. We also work with units of large mass — the <b>tonne</b> and the <b>quintal</b> — in problems about trucks, wagons and harvests.'),
      L('Har bir murakkab masalani bir necha oddiy savolga bo‘lib yechishni o‘rganamiz. Bu — matematikaning eng foydali ko‘nikmasi.', 'Мы учимся разбивать каждую сложную задачу на несколько простых вопросов. Это самый полезный навык математики.', 'We learn to break each hard problem into a few simple questions. This is the most useful skill in maths.')
    ] },
    { kind: 'def', h: L('Tezlik, vaqt, masofa va massa birliklari', 'Скорость, время, расстояние и единицы массы', 'Speed, time, distance and units of mass'), p: [
      L('<b>Tezlik</b> (v) — bir birlik vaqtda bosib o‘tilgan yo‘l. 60 km/soat degani — har soatda 60 km. <b>Vaqt</b> (t) — harakat davomiyligi. <b>Masofa</b> (S) — bosib o‘tilgan yo‘l. Asosiy formula: S = v · t. Undan: v = S : t va t = S : v.', '<b>Скорость</b> (v) — путь за единицу времени. 60 км/ч — это 60 км каждый час. <b>Время</b> (t) — продолжительность движения. <b>Расстояние</b> (S) — пройденный путь. Главная формула: S = v · t. Отсюда v = S : t и t = S : v.', '<b>Speed</b> (v) is the distance covered in one unit of time. 60 km/h means 60 km every hour. <b>Time</b> (t) is how long the motion lasts. <b>Distance</b> (S) is the path covered. The main formula: S = v · t. From it, v = S : t and t = S : v.'),
      L('<b>Qarama-qarshi harakat</b> — ikki jism bir-biriga qarab harakatlanadi. Ularning <b>yaqinlashish tezligi</b> tezliklar yig‘indisiga teng: v₁ + v₂. Har soatda ular orasidagi masofa shuncha kamayadi.', '<b>Встречное движение</b> — два тела движутся навстречу друг другу. Их <b>скорость сближения</b> равна сумме скоростей: v₁ + v₂. Каждый час расстояние между ними уменьшается на столько.', '<b>Moving towards each other</b> — two bodies move to meet each other. Their <b>closing speed</b> is the sum of the speeds: v₁ + v₂. Every hour the distance between them shrinks by that much.')
    ], list: [
      L('1 <b>tonna</b> (t) = 1 000 kg', '1 <b>тонна</b> (т) = 1 000 кг', '1 <b>tonne</b> (t) = 1 000 kg'),
      L('1 <b>sentner</b> (q) = 100 kg', '1 <b>центнер</b> (ц) = 100 кг', '1 <b>quintal</b> (q) = 100 kg'),
      L('1 t = 10 q', '1 т = 10 ц', '1 t = 10 q')
    ] },
    { kind: 'history', h: L('O‘lchovlar tarixidan', 'Из истории мер', 'From the history of measures'), p: [
      L('Qadimda har bir shahar o‘z o‘lchovlariga ega edi. O‘rta Osiyoda og‘irlik «botmon», «qadoq», «misqol» bilan o‘lchangan, masofa esa «farsax» va «tosh» bilan. Bir farsax taxminan 6–7 km bo‘lgan — karvon bir soatda yuradigan yo‘l. Har xil o‘lchovlar savdogarlar uchun ko‘p chalkashlik tug‘dirgan.', 'В старину у каждого города были свои меры. В Средней Азии вес измеряли «ботмоном», «кадоком», «мискалем», а расстояние — «фарсахом» и «ташем». Один фарсах — примерно 6–7 км, путь каравана за час. Разные меры создавали купцам много путаницы.', 'Long ago every city had its own measures. In Central Asia weight was measured in “botmon”, “qadoq” and “misqal”, and distance in “farsakh” and “tosh”. One farsakh was about 6–7 km — the distance a caravan travelled in about an hour. Different measures caused traders a lot of confusion.'),
      L('<b>Abu Rayhon Beruniy</b> (973–1048) «Hindiston» kitobida turli xalqlarning o‘lchov birliklarini taqqoslab, ularni bir-biriga aylantirish usullarini yozgan. U Yer aylanasini o‘lchashda ham masofa va burchaklarni ajoyib aniqlikda hisoblagan.', '<b>Абу Райхан Беруни</b> (973–1048) в книге «Индия» сравнил единицы мер разных народов и описал, как переводить одни в другие. Измеряя окружность Земли, он вычислял расстояния и углы с удивительной точностью.', '<b>Abu Rayhan Biruni</b> (973–1048), in his book on India, compared the measuring units of different peoples and described how to convert between them. When measuring the Earth’s circumference, he calculated distances and angles with remarkable accuracy.'),
      L('Kilogramm va metr Fransiyada 1790-yillarda ixtiro qilingan. Tonna — 1 000 kilogrammga teng bo‘lgan qulay katta birlik. Bugun deyarli butun dunyo shu metrik tizimdan foydalanadi.', 'Килограмм и метр придумали во Франции в 1790-х годах. Тонна — удобная крупная единица, равная 1 000 килограммов. Сегодня почти весь мир пользуется этой метрической системой.', 'The kilogram and the metre were invented in France in the 1790s. The tonne is a convenient large unit equal to 1 000 kilograms. Today almost the whole world uses this metric system.')
    ] },
    { kind: 'rule', h: L('Qarama-qarshi harakat formulasi', 'Формула встречного движения', 'The formula for moving towards each other'), p: [
      L('Ikki jism bir vaqtda bir-biriga qarab yo‘lga chiqsa, uchrashguncha ular birgalikda butun masofani bosib o‘tadi:', 'Если два тела одновременно выходят навстречу друг другу, до встречи они вместе проходят всё расстояние:', 'If two bodies set off towards each other at the same time, together they cover the whole distance before meeting:'),
      L('<b>S = (v₁ + v₂) · t</b>', '<b>S = (v₁ + v₂) · t</b>', '<b>S = (v₁ + v₂) · t</b>'),
      L('Bu yerda qavs juda muhim: avval yaqinlashish tezligini topamiz, keyin uni vaqtga ko‘paytiramiz. Teskari masalalar: uchrashish vaqti t = S : (v₁ + v₂); ikkinchi tezlik v₂ = S : t − v₁.', 'Здесь скобки очень важны: сначала находим скорость сближения, потом умножаем на время. Обратные задачи: время встречи t = S : (v₁ + v₂); вторая скорость v₂ = S : t − v₁.', 'The brackets matter here: first find the closing speed, then multiply by the time. Inverse problems: meeting time t = S : (v₁ + v₂); the second speed v₂ = S : t − v₁.'),
      L('Massa birliklarini aylantirish qoidasi: kattaroq birlikdan kichigiga o‘tishda <b>ko‘paytiramiz</b> (3 t = 3 · 1 000 = 3 000 kg), kichigidan kattasiga o‘tishda <b>bo‘lamiz</b> (2 500 kg = 25 q).', 'Правило перевода единиц массы: от большей единицы к меньшей — <b>умножаем</b> (3 т = 3 · 1 000 = 3 000 кг), от меньшей к большей — <b>делим</b> (2 500 кг = 25 ц).', 'Converting mass units: from a larger unit to a smaller one we <b>multiply</b> (3 t = 3 · 1 000 = 3 000 kg); from smaller to larger we <b>divide</b> (2 500 kg = 25 q).')
    ] },
    { kind: 'steps', h: L('Masala yechish rejasi', 'План решения задачи', 'A plan for solving a problem'), list: [
      L('<b>1. O‘qing.</b> Masalani ikki marta o‘qing. Nima ma’lum, nima so‘ralgan — ajrating.', '<b>1. Прочитай.</b> Прочитай задачу дважды. Отдели, что известно и что спрашивается.', '<b>1. Read.</b> Read the problem twice. Separate what is known from what is asked.'),
      L('<b>2. Qisqa yozing yoki chizing.</b> Harakat masalasida chiziq chizing, ikki uchiga shaharlarni, o‘qlar bilan yo‘nalishni belgilang.', '<b>2. Запиши кратко или начерти.</b> В задаче на движение начерти отрезок, на концах отметь города, стрелками — направления.', '<b>2. Write briefly or draw.</b> For a motion problem draw a line, mark the towns at its ends and the directions with arrows.'),
      L('<b>3. Reja tuzing.</b> «Avval nimani bilsam, keyin javobni topa olaman?» — savollar zanjirini yozing.', '<b>3. Составь план.</b> «Что нужно узнать сначала, чтобы найти ответ?» — запиши цепочку вопросов.', '<b>3. Make a plan.</b> “What must I know first to find the answer?” — write the chain of questions.'),
      L('<b>4. Hisoblang.</b> Har bir savolga amal bilan javob bering, birliklarni yozing.', '<b>4. Вычисли.</b> Ответь на каждый вопрос действием, записывай единицы.', '<b>4. Calculate.</b> Answer each question with an operation and write the units.'),
      L('<b>5. Tekshiring.</b> Javob mantiqiymi? Poyezd soatiga 5 000 km yurmaydi! Teskari masala bilan tekshiring.', '<b>5. Проверь.</b> Разумен ли ответ? Поезд не едет 5 000 км в час! Проверь обратной задачей.', '<b>5. Check.</b> Does the answer make sense? A train does not go 5 000 km per hour! Check with the inverse problem.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Ikki shahardan bir-biriga qarab ikki poyezd chiqdi: 60 km/soat va 40 km/soat tezlikda. Ular 3 soatda uchrashdi. Shaharlar orasidagi masofa qancha?', 'Из двух городов навстречу друг другу вышли два поезда: 60 км/ч и 40 км/ч. Они встретились через 3 ч. Каково расстояние между городами?', 'Two trains left two cities towards each other at 60 km/h and 40 km/h. They met after 3 hours. What is the distance between the cities?'), s: L('1) Yaqinlashish tezligi: 60 + 40 = 100 km/soat. 2) Masofa: 100 · 3 = 300 km. Tekshiruv: birinchisi 60 · 3 = 180 km, ikkinchisi 40 · 3 = 120 km, 180 + 120 = 300. Javob: <b>300 km</b>.', '1) Скорость сближения: 60 + 40 = 100 км/ч. 2) Расстояние: 100 · 3 = 300 км. Проверка: первый 60 · 3 = 180 км, второй 40 · 3 = 120 км, 180 + 120 = 300. Ответ: <b>300 км</b>.', '1) Closing speed: 60 + 40 = 100 km/h. 2) Distance: 100 · 3 = 300 km. Check: the first went 60 · 3 = 180 km, the second 40 · 3 = 120 km, 180 + 120 = 300. Answer: <b>300 km</b>.') },
      { q: L('Ikki qishloq orasidagi masofa 36 km. Ulardan bir vaqtda bir-biriga qarab ikki velosipedchi chiqdi: 10 km/soat va 8 km/soat. Ular necha soatdan keyin uchrashadi?', 'Расстояние между двумя сёлами 36 км. Из них одновременно навстречу друг другу выехали два велосипедиста: 10 км/ч и 8 км/ч. Через сколько часов они встретятся?', 'Two villages are 36 km apart. Two cyclists set off from them towards each other at the same time, at 10 km/h and 8 km/h. After how many hours will they meet?'), s: L('1) 10 + 8 = 18 km/soat. 2) 36 : 18 = 2 soat. Javob: <b>2 soatdan keyin</b>.', '1) 10 + 8 = 18 км/ч. 2) 36 : 18 = 2 ч. Ответ: <b>через 2 часа</b>.', '1) 10 + 8 = 18 km/h. 2) 36 : 18 = 2 h. Answer: <b>after 2 hours</b>.') },
      { q: L('3 t 5 q necha kilogramm?', 'Сколько килограммов в 3 т 5 ц?', 'How many kilograms is 3 t 5 q?'), s: L('3 t = 3 000 kg, 5 q = 500 kg. 3 000 + 500 = <b>3 500 kg</b>.', '3 т = 3 000 кг, 5 ц = 500 кг. 3 000 + 500 = <b>3 500 кг</b>.', '3 t = 3 000 kg, 5 q = 500 kg. 3 000 + 500 = <b>3 500 kg</b>.') },
      { q: L('3 ta bir xil yuk mashinasida 240 yashik olma tashildi. 400 yashik uchun nechta shunday mashina kerak?', 'На 3 одинаковых грузовиках перевезли 240 ящиков яблок. Сколько таких грузовиков нужно для 400 ящиков?', '3 identical trucks carried 240 crates of apples. How many such trucks are needed for 400 crates?'), s: L('1) Bitta mashinaga: 240 : 3 = 80 yashik. 2) 400 : 80 = 5 ta mashina. Javob: <b>5 ta</b>. Bu — «birlikka keltirish» usuli: avval bitta narsaning qiymatini topamiz.', '1) В один грузовик: 240 : 3 = 80 ящиков. 2) 400 : 80 = 5 грузовиков. Ответ: <b>5</b>. Это способ «приведения к единице»: сначала находим значение для одного.', '1) One truck holds 240 : 3 = 80 crates. 2) 400 : 80 = 5 trucks. Answer: <b>5</b>. This is the “unit method”: first find the value for one.') }
    ] },
    { kind: 'table', h: L('Tezliklar va massalar jadvali', 'Таблица скоростей и масс', 'A table of speeds and masses'), p: [
      L('Masalalarda tezliklar va massalarni to‘g‘ri tanlash uchun haqiqiy qiymatlarni bilish foydali.', 'Чтобы выбирать в задачах правдоподобные скорости и массы, полезно знать реальные значения.', 'To pick realistic speeds and masses in problems, it helps to know real values.')
    ], table: { head: [L('Ob’ekt', 'Объект', 'Object'), L('Taxminiy tezlik', 'Примерная скорость', 'Approx. speed'), L('Taxminiy massa', 'Примерная масса', 'Approx. mass')], rows: [
      [L('Piyoda odam', 'Пешеход', 'Walking person'), L('5 km/soat', '5 км/ч', '5 km/h'), L('60 kg', '60 кг', '60 kg')],
      [L('Velosipedchi', 'Велосипедист', 'Cyclist'), L('15 km/soat', '15 км/ч', '15 km/h'), L('75 kg', '75 кг', '75 kg')],
      [L('Yengil avtomobil', 'Легковой автомобиль', 'Car'), L('80 km/soat', '80 км/ч', '80 km/h'), L('1 t 5 q', '1 т 5 ц', '1 t 5 q')],
      [L('«Afrosiyob» poyezdi', 'Поезд «Афросиаб»', 'Afrosiyob train'), L('250 km/soat gacha', 'до 250 км/ч', 'up to 250 km/h'), L('yuzlab tonna', 'сотни тонн', 'hundreds of tonnes')],
      [L('Samolyot', 'Самолёт', 'Airliner'), L('850 km/soat', '850 км/ч', '850 km/h'), L('70 t', '70 т', '70 t')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Tezliklarni ayirish.</b> Qarama-qarshi harakatda v₁ − v₂ ni olish xato. Ular bir-biriga qarab yursa, masofa ikkalasining hissasi bilan qisqaradi — tezliklar <b>qo‘shiladi</b>.', '<b>Вычесть скорости.</b> При встречном движении брать v₁ − v₂ — ошибка. Когда они едут навстречу, расстояние сокращается за счёт обоих — скорости <b>складываются</b>.', '<b>Subtracting the speeds.</b> Using v₁ − v₂ for motion towards each other is wrong. When they move towards each other, both shrink the gap — the speeds <b>add</b>.'),
      L('<b>Qavssiz yozish.</b> 60 + 40 · 3 = 180 deb hisoblash. To‘g‘ri: (60 + 40) · 3 = 300.', '<b>Запись без скобок.</b> Посчитать 60 + 40 · 3 = 180. Верно: (60 + 40) · 3 = 300.', '<b>Writing without brackets.</b> Computing 60 + 40 · 3 = 180. Correct: (60 + 40) · 3 = 300.'),
      L('<b>Birliklarni aralashtirish.</b> 2 t + 300 kg = 302 deyish xato. Avval bir xil birlikka keltiring: 2 000 kg + 300 kg = 2 300 kg.', '<b>Смешать единицы.</b> Сказать 2 т + 300 кг = 302 — ошибка. Сначала приведи к одной единице: 2 000 кг + 300 кг = 2 300 кг.', '<b>Mixing units.</b> Saying 2 t + 300 kg = 302 is wrong. Convert to one unit first: 2 000 kg + 300 kg = 2 300 kg.'),
      L('<b>Sentnerni unutish.</b> 4 t 7 q ni 4 007 kg deb yozish xato. 7 q = 700 kg, demak 4 700 kg.', '<b>Забыть про центнер.</b> Записать 4 т 7 ц как 4 007 кг — ошибка. 7 ц = 700 кг, значит 4 700 кг.', '<b>Forgetting the quintal.</b> Writing 4 t 7 q as 4 007 kg is wrong. 7 q = 700 kg, so it is 4 700 kg.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Temir yo‘lda.</b> «Afrosiyob» tezyurar poyezdi Toshkentdan Samarqandgacha taxminan 2 soat 10 daqiqada yetib boradi. Dispetcherlar qarama-qarshi kelayotgan poyezdlarning uchrashish joyini hisoblab, ularni turli yo‘llarga yo‘naltirishadi.', '<b>На железной дороге.</b> Скоростной поезд «Афросиаб» доезжает из Ташкента до Самарканда примерно за 2 часа 10 минут. Диспетчеры рассчитывают место встречи встречных поездов и направляют их на разные пути.', '<b>On the railway.</b> The Afrosiyob high-speed train gets from Tashkent to Samarkand in about 2 hours 10 minutes. Dispatchers calculate where oncoming trains will meet and route them onto different tracks.'),
      L('<b>Qishloq xo‘jaligida.</b> Paxta va bug‘doy hosili sentner va tonnalarda o‘lchanadi. Agar bir gektardan 35 q bug‘doy olinsa, 20 gektardan 35 · 20 = 700 q = 70 t hosil olinadi.', '<b>В сельском хозяйстве.</b> Урожай хлопка и пшеницы измеряют в центнерах и тоннах. Если с гектара собирают 35 ц пшеницы, то с 20 гектаров — 35 · 20 = 700 ц = 70 т.', '<b>In farming.</b> Cotton and wheat harvests are measured in quintals and tonnes. If one hectare gives 35 q of wheat, 20 hectares give 35 · 20 = 700 q = 70 t.'),
      L('<b>Ko‘priklarda.</b> Ko‘prik oldidagi «10 t» belgisi: massasi 10 tonnadan ortiq mashina o‘tmasin. Haydovchi yuk va mashina massasini qo‘shib tekshiradi.', '<b>На мостах.</b> Знак «10 т» перед мостом: машинам тяжелее 10 тонн проезд запрещён. Водитель складывает массу груза и машины и проверяет.', '<b>On bridges.</b> A “10 t” sign before a bridge means vehicles heavier than 10 tonnes may not cross. The driver adds the mass of the load and the truck to check.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Ko‘k kit — Yer yuzidagi eng og‘ir hayvon: uning massasi 150 tonnagacha yetadi. Bu taxminan 100 ta yengil avtomobilga teng!', 'Синий кит — самое тяжёлое животное на Земле: его масса достигает 150 тонн. Это примерно 100 легковых автомобилей!', 'The blue whale is the heaviest animal on Earth: up to 150 tonnes. That is about 100 cars!'),
      L('Yaponiyaning maglev poyezdi sinovlarda soatiga 603 km tezlikka erishgan — bu temir yo‘l rekordi.', 'Японский поезд на магнитной подушке в испытаниях разогнался до 603 км/ч — это рекорд железной дороги.', 'Japan’s maglev train reached 603 km/h in tests — a railway speed record.'),
      L('Afrikalik fil 6 tonnagacha, ya’ni 60 sentnergacha tortadi. Uning bir kunlik ovqati 150 kg atrofida!', 'Африканский слон весит до 6 тонн, то есть до 60 центнеров. Его дневная еда — около 150 кг!', 'An African elephant weighs up to 6 tonnes, that is 60 quintals. It eats around 150 kg of food a day!'),
      L('Yorug‘lik bir soniyada qariyb 300 000 km yo‘l bosadi. Quyoshdan Yergacha yorug‘lik taxminan 8 daqiqa 20 soniyada yetib keladi.', 'Свет за секунду проходит почти 300 000 км. От Солнца до Земли свет доходит примерно за 8 минут 20 секунд.', 'Light travels almost 300 000 km in one second. Light from the Sun reaches Earth in about 8 minutes 20 seconds.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Ikki piyoda 20 km masofadan bir-biriga qarab yurdi: 4 km/soat va 6 km/soat. Ular necha soatda uchrashadi?', 'Два пешехода идут навстречу друг другу с расстояния 20 км: 4 км/ч и 6 км/ч. Через сколько часов встретятся?', 'Two walkers 20 km apart walk towards each other at 4 km/h and 6 km/h. After how many hours will they meet?'),
      L('7 t 3 q 25 kg necha kilogramm?', 'Сколько килограммов в 7 т 3 ц 25 кг?', 'How many kilograms is 7 t 3 q 25 kg?'),
      L('Ikki avtobus 3 soatda uchrashdi. Masofa 330 km, birinchisining tezligi 60 km/soat. Ikkinchisining tezligi qancha?', 'Два автобуса встретились через 3 ч. Расстояние 330 км, скорость первого 60 км/ч. Какова скорость второго?', 'Two buses met after 3 hours. The distance was 330 km and the first went at 60 km/h. What was the second one’s speed?')
    ], after: [
      L('Javoblar: 1) 20 : (4 + 6) = 2 soat; 2) 7 000 + 300 + 25 = 7 325 kg; 3) 330 : 3 = 110, 110 − 60 = 50 km/soat.', 'Ответы: 1) 20 : (4 + 6) = 2 ч; 2) 7 000 + 300 + 25 = 7 325 кг; 3) 330 : 3 = 110, 110 − 60 = 50 км/ч.', 'Answers: 1) 20 : (4 + 6) = 2 h; 2) 7 000 + 300 + 25 = 7 325 kg; 3) 330 : 3 = 110, 110 − 60 = 50 km/h.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Asosiy formula: S = v · t, v = S : t, t = S : v.', 'Главная формула: S = v · t, v = S : t, t = S : v.', 'Main formula: S = v · t, v = S : t, t = S : v.'),
      L('Qarama-qarshi harakatda tezliklar qo‘shiladi: S = (v₁ + v₂) · t.', 'При встречном движении скорости складываются: S = (v₁ + v₂) · t.', 'When moving towards each other the speeds add: S = (v₁ + v₂) · t.'),
      L('Uchrashish vaqti: t = S : (v₁ + v₂).', 'Время встречи: t = S : (v₁ + v₂).', 'Meeting time: t = S : (v₁ + v₂).'),
      L('1 t = 10 q = 1 000 kg; 1 q = 100 kg.', '1 т = 10 ц = 1 000 кг; 1 ц = 100 кг.', '1 t = 10 q = 1 000 kg; 1 q = 100 kg.'),
      L('Katta birlikdan kichikka — ko‘paytiramiz, kichikdan kattaga — bo‘lamiz.', 'От большей единицы к меньшей — умножаем, от меньшей к большей — делим.', 'Larger to smaller unit — multiply; smaller to larger — divide.'),
      L('Murakkab masalani oddiy savollar zanjiriga bo‘ling va javobni tekshiring.', 'Разбивай сложную задачу на цепочку простых вопросов и проверяй ответ.', 'Split a hard problem into a chain of simple questions and check the answer.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t5. Ko‘p xonali sonni ikki xonali songa ko‘paytirish ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Katta ko‘paytirishni bo‘laklarga bo‘lamiz', 'Делим большое умножение на части', 'Breaking a big multiplication into pieces'), p: [
      L('Bir xonali songa ko‘paytirishni yaxshi bilasiz: 324 · 3 = 972. Lekin 324 · 23 ni qanday hisoblaymiz? Ko‘paytirish jadvalida 23 yo‘q! Bu yerda matematikaning eng kuchli fokuslaridan biri yordam beradi: murakkab ishni oddiy bo‘laklarga ajratish.', 'Умножать на однозначное число ты уже умеешь: 324 · 3 = 972. А как посчитать 324 · 23? В таблице умножения нет 23! Здесь поможет один из самых сильных приёмов математики: разбить сложную работу на простые части.', 'You already know how to multiply by a one-digit number: 324 · 3 = 972. But how do we work out 324 · 23? There is no 23 in the times table! One of the most powerful tricks in maths helps here: splitting a hard job into simple pieces.'),
      L('Tasavvur qiling, maktab zalida 23 qator stul bor, har qatorda 324 ta… yo‘q, bu juda katta zal bo‘lardi. Yaxshisi: 23 ta avtobusda 32 nafardan yo‘lovchi. Biz 23 ta avtobusni ikki guruhga bo‘lamiz: 20 ta va 3 ta. 20 ta avtobusda 32 · 20 = 640 kishi, 3 ta avtobusda 32 · 3 = 96 kishi. Jami 640 + 96 = 736. Mana, hech qanday yangi jadval kerak bo‘lmadi!', 'Представь 23 автобуса, в каждом по 32 пассажира. Разделим 23 автобуса на две группы: 20 и 3. В 20 автобусах 32 · 20 = 640 человек, в 3 автобусах 32 · 3 = 96 человек. Всего 640 + 96 = 736. Никакая новая таблица не понадобилась!', 'Imagine 23 buses with 32 passengers each. Split the 23 buses into two groups: 20 and 3. The 20 buses carry 32 · 20 = 640 people, the 3 buses carry 32 · 3 = 96. Total: 640 + 96 = 736. No new table was needed!'),
      L('Bu usulning nomi — ko‘paytirishning <b>taqsimot xossasi</b>. U ustunda ko‘paytirishning asosi bo‘lib xizmat qiladi, shuning uchun uni yaxshilab tushunib olish juda muhim.', 'Этот приём называется <b>распределительным свойством</b> умножения. Он лежит в основе умножения столбиком, поэтому его важно хорошо понять.', 'This trick is called the <b>distributive property</b> of multiplication. It is the basis of column multiplication, so understanding it well is very important.')
    ] },
    { kind: 'def', h: L('Taqsimot xossasi', 'Распределительное свойство', 'The distributive property'), p: [
      L('Sonni yig‘indiga ko‘paytirish uchun uni har bir qo‘shiluvchiga alohida ko‘paytirib, natijalarni qo‘shish mumkin: <b>a · (b + c) = a · b + a · c</b>. Bu xossa «taqsimot» deyiladi, chunki ko‘paytuvchi a qavs ichidagi har bir songa «taqsimlanadi».', 'Чтобы умножить число на сумму, можно умножить его на каждое слагаемое отдельно и сложить результаты: <b>a · (b + c) = a · b + a · c</b>. Свойство называется «распределительным», потому что множитель a «распределяется» на каждое число в скобках.', 'To multiply a number by a sum, you can multiply it by each addend separately and add the results: <b>a · (b + c) = a · b + a · c</b>. It is called “distributive” because the factor a is “distributed” to every number in the brackets.'),
      L('Ikki xonali son har doim o‘nliklar va birliklar yig‘indisi: 23 = 20 + 3, 47 = 40 + 7, 58 = 50 + 8. Shuning uchun: 324 · 23 = 324 · (20 + 3) = 324 · 20 + 324 · 3.', 'Двузначное число всегда — сумма десятков и единиц: 23 = 20 + 3, 47 = 40 + 7, 58 = 50 + 8. Поэтому: 324 · 23 = 324 · (20 + 3) = 324 · 20 + 324 · 3.', 'A two-digit number is always a sum of tens and ones: 23 = 20 + 3, 47 = 40 + 7, 58 = 50 + 8. So: 324 · 23 = 324 · (20 + 3) = 324 · 20 + 324 · 3.'),
      L('Xossa ayirish uchun ham ishlaydi: a · (b − c) = a · b − a · c. Masalan, 25 · 19 = 25 · (20 − 1) = 500 − 25 = 475. Bu og‘zaki hisob uchun juda qulay.', 'Свойство работает и для вычитания: a · (b − c) = a · b − a · c. Например, 25 · 19 = 25 · (20 − 1) = 500 − 25 = 475. Это очень удобно для устного счёта.', 'It works for subtraction too: a · (b − c) = a · b − a · c. For example, 25 · 19 = 25 · (20 − 1) = 500 − 25 = 475. This is very handy for mental maths.')
    ] },
    { kind: 'history', h: L('Qadimgi ko‘paytirish usullari', 'Древние способы умножения', 'Ancient ways of multiplying'), p: [
      L('Qadimgi Misrda, bundan 3 500 yil oldin, ko‘paytirish <b>ikkilantirish</b> bilan bajarilgan. 13 · 24 ni hisoblash uchun misrliklar 24 ni ketma-ket ikkilantirishgan: 24, 48, 96, 192 (bu 1, 2, 4, 8 marta). 13 = 8 + 4 + 1, shuning uchun 192 + 96 + 24 = 312. Bu ham aslida taqsimot xossasi!', 'В Древнем Египте, 3 500 лет назад, умножали <b>удвоением</b>. Чтобы найти 13 · 24, египтяне удваивали 24: 24, 48, 96, 192 (это 1, 2, 4, 8 раз). 13 = 8 + 4 + 1, поэтому 192 + 96 + 24 = 312. Это тоже распределительное свойство!', 'In Ancient Egypt, 3 500 years ago, people multiplied by <b>doubling</b>. To find 13 · 24, Egyptians doubled 24 again and again: 24, 48, 96, 192 (that is 1, 2, 4 and 8 times). Since 13 = 8 + 4 + 1, the answer is 192 + 96 + 24 = 312. That is the distributive property too!'),
      L('Bu usul «Rind papirusi»da yozib qoldirilgan — bu qadimgi misrlik kotib Ahmes ko‘chirgan, dunyodagi eng qadimgi matematik qo‘llanmalardan biri. Hozir u Londondagi Britaniya muzeyida saqlanadi.', 'Этот способ записан в «папирусе Ринда» — одном из древнейших математических пособий в мире, переписанном египетским писцом Ахмесом. Сейчас он хранится в Британском музее в Лондоне.', 'This method is recorded in the Rhind Papyrus — one of the oldest maths handbooks in the world, copied by the Egyptian scribe Ahmes. Today it is kept in the British Museum in London.'),
      L('Xorazmiy esa hind usulini tushuntirgan: sonni xonalarga ajratib, har bir xonani alohida ko‘paytirish. Aynan shu g‘oya bugungi ustunda ko‘paytirishga aylangan. Taqsimot xossasi ming yillar davomida turli xalqlar tomonidan qayta-qayta kashf qilingan.', 'А аль-Хорезми объяснил индийский способ: разложить число на разряды и умножать каждый разряд отдельно. Именно эта идея превратилась в сегодняшнее умножение столбиком. Распределительное свойство тысячелетиями открывали снова и снова разные народы.', 'Al-Khwarizmi explained the Indian way: split a number into places and multiply each place separately. This very idea became today’s column multiplication. The distributive property has been rediscovered again and again by different peoples over thousands of years.')
    ] },
    { kind: 'rule', h: L('Qoida: ikki xonali songa ko‘paytirish', 'Правило: умножение на двузначное число', 'Rule: multiplying by a two-digit number'), list: [
      L('Ikki xonali ko‘paytuvchini o‘nliklar va birliklarga ajrating: 23 = 20 + 3.', 'Разложи двузначный множитель на десятки и единицы: 23 = 20 + 3.', 'Split the two-digit factor into tens and ones: 23 = 20 + 3.'),
      L('Birinchi sonni o‘nliklarga ko‘paytiring. Yaxlit o‘nlikka ko‘paytirish oson: 324 · 20 = 324 · 2 · 10 = 648 · 10 = 6 480 (oxiriga nol qo‘shiladi).', 'Умножь первое число на десятки. На круглые десятки умножать легко: 324 · 20 = 324 · 2 · 10 = 648 · 10 = 6 480 (на конце дописываем нуль).', 'Multiply the first number by the tens. Multiplying by whole tens is easy: 324 · 20 = 324 · 2 · 10 = 648 · 10 = 6 480 (add a zero at the end).'),
      L('Birinchi sonni birliklarga ko‘paytiring: 324 · 3 = 972.', 'Умножь первое число на единицы: 324 · 3 = 972.', 'Multiply the first number by the ones: 324 · 3 = 972.'),
      L('Ikki natijani qo‘shing: 6 480 + 972 = <b>7 452</b>.', 'Сложи два результата: 6 480 + 972 = <b>7 452</b>.', 'Add the two results: 6 480 + 972 = <b>7 452</b>.')
    ], after: [
      L('Nega 324 · 20 = 6 480? Chunki 20 = 2 · 10. Avval 2 ga, keyin 10 ga ko‘paytiramiz. 10 ga ko‘paytirish esa sonning oxiriga bitta nol yozish demak: har bir raqam bir xona chapga suriladi.', 'Почему 324 · 20 = 6 480? Потому что 20 = 2 · 10. Сначала умножаем на 2, потом на 10. А умножить на 10 — значит дописать в конце один нуль: каждая цифра сдвигается на разряд влево.', 'Why is 324 · 20 = 6 480? Because 20 = 2 · 10. First multiply by 2, then by 10. Multiplying by 10 means writing one zero at the end: every digit moves one place to the left.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 156 · 47', 'Пошагово: 156 · 47', 'Step by step: 156 · 47'), list: [
      L('<b>Ajratamiz:</b> 47 = 40 + 7. Demak, 156 · 47 = 156 · 40 + 156 · 7.', '<b>Раскладываем:</b> 47 = 40 + 7. Значит, 156 · 47 = 156 · 40 + 156 · 7.', '<b>Split:</b> 47 = 40 + 7. So 156 · 47 = 156 · 40 + 156 · 7.'),
      L('<b>O‘nliklarga:</b> 156 · 4 = 624 (6 · 4 = 24, 5 · 4 + 2 = 22, 1 · 4 + 2 = 6). Oxiriga nol: 156 · 40 = 6 240.', '<b>На десятки:</b> 156 · 4 = 624 (6 · 4 = 24, 5 · 4 + 2 = 22, 1 · 4 + 2 = 6). Дописываем нуль: 156 · 40 = 6 240.', '<b>By the tens:</b> 156 · 4 = 624 (6 · 4 = 24, 5 · 4 + 2 = 22, 1 · 4 + 2 = 6). Add a zero: 156 · 40 = 6 240.'),
      L('<b>Birliklarga:</b> 156 · 7 = 1 092 (6 · 7 = 42, 5 · 7 + 4 = 39, 1 · 7 + 3 = 10).', '<b>На единицы:</b> 156 · 7 = 1 092 (6 · 7 = 42, 5 · 7 + 4 = 39, 1 · 7 + 3 = 10).', '<b>By the ones:</b> 156 · 7 = 1 092 (6 · 7 = 42, 5 · 7 + 4 = 39, 1 · 7 + 3 = 10).'),
      L('<b>Qo‘shamiz:</b> 6 240 + 1 092 = 7 332. Javob: <b>7 332</b>.', '<b>Складываем:</b> 6 240 + 1 092 = 7 332. Ответ: <b>7 332</b>.', '<b>Add:</b> 6 240 + 1 092 = 7 332. Answer: <b>7 332</b>.'),
      L('<b>Baholaymiz:</b> 156 ≈ 150, 47 ≈ 50, 150 · 50 = 7 500. Javobimiz unga yaqin — demak, mantiqiy.', '<b>Оцениваем:</b> 156 ≈ 150, 47 ≈ 50, 150 · 50 = 7 500. Наш ответ близок — значит, разумен.', '<b>Estimate:</b> 156 ≈ 150, 47 ≈ 50, 150 · 50 = 7 500. Our answer is close — so it makes sense.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '25 · 12', s: L('12 = 10 + 2. 25 · 10 = 250, 25 · 2 = 50. 250 + 50 = <b>300</b>.', '12 = 10 + 2. 25 · 10 = 250, 25 · 2 = 50. 250 + 50 = <b>300</b>.', '12 = 10 + 2. 25 · 10 = 250, 25 · 2 = 50. 250 + 50 = <b>300</b>.') },
      { q: '213 · 34', s: L('34 = 30 + 4. 213 · 30 = 6 390, 213 · 4 = 852. 6 390 + 852 = <b>7 242</b>.', '34 = 30 + 4. 213 · 30 = 6 390, 213 · 4 = 852. 6 390 + 852 = <b>7 242</b>.', '34 = 30 + 4. 213 · 30 = 6 390, 213 · 4 = 852. 6 390 + 852 = <b>7 242</b>.') },
      { q: L('48 · 99 ni og‘zaki hisoblang.', 'Вычисли устно 48 · 99.', 'Work out 48 · 99 mentally.'), s: L('99 = 100 − 1. 48 · 100 = 4 800, 48 · 1 = 48. 4 800 − 48 = <b>4 752</b>. Ayirish bilan taqsimot xossasi hisobni ancha tezlashtirdi.', '99 = 100 − 1. 48 · 100 = 4 800, 48 · 1 = 48. 4 800 − 48 = <b>4 752</b>. Распределительное свойство с вычитанием сильно ускорило счёт.', '99 = 100 − 1. 48 · 100 = 4 800, 48 · 1 = 48. 4 800 − 48 = <b>4 752</b>. The distributive property with subtraction made it much faster.') },
      { q: L('Kinoteatrda 18 qator, har qatorda 26 ta o‘rin. Jami nechta o‘rin?', 'В кинотеатре 18 рядов по 26 мест. Сколько всего мест?', 'A cinema has 18 rows of 26 seats. How many seats in all?'), s: L('26 · 18 = 26 · 10 + 26 · 8 = 260 + 208 = 468. Javob: <b>468 ta o‘rin</b>.', '26 · 18 = 26 · 10 + 26 · 8 = 260 + 208 = 468. Ответ: <b>468 мест</b>.', '26 · 18 = 26 · 10 + 26 · 8 = 260 + 208 = 468. Answer: <b>468 seats</b>.') }
    ] },
    { kind: 'table', h: L('Yaxlit o‘nliklarga ko‘paytirish', 'Умножение на круглые десятки', 'Multiplying by whole tens'), p: [
      L('Yaxlit o‘nlikka ko‘paytirishda: avval o‘nliklar soniga ko‘paytiring, so‘ng oxiriga bitta nol qo‘shing.', 'При умножении на круглые десятки: сначала умножь на число десятков, затем допиши нуль.', 'To multiply by whole tens: first multiply by the number of tens, then add one zero.')
    ], table: { head: [L('Misol', 'Пример', 'Example'), L('Avval', 'Сначала', 'First'), L('Nol qo‘shamiz', 'Дописываем нуль', 'Add a zero')], rows: [
      ['324 · 20', '324 · 2 = 648', '6 480'],
      ['156 · 40', '156 · 4 = 624', '6 240'],
      ['213 · 30', '213 · 3 = 639', '6 390'],
      ['125 · 80', '125 · 8 = 1 000', '10 000'],
      ['47 · 60', '47 · 6 = 282', '2 820']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Faqat birinchi qismni ko‘paytirish.</b> 324 · 23 = 324 · 20 + 3 deb yozish. Ikkinchi qo‘shiluvchi ham ko‘paytirilishi kerak: 324 · 20 + 324 · 3.', '<b>Умножить только первую часть.</b> Записать 324 · 23 = 324 · 20 + 3. Второе слагаемое тоже нужно умножить: 324 · 20 + 324 · 3.', '<b>Multiplying only the first part.</b> Writing 324 · 23 = 324 · 20 + 3. The second addend must be multiplied too: 324 · 20 + 324 · 3.'),
      L('<b>Nolni unutish.</b> 324 · 20 ni 648 deb qoldirish. 2 ga emas, 20 ga ko‘paytirdik — natija 10 marta katta: 6 480.', '<b>Забыть нуль.</b> Оставить 324 · 20 = 648. Мы умножали не на 2, а на 20 — результат в 10 раз больше: 6 480.', '<b>Forgetting the zero.</b> Leaving 324 · 20 as 648. We multiplied by 20, not 2 — the result is ten times bigger: 6 480.'),
      L('<b>Raqamlarni noto‘g‘ri ajratish.</b> 47 ni 4 + 7 deb ajratish. 4 raqami o‘nliklar xonasida, demak u 40: 47 = 40 + 7.', '<b>Неверно разложить.</b> Разложить 47 как 4 + 7. Цифра 4 стоит в разряде десятков, значит, это 40: 47 = 40 + 7.', '<b>Splitting wrongly.</b> Splitting 47 as 4 + 7. The 4 is in the tens place, so it is 40: 47 = 40 + 7.'),
      L('<b>Baholamaslik.</b> 156 · 47 ga 73 320 javob chiqsa — bu 10 marta ko‘p. Taxminiy hisob (150 · 50 = 7 500) bunday xatoni darhol ko‘rsatadi.', '<b>Не оценивать.</b> Если для 156 · 47 вышло 73 320 — это в 10 раз больше. Прикидка (150 · 50 = 7 500) сразу покажет ошибку.', '<b>Not estimating.</b> If 156 · 47 gives 73 320, that is ten times too big. An estimate (150 · 50 = 7 500) reveals the mistake at once.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Maktab oshxonasi.</b> Har kuni 235 nafar o‘quvchi tushlik qiladi. 24 o‘quv kunida nechta tushlik tayyorlanadi? 235 · 24 = 235 · 20 + 235 · 4 = 4 700 + 940 = 5 640 ta. Oshpaz mahsulotlarni aynan shu hisob bilan buyurtma qiladi.', '<b>Школьная столовая.</b> Каждый день обедают 235 учеников. Сколько обедов готовят за 24 учебных дня? 235 · 24 = 235 · 20 + 235 · 4 = 4 700 + 940 = 5 640. Повар заказывает продукты именно по такому расчёту.', '<b>The school canteen.</b> 235 pupils have lunch every day. How many lunches over 24 school days? 235 · 24 = 235 · 20 + 235 · 4 = 4 700 + 940 = 5 640. The cook orders food using exactly this calculation.'),
      L('<b>Oylik to‘lov.</b> Internet uchun oyiga 85 000 so‘m to‘lanadi. Bir yilda (12 oy): 85 000 · 12 = 85 000 · 10 + 85 000 · 2 = 850 000 + 170 000 = 1 020 000 so‘m.', '<b>Ежемесячная плата.</b> За интернет платят 85 000 сум в месяц. За год (12 месяцев): 85 000 · 12 = 850 000 + 170 000 = 1 020 000 сум.', '<b>Monthly bills.</b> Internet costs 85 000 sum a month. For a year (12 months): 85 000 · 12 = 850 000 + 170 000 = 1 020 000 sum.'),
      L('<b>Sport.</b> Yugurish yo‘lakchasining bir aylanasi 400 m. 15 aylana: 400 · 15 = 400 · 10 + 400 · 5 = 4 000 + 2 000 = 6 000 m = 6 km.', '<b>Спорт.</b> Один круг беговой дорожки — 400 м. 15 кругов: 400 · 15 = 4 000 + 2 000 = 6 000 м = 6 км.', '<b>Sport.</b> One lap of a running track is 400 m. 15 laps: 400 · 15 = 4 000 + 2 000 = 6 000 m = 6 km.')
    ] },
    { kind: 'fact', h: L('Qiziqarli fokuslar', 'Интересные фокусы', 'Fun tricks'), list: [
      L('<b>11 ga ko‘paytirish:</b> ikki xonali sonning raqamlari orasiga ularning yig‘indisini yozing. 36 · 11: 3, (3 + 6 = 9), 6 → 396. Bu taqsimot xossasidan kelib chiqadi: 36 · 11 = 360 + 36.', '<b>Умножение на 11:</b> между цифрами двузначного числа впиши их сумму. 36 · 11: 3, (3 + 6 = 9), 6 → 396. Это следует из распределительного свойства: 36 · 11 = 360 + 36.', '<b>Multiplying by 11:</b> write the sum of the two digits between them. 36 · 11: 3, (3 + 6 = 9), 6 → 396. It follows from the distributive property: 36 · 11 = 360 + 36.'),
      L('<b>25 ga ko‘paytirish:</b> 25 = 100 : 4. Shuning uchun 36 · 25 = 3 600 : 4 = 900.', '<b>Умножение на 25:</b> 25 = 100 : 4. Поэтому 36 · 25 = 3 600 : 4 = 900.', '<b>Multiplying by 25:</b> 25 = 100 : 4. So 36 · 25 = 3 600 : 4 = 900.'),
      L('<b>«Rus dehqoni» usuli:</b> bir sonni ikkiga bo‘lib, ikkinchisini ikkilantirib borasiz; birinchi son toq bo‘lgan qatorlardagi ikkinchi sonlarni qo‘shasiz. Bu Misr usuliga juda o‘xshaydi.', '<b>«Русский крестьянский» способ:</b> одно число делим пополам, другое удваиваем; складываем числа второго столбца в строках, где первое число нечётное. Он очень похож на египетский.', '<b>The “Russian peasant” method:</b> halve one number and double the other repeatedly; add the second numbers in the rows where the first is odd. It is very similar to the Egyptian method.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 125 · 16 (16 = 10 + 6).', 'Вычисли: 125 · 16 (16 = 10 + 6).', 'Work out: 125 · 16 (16 = 10 + 6).'),
      L('Og‘zaki: 34 · 11 va 52 · 11.', 'Устно: 34 · 11 и 52 · 11.', 'Mentally: 34 · 11 and 52 · 11.'),
      L('Bir qutida 144 ta qalam bor. 35 ta qutida nechta qalam?', 'В коробке 144 карандаша. Сколько карандашей в 35 коробках?', 'A box holds 144 pencils. How many pencils are in 35 boxes?')
    ], after: [
      L('Javoblar: 1) 1 250 + 750 = 2 000; 2) 374 va 572; 3) 144 · 30 + 144 · 5 = 4 320 + 720 = 5 040 ta.', 'Ответы: 1) 1 250 + 750 = 2 000; 2) 374 и 572; 3) 144 · 30 + 144 · 5 = 4 320 + 720 = 5 040 карандашей.', 'Answers: 1) 1 250 + 750 = 2 000; 2) 374 and 572; 3) 144 · 30 + 144 · 5 = 4 320 + 720 = 5 040 pencils.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Taqsimot xossasi: a · (b + c) = a · b + a · c.', 'Распределительное свойство: a · (b + c) = a · b + a · c.', 'Distributive property: a · (b + c) = a · b + a · c.'),
      L('Ikki xonali sonni o‘nliklar va birliklarga ajratamiz: 23 = 20 + 3.', 'Двузначное число раскладываем на десятки и единицы: 23 = 20 + 3.', 'Split a two-digit number into tens and ones: 23 = 20 + 3.'),
      L('Yaxlit o‘nlikka ko‘paytirishda o‘nliklar soniga ko‘paytirib, oxiriga nol qo‘shamiz.', 'При умножении на круглые десятки умножаем на число десятков и дописываем нуль.', 'For whole tens, multiply by the number of tens and add a zero.'),
      L('Ikki qismning natijalarini qo‘shamiz: 324 · 23 = 6 480 + 972 = 7 452.', 'Складываем результаты двух частей: 324 · 23 = 6 480 + 972 = 7 452.', 'Add the two partial results: 324 · 23 = 6 480 + 972 = 7 452.'),
      L('Xossa ayirish uchun ham ishlaydi: 48 · 99 = 4 800 − 48.', 'Свойство работает и с вычитанием: 48 · 99 = 4 800 − 48.', 'It works with subtraction too: 48 · 99 = 4 800 − 48.'),
      L('Javobni har doim taxminiy hisob bilan baholang.', 'Всегда оценивай ответ прикидкой.', 'Always estimate the answer.')
    ] }
  ] });

  // ---------- t6. Ikki xonali songa ko‘paytirish algoritmi ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Ustunda ko‘paytirish — qisqa va ishonchli yo‘l', 'Умножение столбиком — короткий и надёжный путь', 'Column multiplication: a short, reliable route'), p: [
      L('O‘tgan mavzuda 324 · 23 ni bo‘laklarga ajratib hisobladik: 324 · 20 + 324 · 3. Bu usul to‘g‘ri, lekin uzun yozuv talab qiladi. Endi xuddi shu g‘oyani ixcham shaklda — <b>ustunda</b> yozishni o‘rganamiz. Ustunda ko‘paytirish — dunyodagi millionlab o‘quvchilar, buxgalterlar va muhandislar ishlatadigan algoritm.', 'В прошлой теме мы считали 324 · 23 по частям: 324 · 20 + 324 · 3. Способ верный, но требует длинной записи. Теперь научимся записывать ту же идею компактно — <b>столбиком</b>. Умножение столбиком — алгоритм, которым пользуются миллионы школьников, бухгалтеров и инженеров.', 'In the last topic we worked out 324 · 23 in pieces: 324 · 20 + 324 · 3. That is correct but takes a long record. Now we learn to write the same idea compactly — <b>in a column</b>. Column multiplication is an algorithm used by millions of pupils, accountants and engineers.'),
      L('Algoritm — bu aniq qadamlar ketma-ketligi. Agar har bir qadamni to‘g‘ri bajarsangiz, javob albatta to‘g‘ri chiqadi. Kompyuterlar ham ko‘paytirishni aynan shunday qadamlar bilan bajaradi, faqat juda tez.', 'Алгоритм — точная последовательность шагов. Если правильно выполнить каждый шаг, ответ обязательно будет верным. Компьютеры тоже умножают такими шагами, только очень быстро.', 'An algorithm is an exact sequence of steps. If you do each step correctly, the answer will certainly be right. Computers also multiply with such steps, only very fast.'),
      L('Bu mavzuda ikkita yangi atama paydo bo‘ladi: <b>to‘liqsiz ko‘paytma</b> va <b>surib yozish</b>. Ularni tushunsangiz, har qanday katta sonni ko‘paytira olasiz.', 'В этой теме появятся два новых понятия: <b>неполное произведение</b> и <b>запись со сдвигом</b>. Поймёшь их — сможешь умножить любые большие числа.', 'Two new ideas appear in this topic: the <b>partial product</b> and <b>writing with a shift</b>. Understand them and you can multiply any big numbers.')
    ] },
    { kind: 'def', h: L('To‘liqsiz ko‘paytmalar', 'Неполные произведения', 'Partial products'), p: [
      L('Ko‘paytirishda: <b>ko‘paytuvchi · ko‘paytuvchi = ko‘paytma</b>. 324 · 23 da 324 va 23 — ko‘paytuvchilar. Ustunda kattaroq sonni tepaga, kichigini pastga yozamiz, birliklar ostida birliklar.', 'При умножении: <b>множитель · множитель = произведение</b>. В 324 · 23 числа 324 и 23 — множители. В столбике большее число пишем сверху, меньшее снизу, единицы под единицами.', 'In multiplication: <b>factor · factor = product</b>. In 324 · 23, 324 and 23 are the factors. In a column we write the larger number on top and the smaller below, ones under ones.'),
      L('<b>Birinchi to‘liqsiz ko‘paytma</b> — yuqoridagi sonni pastki sonning birliklariga ko‘paytirish natijasi: 324 · 3 = 972. <b>Ikkinchi to‘liqsiz ko‘paytma</b> — o‘nliklariga ko‘paytirish natijasi: 324 · 2 = 648, lekin bu aslida 648 o‘nlik, ya’ni 6 480.', '<b>Первое неполное произведение</b> — результат умножения верхнего числа на единицы нижнего: 324 · 3 = 972. <b>Второе неполное произведение</b> — на десятки: 324 · 2 = 648, но на самом деле это 648 десятков, то есть 6 480.', 'The <b>first partial product</b> is the top number times the ones of the bottom number: 324 · 3 = 972. The <b>second partial product</b> is times the tens: 324 · 2 = 648, but this is really 648 tens, i.e. 6 480.'),
      L('Shuning uchun ikkinchi to‘liqsiz ko‘paytmani <b>bir xona chapga surib</b> yozamiz: uning oxirgi raqami o‘nliklar ostiga tushadi. Nolni yozmasa ham bo‘ladi — bo‘sh joy uning o‘rnini bosadi.', 'Поэтому второе неполное произведение записываем <b>со сдвигом на один разряд влево</b>: его последняя цифра встаёт под десятками. Нуль можно не писать — его заменяет пустое место.', 'That is why we write the second partial product <b>shifted one place to the left</b>: its last digit goes under the tens. You may leave out the zero — the empty space stands in for it.')
    ] },
    { kind: 'history', h: L('Samarqand va hisob san’ati', 'Самарканд и искусство счёта', 'Samarkand and the art of calculation'), p: [
      L('XV asrda Samarqandda <b>Mirzo Ulug‘bek</b> rasadxona va madrasa qurdirdi. U yerda o‘sha davrning eng kuchli hisobchi olimlari ishlagan. Ulardan biri — <b>G‘iyosiddin Jamshid al-Koshiy</b>. U 1427-yilda «Arifmetika kaliti» nomli katta kitob yozgan.', 'В XV веке в Самарканде <b>Мирзо Улугбек</b> построил обсерваторию и медресе. Там работали сильнейшие вычислители того времени. Один из них — <b>Гиясиддин Джамшид аль-Каши</b>. В 1427 году он написал большую книгу «Ключ арифметики».', 'In the 15th century <b>Mirzo Ulugh Beg</b> built an observatory and a madrasa in Samarkand. The strongest calculators of the time worked there. One of them was <b>Ghiyath al-Din Jamshid al-Kashi</b>. In 1427 he wrote a large book, “The Key to Arithmetic”.'),
      L('Al-Koshiy kitobida katta sonlarni ko‘paytirishning bir necha usulini tasvirlagan, jumladan «to‘r» usulini: sonlar katakli jadvalga yoziladi, har bir katakka raqamlar ko‘paytmasi qo‘yiladi va diagonallar bo‘yicha qo‘shiladi. Bu usul keyinchalik Yevropada ham mashhur bo‘lgan.', 'В книге аль-Каши описал несколько способов умножения больших чисел, в том числе способ «сетки»: числа записывают в клетчатую таблицу, в каждую клетку ставят произведение цифр, а потом складывают по диагоналям. Позже этот способ стал известен и в Европе.', 'In his book al-Kashi described several ways to multiply big numbers, including the “lattice” method: the numbers are written around a grid, each cell gets the product of two digits, and the results are added along the diagonals. This method later became popular in Europe too.'),
      L('Al-Koshiy π sonini 16 ta aniq o‘nli raqamgacha hisoblagan — bu rekordni 170 yildan ortiq vaqt hech kim buza olmagan! Bunday hisoblar uchun minglab ko‘paytirishni xatosiz bajarish kerak edi.', 'Аль-Каши вычислил число π с 16 верными десятичными знаками — этот рекорд никто не мог побить более 170 лет! Для таких расчётов нужно было безошибочно выполнить тысячи умножений.', 'Al-Kashi computed the number π to 16 correct decimal places — a record nobody beat for more than 170 years! Such work required thousands of multiplications without a single slip.')
    ] },
    { kind: 'rule', h: L('Algoritm', 'Алгоритм', 'The algorithm'), list: [
      L('<b>1.</b> Sonlarni ustunga yozing: birliklar ostida birliklar, o‘nliklar ostida o‘nliklar.', '<b>1.</b> Запиши числа столбиком: единицы под единицами, десятки под десятками.', '<b>1.</b> Write the numbers in a column: ones under ones, tens under tens.'),
      L('<b>2.</b> Yuqori sonni pastki sonning <b>birliklariga</b> ko‘paytiring — 1-to‘liqsiz ko‘paytma. Uni chiziq ostiga, o‘ng chetidan boshlab yozing.', '<b>2.</b> Умножь верхнее число на <b>единицы</b> нижнего — 1-е неполное произведение. Запиши его под чертой, начиная с правого края.', '<b>2.</b> Multiply the top number by the <b>ones</b> of the bottom one — the 1st partial product. Write it under the line, starting at the right edge.'),
      L('<b>3.</b> Yuqori sonni pastki sonning <b>o‘nliklariga</b> ko‘paytiring — 2-to‘liqsiz ko‘paytma. Uni bir xona chapga surib, o‘nliklar ostidan boshlab yozing.', '<b>3.</b> Умножь верхнее число на <b>десятки</b> нижнего — 2-е неполное произведение. Запиши его со сдвигом на разряд влево, начиная под десятками.', '<b>3.</b> Multiply the top number by the <b>tens</b> of the bottom one — the 2nd partial product. Write it shifted one place left, starting under the tens.'),
      L('<b>4.</b> To‘liqsiz ko‘paytmalarni qo‘shing. Yig‘indi — javob.', '<b>4.</b> Сложи неполные произведения. Сумма — ответ.', '<b>4.</b> Add the partial products. The sum is the answer.')
    ], after: [
      L('Har bir ko‘paytirishda o‘tkazilgan raqamni yodda tuting yoki tepaga kichik qilib yozing, lekin har yangi to‘liqsiz ko‘paytmadan oldin eskilarini o‘chiring — aks holda ular aralashib ketadi.', 'При каждом умножении держи перенос в уме или пиши его маленькой цифрой сверху, но перед новым неполным произведением стирай старые переносы — иначе они перепутаются.', 'Keep each carry in your head or write it small on top, but clear the old carries before each new partial product — otherwise they get mixed up.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 437 · 56', 'Пошагово: 437 · 56', 'Step by step: 437 · 56'), list: [
      L('<b>Yozamiz:</b> 437 tepada, 56 pastda: 6 raqami 7 ostida, 5 raqami 3 ostida.', '<b>Записываем:</b> 437 сверху, 56 снизу: 6 под 7, 5 под 3.', '<b>Write:</b> 437 on top, 56 below: 6 under 7, 5 under 3.'),
      L('<b>1-to‘liqsiz ko‘paytma (· 6):</b> 7 · 6 = 42 — 2 yozamiz, 4 xotirada. 3 · 6 = 18, + 4 = 22 — 2 yozamiz, 2 xotirada. 4 · 6 = 24, + 2 = 26. Natija: <b>2 622</b>.', '<b>1-е неполное произведение (· 6):</b> 7 · 6 = 42 — пишем 2, 4 в уме. 3 · 6 = 18, + 4 = 22 — пишем 2, 2 в уме. 4 · 6 = 24, + 2 = 26. Итог: <b>2 622</b>.', '<b>1st partial product (· 6):</b> 7 · 6 = 42 — write 2, carry 4. 3 · 6 = 18, + 4 = 22 — write 2, carry 2. 4 · 6 = 24, + 2 = 26. Result: <b>2 622</b>.'),
      L('<b>2-to‘liqsiz ko‘paytma (· 5 o‘nlik):</b> 7 · 5 = 35 — 5 ni o‘nliklar ostiga yozamiz, 3 xotirada. 3 · 5 = 15, + 3 = 18 — 8 yozamiz, 1 xotirada. 4 · 5 = 20, + 1 = 21. Natija: <b>2 185</b> (surilgan, ya’ni 21 850).', '<b>2-е неполное произведение (· 5 десятков):</b> 7 · 5 = 35 — 5 пишем под десятками, 3 в уме. 3 · 5 = 15, + 3 = 18 — пишем 8, 1 в уме. 4 · 5 = 20, + 1 = 21. Итог: <b>2 185</b> (со сдвигом, то есть 21 850).', '<b>2nd partial product (· 5 tens):</b> 7 · 5 = 35 — write 5 under the tens, carry 3. 3 · 5 = 15, + 3 = 18 — write 8, carry 1. 4 · 5 = 20, + 1 = 21. Result: <b>2 185</b> (shifted, i.e. 21 850).'),
      L('<b>Qo‘shamiz:</b> 2 622 + 21 850 = <b>24 472</b>.', '<b>Складываем:</b> 2 622 + 21 850 = <b>24 472</b>.', '<b>Add:</b> 2 622 + 21 850 = <b>24 472</b>.'),
      L('<b>Baholaymiz:</b> 400 · 60 = 24 000 — javob yaqin, demak to‘g‘ri yo‘ldamiz.', '<b>Оцениваем:</b> 400 · 60 = 24 000 — ответ близок, значит, всё верно.', '<b>Estimate:</b> 400 · 60 = 24 000 — close, so we are on track.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '45 · 12', s: L('1) 45 · 2 = 90. 2) 45 · 1 = 45 (surib — 450). 90 + 450 = <b>540</b>.', '1) 45 · 2 = 90. 2) 45 · 1 = 45 (со сдвигом — 450). 90 + 450 = <b>540</b>.', '1) 45 · 2 = 90. 2) 45 · 1 = 45 (shifted — 450). 90 + 450 = <b>540</b>.') },
      { q: '123 · 11', s: L('1) 123 · 1 = 123. 2) 123 · 1 = 123 (surib — 1 230). 123 + 1 230 = <b>1 353</b>.', '1) 123 · 1 = 123. 2) 123 · 1 = 123 (со сдвигом — 1 230). 123 + 1 230 = <b>1 353</b>.', '1) 123 · 1 = 123. 2) 123 · 1 = 123 (shifted — 1 230). 123 + 1 230 = <b>1 353</b>.') },
      { q: '2 708 · 34', s: L('1) 2 708 · 4 = 10 832. 2) 2 708 · 3 = 8 124 (surib — 81 240). 10 832 + 81 240 = <b>92 072</b>. Taxmin: 2 700 · 30 ≈ 81 000 dan biroz ko‘p — to‘g‘ri.', '1) 2 708 · 4 = 10 832. 2) 2 708 · 3 = 8 124 (со сдвигом — 81 240). 10 832 + 81 240 = <b>92 072</b>. Прикидка: чуть больше 2 700 · 30 ≈ 81 000 — верно.', '1) 2 708 · 4 = 10 832. 2) 2 708 · 3 = 8 124 (shifted — 81 240). 10 832 + 81 240 = <b>92 072</b>. Estimate: a bit more than 2 700 · 30 ≈ 81 000 — fine.') },
      { q: L('Oromgohga 14 ta avtobus keldi, har birida 42 nafardan bola. Jami nechta bola?', 'В лагерь приехали 14 автобусов, в каждом по 42 ребёнка. Сколько всего детей?', '14 buses came to the camp with 42 children each. How many children in all?'), s: L('42 · 14: 1) 42 · 4 = 168. 2) 42 · 1 = 42 (surib — 420). 168 + 420 = <b>588 nafar</b>.', '42 · 14: 1) 42 · 4 = 168. 2) 42 · 1 = 42 (со сдвигом — 420). 168 + 420 = <b>588 детей</b>.', '42 · 14: 1) 42 · 4 = 168. 2) 42 · 1 = 42 (shifted — 420). 168 + 420 = <b>588 children</b>.') }
    ] },
    { kind: 'table', h: L('Ustun yozuvi qanday ko‘rinadi', 'Как выглядит запись столбиком', 'What the column record looks like'), p: [
      L('437 · 56 ning ustundagi yozuvi. Har bir qator — algoritmning bir qadami. Nuqta (·) — surilgan bo‘sh joy.', 'Запись 437 · 56 столбиком. Каждая строка — один шаг алгоритма. Точка (·) — пустое место сдвига.', 'The column record of 437 · 56. Each row is one step. A dot (·) marks the empty shifted place.')
    ], table: { head: [L('Qator', 'Строка', 'Row'), L('Yozuv', 'Запись', 'Record'), L('Ma’nosi', 'Смысл', 'Meaning')], rows: [
      [L('1-ko‘paytuvchi', '1-й множитель', '1st factor'), '437', '437'],
      [L('2-ko‘paytuvchi', '2-й множитель', '2nd factor'), '× 56', '50 + 6'],
      [L('1-to‘liqsiz', '1-е неполное', '1st partial'), '2 622', '437 · 6'],
      [L('2-to‘liqsiz', '2-е неполное', '2nd partial'), '2 185·', '437 · 50 = 21 850'],
      [L('Ko‘paytma', 'Произведение', 'Product'), '24 472', '2 622 + 21 850']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Surmasdan yozish.</b> 2-to‘liqsiz ko‘paytmani 1-sining ostiga to‘g‘ri yozish: 2 622 + 2 185 = 4 807 — bu 10 baravar kam! O‘nliklarga ko‘paytirganmiz, shuning uchun bir xona chapga suramiz.', '<b>Запись без сдвига.</b> Записать 2-е неполное произведение прямо под первым: 2 622 + 2 185 = 4 807 — в 10 раз меньше! Мы умножали на десятки, поэтому сдвигаем на разряд влево.', '<b>No shift.</b> Writing the 2nd partial product straight under the first: 2 622 + 2 185 = 4 807 — ten times too small! We multiplied by tens, so we shift one place left.'),
      L('<b>Eski o‘tkazmani ishlatish.</b> 1-to‘liqsiz ko‘paytmadagi xotiradagi sonni 2-siga qo‘shib yuborish. Har yangi qatorni «toza xotira» bilan boshlang.', '<b>Использовать старый перенос.</b> Прибавить число «в уме» из 1-го неполного произведения ко 2-му. Каждую новую строку начинай «с чистой памятью».', '<b>Reusing an old carry.</b> Adding a carry from the 1st partial product into the 2nd. Start each new row with a clear memory.'),
      L('<b>O‘tkazishni ko‘paytirib yuborish.</b> 3 · 6 + 4 o‘rniga (3 + 4) · 6 hisoblash. Avval ko‘paytiring, keyin xotiradagini qo‘shing.', '<b>Умножить перенос.</b> Посчитать (3 + 4) · 6 вместо 3 · 6 + 4. Сначала умножай, потом прибавляй число в уме.', '<b>Multiplying the carry.</b> Computing (3 + 4) · 6 instead of 3 · 6 + 4. Multiply first, then add the carry.'),
      L('<b>Oxirgi o‘tkazmani yo‘qotish.</b> 4 · 6 + 2 = 26 da faqat 6 ni yozish. Eng chap raqamda butun sonni yozamiz: 26.', '<b>Потерять последний перенос.</b> В 4 · 6 + 2 = 26 записать только 6. У самой левой цифры пишем всё число: 26.', '<b>Losing the last carry.</b> Writing only 6 from 4 · 6 + 2 = 26. At the leftmost digit write the whole number: 26.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Qurilishda.</b> Uyning bir qavatiga 2 450 ta g‘isht kerak. 16 qavatli uy uchun: 2 450 · 16 = 39 200 ta g‘isht. Quruvchilar materiallarni oldindan aynan shunday hisoblashadi.', '<b>На стройке.</b> На один этаж дома нужно 2 450 кирпичей. Для 16-этажного дома: 2 450 · 16 = 39 200 кирпичей. Строители заранее считают материалы именно так.', '<b>On a building site.</b> One floor of a house needs 2 450 bricks. For a 16-storey house: 2 450 · 16 = 39 200 bricks. Builders calculate materials in advance exactly like this.'),
      L('<b>Bog‘dorchilikda.</b> Fermer 36 qator pomidor ekdi, har qatorda 125 tup. Jami: 125 · 36 = 4 500 tup. Har tupdan o‘rtacha 3 kg hosil — 13 500 kg, ya’ni 13 t 5 q.', '<b>В садоводстве.</b> Фермер посадил 36 рядов помидоров по 125 кустов. Всего: 125 · 36 = 4 500 кустов. С куста в среднем 3 кг — 13 500 кг, то есть 13 т 5 ц.', '<b>In gardening.</b> A farmer planted 36 rows of 125 tomato plants. Total: 125 · 36 = 4 500 plants. At about 3 kg each, that is 13 500 kg, i.e. 13 t 5 q.'),
      L('<b>Vaqt hisobida.</b> Bir sutkada 24 soat, bir soatda 60 daqiqa. Bir sutkada 24 · 60 = 1 440 daqiqa. Bir haftada esa 1 440 · 7 = 10 080 daqiqa.', '<b>В счёте времени.</b> В сутках 24 часа, в часе 60 минут. В сутках 24 · 60 = 1 440 минут. А в неделе 1 440 · 7 = 10 080 минут.', '<b>Counting time.</b> A day has 24 hours, an hour 60 minutes. So a day has 24 · 60 = 1 440 minutes, and a week 1 440 · 7 = 10 080 minutes.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('111 111 111 · 111 111 111 = 12 345 678 987 654 321 — natija chiroyli «tog‘» shaklida!', '111 111 111 · 111 111 111 = 12 345 678 987 654 321 — результат похож на красивую «гору»!', '111 111 111 · 111 111 111 = 12 345 678 987 654 321 — the result looks like a beautiful “mountain”!'),
      L('1980-yilda hindistonlik Shakuntala Devi ikki 13 xonali sonni xayolan 28 soniyada ko‘paytirgan va Ginnes rekordlar kitobiga kirgan.', 'В 1980 году индианка Шакунтала Деви умножила в уме два 13-значных числа за 28 секунд и попала в Книгу рекордов Гиннесса.', 'In 1980 Shakuntala Devi of India multiplied two 13-digit numbers in her head in 28 seconds and entered the Guinness Book of Records.'),
      L('Ikki xonali songa ko‘paytirishda doimo ikkita to‘liqsiz ko‘paytma bo‘ladi, uch xonalida — uchta. To‘liqsiz ko‘paytmalar soni pastki sonning raqamlari soniga teng.', 'При умножении на двузначное число всегда два неполных произведения, на трёхзначное — три. Их число равно количеству цифр нижнего множителя.', 'Multiplying by a two-digit number always gives two partial products, by a three-digit number three. Their count equals the number of digits in the bottom factor.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Ustunda hisoblang: 318 · 27.', 'Вычисли столбиком: 318 · 27.', 'Work out in a column: 318 · 27.'),
      L('Xatoni toping: 64 · 23 = 192 + 128 = 320.', 'Найди ошибку: 64 · 23 = 192 + 128 = 320.', 'Find the mistake: 64 · 23 = 192 + 128 = 320.'),
      L('Bir kitobda 96 bet. Kutubxonaga shunday 45 ta kitob keldi. Jami necha bet?', 'В книге 96 страниц. В библиотеку привезли 45 таких книг. Сколько всего страниц?', 'A book has 96 pages. The library received 45 such books. How many pages in all?')
    ], after: [
      L('Javoblar: 1) 2 226 + 6 360 = 8 586; 2) 128 surilmagan, to‘g‘risi 192 + 1 280 = 1 472; 3) 96 · 45 = 480 + 3 840 = 4 320 bet.', 'Ответы: 1) 2 226 + 6 360 = 8 586; 2) 128 не сдвинули, верно 192 + 1 280 = 1 472; 3) 96 · 45 = 480 + 3 840 = 4 320 страниц.', 'Answers: 1) 2 226 + 6 360 = 8 586; 2) 128 was not shifted; correct is 192 + 1 280 = 1 472; 3) 96 · 45 = 480 + 3 840 = 4 320 pages.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ustunda yozishda birliklar ostida birliklar turadi.', 'В столбике единицы стоят под единицами.', 'In a column, ones stand under ones.'),
      L('1-to‘liqsiz ko‘paytma — birliklarga ko‘paytirish natijasi.', '1-е неполное произведение — результат умножения на единицы.', 'The 1st partial product comes from multiplying by the ones.'),
      L('2-to‘liqsiz ko‘paytma — o‘nliklarga ko‘paytirish natijasi, bir xona chapga surib yoziladi.', '2-е неполное произведение — на десятки, записывается со сдвигом влево.', 'The 2nd partial product comes from the tens and is shifted one place left.'),
      L('To‘liqsiz ko‘paytmalar yig‘indisi — javob.', 'Сумма неполных произведений — ответ.', 'The sum of the partial products is the answer.'),
      L('Har yangi qatorni toza xotira bilan boshlang.', 'Каждую новую строку начинай с чистой памятью.', 'Start each new row with a clear memory.'),
      L('Javobni yaxlitlangan sonlar bilan baholang.', 'Оценивай ответ округлёнными числами.', 'Estimate the answer with rounded numbers.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t7. Uch xonali songa ko‘paytirish ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Uchinchi qavat qo‘shiladi', 'Добавляется третий этаж', 'A third floor is added'), p: [
      L('Ikki xonali songa ko‘paytirishni o‘rgandik: ikkita to‘liqsiz ko‘paytma, ikkinchisi surib yoziladi. Endi ko‘paytuvchi uch xonali bo‘lsa-chi? Masalan, 214 · 123. Javob oddiy: algoritm o‘zgarmaydi, faqat unga yana bitta «qavat» qo‘shiladi — yuzliklarga ko‘paytirish.', 'Мы научились умножать на двузначное число: два неполных произведения, второе со сдвигом. А если множитель трёхзначный? Например, 214 · 123. Ответ простой: алгоритм не меняется, к нему лишь добавляется ещё один «этаж» — умножение на сотни.', 'We learned to multiply by a two-digit number: two partial products, the second shifted. What if the factor has three digits? For example, 214 · 123. The answer is simple: the algorithm does not change, it just gets one more “floor” — multiplying by the hundreds.'),
      L('Bu xuddi zinapoyaga o‘xshaydi: har bir yangi to‘liqsiz ko‘paytma oldingisidan bir pog‘ona chaproqda turadi. Uch xonali son — uch pog‘ona. Zinapoyani to‘g‘ri qursangiz, javob ham to‘g‘ri chiqadi.', 'Это похоже на лестницу: каждое новое неполное произведение стоит на ступеньку левее предыдущего. Трёхзначное число — три ступеньки. Правильно построишь лестницу — получишь правильный ответ.', 'It looks like a staircase: each new partial product stands one step further left than the previous one. A three-digit number means three steps. Build the staircase correctly and the answer will be correct.'),
      L('Bu mavzuda uch xonali songa ustunda ko‘paytirishni, yaxlit yuzliklarga tez ko‘paytirishni va katta natijalarni baholashni o‘rganamiz. Natijalar endi yuz minglargacha yetadi!', 'В этой теме мы учимся умножать на трёхзначное число столбиком, быстро умножать на круглые сотни и оценивать большие результаты. Ответы теперь доходят до сотен тысяч!', 'In this topic we learn to multiply by a three-digit number in a column, to multiply quickly by whole hundreds and to estimate big results. Answers now reach hundreds of thousands!')
    ] },
    { kind: 'def', h: L('Uchta to‘liqsiz ko‘paytma', 'Три неполных произведения', 'Three partial products'), p: [
      L('Uch xonali son — yuzliklar, o‘nliklar va birliklar yig‘indisi: 123 = 100 + 20 + 3. Taqsimot xossasi bo‘yicha: 214 · 123 = 214 · 100 + 214 · 20 + 214 · 3.', 'Трёхзначное число — сумма сотен, десятков и единиц: 123 = 100 + 20 + 3. По распределительному свойству: 214 · 123 = 214 · 100 + 214 · 20 + 214 · 3.', 'A three-digit number is a sum of hundreds, tens and ones: 123 = 100 + 20 + 3. By the distributive property: 214 · 123 = 214 · 100 + 214 · 20 + 214 · 3.')
    ], list: [
      L('<b>1-to‘liqsiz ko‘paytma:</b> 214 · 3 = 642 — o‘ng chetdan yoziladi.', '<b>1-е неполное:</b> 214 · 3 = 642 — пишется от правого края.', '<b>1st partial:</b> 214 · 3 = 642 — written from the right edge.'),
      L('<b>2-to‘liqsiz ko‘paytma:</b> 214 · 2 = 428 — bir xona chapga surib (aslida 4 280).', '<b>2-е неполное:</b> 214 · 2 = 428 — со сдвигом на один разряд (на деле 4 280).', '<b>2nd partial:</b> 214 · 2 = 428 — shifted one place (really 4 280).'),
      L('<b>3-to‘liqsiz ko‘paytma:</b> 214 · 1 = 214 — ikki xona chapga surib (aslida 21 400).', '<b>3-е неполное:</b> 214 · 1 = 214 — со сдвигом на два разряда (на деле 21 400).', '<b>3rd partial:</b> 214 · 1 = 214 — shifted two places (really 21 400).')
    ], after: [
      L('Yig‘indi: 642 + 4 280 + 21 400 = <b>26 322</b>. Har bir to‘liqsiz ko‘paytmaning oxirgi raqami o‘sha raqam ostiga tushadi, qaysi raqamga ko‘paytirgan bo‘lsak.', 'Сумма: 642 + 4 280 + 21 400 = <b>26 322</b>. Последняя цифра каждого неполного произведения встаёт под той цифрой, на которую умножали.', 'Sum: 642 + 4 280 + 21 400 = <b>26 322</b>. The last digit of each partial product goes under the digit we multiplied by.')
    ] },
    { kind: 'history', h: L('Ulug‘bek rasadxonasidagi hisoblar', 'Вычисления в обсерватории Улугбека', 'Calculations at Ulugh Beg’s observatory'), p: [
      L('<b>Mirzo Ulug‘bek</b> (1394–1449) — Amir Temurning nabirasi, Samarqand hukmdori va buyuk astronom. U 1420-yillarda Samarqandda o‘sha davrdagi eng katta rasadxonani qurdirgan. Uning ulkan o‘lchov asbobi — sekstantining yoy qismi bugungacha saqlanib qolgan, uni Samarqandga borsangiz ko‘rishingiz mumkin.', '<b>Мирзо Улугбек</b> (1394–1449) — внук Амира Темура, правитель Самарканда и великий астроном. В 1420-х годах он построил в Самарканде крупнейшую обсерваторию того времени. Дуга его огромного измерительного инструмента — секстанта — сохранилась до наших дней, её можно увидеть в Самарканде.', '<b>Mirzo Ulugh Beg</b> (1394–1449) was Amir Temur’s grandson, ruler of Samarkand and a great astronomer. In the 1420s he built the largest observatory of its time in Samarkand. The arc of his giant measuring instrument, a sextant, survives to this day — you can see it if you visit Samarkand.'),
      L('Ulug‘bek va uning shogirdlari mingdan ortiq yulduzning o‘rnini o‘lchab, «Ziji jadidi Ko‘ragoniy» nomli yulduzlar jadvalini tuzishgan. Ular yil uzunligini 365 kun 6 soat 10 daqiqa 8 soniya deb hisoblagan — hozirgi zamonaviy qiymatdan bir daqiqadan ham kam farq qiladi!', 'Улугбек и его ученики измерили положение более тысячи звёзд и составили звёздные таблицы «Зидж-и Гурагани». Длину года они вычислили как 365 дней 6 часов 10 минут 8 секунд — отличие от современного значения меньше минуты!', 'Ulugh Beg and his students measured the positions of over a thousand stars and compiled star tables known as the Zij of Gurgan. They computed the length of the year as 365 days 6 hours 10 minutes 8 seconds — less than a minute off the modern value!'),
      L('Bunday aniqlik uchun olimlar ko‘p xonali sonlarni minglab marta ko‘paytirishgan. Kalkulyator yo‘q edi — hammasi qo‘lda, ustunda va jadvallar yordamida bajarilgan. Siz hozir o‘rganayotgan algoritm o‘sha olimlarning asosiy quroli bo‘lgan.', 'Для такой точности учёные тысячи раз перемножали многозначные числа. Калькуляторов не было — всё делали вручную, столбиком и с помощью таблиц. Алгоритм, который ты сейчас учишь, был главным инструментом этих учёных.', 'For such accuracy the scholars multiplied large numbers thousands of times. There were no calculators — everything was done by hand, in columns and with tables. The algorithm you are learning now was those scholars’ main tool.')
    ] },
    { kind: 'rule', h: L('Qoida', 'Правило', 'The rule'), list: [
      L('Sonlarni ustunga yozing — xona ostiga xona.', 'Запиши числа столбиком — разряд под разрядом.', 'Write the numbers in a column — place under place.'),
      L('Pastki sonning har bir raqamiga o‘ngdan chapga navbat bilan ko‘paytiring.', 'Умножай поочерёдно на каждую цифру нижнего числа справа налево.', 'Multiply by each digit of the bottom number in turn, right to left.'),
      L('Har bir yangi to‘liqsiz ko‘paytmani oldingisidan bir xona chapga surib yozing.', 'Каждое новое неполное произведение пиши со сдвигом на разряд влево от предыдущего.', 'Write each new partial product one place further left than the previous one.'),
      L('Barcha to‘liqsiz ko‘paytmalarni ustunda qo‘shing.', 'Сложи все неполные произведения столбиком.', 'Add all the partial products in a column.')
    ], after: [
      L('<b>Yaxlit sonlar uchun qoida.</b> Ko‘paytuvchilar nol bilan tugasa, nollarni chetga qo‘yib, qolgan qismlarni ko‘paytiring va keyin barcha nollarni oxiriga yozing: 250 · 400 → 25 · 4 = 100, nollar uchta → 100 000.', '<b>Правило для круглых чисел.</b> Если множители оканчиваются нулями, отложи нули, перемножь остальное и потом допиши все нули: 250 · 400 → 25 · 4 = 100, нулей три → 100 000.', '<b>Rule for round numbers.</b> If the factors end in zeros, set the zeros aside, multiply the rest and then append all the zeros: 250 · 400 → 25 · 4 = 100, three zeros → 100 000.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 352 · 247', 'Пошагово: 352 · 247', 'Step by step: 352 · 247'), list: [
      L('<b>· 7 (birliklar):</b> 2 · 7 = 14 — 4, xotirada 1. 5 · 7 = 35, + 1 = 36 — 6, xotirada 3. 3 · 7 = 21, + 3 = 24. Natija: <b>2 464</b>.', '<b>· 7 (единицы):</b> 2 · 7 = 14 — 4, в уме 1. 5 · 7 = 35, + 1 = 36 — 6, в уме 3. 3 · 7 = 21, + 3 = 24. Итог: <b>2 464</b>.', '<b>· 7 (ones):</b> 2 · 7 = 14 — 4, carry 1. 5 · 7 = 35, + 1 = 36 — 6, carry 3. 3 · 7 = 21, + 3 = 24. Result: <b>2 464</b>.'),
      L('<b>· 4 (o‘nliklar):</b> 2 · 4 = 8. 5 · 4 = 20 — 0, xotirada 2. 3 · 4 = 12, + 2 = 14. Natija: <b>1 408</b>, bir xona surilgan (14 080).', '<b>· 4 (десятки):</b> 2 · 4 = 8. 5 · 4 = 20 — 0, в уме 2. 3 · 4 = 12, + 2 = 14. Итог: <b>1 408</b> со сдвигом на разряд (14 080).', '<b>· 4 (tens):</b> 2 · 4 = 8. 5 · 4 = 20 — 0, carry 2. 3 · 4 = 12, + 2 = 14. Result: <b>1 408</b>, shifted one place (14 080).'),
      L('<b>· 2 (yuzliklar):</b> 2 · 2 = 4, 5 · 2 = 10 — 0, xotirada 1. 3 · 2 = 6, + 1 = 7. Natija: <b>704</b>, ikki xona surilgan (70 400).', '<b>· 2 (сотни):</b> 2 · 2 = 4, 5 · 2 = 10 — 0, в уме 1. 3 · 2 = 6, + 1 = 7. Итог: <b>704</b> со сдвигом на два разряда (70 400).', '<b>· 2 (hundreds):</b> 2 · 2 = 4, 5 · 2 = 10 — 0, carry 1. 3 · 2 = 6, + 1 = 7. Result: <b>704</b>, shifted two places (70 400).'),
      L('<b>Qo‘shamiz:</b> 2 464 + 14 080 + 70 400 = <b>86 944</b>.', '<b>Складываем:</b> 2 464 + 14 080 + 70 400 = <b>86 944</b>.', '<b>Add:</b> 2 464 + 14 080 + 70 400 = <b>86 944</b>.'),
      L('<b>Baholaymiz:</b> 350 · 250 = 87 500. Juda yaqin!', '<b>Оцениваем:</b> 350 · 250 = 87 500. Очень близко!', '<b>Estimate:</b> 350 · 250 = 87 500. Very close!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '111 · 111', s: L('1) 111 · 1 = 111. 2) 111 (surib — 1 110). 3) 111 (ikki xona surib — 11 100). 111 + 1 110 + 11 100 = <b>12 321</b>. Chiroyli simmetrik son!', '1) 111 · 1 = 111. 2) 111 (со сдвигом — 1 110). 3) 111 (сдвиг на два — 11 100). 111 + 1 110 + 11 100 = <b>12 321</b>. Красивое симметричное число!', '1) 111 · 1 = 111. 2) 111 (shifted — 1 110). 3) 111 (two places — 11 100). 111 + 1 110 + 11 100 = <b>12 321</b>. A beautiful symmetric number!') },
      { q: '250 · 400', s: L('Nollarni chetga qo‘yamiz: 25 · 4 = 100. Nollar: 250 da bitta, 400 da ikkita — jami uchta. 100 ga uchta nol: <b>100 000</b>.', 'Откладываем нули: 25 · 4 = 100. Нулей: в 250 — один, в 400 — два, всего три. К 100 приписываем три нуля: <b>100 000</b>.', 'Set zeros aside: 25 · 4 = 100. Zeros: one in 250, two in 400 — three in all. Append three zeros to 100: <b>100 000</b>.') },
      { q: '506 · 132', s: L('1) 506 · 2 = 1 012. 2) 506 · 3 = 1 518 (surib — 15 180). 3) 506 · 1 = 506 (ikki xona — 50 600). 1 012 + 15 180 + 50 600 = <b>66 792</b>.', '1) 506 · 2 = 1 012. 2) 506 · 3 = 1 518 (со сдвигом — 15 180). 3) 506 · 1 = 506 (сдвиг на два — 50 600). 1 012 + 15 180 + 50 600 = <b>66 792</b>.', '1) 506 · 2 = 1 012. 2) 506 · 3 = 1 518 (shifted — 15 180). 3) 506 · 1 = 506 (two places — 50 600). 1 012 + 15 180 + 50 600 = <b>66 792</b>.') },
      { q: L('Bir qopda 125 kg un bor. Nonvoyxonaga 208 qop keltirildi. Jami necha kilogramm un?', 'В мешке 125 кг муки. В пекарню привезли 208 мешков. Сколько всего муки?', 'A sack holds 125 kg of flour. A bakery received 208 sacks. How much flour in all?'), s: L('125 · 208: 1) 125 · 8 = 1 000. 2) 125 · 0 = 0 — bu qatorni yozmasak ham bo‘ladi. 3) 125 · 2 = 250 (ikki xona — 25 000). 1 000 + 25 000 = <b>26 000 kg</b> = 26 t.', '125 · 208: 1) 125 · 8 = 1 000. 2) 125 · 0 = 0 — эту строку можно не писать. 3) 125 · 2 = 250 (сдвиг на два — 25 000). 1 000 + 25 000 = <b>26 000 кг</b> = 26 т.', '125 · 208: 1) 125 · 8 = 1 000. 2) 125 · 0 = 0 — this row can be skipped. 3) 125 · 2 = 250 (two places — 25 000). 1 000 + 25 000 = <b>26 000 kg</b> = 26 t.') }
    ] },
    { kind: 'table', h: L('10, 100, 1 000 ga ko‘paytirish', 'Умножение на 10, 100, 1 000', 'Multiplying by 10, 100, 1 000'), p: [
      L('Xona birligiga ko‘paytirish — eng oson ko‘paytirish: songa shuncha nol qo‘shiladi, nechta nol ko‘paytuvchida bo‘lsa.', 'Умножение на разрядную единицу — самое лёгкое: к числу приписывают столько нулей, сколько их в множителе.', 'Multiplying by a place unit is the easiest: add as many zeros as the factor has.')
    ], table: { head: [L('Son', 'Число', 'Number'), '· 10', '· 100', '· 1 000'], rows: [
      ['7', '70', '700', '7 000'],
      ['45', '450', '4 500', '45 000'],
      ['214', '2 140', '21 400', '214 000'],
      ['360', '3 600', '36 000', '360 000']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Uchinchi qatorni bir xona surish.</b> Yuzliklarga ko‘paytirganda natijani faqat bir xona surish. Yuzliklar uchun <b>ikki</b> xona surish kerak.', '<b>Сдвинуть третью строку на один разряд.</b> При умножении на сотни сдвинуть результат лишь на один разряд. Для сотен нужен сдвиг на <b>два</b> разряда.', '<b>Shifting the third row by one place.</b> Multiplying by hundreds needs a shift of <b>two</b> places, not one.'),
      L('<b>Nollarni sanashda xato.</b> 250 · 400 = 10 000 deyish — 250 dagi nolni unutish. Ikkala ko‘paytuvchidagi nollarni ham sanang.', '<b>Ошибка в подсчёте нулей.</b> Сказать 250 · 400 = 10 000 — забыть нуль в 250. Считай нули в обоих множителях.', '<b>Miscounting zeros.</b> Saying 250 · 400 = 10 000 — forgetting the zero in 250. Count the zeros in both factors.'),
      L('<b>«Yashirin» nolni unutish.</b> 25 · 4 = 100 da allaqachon ikkita nol bor. Ularga yana uchta nol qo‘shiladi: 100 000, 1 000 emas.', '<b>Забыть «скрытые» нули.</b> В 25 · 4 = 100 уже два нуля. К ним добавляются ещё три: 100 000, а не 1 000.', '<b>Forgetting “hidden” zeros.</b> 25 · 4 = 100 already has two zeros. Three more are added: 100 000, not 1 000.'),
      L('<b>Qo‘shishda adashish.</b> Uchta qatorni qo‘shganda xonalarni chalkashtirish. Qatorlarni toza, katakka bitta raqamdan yozing.', '<b>Сбиться при сложении.</b> Путать разряды, складывая три строки. Пиши аккуратно, по одной цифре в клетке.', '<b>Slipping in the addition.</b> Mixing up places when adding three rows. Write neatly, one digit per square.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Kitob nashriyoti.</b> Bitta kitobda 256 bet. Nashriyot 1 500 nusxa chop etdi. Jami: 256 · 1 500 = 384 000 bet. Qog‘oz shu hisob bilan buyurtma qilinadi.', '<b>Издательство.</b> В одной книге 256 страниц. Напечатали 1 500 экземпляров. Всего: 256 · 1 500 = 384 000 страниц. По этому расчёту заказывают бумагу.', '<b>A publisher.</b> One book has 256 pages and 1 500 copies were printed. Total: 256 · 1 500 = 384 000 pages. Paper is ordered by this calculation.'),
      L('<b>Yil davomidagi qadamlar.</b> Agar siz kuniga 8 000 qadam yursangiz, bir yilda (365 kun): 8 000 · 365 = 2 920 000 qadam — qariyb uch million!', '<b>Шаги за год.</b> Если ты проходишь 8 000 шагов в день, то за год (365 дней): 8 000 · 365 = 2 920 000 шагов — почти три миллиона!', '<b>Steps in a year.</b> If you walk 8 000 steps a day, in a year (365 days) that is 8 000 · 365 = 2 920 000 steps — almost three million!'),
      L('<b>Yurak urishi.</b> Yurak daqiqasiga 80 marta uradi. Bir sutkada: 80 · 1 440 = 115 200 marta. Shifokorlar shunday hisoblar bilan sog‘liqni kuzatadi.', '<b>Сердцебиение.</b> Сердце бьётся 80 раз в минуту. За сутки: 80 · 1 440 = 115 200 раз. Врачи следят за здоровьем с помощью таких расчётов.', '<b>Heartbeats.</b> A heart beats 80 times a minute. In a day: 80 · 1 440 = 115 200 times. Doctors use such calculations to monitor health.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('1617-yilda shotlandiyalik Jon Neper ko‘paytirish uchun maxsus «tayoqchalar» o‘ylab topgan. Ular ham to‘r usuliga asoslangan.', 'В 1617 году шотландец Джон Непер придумал для умножения особые «палочки». Они тоже основаны на способе сетки.', 'In 1617 the Scot John Napier invented special “rods” (Napier’s bones) for multiplying. They are also based on the lattice method.'),
      L('Har qanday uch xonali sonni 1 001 ga ko‘paytirsangiz, son ikki marta takrorlanadi: 347 · 1 001 = 347 347.', 'Умножь любое трёхзначное число на 1 001 — и оно повторится дважды: 347 · 1 001 = 347 347.', 'Multiply any three-digit number by 1 001 and it repeats twice: 347 · 1 001 = 347 347.'),
      L('Ikki uch xonali sonning ko‘paytmasi eng ko‘pi bilan olti xonali bo‘ladi: 999 · 999 = 998 001.', 'Произведение двух трёхзначных чисел — не более шестизначного: 999 · 999 = 998 001.', 'The product of two three-digit numbers has at most six digits: 999 · 999 = 998 001.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 123 · 321.', 'Вычисли: 123 · 321.', 'Work out: 123 · 321.'),
      L('Og‘zaki: 40 · 500 va 120 · 300.', 'Устно: 40 · 500 и 120 · 300.', 'Mentally: 40 · 500 and 120 · 300.'),
      L('Maktab 365 kunda har kuni 120 litr suv ishlatadi. Bir yilda necha litr?', 'Школа каждый из 365 дней расходует 120 литров воды. Сколько литров за год?', 'A school uses 120 litres of water on each of 365 days. How many litres in a year?')
    ], after: [
      L('Javoblar: 1) 123 + 2 460 + 36 900 = 39 483; 2) 20 000 va 36 000; 3) 365 · 120 = 43 800 litr.', 'Ответы: 1) 123 + 2 460 + 36 900 = 39 483; 2) 20 000 и 36 000; 3) 365 · 120 = 43 800 литров.', 'Answers: 1) 123 + 2 460 + 36 900 = 39 483; 2) 20 000 and 36 000; 3) 365 · 120 = 43 800 litres.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Uch xonali songa ko‘paytirishda uchta to‘liqsiz ko‘paytma hosil bo‘ladi.', 'При умножении на трёхзначное число получаются три неполных произведения.', 'Multiplying by a three-digit number gives three partial products.'),
      L('Har biri oldingisidan bir xona chapga suriladi; yuzliklar qatori ikki xona surilgan.', 'Каждое сдвигается на разряд левее предыдущего; строка сотен сдвинута на два.', 'Each shifts one place further left; the hundreds row is shifted two places.'),
      L('Ko‘paytuvchida nol bo‘lsa, o‘sha qator nollardan iborat va uni tashlab ketish mumkin.', 'Если в множителе нуль, его строка состоит из нулей, её можно пропустить.', 'A zero in the factor gives a row of zeros that can be skipped.'),
      L('Yaxlit sonlarda nollarni chetga olib, oxirida hammasini qo‘shamiz.', 'У круглых чисел откладываем нули, а в конце приписываем все.', 'With round numbers, set zeros aside and append them all at the end.'),
      L('Javobni yaxlitlangan sonlar bilan baholang: 352 · 247 ≈ 350 · 250.', 'Оценивай ответ округлением: 352 · 247 ≈ 350 · 250.', 'Estimate with rounding: 352 · 247 ≈ 350 · 250.')
    ] }
  ] });

  // ---------- t8. O‘rtasida nol bo‘lgan sonlarni ko‘paytirish. Masalalar ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Nol — kichkina, lekin muhim', 'Нуль — маленький, но важный', 'Zero: small but important'), p: [
      L('305 va 35 — ikkala sonda ham 3 va 5 raqamlari bor. Lekin 305 deyarli 10 baravar katta! Farqni o‘rtadagi bitta nol yaratadi. Nol «hech narsa» degani bo‘lsa ham, sonda u juda muhim ish qiladi: xonani band qiladi va boshqa raqamlarni o‘z joyida ushlab turadi.', '305 и 35 — в обоих числах есть цифры 3 и 5. Но 305 почти в 10 раз больше! Разницу создаёт один нуль в середине. Хоть нуль и значит «ничего», в числе он делает важную работу: занимает разряд и держит другие цифры на своих местах.', '305 and 35 both contain the digits 3 and 5. Yet 305 is almost ten times bigger! One zero in the middle makes the difference. Even though zero means “nothing”, in a number it does an important job: it holds a place and keeps the other digits where they belong.'),
      L('Ko‘paytirishda nollar bilan ishlash ikki xil bo‘ladi. Birinchisi — o‘rtadagi nol: 305 · 24 yoki 125 · 208. Ikkinchisi — oxiridagi nollar: 4 200 · 30. Ikkalasida ham o‘z qulay usullari bor, ularni bilsangiz hisob ancha tezlashadi.', 'При умножении нули встречаются двумя способами. Первый — нуль в середине: 305 · 24 или 125 · 208. Второй — нули на конце: 4 200 · 30. В обоих случаях есть свои удобные приёмы, которые сильно ускоряют счёт.', 'In multiplication zeros come in two ways. First, a zero in the middle: 305 · 24 or 125 · 208. Second, zeros at the end: 4 200 · 30. Each case has its own handy tricks that speed up the work a lot.'),
      L('Bu mavzuda shuningdek <b>narx, miqdor, qiymat</b> masalalarini yechamiz — do‘kon va bozordagi har kungi hisob-kitoblar.', 'В этой теме мы также решаем задачи на <b>цену, количество, стоимость</b> — ежедневные расчёты в магазине и на базаре.', 'In this topic we also solve <b>price, quantity and cost</b> problems — the everyday calculations of the shop and the market.')
    ] },
    { kind: 'def', h: L('Nol bilan ko‘paytirish va narx–miqdor–qiymat', 'Умножение с нулём и цена–количество–стоимость', 'Multiplying with zero; price, quantity, cost'), p: [
      L('Har qanday sonni nolga ko‘paytirsak, nol chiqadi: 24 · 0 = 0. Shuning uchun 305 · 24 da o‘nliklar xonasidagi 0 ni ko‘paytirganda hech narsa qo‘shilmaydi, lekin uning <b>joyi</b> saqlanadi.', 'Любое число, умноженное на нуль, даёт нуль: 24 · 0 = 0. Поэтому в 305 · 24 умножение нуля в разряде десятков ничего не добавляет, но его <b>место</b> сохраняется.', 'Any number times zero gives zero: 24 · 0 = 0. So in 305 · 24, the zero in the tens place adds nothing when multiplied, but its <b>place</b> is kept.'),
      L('<b>Narx</b> — bitta narsaning puli. <b>Miqdor</b> — nechta narsa olingani. <b>Qiymat</b> — hammasi uchun to‘lanadigan pul. Ular orasidagi bog‘lanish: <b>qiymat = narx · miqdor</b>. Undan: narx = qiymat : miqdor, miqdor = qiymat : narx.', '<b>Цена</b> — стоимость одной вещи. <b>Количество</b> — сколько вещей купили. <b>Стоимость</b> — сколько платим за всё. Связь между ними: <b>стоимость = цена · количество</b>. Отсюда: цена = стоимость : количество, количество = стоимость : цена.', '<b>Price</b> is the money for one item. <b>Quantity</b> is how many items. <b>Cost</b> is the money paid for all of them. They are linked: <b>cost = price · quantity</b>. So price = cost : quantity and quantity = cost : price.')
    ] },
    { kind: 'history', h: L('Nolning sarguzashtlari', 'Приключения нуля', 'The adventures of zero'), p: [
      L('Qadimgi Bobil olimlari bo‘sh xonani ko‘rsatish uchun maxsus belgi ishlatishgan, lekin uni son deb hisoblamagan. Mayya xalqi ham o‘z nolini o‘ylab topgan. Ammo nolni haqiqiy son sifatida qabul qilib, u bilan amallarni bajarish qoidalarini birinchi bo‘lib hind olimi <b>Braxmagupta</b> 628-yilda yozgan: «son nolga ko‘paytirilsa, nol bo‘ladi».', 'Древние вавилоняне использовали особый знак для пустого разряда, но числом его не считали. Свой нуль придумали и майя. Но первым признал нуль настоящим числом и записал правила действий с ним индийский учёный <b>Брахмагупта</b> в 628 году: «число, умноженное на нуль, есть нуль».', 'Ancient Babylonian scholars used a special mark for an empty place but did not treat it as a number. The Maya also invented their own zero. But the first to accept zero as a real number and write rules for working with it was the Indian scholar <b>Brahmagupta</b> in 628: “a number multiplied by zero is zero”.'),
      L('Xorazmiy hind raqamlarini tasvirlaganda nolni kichik doiracha bilan belgilagan va uni «sifr» — ya’ni «bo‘sh» deb atagan. Bu arabcha so‘zdan ko‘plab tillardagi so‘zlar kelib chiqqan: inglizcha «zero», ruscha «цифра» va boshqalar.', 'Описывая индийские цифры, аль-Хорезми обозначал нуль кружком и называл его «сифр» — «пустой». От этого арабского слова произошли слова во многих языках: английское «zero», русское «цифра» и другие.', 'Describing the Indian numerals, al-Khwarizmi marked zero with a small circle and called it “sifr” — “empty”. Words in many languages come from this Arabic word: English “zero” and “cipher”, Russian “tsifra” (digit) and others.'),
      L('Yevropada nol uzoq vaqt shubha bilan qabul qilingan. 1299-yilda Florensiya shahrida savdogarlarga hind raqamlarini ishlatish taqiqlangan, chunki nolni osongina 6 yoki 9 ga o‘zgartirib, hujjatni soxtalashtirish mumkin edi!', 'В Европе нуль долго принимали с недоверием. В 1299 году во Флоренции купцам запретили пользоваться индийскими цифрами, потому что нуль легко переделать в 6 или 9 и подделать документ!', 'In Europe zero was long treated with suspicion. In 1299 the city of Florence banned merchants from using Indian numerals because a 0 could easily be changed into a 6 or 9 to forge a document!')
    ] },
    { kind: 'rule', h: L('Ikki qoida', 'Два правила', 'Two rules'), p: [
      L('<b>1-qoida (o‘rtadagi nol).</b> Ustunda ko‘paytirganda nol ham xona sifatida qatnashadi. 305 · 4: 5 · 4 = 20 — 0 yozamiz, 2 xotirada. 0 · 4 = 0, + 2 = 2 — 2 yozamiz. 3 · 4 = 12. Natija: 1 220. Xotiradagi son nolning o‘rniga tushadi!', '<b>Правило 1 (нуль в середине).</b> При умножении столбиком нуль тоже участвует как разряд. 305 · 4: 5 · 4 = 20 — пишем 0, 2 в уме. 0 · 4 = 0, + 2 = 2 — пишем 2. 3 · 4 = 12. Итог: 1 220. Число в уме встаёт на место нуля!', '<b>Rule 1 (middle zero).</b> In column multiplication zero takes part as a place. 305 · 4: 5 · 4 = 20 — write 0, carry 2. 0 · 4 = 0, + 2 = 2 — write 2. 3 · 4 = 12. Result: 1 220. The carry lands in the zero’s place!'),
      L('Agar nol pastki ko‘paytuvchining o‘rtasida bo‘lsa (125 · 208), nollardan iborat qatorni yozmaymiz, lekin keyingi qatorni <b>ikki</b> xona surib yozamiz.', 'Если нуль в середине нижнего множителя (125 · 208), строку из нулей не пишем, но следующую строку сдвигаем на <b>два</b> разряда.', 'If the zero is in the middle of the bottom factor (125 · 208), we skip the row of zeros but shift the next row <b>two</b> places.'),
      L('<b>2-qoida (oxiridagi nollar).</b> Nollarni chetga olib, nolsiz qismlarni ko‘paytiramiz, so‘ng ikkala ko‘paytuvchidagi barcha nollarni javob oxiriga yozamiz: 4 200 · 30 → 42 · 3 = 126, nollar 3 ta → 126 000. Ustunda yozganda nollar o‘ng tomonga «chiqarib» qo‘yiladi.', '<b>Правило 2 (нули на конце).</b> Откладываем нули, умножаем части без нулей, потом приписываем к ответу все нули обоих множителей: 4 200 · 30 → 42 · 3 = 126, нулей 3 → 126 000. В столбике нули «выносят» вправо.', '<b>Rule 2 (trailing zeros).</b> Set the zeros aside, multiply the parts without zeros, then append all the zeros of both factors: 4 200 · 30 → 42 · 3 = 126, three zeros → 126 000. In a column the zeros are “moved out” to the right.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 305 · 24', 'Пошагово: 305 · 24', 'Step by step: 305 · 24'), list: [
      L('<b>· 4:</b> 5 · 4 = 20 — 0, xotirada 2. 0 · 4 = 0, + 2 = 2. 3 · 4 = 12. Natija: <b>1 220</b>.', '<b>· 4:</b> 5 · 4 = 20 — 0, в уме 2. 0 · 4 = 0, + 2 = 2. 3 · 4 = 12. Итог: <b>1 220</b>.', '<b>· 4:</b> 5 · 4 = 20 — 0, carry 2. 0 · 4 = 0, + 2 = 2. 3 · 4 = 12. Result: <b>1 220</b>.'),
      L('<b>· 2 (o‘nlik):</b> 5 · 2 = 10 — 0, xotirada 1. 0 · 2 = 0, + 1 = 1. 3 · 2 = 6. Natija: <b>610</b>, surib — 6 100.', '<b>· 2 (десятки):</b> 5 · 2 = 10 — 0, в уме 1. 0 · 2 = 0, + 1 = 1. 3 · 2 = 6. Итог: <b>610</b>, со сдвигом — 6 100.', '<b>· 2 (tens):</b> 5 · 2 = 10 — 0, carry 1. 0 · 2 = 0, + 1 = 1. 3 · 2 = 6. Result: <b>610</b>, shifted — 6 100.'),
      L('<b>Qo‘shamiz:</b> 1 220 + 6 100 = <b>7 320</b>.', '<b>Складываем:</b> 1 220 + 6 100 = <b>7 320</b>.', '<b>Add:</b> 1 220 + 6 100 = <b>7 320</b>.'),
      L('<b>Tekshiramiz:</b> 300 · 24 = 7 200, 5 · 24 = 120, 7 200 + 120 = 7 320. To‘g‘ri!', '<b>Проверяем:</b> 300 · 24 = 7 200, 5 · 24 = 120, 7 200 + 120 = 7 320. Верно!', '<b>Check:</b> 300 · 24 = 7 200, 5 · 24 = 120, 7 200 + 120 = 7 320. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '4 200 · 30', s: L('42 · 3 = 126. Nollar: 4 200 da ikkita, 30 da bitta — uchta. Javob: <b>126 000</b>.', '42 · 3 = 126. Нулей: в 4 200 — два, в 30 — один, всего три. Ответ: <b>126 000</b>.', '42 · 3 = 126. Zeros: two in 4 200, one in 30 — three. Answer: <b>126 000</b>.') },
      { q: '1 007 · 6', s: L('7 · 6 = 42 — 2, xotirada 4. 0 · 6 + 4 = 4. 0 · 6 = 0. 1 · 6 = 6. Javob: <b>6 042</b>.', '7 · 6 = 42 — 2, в уме 4. 0 · 6 + 4 = 4. 0 · 6 = 0. 1 · 6 = 6. Ответ: <b>6 042</b>.', '7 · 6 = 42 — 2, carry 4. 0 · 6 + 4 = 4. 0 · 6 = 0. 1 · 6 = 6. Answer: <b>6 042</b>.') },
      { q: '3 040 · 205', s: L('Avval nolni chetga: 304 · 205. 1) 304 · 5 = 1 520. 2) 0 ga — qator yo‘q. 3) 304 · 2 = 608 (ikki xona surib — 60 800). 1 520 + 60 800 = 62 320. Chetdagi nolni qo‘shamiz: <b>623 200</b>.', 'Сначала откладываем нуль: 304 · 205. 1) 304 · 5 = 1 520. 2) на 0 — строки нет. 3) 304 · 2 = 608 (сдвиг на два — 60 800). 1 520 + 60 800 = 62 320. Приписываем отложенный нуль: <b>623 200</b>.', 'First set the zero aside: 304 · 205. 1) 304 · 5 = 1 520. 2) by 0 — no row. 3) 304 · 2 = 608 (two places — 60 800). 1 520 + 60 800 = 62 320. Append the zero: <b>623 200</b>.') },
      { q: L('Akmal 4 ta kitob 35 000 so‘mdan va 3 ta albom 60 000 so‘mdan oldi. Jami qancha to‘ladi?', 'Акмаль купил 4 книги по 35 000 сум и 3 альбома по 60 000 сум. Сколько он заплатил?', 'Akmal bought 4 books at 35 000 sum and 3 albums at 60 000 sum. How much did he pay?'), s: L('Kitoblar qiymati: 35 000 · 4 = 140 000. Albomlar: 60 000 · 3 = 180 000. Jami: 140 000 + 180 000 = <b>320 000 so‘m</b>.', 'Стоимость книг: 35 000 · 4 = 140 000. Альбомов: 60 000 · 3 = 180 000. Всего: 140 000 + 180 000 = <b>320 000 сум</b>.', 'Books: 35 000 · 4 = 140 000. Albums: 60 000 · 3 = 180 000. Total: 140 000 + 180 000 = <b>320 000 sum</b>.') }
    ] },
    { kind: 'table', h: L('Narx, miqdor, qiymat jadvali', 'Таблица цены, количества, стоимости', 'Price, quantity, cost table'), p: [
      L('Masalalarni jadval ko‘rinishida yozsangiz, qaysi kattalik noma’lumligi darhol ko‘rinadi.', 'Если записать задачу таблицей, сразу видно, какая величина неизвестна.', 'If you write a problem as a table, you see at once which quantity is unknown.')
    ], table: { head: [L('Mahsulot', 'Товар', 'Item'), L('Narx', 'Цена', 'Price'), L('Miqdor', 'Количество', 'Quantity'), L('Qiymat', 'Стоимость', 'Cost')], rows: [
      [L('Daftar', 'Тетрадь', 'Notebook'), '4 500', '12', '54 000'],
      [L('Ruchka', 'Ручка', 'Pen'), '3 000', '?', '21 000'],
      [L('Kitob', 'Книга', 'Book'), '?', '5', '175 000'],
      [L('Futbol to‘pi', 'Футбольный мяч', 'Football'), '120 000', '2', '?']
    ] }, after: [
      L('Javoblar: ruchkalar 21 000 : 3 000 = 7 ta; kitob narxi 175 000 : 5 = 35 000 so‘m; to‘plar qiymati 120 000 · 2 = 240 000 so‘m.', 'Ответы: ручек 21 000 : 3 000 = 7; цена книги 175 000 : 5 = 35 000 сум; стоимость мячей 120 000 · 2 = 240 000 сум.', 'Answers: pens 21 000 : 3 000 = 7; book price 175 000 : 5 = 35 000 sum; balls cost 120 000 · 2 = 240 000 sum.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>O‘rtadagi nolni tashlab ketish.</b> 305 · 4 ni 35 · 4 = 140 deb hisoblash. Nol xona — uni tashlab bo‘lmaydi: 1 220.', '<b>Выбросить нуль в середине.</b> Посчитать 305 · 4 как 35 · 4 = 140. Нуль — разряд, его нельзя выбросить: 1 220.', '<b>Dropping the middle zero.</b> Working out 305 · 4 as 35 · 4 = 140. The zero is a place and cannot be dropped: 1 220.'),
      L('<b>Xotiradagini nolga ko‘paytirish.</b> 0 · 4 + 2 o‘rniga (0 + 2) · 4 = 8 deyish. Avval 0 · 4 = 0, keyin + 2.', '<b>Умножить перенос на нуль.</b> Сказать (0 + 2) · 4 = 8 вместо 0 · 4 + 2. Сначала 0 · 4 = 0, потом + 2.', '<b>Multiplying the carry.</b> Saying (0 + 2) · 4 = 8 instead of 0 · 4 + 2. First 0 · 4 = 0, then + 2.'),
      L('<b>Nol qatoridan keyin surishni unutish.</b> 125 · 208 da 250 ni bir xona surib yozish. Nol qatori tashlansa ham, uning o‘rni hisobga olinadi — ikki xona suriladi.', '<b>Забыть сдвиг после нулевой строки.</b> В 125 · 208 сдвинуть 250 только на один разряд. Даже если строку нулей пропускаем, её место учитываем — сдвиг на два разряда.', '<b>Forgetting the shift after a zero row.</b> In 125 · 208, shifting 250 by one place only. Even if the zero row is skipped, its place counts — shift two places.'),
      L('<b>Narx va qiymatni almashtirish.</b> «Qiymat» — hammasi uchun, «narx» — bittasi uchun. Masalani o‘qib, avval jadval tuzing.', '<b>Путать цену и стоимость.</b> «Стоимость» — за всё, «цена» — за одну вещь. Прочитав задачу, сначала составь таблицу.', '<b>Mixing up price and cost.</b> “Cost” is for everything, “price” for one item. Read the problem and make a table first.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Bozorda.</b> Kartoshkaning narxi kilosiga 6 000 so‘m. Oila qishga 205 kg kartoshka oldi: 6 000 · 205 = 1 230 000 so‘m. Bu yerda o‘rtadagi nol ham, oxiridagi nollar ham bor!', '<b>На базаре.</b> Картофель стоит 6 000 сум за килограмм. Семья купила на зиму 205 кг: 6 000 · 205 = 1 230 000 сум. Здесь есть и нуль в середине, и нули на конце!', '<b>At the market.</b> Potatoes cost 6 000 sum per kilogram. A family bought 205 kg for winter: 6 000 · 205 = 1 230 000 sum. Here we have both a middle zero and trailing zeros!'),
      L('<b>Maktab ta’miri.</b> Bitta partaning narxi 450 000 so‘m. Maktab 30 ta parta oldi: 45 · 3 = 135, nollar to‘rtta — 13 500 000 so‘m. Direktor byudjetni shunday rejalashtiradi.', '<b>Ремонт школы.</b> Одна парта стоит 450 000 сум. Школа купила 30 парт: 45 · 3 = 135, нулей четыре — 13 500 000 сум. Так директор планирует бюджет.', '<b>School repairs.</b> One desk costs 450 000 sum. The school bought 30 desks: 45 · 3 = 135, four zeros — 13 500 000 sum. That is how the head teacher plans the budget.'),
      L('<b>Tejash.</b> Har hafta 20 000 so‘m yig‘sangiz, bir yilda (52 hafta): 20 000 · 52 = 1 040 000 so‘m. Bu pulga velosiped olish mumkin!', '<b>Копилка.</b> Если откладывать по 20 000 сум в неделю, за год (52 недели): 20 000 · 52 = 1 040 000 сум. На эти деньги можно купить велосипед!', '<b>Saving.</b> If you save 20 000 sum a week, in a year (52 weeks) you have 20 000 · 52 = 1 040 000 sum — enough for a bicycle!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Rim raqamlarida nol yo‘q. Shuning uchun Rim tizimida «0» ni yozib bo‘lmaydi, va 305 ni CCCV deb yozishadi.', 'В римских цифрах нет нуля. Поэтому «0» в римской системе не записать, а 305 пишут как CCCV.', 'Roman numerals have no zero. So “0” cannot be written in the Roman system, and 305 is written CCCV.'),
      L('Nolga bo‘lish mumkin emas! 6 : 0 ning javobi yo‘q, chunki hech qaysi sonni 0 ga ko‘paytirib 6 ni olib bo‘lmaydi.', 'На нуль делить нельзя! У 6 : 0 нет ответа, ведь никакое число, умноженное на 0, не даст 6.', 'You cannot divide by zero! 6 : 0 has no answer, because no number times 0 gives 6.'),
      L('«Googol» — 1 dan keyin 100 ta nol yozilgan son. Bu nomni 1938-yilda 9 yoshli bola Milton Sirotta o‘ylab topgan.', '«Гугол» — число из единицы и 100 нулей. Это название в 1938 году придумал 9-летний мальчик Милтон Сиротта.', 'A “googol” is 1 followed by 100 zeros. The name was made up in 1938 by a 9-year-old boy, Milton Sirotta.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 408 · 25.', 'Вычисли: 408 · 25.', 'Work out: 408 · 25.'),
      L('Og‘zaki: 7 000 · 80 va 1 500 · 40.', 'Устно: 7 000 · 80 и 1 500 · 40.', 'Mentally: 7 000 · 80 and 1 500 · 40.'),
      L('Bitta chipta 45 000 so‘m. 600 000 so‘mga nechta chipta olish mumkin va qancha qoladi?', 'Билет стоит 45 000 сум. Сколько билетов можно купить на 600 000 сум и сколько останется?', 'A ticket costs 45 000 sum. How many tickets can you buy with 600 000 sum and how much is left?')
    ], after: [
      L('Javoblar: 1) 2 040 + 8 160 = 10 200; 2) 560 000 va 60 000; 3) 45 000 · 13 = 585 000, demak 13 ta chipta va 15 000 so‘m qoladi.', 'Ответы: 1) 2 040 + 8 160 = 10 200; 2) 560 000 и 60 000; 3) 45 000 · 13 = 585 000, значит 13 билетов и останется 15 000 сум.', 'Answers: 1) 2 040 + 8 160 = 10 200; 2) 560 000 and 60 000; 3) 45 000 · 13 = 585 000, so 13 tickets with 15 000 sum left.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘rtadagi nol ham xona — uni ko‘paytirishda tashlab ketmaymiz.', 'Нуль в середине — тоже разряд, при умножении его не пропускаем.', 'A middle zero is a place too — never skip it.'),
      L('0 · a = 0, lekin xotiradagi son nol o‘rniga yoziladi.', '0 · a = 0, но число в уме записывается на место нуля.', '0 · a = 0, but the carry is written in the zero’s place.'),
      L('Pastki ko‘paytuvchidagi nol qatori tashlansa, keyingi qator ikki xona suriladi.', 'Если пропускаем нулевую строку, следующую сдвигаем на два разряда.', 'If a zero row is skipped, the next row shifts two places.'),
      L('Oxiridagi nollarni chetga olib, oxirida hammasini qo‘shamiz: 4 200 · 30 = 126 000.', 'Нули на конце откладываем и в конце приписываем все: 4 200 · 30 = 126 000.', 'Set trailing zeros aside and append them all: 4 200 · 30 = 126 000.'),
      L('Qiymat = narx · miqdor; narx = qiymat : miqdor; miqdor = qiymat : narx.', 'Стоимость = цена · количество; цена = стоимость : количество; количество = стоимость : цена.', 'Cost = price · quantity; price = cost : quantity; quantity = cost : price.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t9. Bo‘luvchilar va karralilar ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Konfetlarni teng bo‘lish', 'Делим конфеты поровну', 'Sharing sweets equally'), p: [
      L('Sizda 12 ta konfet bor va ularni do‘stlar bilan teng bo‘lishmoqchisiz, hech biri ortib qolmasin. Nechta do‘stga bo‘lish mumkin? 2 kishiga — 6 tadan, 3 kishiga — 4 tadan, 4 kishiga — 3 tadan, 6 kishiga — 2 tadan. 5 kishiga esa bo‘lmaydi: 2 ta ortib qoladi. 12 ni qoldiqsiz bo‘ladigan sonlar — 1, 2, 3, 4, 6, 12 — 12 ning <b>bo‘luvchilari</b>.', 'У тебя 12 конфет, и ты хочешь поделить их с друзьями поровну, чтобы ничего не осталось. На сколько друзей можно поделить? На 2 — по 6, на 3 — по 4, на 4 — по 3, на 6 — по 2. А на 5 нельзя: останется 2. Числа, на которые 12 делится без остатка — 1, 2, 3, 4, 6, 12, — <b>делители</b> числа 12.', 'You have 12 sweets and want to share them equally with friends, with none left over. How many friends can you share with? 2 — 6 each, 3 — 4 each, 4 — 3 each, 6 — 2 each. But not 5: there would be 2 left. The numbers 12 divides by with no remainder — 1, 2, 3, 4, 6, 12 — are the <b>divisors</b> of 12.'),
      L('Endi teskari savol: har bir qutida 4 ta konfet bo‘lsa, 1, 2, 3, … quti olsak, nechta konfet bo‘ladi? 4, 8, 12, 16, 20, … Bu sonlar 4 ga <b>karrali</b> sonlar. Ular hech qachon tugamaydi!', 'Теперь обратный вопрос: если в каждой коробке 4 конфеты, сколько конфет в 1, 2, 3, … коробках? 4, 8, 12, 16, 20, … Это числа, <b>кратные</b> 4. Они никогда не кончаются!', 'Now the reverse question: if each box has 4 sweets, how many sweets are in 1, 2, 3, … boxes? 4, 8, 12, 16, 20, … These are the <b>multiples</b> of 4. They never end!'),
      L('Bu mavzuda bo‘luvchi va karrali tushunchalarini, ularni topish usullarini va <b>tub sonlar</b> degan ajoyib sonlarni o‘rganamiz.', 'В этой теме мы изучим понятия делителя и кратного, способы их находить и удивительные <b>простые числа</b>.', 'In this topic we study divisors and multiples, how to find them, and the wonderful <b>prime numbers</b>.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('Agar a soni b soniga <b>qoldiqsiz</b> bo‘linsa, b soni a ning <b>bo‘luvchisi</b> deyiladi, a soni esa b ga <b>karrali</b> deyiladi. Masalan, 20 : 4 = 5 — qoldiqsiz. Demak, 4 — 20 ning bo‘luvchisi, 20 — 4 ga karrali.', 'Если число a делится на число b <b>без остатка</b>, то b называют <b>делителем</b> числа a, а a — <b>кратным</b> числа b. Например, 20 : 4 = 5 — без остатка. Значит, 4 — делитель 20, а 20 кратно 4.', 'If a number a divides by b <b>with no remainder</b>, then b is called a <b>divisor</b> of a, and a is a <b>multiple</b> of b. For example, 20 : 4 = 5 with no remainder. So 4 is a divisor of 20, and 20 is a multiple of 4.')
    ], list: [
      L('1 — har qanday sonning bo‘luvchisi. Son o‘zi ham o‘zining bo‘luvchisi.', '1 — делитель любого числа. Само число — тоже свой делитель.', '1 divides every number. A number is also a divisor of itself.'),
      L('Sonning bo‘luvchilari soni chekli: eng kattasi — sonning o‘zi.', 'Делителей у числа конечное количество: самый большой — само число.', 'A number has finitely many divisors; the largest is the number itself.'),
      L('Sonning karralilari cheksiz ko‘p: eng kichigi — sonning o‘zi.', 'Кратных у числа бесконечно много: самое маленькое — само число.', 'A number has infinitely many multiples; the smallest is the number itself.'),
      L('<b>Tub son</b> — faqat ikkita bo‘luvchisi (1 va o‘zi) bor son: 2, 3, 5, 7, 11, 13, … <b>Murakkab son</b> — ikkitadan ko‘p bo‘luvchisi bor son: 4, 6, 8, 9, 10, … 1 soni na tub, na murakkab.', '<b>Простое число</b> — число, у которого ровно два делителя (1 и оно само): 2, 3, 5, 7, 11, 13, … <b>Составное число</b> — у которого больше двух делителей: 4, 6, 8, 9, 10, … Число 1 ни простое, ни составное.', 'A <b>prime number</b> has exactly two divisors (1 and itself): 2, 3, 5, 7, 11, 13, … A <b>composite number</b> has more than two: 4, 6, 8, 9, 10, … The number 1 is neither prime nor composite.')
    ] },
    { kind: 'history', h: L('Tub sonlar tarixi', 'История простых чисел', 'A history of prime numbers'), p: [
      L('Qadimgi yunon olimi <b>Yevklid</b> (miloddan avvalgi III asr) «Negizlar» kitobida tub sonlar <b>cheksiz ko‘p</b> ekanini isbotlagan. Uning g‘oyasi oddiy: tub sonlar tugaydi deb faraz qilsak, ularning hammasini ko‘paytirib 1 qo‘shamiz. Hosil bo‘lgan son hech biriga bo‘linmaydi — demak, yana yangi tub son bor!', 'Древнегреческий учёный <b>Евклид</b> (III век до н. э.) в книге «Начала» доказал, что простых чисел <b>бесконечно много</b>. Его идея проста: если бы простые числа кончались, перемножим их все и прибавим 1. Полученное число ни на одно из них не делится — значит, есть ещё новое простое!', 'The ancient Greek scholar <b>Euclid</b> (3rd century BC) proved in his “Elements” that there are <b>infinitely many</b> primes. His idea is simple: if primes ran out, multiply them all and add 1. The new number divides by none of them — so there must be another prime!'),
      L('Boshqa yunon olimi <b>Eratosfen</b> tub sonlarni topishning qulay usulini — «Eratosfen g‘alviri»ni o‘ylab topgan. 1 dan 100 gacha sonlarni yozamiz, 2 dan boshqa barcha 2 ga karralilarni o‘chiramiz, keyin 3 dan boshqa 3 ga karralilarni, keyin 5 ga, 7 ga… O‘chirilmay qolganlar — tub sonlar. 100 gacha ular 25 ta.', 'Другой греческий учёный, <b>Эратосфен</b>, придумал удобный способ находить простые числа — «решето Эратосфена». Записываем числа от 1 до 100, вычёркиваем все кратные 2, кроме самой 2, затем кратные 3, кроме 3, потом 5, 7… Невычеркнутые — простые. До 100 их 25.', 'Another Greek scholar, <b>Eratosthenes</b>, invented a handy way to find primes — the “sieve of Eratosthenes”. Write the numbers 1 to 100, cross out all multiples of 2 except 2, then multiples of 3 except 3, then 5, 7… Those left are prime. There are 25 of them up to 100.'),
      L('O‘rta asrlarda Sharq olimlari ham sonlarning bo‘luvchilarini chuqur o‘rganishgan. Masalan, Sobit ibn Qurra (IX asr) «do‘st sonlar» juftliklarini topish qoidasini yaratgan — bunday ikki sondan har birining bo‘luvchilari yig‘indisi (sonning o‘zidan tashqari) ikkinchisiga teng. Eng mashhur juftlik — 220 va 284.', 'В Средние века восточные учёные тоже глубоко изучали делители чисел. Например, Сабит ибн Курра (IX век) нашёл правило для пар «дружественных чисел» — у каждого из двух чисел сумма делителей (кроме самого числа) равна другому числу. Самая известная пара — 220 и 284.', 'In the Middle Ages scholars of the East also studied divisors deeply. For example, Thabit ibn Qurra (9th century) found a rule for pairs of “amicable numbers” — for each of the two numbers, the sum of its divisors (except itself) equals the other number. The most famous pair is 220 and 284.')
    ] },
    { kind: 'rule', h: L('Bo‘luvchilarni juft-juft topish qoidasi', 'Правило: ищем делители парами', 'Rule: find divisors in pairs'), p: [
      L('Bo‘luvchilar doimo <b>juft</b> bo‘lib keladi: agar a = b · c bo‘lsa, b ham, c ham a ning bo‘luvchisi. Shuning uchun 1 dan boshlab sinab ko‘ramiz va har bir topilgan bo‘luvchiga uning «juftini» ham yozamiz.', 'Делители всегда идут <b>парами</b>: если a = b · c, то и b, и c — делители a. Поэтому проверяем числа, начиная с 1, и к каждому найденному делителю сразу пишем его «пару».', 'Divisors always come in <b>pairs</b>: if a = b · c, then both b and c divide a. So we test numbers from 1 upwards and, for each divisor found, write its “partner” at once.'),
      L('36 uchun: 1 · 36, 2 · 18, 3 · 12, 4 · 9, 6 · 6. 5 — bo‘luvchi emas. 6 dan keyin juftlar takrorlana boshlaydi, shuning uchun to‘xtaymiz. Bo‘luvchilar: 1, 2, 3, 4, 6, 9, 12, 18, 36 — jami 9 ta.', 'Для 36: 1 · 36, 2 · 18, 3 · 12, 4 · 9, 6 · 6. 5 — не делитель. После 6 пары начинают повторяться, поэтому останавливаемся. Делители: 1, 2, 3, 4, 6, 9, 12, 18, 36 — всего 9.', 'For 36: 1 · 36, 2 · 18, 3 · 12, 4 · 9, 6 · 6. 5 is not a divisor. After 6 the pairs start repeating, so we stop. Divisors: 1, 2, 3, 4, 6, 9, 12, 18, 36 — 9 in all.'),
      L('<b>Karralilarni topish qoidasi:</b> sonni 1, 2, 3, 4, … ga ketma-ket ko‘paytiramiz. 7 ga karralilar: 7, 14, 21, 28, 35, … Bu — ko‘paytirish jadvalidagi 7 ustuni!', '<b>Правило поиска кратных:</b> умножаем число по очереди на 1, 2, 3, 4, … Кратные 7: 7, 14, 21, 28, 35, … Это столбик 7 в таблице умножения!', '<b>Rule for multiples:</b> multiply the number by 1, 2, 3, 4, … in turn. Multiples of 7: 7, 14, 21, 28, 35, … That is the 7 column of the times table!')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 48 ning barcha bo‘luvchilari', 'Пошагово: все делители 48', 'Step by step: all divisors of 48'), list: [
      L('<b>1</b> — har doim bo‘luvchi: 48 = 1 · 48. Yozamiz: 1 va 48.', '<b>1</b> — всегда делитель: 48 = 1 · 48. Пишем 1 и 48.', '<b>1</b> always divides: 48 = 1 · 48. Write 1 and 48.'),
      L('<b>2</b>: 48 : 2 = 24. Yozamiz 2 va 24. <b>3</b>: 48 : 3 = 16. Yozamiz 3 va 16.', '<b>2</b>: 48 : 2 = 24. Пишем 2 и 24. <b>3</b>: 48 : 3 = 16. Пишем 3 и 16.', '<b>2</b>: 48 : 2 = 24. Write 2 and 24. <b>3</b>: 48 : 3 = 16. Write 3 and 16.'),
      L('<b>4</b>: 48 : 4 = 12. Yozamiz 4 va 12. <b>5</b>: bo‘linmaydi (3 qoladi).', '<b>4</b>: 48 : 4 = 12. Пишем 4 и 12. <b>5</b>: не делится (остаток 3).', '<b>4</b>: 48 : 4 = 12. Write 4 and 12. <b>5</b>: no (remainder 3).'),
      L('<b>6</b>: 48 : 6 = 8. Yozamiz 6 va 8. <b>7</b>: bo‘linmaydi. Keyingi 8 allaqachon ro‘yxatda — to‘xtaymiz.', '<b>6</b>: 48 : 6 = 8. Пишем 6 и 8. <b>7</b>: не делится. Следующее 8 уже есть в списке — останавливаемся.', '<b>6</b>: 48 : 6 = 8. Write 6 and 8. <b>7</b>: no. Next, 8 is already listed — stop.'),
      L('Tartib bilan: 1, 2, 3, 4, 6, 8, 12, 16, 24, 48 — <b>10 ta bo‘luvchi</b>.', 'По порядку: 1, 2, 3, 4, 6, 8, 12, 16, 24, 48 — <b>10 делителей</b>.', 'In order: 1, 2, 3, 4, 6, 8, 12, 16, 24, 48 — <b>10 divisors</b>.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('20 ning bo‘luvchilarini toping.', 'Найди делители числа 20.', 'Find the divisors of 20.'), s: L('Juftlar: 1 · 20, 2 · 10, 4 · 5. 3 — bo‘linmaydi. Bo‘luvchilar: <b>1, 2, 4, 5, 10, 20</b>.', 'Пары: 1 · 20, 2 · 10, 4 · 5. На 3 — не делится. Делители: <b>1, 2, 4, 5, 10, 20</b>.', 'Pairs: 1 · 20, 2 · 10, 4 · 5. 3 does not divide. Divisors: <b>1, 2, 4, 5, 10, 20</b>.') },
      { q: L('15 ga karrali, 100 dan kichik sonlarni yozing.', 'Запиши числа, кратные 15, меньшие 100.', 'Write the multiples of 15 that are less than 100.'), s: L('15 · 1 = 15, 15 · 2 = 30, … , 15 · 6 = 90. 15 · 7 = 105 — katta. Javob: <b>15, 30, 45, 60, 75, 90</b>.', '15 · 1 = 15, 15 · 2 = 30, … , 15 · 6 = 90. 15 · 7 = 105 — больше. Ответ: <b>15, 30, 45, 60, 75, 90</b>.', '15 · 1 = 15, 15 · 2 = 30, … , 15 · 6 = 90. 15 · 7 = 105 — too big. Answer: <b>15, 30, 45, 60, 75, 90</b>.') },
      { q: L('29 tub sonmi?', 'Простое ли число 29?', 'Is 29 prime?'), s: L('29 ni 2, 3, 4, 5 ga bo‘lib ko‘ramiz — hech biriga bo‘linmaydi. 6 · 6 = 36 > 29, shuning uchun bundan kattalarini tekshirish shart emas. Javob: <b>ha, tub son</b>.', 'Делим 29 на 2, 3, 4, 5 — ни на одно не делится. 6 · 6 = 36 > 29, поэтому большие проверять не нужно. Ответ: <b>да, простое</b>.', 'Divide 29 by 2, 3, 4, 5 — none works. 6 · 6 = 36 > 29, so no need to test larger ones. Answer: <b>yes, prime</b>.') },
      { q: L('Ham 4 ga, ham 6 ga karrali eng kichik sonni toping.', 'Найди наименьшее число, кратное и 4, и 6.', 'Find the smallest number that is a multiple of both 4 and 6.'), s: L('4 ga karralilar: 4, 8, 12, 16, 20, 24. 6 ga karralilar: 6, 12, 18, 24. Birinchi umumiysi — <b>12</b>. Bu ikki sonning eng kichik umumiy karralisi.', 'Кратные 4: 4, 8, 12, 16, 20, 24. Кратные 6: 6, 12, 18, 24. Первое общее — <b>12</b>. Это наименьшее общее кратное.', 'Multiples of 4: 4, 8, 12, 16, 20, 24. Multiples of 6: 6, 12, 18, 24. The first common one is <b>12</b> — the least common multiple.') }
    ] },
    { kind: 'table', h: L('Bo‘luvchilar jadvali', 'Таблица делителей', 'A table of divisors'), table: { head: [L('Son', 'Число', 'Number'), L('Bo‘luvchilari', 'Делители', 'Divisors'), L('Soni', 'Количество', 'How many'), L('Turi', 'Вид', 'Type')], rows: [
      ['7', '1, 7', '2', L('tub', 'простое', 'prime')],
      ['12', '1, 2, 3, 4, 6, 12', '6', L('murakkab', 'составное', 'composite')],
      ['16', '1, 2, 4, 8, 16', '5', L('murakkab', 'составное', 'composite')],
      ['23', '1, 23', '2', L('tub', 'простое', 'prime')],
      ['30', '1, 2, 3, 5, 6, 10, 15, 30', '8', L('murakkab', 'составное', 'composite')],
      ['45', '1, 3, 5, 9, 15, 45', '6', L('murakkab', 'составное', 'composite')]
    ] }, after: [
      L('E’tibor bering: 16 ning bo‘luvchilari soni toq (5 ta). Bu doim kvadrat sonlarda bo‘ladi (4 · 4 = 16), chunki 4 o‘ziga o‘zi juft bo‘ladi.', 'Заметь: у 16 нечётное число делителей (5). Так всегда у квадратов (4 · 4 = 16), ведь 4 — пара самому себе.', 'Notice: 16 has an odd number of divisors (5). This always happens with squares (4 · 4 = 16), because 4 is its own partner.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>«Bo‘luvchi» va «karrali»ni almashtirish.</b> «20 — 4 ning bo‘luvchisi» deyish xato. Kichik son katta sonning bo‘luvchisi, katta son esa kichigiga karrali: 4 — 20 ning bo‘luvchisi.', '<b>Путать «делитель» и «кратное».</b> Сказать «20 — делитель 4» — ошибка. Меньшее число — делитель большего, а большее кратно меньшему: 4 — делитель 20.', '<b>Mixing up “divisor” and “multiple”.</b> Saying “20 is a divisor of 4” is wrong. The smaller number divides the larger; the larger is a multiple of the smaller: 4 divides 20.'),
      L('<b>1 va sonning o‘zini unutish.</b> 12 ning bo‘luvchilari deb faqat 2, 3, 4, 6 ni yozish. 1 va 12 ham bo‘luvchi!', '<b>Забыть 1 и само число.</b> Записать делителями 12 только 2, 3, 4, 6. 1 и 12 — тоже делители!', '<b>Forgetting 1 and the number itself.</b> Listing only 2, 3, 4, 6 as divisors of 12. 1 and 12 are divisors too!'),
      L('<b>1 ni tub son deyish.</b> 1 ning faqat bitta bo‘luvchisi bor, tub sonda esa aniq ikkita bo‘lishi kerak.', '<b>Назвать 1 простым.</b> У 1 только один делитель, а у простого числа их ровно два.', '<b>Calling 1 prime.</b> 1 has only one divisor, while a prime must have exactly two.'),
      L('<b>Barcha toq sonlarni tub deb o‘ylash.</b> 9, 15, 21, 25 — toq, lekin murakkab: 9 = 3 · 3, 25 = 5 · 5. 2 esa juft, lekin tub!', '<b>Считать все нечётные простыми.</b> 9, 15, 21, 25 нечётные, но составные: 9 = 3 · 3, 25 = 5 · 5. А 2 — чётное, но простое!', '<b>Thinking every odd number is prime.</b> 9, 15, 21, 25 are odd but composite: 9 = 3 · 3, 25 = 5 · 5. And 2 is even yet prime!')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Sinfni guruhlarga bo‘lish.</b> Sinfda 24 o‘quvchi. O‘qituvchi ularni teng guruhlarga bo‘lmoqchi. 24 ning bo‘luvchilari 2, 3, 4, 6, 8, 12 — demak, 2, 3, 4, 6, 8 yoki 12 ta guruh tuzish mumkin. 5 ta guruhga esa teng bo‘lib bo‘lmaydi.', '<b>Деление класса на группы.</b> В классе 24 ученика. Учитель хочет разбить их на равные группы. Делители 24: 2, 3, 4, 6, 8, 12 — значит, можно сделать 2, 3, 4, 6, 8 или 12 групп. А на 5 групп поровну не разбить.', '<b>Splitting a class into groups.</b> A class has 24 pupils. The teacher wants equal groups. The divisors of 24 are 2, 3, 4, 6, 8, 12 — so 2, 3, 4, 6, 8 or 12 groups are possible, but not 5.'),
      L('<b>Avtobus jadvali.</b> Bir avtobus har 6 daqiqada, ikkinchisi har 8 daqiqada keladi. Ikkalasi bir vaqtda 24 daqiqadan keyin keladi — 24 ikkala songa karrali eng kichik son.', '<b>Расписание автобусов.</b> Один автобус приходит каждые 6 минут, другой — каждые 8. Вместе они придут через 24 минуты — наименьшее число, кратное обоим.', '<b>Bus timetables.</b> One bus comes every 6 minutes, another every 8. They arrive together after 24 minutes — the smallest common multiple.'),
      L('<b>Internet xavfsizligi.</b> Bank kartalaringiz va xabarlaringiz juda katta tub sonlar yordamida shifrlanadi. Ikki katta tub sonni ko‘paytirish oson, lekin natijani qaytib bo‘luvchilarga ajratish hatto kompyuter uchun ham juda qiyin.', '<b>Безопасность в интернете.</b> Банковские карты и сообщения шифруются с помощью очень больших простых чисел. Перемножить два больших простых числа легко, а разложить результат обратно на делители очень трудно даже компьютеру.', '<b>Internet security.</b> Bank cards and messages are encrypted with very large primes. Multiplying two big primes is easy, but splitting the result back into its divisors is extremely hard even for a computer.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('2024-yilda topilgan eng katta ma’lum tub son 41 milliondan ortiq raqamdan iborat. Uni oddiy kitobga yozsangiz, minglab sahifa kerak bo‘ladi!', 'Самое большое известное простое число, найденное в 2024 году, содержит больше 41 миллиона цифр. Чтобы его напечатать, понадобились бы тысячи страниц!', 'The largest known prime, found in 2024, has more than 41 million digits. Printing it would take thousands of pages!'),
      L('<b>Mukammal son</b> — o‘z bo‘luvchilari (o‘zidan tashqari) yig‘indisiga teng son: 6 = 1 + 2 + 3, 28 = 1 + 2 + 4 + 7 + 14.', '<b>Совершенное число</b> равно сумме своих делителей (кроме себя): 6 = 1 + 2 + 3, 28 = 1 + 2 + 4 + 7 + 14.', 'A <b>perfect number</b> equals the sum of its divisors other than itself: 6 = 1 + 2 + 3, 28 = 1 + 2 + 4 + 7 + 14.'),
      L('Shimoliy Amerikadagi tsikadalar yer ostida 13 yoki 17 yil yashab, keyin bir vaqtda chiqadi. Olimlarning fikricha, tub sonli davr ularni dushmanlar bilan kamroq uchrashtiradi.', 'Цикады в Северной Америке живут под землёй 13 или 17 лет, а потом выходят все разом. Учёные считают, что простой период помогает им реже встречаться с врагами.', 'Some North American cicadas live underground for 13 or 17 years and then emerge all at once. Scientists think a prime-length cycle helps them avoid predators.'),
      L('60 ning bo‘luvchilari juda ko‘p — 12 ta. Shuning uchun qadimgi Bobilliklar 60 lik sanoq sistemasini tanlashgan va biz hozir ham soatni 60 daqiqaga bo‘lamiz.', 'У 60 очень много делителей — 12. Поэтому древние вавилоняне выбрали шестидесятеричную систему, и мы до сих пор делим час на 60 минут.', '60 has many divisors — 12 of them. That is why the ancient Babylonians chose a base-60 system, and we still divide an hour into 60 minutes.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('18 ning nechta bo‘luvchisi bor?', 'Сколько делителей у 18?', 'How many divisors does 18 have?'),
      L('20 dan 40 gacha bo‘lgan tub sonlarni yozing.', 'Запиши простые числа от 20 до 40.', 'Write the primes between 20 and 40.'),
      L('Qaysi son ham 3 ga, ham 5 ga karrali va 40 dan 50 gacha oraliqda?', 'Какое число кратно и 3, и 5 и лежит между 40 и 50?', 'Which number between 40 and 50 is a multiple of both 3 and 5?')
    ], after: [
      L('Javoblar: 1) 1, 2, 3, 6, 9, 18 — 6 ta; 2) 23, 29, 31, 37; 3) 45.', 'Ответы: 1) 1, 2, 3, 6, 9, 18 — 6; 2) 23, 29, 31, 37; 3) 45.', 'Answers: 1) 1, 2, 3, 6, 9, 18 — 6; 2) 23, 29, 31, 37; 3) 45.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('a soni b ga qoldiqsiz bo‘linsa, b — a ning bo‘luvchisi, a — b ga karrali.', 'Если a делится на b без остатка, b — делитель a, а a кратно b.', 'If a divides by b with no remainder, b is a divisor of a and a is a multiple of b.'),
      L('Bo‘luvchilar chekli va juft-juft topiladi; karralilar cheksiz.', 'Делителей конечное число, их ищем парами; кратных — бесконечно много.', 'Divisors are finite and found in pairs; multiples are infinite.'),
      L('1 va sonning o‘zi — har doim bo‘luvchi.', '1 и само число — всегда делители.', '1 and the number itself always divide it.'),
      L('Tub sonning aniq ikkita bo‘luvchisi bor; 1 — tub emas.', 'У простого числа ровно два делителя; 1 — не простое.', 'A prime has exactly two divisors; 1 is not prime.'),
      L('Yevklid tub sonlar cheksiz ko‘p ekanini isbotlagan; Eratosfen g‘alviri ularni topishga yordam beradi.', 'Евклид доказал, что простых чисел бесконечно много; решето Эратосфена помогает их находить.', 'Euclid proved there are infinitely many primes; the sieve of Eratosthenes helps find them.')
    ] }
  ] });

  // ---------- t10. 2, 4, 5 va 10 ga bo‘linish alomatlari ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Bo‘lmasdan bilish mumkinmi?', 'Можно ли узнать, не деля?', 'Can we tell without dividing?'), p: [
      L('7 904 soni 4 ga bo‘linadimi? 35 715 soni 5 ga-chi? Albatta, ustunda bo‘lib ko‘rish mumkin. Lekin matematiklar ancha tezroq yo‘lni topishgan: sonning <b>oxirgi raqamlariga</b> bir qarash kifoya! Bu yashirin «kalitlar» <b>bo‘linish alomatlari</b> deyiladi.', 'Делится ли 7 904 на 4? А 35 715 на 5? Конечно, можно поделить столбиком. Но математики нашли путь гораздо быстрее: достаточно взглянуть на <b>последние цифры</b> числа! Эти тайные «ключи» называются <b>признаками делимости</b>.', 'Does 7 904 divide by 4? Does 35 715 divide by 5? Of course you could do long division. But mathematicians found a much faster way: just glance at the <b>last digits</b>! These secret “keys” are called <b>divisibility rules</b>.'),
      L('Alomatlar hayotni ancha osonlashtiradi: kasrlarni qisqartirishda, narsalarni teng bo‘lishda, xatolarni tekshirishda. Bu mavzuda biz 2, 5, 10 va 4 ga bo‘linish alomatlarini o‘rganamiz va eng muhimi — ular <b>nega</b> ishlashini tushunamiz.', 'Признаки сильно упрощают жизнь: при сокращении дробей, при делении поровну, при проверке ошибок. В этой теме мы изучим признаки делимости на 2, 5, 10 и 4 и, главное, поймём, <b>почему</b> они работают.', 'Divisibility rules make life much easier: when reducing fractions, sharing things equally, checking for mistakes. In this topic we learn the rules for 2, 5, 10 and 4 and, most importantly, understand <b>why</b> they work.'),
      L('Sir shundaki, 10, 100, 1 000 kabi sonlar 2 ga ham, 5 ga ham, 4 ga ham yaxshi bo‘linadi. Shuning uchun sonning katta qismi «xavfsiz», faqat oxirini tekshirish kerak.', 'Секрет в том, что числа 10, 100, 1 000 хорошо делятся и на 2, и на 5, и на 4. Поэтому большая часть числа «безопасна» — проверять нужно только конец.', 'The secret is that numbers like 10, 100, 1 000 divide nicely by 2, by 5 and by 4. So most of the number is “safe” — only the end needs checking.')
    ] },
    { kind: 'def', h: L('Juft va toq sonlar. Alomat nima?', 'Чётные и нечётные числа. Что такое признак?', 'Even and odd numbers. What is a rule?'), p: [
      L('<b>Juft son</b> — 2 ga qoldiqsiz bo‘linadigan son: 0, 2, 4, 6, 8, 10, 12, … <b>Toq son</b> — 2 ga bo‘lganda 1 qoldiq qoladigan son: 1, 3, 5, 7, 9, 11, … Juft va toq sonlar navbatma-navbat keladi.', '<b>Чётное число</b> делится на 2 без остатка: 0, 2, 4, 6, 8, 10, 12, … <b>Нечётное число</b> при делении на 2 даёт остаток 1: 1, 3, 5, 7, 9, 11, … Чётные и нечётные идут по очереди.', 'An <b>even number</b> divides by 2 with no remainder: 0, 2, 4, 6, 8, 10, 12, … An <b>odd number</b> leaves remainder 1: 1, 3, 5, 7, 9, 11, … Even and odd numbers alternate.'),
      L('<b>Bo‘linish alomati</b> — sonni bo‘lmasdan, uning raqamlariga qarab, u biror songa bo‘linish-bo‘linmasligini aniqlash qoidasi. Alomat «ha» yoki «yo‘q» deb aniq javob beradi.', '<b>Признак делимости</b> — правило, позволяющее по цифрам числа, не деля его, узнать, делится ли оно на данное число. Признак даёт точный ответ «да» или «нет».', 'A <b>divisibility rule</b> tells you, from the digits alone and without dividing, whether a number divides by a given number. It gives an exact “yes” or “no”.')
    ], list: [
      L('<b>2 ga:</b> oxirgi raqam juft — 0, 2, 4, 6 yoki 8.', '<b>На 2:</b> последняя цифра чётная — 0, 2, 4, 6 или 8.', '<b>By 2:</b> the last digit is even — 0, 2, 4, 6 or 8.'),
      L('<b>5 ga:</b> oxirgi raqam 0 yoki 5.', '<b>На 5:</b> последняя цифра 0 или 5.', '<b>By 5:</b> the last digit is 0 or 5.'),
      L('<b>10 ga:</b> oxirgi raqam 0.', '<b>На 10:</b> последняя цифра 0.', '<b>By 10:</b> the last digit is 0.'),
      L('<b>4 ga:</b> oxirgi ikki raqamdan tuzilgan son 4 ga bo‘linadi (yoki u 00).', '<b>На 4:</b> число из двух последних цифр делится на 4 (или это 00).', '<b>By 4:</b> the number formed by the last two digits divides by 4 (or is 00).')
    ] },
    { kind: 'history', h: L('Alomatlar tarixi', 'История признаков', 'A history of the rules'), p: [
      L('Juft va toq sonlarni qadimgi yunonlar, ayniqsa Pifagor va uning shogirdlari (miloddan avvalgi VI asr) chuqur o‘rganishgan. Ular juft sonlarni «ayol», toq sonlarni «erkak» sonlar deb atab, sonlarga sehrli xususiyatlar berishgan.', 'Чётные и нечётные числа глубоко изучали древние греки, особенно Пифагор и его ученики (VI век до н. э.). Они называли чётные числа «женскими», нечётные — «мужскими» и наделяли числа волшебными свойствами.', 'The ancient Greeks, especially Pythagoras and his followers (6th century BC), studied even and odd numbers deeply. They called even numbers “female” and odd ones “male” and gave numbers magical qualities.'),
      L('Bo‘linish alomatlari hind-arab xonali yozuvi tarqalgandan keyin ayniqsa qulay bo‘lib qoldi. Xonali yozuvda sonning oxirgi raqamlari uning 10 ga, 100 ga bo‘linishdagi qoldig‘ini darhol ko‘rsatadi. Rim raqamlarida (masalan, MCMXCIV) bunday alomatlarni ishlatib bo‘lmaydi!', 'Признаки делимости стали особенно удобны после распространения индийско-арабской позиционной записи. В ней последние цифры сразу показывают остаток от деления на 10, на 100. С римскими цифрами (например, MCMXCIV) такие признаки не работают!', 'Divisibility rules became especially handy after Hindu-Arabic place-value notation spread. In it, the last digits immediately show the remainder on division by 10 or 100. With Roman numerals (like MCMXCIV) such rules do not work!'),
      L('XVII asrda fransuz olimi Blez Paskal har qanday son uchun bo‘linish alomatini topishning umumiy usulini yaratgan. Uning g‘oyasi ham xuddi shu: 10, 100, 1 000 sonlari berilgan songa bo‘lganda qanday qoldiq qoldirishini bilish.', 'В XVII веке французский учёный Блез Паскаль создал общий способ находить признак делимости на любое число. Его идея та же: знать, какие остатки дают 10, 100, 1 000 при делении на данное число.', 'In the 17th century the French scholar Blaise Pascal created a general method for finding a divisibility rule for any number. His idea was the same: know what remainders 10, 100, 1 000 leave when divided by that number.')
    ] },
    { kind: 'rule', h: L('Nega alomatlar ishlaydi? Isbot', 'Почему признаки работают? Доказательство', 'Why do the rules work? A proof'), p: [
      L('Har qanday sonni «o‘nliklar + oxirgi raqam» ko‘rinishida yozish mumkin: 3 458 = 3 450 + 8 = 345 · 10 + 8. Birinchi qism 10 ga karrali. 10 esa 2 ga ham (10 = 2 · 5), 5 ga ham bo‘linadi. Demak, 345 · 10 doim 2 ga ham, 5 ga ham bo‘linadi.', 'Любое число можно записать как «десятки + последняя цифра»: 3 458 = 3 450 + 8 = 345 · 10 + 8. Первая часть кратна 10. А 10 делится и на 2 (10 = 2 · 5), и на 5. Значит, 345 · 10 всегда делится и на 2, и на 5.', 'Any number can be written as “tens + last digit”: 3 458 = 3 450 + 8 = 345 · 10 + 8. The first part is a multiple of 10, and 10 divides by both 2 (10 = 2 · 5) and 5. So 345 · 10 always divides by 2 and by 5.'),
      L('Ikki son yig‘indisida birinchisi bo‘linsa, butun yig‘indi bo‘linishi faqat ikkinchisiga bog‘liq. Shuning uchun 3 458 ning 2 ga bo‘linishi faqat 8 ga bog‘liq. 8 juft — demak, 3 458 ham juft! 5 ga bo‘linish uchun oxirgi raqam 5 ga bo‘linishi kerak — bunday raqamlar faqat 0 va 5.', 'Если в сумме первое слагаемое делится, то делимость всей суммы зависит только от второго. Поэтому делимость 3 458 на 2 зависит только от 8. 8 чётное — значит, и 3 458 чётное! Для деления на 5 последняя цифра должна делиться на 5 — такие цифры только 0 и 5.', 'If in a sum the first part divides, whether the whole sum divides depends only on the second part. So whether 3 458 divides by 2 depends only on 8. 8 is even — so 3 458 is even! For 5, the last digit must divide by 5 — only 0 and 5 do.'),
      L('<b>4 ga:</b> 100 = 4 · 25, demak har qanday yuzliklar soni 4 ga bo‘linadi. 7 904 = 7 900 + 04. 7 900 — 4 ga bo‘linadi, 4 — ham. Demak, 7 904 ham 4 ga bo‘linadi. Shuning uchun faqat <b>oxirgi ikki raqamni</b> tekshirish yetarli. Lekin 10 4 ga bo‘linmaydi, shuning uchun bitta oxirgi raqam yetarli emas: 12 bo‘linadi, 32 ham, lekin 22 — yo‘q.', '<b>На 4:</b> 100 = 4 · 25, значит, любое число сотен делится на 4. 7 904 = 7 900 + 04. 7 900 делится на 4, 4 — тоже. Значит, 7 904 делится на 4. Поэтому достаточно проверить <b>две последние цифры</b>. Но 10 на 4 не делится, поэтому одной последней цифры мало: 12 делится, 32 тоже, а 22 — нет.', '<b>By 4:</b> 100 = 4 · 25, so any number of hundreds divides by 4. 7 904 = 7 900 + 04. 7 900 divides by 4, and so does 4. Hence 7 904 divides by 4. So checking the <b>last two digits</b> is enough. But 10 does not divide by 4, so one last digit is not enough: 12 divides, 32 does too, but 22 does not.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 53 716 ni tekshiramiz', 'Пошагово: проверяем 53 716', 'Step by step: checking 53 716'), list: [
      L('<b>2 ga:</b> oxirgi raqam 6 — juft. <b>Bo‘linadi.</b>', '<b>На 2:</b> последняя цифра 6 — чётная. <b>Делится.</b>', '<b>By 2:</b> last digit 6 — even. <b>Yes.</b>'),
      L('<b>5 ga:</b> oxirgi raqam 6 — 0 ham, 5 ham emas. <b>Bo‘linmaydi.</b>', '<b>На 5:</b> последняя цифра 6 — не 0 и не 5. <b>Не делится.</b>', '<b>By 5:</b> last digit 6 — neither 0 nor 5. <b>No.</b>'),
      L('<b>10 ga:</b> oxirgi raqam 0 emas. <b>Bo‘linmaydi.</b>', '<b>На 10:</b> последняя цифра не 0. <b>Не делится.</b>', '<b>By 10:</b> last digit is not 0. <b>No.</b>'),
      L('<b>4 ga:</b> oxirgi ikki raqam — 16. 16 : 4 = 4. <b>Bo‘linadi.</b>', '<b>На 4:</b> две последние цифры — 16. 16 : 4 = 4. <b>Делится.</b>', '<b>By 4:</b> last two digits — 16. 16 : 4 = 4. <b>Yes.</b>'),
      L('Tekshiruv: 53 716 : 4 = 13 429. To‘g‘ri!', 'Проверка: 53 716 : 4 = 13 429. Верно!', 'Check: 53 716 : 4 = 13 429. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('215, 317, 103 dan qaysi biri 5 ga bo‘linadi?', 'Какое из чисел 215, 317, 103 делится на 5?', 'Which of 215, 317, 103 divides by 5?'), s: L('Oxirgi raqamlar: 5, 7, 3. Faqat 215 ning oxiri 5. Javob: <b>215</b>.', 'Последние цифры: 5, 7, 3. Только у 215 на конце 5. Ответ: <b>215</b>.', 'Last digits: 5, 7, 3. Only 215 ends in 5. Answer: <b>215</b>.') },
      { q: L('8 742 4 ga bo‘linadimi?', 'Делится ли 8 742 на 4?', 'Does 8 742 divide by 4?'), s: L('Oxirgi ikki raqam — 42. 42 : 4 = 10 (qoldiq 2). <b>Bo‘linmaydi</b>, garchi 8 742 juft bo‘lsa ham.', 'Две последние цифры — 42. 42 : 4 = 10 (остаток 2). <b>Не делится</b>, хотя 8 742 чётное.', 'Last two digits — 42. 42 : 4 = 10 remainder 2. <b>No</b>, even though 8 742 is even.') },
      { q: L('3 7*0 sonida * o‘rniga qanday raqam qo‘yilsa, son 4 ga bo‘linadi?', 'Какую цифру поставить вместо * в 3 7*0, чтобы число делилось на 4?', 'Which digit replaces * in 3 7*0 so that the number divides by 4?'), s: L('Oxirgi ikki raqam — *0. 4 ga bo‘linadiganlari: 00, 20, 40, 60, 80. Javob: <b>* = 0, 2, 4, 6 yoki 8</b>.', 'Две последние цифры — *0. На 4 делятся: 00, 20, 40, 60, 80. Ответ: <b>* = 0, 2, 4, 6 или 8</b>.', 'The last two digits are *0. Those divisible by 4: 00, 20, 40, 60, 80. Answer: <b>* = 0, 2, 4, 6 or 8</b>.') },
      { q: L('Ham 2 ga, ham 5 ga bo‘linadigan son qanday raqam bilan tugaydi?', 'На какую цифру оканчивается число, делящееся и на 2, и на 5?', 'What digit ends a number divisible by both 2 and 5?'), s: L('2 ga: 0, 2, 4, 6, 8. 5 ga: 0, 5. Umumiy — faqat <b>0</b>. Shuning uchun 2 ga va 5 ga bo‘linadigan son 10 ga ham bo‘linadi.', 'На 2: 0, 2, 4, 6, 8. На 5: 0, 5. Общая — только <b>0</b>. Поэтому число, делящееся на 2 и на 5, делится и на 10.', 'By 2: 0, 2, 4, 6, 8. By 5: 0, 5. Common — only <b>0</b>. So a number divisible by 2 and 5 also divides by 10.') }
    ] },
    { kind: 'table', h: L('Alomatlar jadvali', 'Таблица признаков', 'Table of rules'), table: { head: [L('Son', 'Число', 'Number'), L(': 2', ': 2', ': 2'), L(': 4', ': 4', ': 4'), L(': 5', ': 5', ': 5'), L(': 10', ': 10', ': 10')], rows: [
      ['7 904', L('ha', 'да', 'yes'), L('ha (04)', 'да (04)', 'yes (04)'), L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'no')],
      ['35 715', L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes'), L('yo‘q', 'нет', 'no')],
      ['12 340', L('ha', 'да', 'yes'), L('ha (40)', 'да (40)', 'yes (40)'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
      ['8 742', L('ha', 'да', 'yes'), L('yo‘q (42)', 'нет (42)', 'no (42)'), L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'no')],
      ['60 100', L('ha', 'да', 'yes'), L('ha (00)', 'да (00)', 'yes (00)'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Birinchi raqamga qarash.</b> 4 317 ni «4 bilan boshlangani uchun juft» deyish. Juftlik faqat <b>oxirgi</b> raqamga bog‘liq: 7 — toq.', '<b>Смотреть на первую цифру.</b> Сказать, что 4 317 чётное, «потому что начинается с 4». Чётность зависит только от <b>последней</b> цифры: 7 — нечётная.', '<b>Looking at the first digit.</b> Saying 4 317 is even “because it starts with 4”. Evenness depends only on the <b>last</b> digit: 7 is odd.'),
      L('<b>4 ga bo‘linishni bitta raqam bo‘yicha tekshirish.</b> «Oxiri 2 — demak 4 ga bo‘linadi» xato: 22, 42, 62 — 4 ga bo‘linmaydi. Ikki raqamga qarang.', '<b>Проверять делимость на 4 по одной цифре.</b> «На конце 2 — делится на 4» — ошибка: 22, 42, 62 не делятся на 4. Смотри на две цифры.', '<b>Checking 4 with one digit.</b> “It ends in 2, so it divides by 4” is wrong: 22, 42, 62 do not. Look at two digits.'),
      L('<b>Juft sonlarning hammasi 4 ga bo‘linadi deb o‘ylash.</b> 6, 10, 14 — juft, ammo 4 ga bo‘linmaydi. Aksincha esa to‘g‘ri: 4 ga bo‘linadigan har bir son juft.', '<b>Думать, что все чётные делятся на 4.</b> 6, 10, 14 чётные, но на 4 не делятся. А наоборот верно: всякое число, делящееся на 4, чётное.', '<b>Thinking all even numbers divide by 4.</b> 6, 10, 14 are even but not divisible by 4. The reverse is true: every multiple of 4 is even.'),
      L('<b>0 ni unutish.</b> 0 ham juft son va u har qanday songa bo‘linadi: 0 : 5 = 0.', '<b>Забыть про 0.</b> 0 — тоже чётное число, и оно делится на любое число: 0 : 5 = 0.', '<b>Forgetting 0.</b> 0 is even too and divides by any number: 0 : 5 = 0.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Kabisa yili.</b> Yil 4 ga bo‘linsa, u odatda kabisa — fevral 29 kun bo‘ladi. 2024 kabisa (24 : 4 = 6), 2026 esa yo‘q (26 4 ga bo‘linmaydi). Bu yerda 4 ga bo‘linish alomati ishlaydi! (Yuzlik yillar uchun qo‘shimcha qoida bor: 1900 kabisa emas edi, 2000 esa kabisa bo‘lgan.)', '<b>Високосный год.</b> Если год делится на 4, он обычно високосный — в феврале 29 дней. 2024 — високосный (24 : 4 = 6), а 2026 — нет (26 на 4 не делится). Здесь работает признак делимости на 4! (Для «круглых» вековых лет есть дополнительное правило: 1900 не был високосным, а 2000 был.)', '<b>Leap years.</b> If a year divides by 4, it is usually a leap year — February has 29 days. 2024 was a leap year (24 : 4 = 6), 2026 is not (26 is not divisible by 4). The rule for 4 at work! (Century years have an extra rule: 1900 was not a leap year, but 2000 was.)'),
      L('<b>Pul bilan.</b> O‘zbekistonda tangalar va banknotlar 50, 100, 200, 500, 1 000, … so‘mlik. Agar narx 5 ga bo‘linmasa (masalan, 1 233 so‘m), uni aniq to‘lab bo‘lmaydi — shuning uchun narxlar odatda 0 yoki 5 bilan tugaydi.', '<b>С деньгами.</b> В Узбекистане монеты и купюры по 50, 100, 200, 500, 1 000, … сум. Если цена не делится на 5 (например, 1 233 сума), её не заплатить точно — поэтому цены обычно оканчиваются на 0 или 5.', '<b>With money.</b> Uzbek coins and notes come in 50, 100, 200, 500, 1 000, … sum. A price not divisible by 5 (say 1 233 sum) cannot be paid exactly — so prices usually end in 0 or 5.'),
      L('<b>Juftlab o‘ynash.</b> Sport zalida 37 bola bor. Ularni juftlarga bo‘lsak, bittasi juftsiz qoladi — chunki 37 toq. O‘qituvchi bir qarashda buni biladi.', '<b>Игра в парах.</b> В спортзале 37 детей. Если разбить их на пары, один останется без пары — ведь 37 нечётное. Учитель видит это сразу.', '<b>Pairing up.</b> 37 children are in the gym. Put them in pairs and one is left out — 37 is odd. The teacher knows at a glance.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('<b>8 ga bo‘linish alomati:</b> oxirgi uchta raqamdan tuzilgan son 8 ga bo‘linsa, son ham 8 ga bo‘linadi. Sababi: 1 000 = 8 · 125.', '<b>Признак делимости на 8:</b> если число из трёх последних цифр делится на 8, то и всё число делится на 8. Причина: 1 000 = 8 · 125.', '<b>Rule for 8:</b> if the number formed by the last three digits divides by 8, so does the whole number. Because 1 000 = 8 · 125.'),
      L('<b>25 ga:</b> oxirgi ikki raqam 00, 25, 50 yoki 75. Sababi: 100 = 4 · 25. Shuning uchun narxlar ko‘pincha shunday tugaydi.', '<b>На 25:</b> две последние цифры 00, 25, 50 или 75. Причина: 100 = 4 · 25.', '<b>By 25:</b> the last two digits are 00, 25, 50 or 75. Because 100 = 4 · 25.'),
      L('Ikki juft sonning yig‘indisi doim juft, ikki toq sonniki ham juft, juft va toqniki esa — toq.', 'Сумма двух чётных — чётная, двух нечётных — тоже чётная, а чётного и нечётного — нечётная.', 'Even + even is even, odd + odd is even, and even + odd is odd.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('5 ta raqam — 1, 3, 4, 6, 0 — dan 10 ga bo‘linadigan eng katta besh xonali sonni tuzing.', 'Из цифр 1, 3, 4, 6, 0 составь самое большое пятизначное число, делящееся на 10.', 'From the digits 1, 3, 4, 6, 0 make the largest five-digit number divisible by 10.'),
      L('2028-yil kabisa bo‘ladimi?', 'Будет ли 2028 год високосным?', 'Will 2028 be a leap year?'),
      L('Qaysi biri 4 ga bo‘linadi: 1 114, 2 236, 5 550?', 'Что делится на 4: 1 114, 2 236, 5 550?', 'Which divides by 4: 1 114, 2 236, 5 550?')
    ], after: [
      L('Javoblar: 1) 64 310; 2) ha, 28 : 4 = 7; 3) faqat 2 236 (36 : 4 = 9).', 'Ответы: 1) 64 310; 2) да, 28 : 4 = 7; 3) только 2 236 (36 : 4 = 9).', 'Answers: 1) 64 310; 2) yes, 28 : 4 = 7; 3) only 2 236 (36 : 4 = 9).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('2 ga: oxirgi raqam juft (0, 2, 4, 6, 8).', 'На 2: последняя цифра чётная (0, 2, 4, 6, 8).', 'By 2: last digit even (0, 2, 4, 6, 8).'),
      L('5 ga: oxirgi raqam 0 yoki 5. 10 ga: oxirgi raqam 0.', 'На 5: последняя цифра 0 или 5. На 10: последняя цифра 0.', 'By 5: last digit 0 or 5. By 10: last digit 0.'),
      L('4 ga: oxirgi ikki raqamdan tuzilgan son 4 ga bo‘linadi yoki 00.', 'На 4: число из двух последних цифр делится на 4 или это 00.', 'By 4: the last two digits form a multiple of 4, or 00.'),
      L('Alomatlar ishlaydi, chunki 10 son 2 va 5 ga, 100 esa 4 ga bo‘linadi.', 'Признаки работают, потому что 10 делится на 2 и 5, а 100 — на 4.', 'The rules work because 10 divides by 2 and 5, and 100 by 4.'),
      L('2 ga va 5 ga bo‘linadigan son 10 ga ham bo‘linadi.', 'Число, делящееся на 2 и на 5, делится и на 10.', 'A number divisible by 2 and 5 also divides by 10.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t11. 3 va 9 ga bo‘linish alomatlari ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Raqamlarni qo‘shib, sirni ochamiz', 'Складываем цифры — раскрываем тайну', 'Add the digits, unlock the secret'), p: [
      L('2 va 5 ga bo‘linishni oxirgi raqamdan bildik. Lekin 3 ga bo‘linishda bu usul ishlamaydi: 13 ham, 33 ham 3 bilan tugaydi, biroq 33 bo‘linadi, 13 esa yo‘q. 12 ham, 22 ham 2 bilan tugaydi, ammo faqat 12 bo‘linadi. Demak, 3 ga bo‘linish uchun boshqa kalit kerak.', 'Делимость на 2 и 5 мы узнавали по последней цифре. Но для 3 этот способ не работает: и 13, и 33 оканчиваются на 3, но 33 делится, а 13 — нет. И 12, и 22 оканчиваются на 2, а делится только 12. Значит, для 3 нужен другой ключ.', 'For 2 and 5 we used the last digit. But this does not work for 3: 13 and 33 both end in 3, yet 33 divides and 13 does not. 12 and 22 both end in 2, but only 12 divides. So 3 needs another key.'),
      L('Bu kalit juda chiroyli: sonning <b>barcha raqamlarini qo‘shamiz</b>. 4 572 uchun: 4 + 5 + 7 + 2 = 18. 18 soni 3 ga ham, 9 ga ham bo‘linadi — demak, 4 572 ham 3 ga va 9 ga bo‘linadi! Tekshiramiz: 4 572 : 9 = 508. Ajoyib!', 'Этот ключ очень красив: <b>складываем все цифры</b> числа. Для 4 572: 4 + 5 + 7 + 2 = 18. 18 делится и на 3, и на 9 — значит, и 4 572 делится на 3 и на 9! Проверим: 4 572 : 9 = 508. Чудесно!', 'This key is beautiful: <b>add up all the digits</b>. For 4 572: 4 + 5 + 7 + 2 = 18. 18 divides by both 3 and 9 — so 4 572 does too! Check: 4 572 : 9 = 508. Wonderful!'),
      L('Bu mavzuda 3 va 9 ga bo‘linish alomatlarini, ularning isbotini va «to‘qqizlik bilan tekshirish» degan qadimiy usulni o‘rganamiz. Shuningdek, 6 ga bo‘linishni ham bilib olamiz.', 'В этой теме мы изучим признаки делимости на 3 и 9, их доказательство и старинный способ «проверки девяткой». А ещё узнаем о делимости на 6.', 'In this topic we learn the rules for 3 and 9, their proof and the ancient “check by nines”. We also find out about dividing by 6.')
    ] },
    { kind: 'def', h: L('Raqamlar yig‘indisi va alomatlar', 'Сумма цифр и признаки', 'Digit sum and the rules'), p: [
      L('<b>Raqamlar yig‘indisi</b> — sonning barcha raqamlarini qo‘shganda chiqadigan son. 52 647 ning raqamlar yig‘indisi: 5 + 2 + 6 + 4 + 7 = 24. Diqqat: bu xona qo‘shiluvchilari emas, oddiy raqamlar!', '<b>Сумма цифр</b> — число, которое получается, если сложить все цифры числа. Сумма цифр 52 647: 5 + 2 + 6 + 4 + 7 = 24. Внимание: складываем не разрядные слагаемые, а просто цифры!', 'The <b>digit sum</b> is what you get by adding all the digits. For 52 647: 5 + 2 + 6 + 4 + 7 = 24. Careful: we add the plain digits, not the place values!')
    ], list: [
      L('<b>3 ga bo‘linish alomati:</b> son raqamlarining yig‘indisi 3 ga bo‘linsa, son ham 3 ga bo‘linadi. Bo‘linmasa — son ham bo‘linmaydi.', '<b>Признак делимости на 3:</b> если сумма цифр делится на 3, то и число делится на 3. Если не делится — число тоже не делится.', '<b>Rule for 3:</b> if the digit sum divides by 3, the number divides by 3. If not, neither does the number.'),
      L('<b>9 ga bo‘linish alomati:</b> son raqamlarining yig‘indisi 9 ga bo‘linsa, son ham 9 ga bo‘linadi.', '<b>Признак делимости на 9:</b> если сумма цифр делится на 9, то и число делится на 9.', '<b>Rule for 9:</b> if the digit sum divides by 9, the number divides by 9.'),
      L('<b>6 ga:</b> son 2 ga ham, 3 ga ham bo‘linsa, u 6 ga bo‘linadi (6 = 2 · 3). Ya’ni: juft va raqamlar yig‘indisi 3 ga bo‘linadi.', '<b>На 6:</b> если число делится и на 2, и на 3, оно делится на 6 (6 = 2 · 3). То есть: чётное и сумма цифр делится на 3.', '<b>By 6:</b> if a number divides by both 2 and 3, it divides by 6 (6 = 2 · 3). That is: even, with a digit sum divisible by 3.')
    ], after: [
      L('9 ga bo‘linadigan har bir son 3 ga ham bo‘linadi (9 = 3 · 3). Aksincha emas: 12 3 ga bo‘linadi, lekin 9 ga — yo‘q.', 'Каждое число, делящееся на 9, делится и на 3 (9 = 3 · 3). Наоборот — нет: 12 делится на 3, но не на 9.', 'Every multiple of 9 is a multiple of 3 (9 = 3 · 3). Not the other way round: 12 divides by 3 but not by 9.')
    ] },
    { kind: 'history', h: L('«To‘qqizlik bilan tekshirish»', '«Проверка девяткой»', 'The check by nines'), p: [
      L('Raqamlar yig‘indisining 9 ga bog‘liq xossasini hind matematiklari bilgan. Undan O‘rta asrlarda arab va fors tilidagi arifmetika kitoblarida «to‘qqizlik bilan tekshirish» usuli sifatida keng foydalanilgan: bu usul hisobchilar uchun kalkulyatorsiz xatoni topishning eng mashhur yo‘li edi.', 'Свойство суммы цифр, связанное с 9, знали индийские математики. В Средние века в арабских и персидских книгах по арифметике его широко использовали как «проверку девяткой» — это был самый известный способ найти ошибку без калькулятора.', 'Indian mathematicians knew the property of the digit sum linked to 9. In medieval Arabic and Persian arithmetic books it was widely used as the “check by nines” — the most popular way for calculators to catch a mistake without any machine.'),
      L('Usul quyidagicha: har bir sonning raqamlarini qo‘shib, 9 ga bo‘lgandagi qoldig‘ini topamiz. Masalan, 48 · 23 = 1 104 ni tekshiramiz. 48 → 4 + 8 = 12 → 1 + 2 = 3. 23 → 2 + 3 = 5. 3 · 5 = 15 → 1 + 5 = 6. Javob: 1 104 → 1 + 1 + 0 + 4 = 6. Ikkalasi 6 — demak, javob katta ehtimol bilan to‘g‘ri!', 'Способ такой: у каждого числа складываем цифры и находим остаток от деления на 9. Проверим 48 · 23 = 1 104. 48 → 4 + 8 = 12 → 1 + 2 = 3. 23 → 2 + 3 = 5. 3 · 5 = 15 → 1 + 5 = 6. Ответ: 1 104 → 1 + 1 + 0 + 4 = 6. Оба — 6, значит, ответ скорее всего верен!', 'The method: add up the digits of each number to get its remainder on division by 9. Check 48 · 23 = 1 104. 48 → 4 + 8 = 12 → 1 + 2 = 3. 23 → 2 + 3 = 5. 3 · 5 = 15 → 1 + 5 = 6. The answer: 1 104 → 1 + 1 + 0 + 4 = 6. Both give 6 — so the answer is very likely right!'),
      L('Yevropaga bu usul Fibonachchining 1202-yilda yozilgan «Abak kitobi» orqali kelgan. Bu kitob hind-arab raqamlarini Yevropada tarqatgan asosiy asarlardan biri bo‘lib, unda Xorazmiy an’analari davom ettirilgan.', 'В Европу этот способ пришёл через «Книгу абака» Фибоначчи 1202 года. Эта книга — одна из главных, распространивших в Европе индийско-арабские цифры, и в ней продолжены традиции аль-Хорезми.', 'The method reached Europe through Fibonacci’s “Book of Calculation” (Liber Abaci) of 1202. This book was one of the main works that spread Hindu-Arabic numerals in Europe, continuing the tradition of al-Khwarizmi.')
    ] },
    { kind: 'rule', h: L('Nega alomat ishlaydi? Isbot', 'Почему признак работает? Доказательство', 'Why does the rule work? A proof'), p: [
      L('Kalit — 9 ga yaqin sonlarda: 10 = 9 + 1, 100 = 99 + 1, 1 000 = 999 + 1. 9, 99, 999 sonlarining hammasi 9 ga (demak, 3 ga ham) bo‘linadi.', 'Ключ — в числах рядом с 9: 10 = 9 + 1, 100 = 99 + 1, 1 000 = 999 + 1. Все числа 9, 99, 999 делятся на 9 (а значит, и на 3).', 'The key lies in numbers near 9: 10 = 9 + 1, 100 = 99 + 1, 1 000 = 999 + 1. 9, 99 and 999 all divide by 9 (and so by 3).'),
      L('Endi 4 572 ni yoyamiz: 4 · 1 000 + 5 · 100 + 7 · 10 + 2 = 4 · (999 + 1) + 5 · (99 + 1) + 7 · (9 + 1) + 2 = (4 · 999 + 5 · 99 + 7 · 9) + (4 + 5 + 7 + 2).', 'Теперь разложим 4 572: 4 · 1 000 + 5 · 100 + 7 · 10 + 2 = 4 · (999 + 1) + 5 · (99 + 1) + 7 · (9 + 1) + 2 = (4 · 999 + 5 · 99 + 7 · 9) + (4 + 5 + 7 + 2).', 'Now expand 4 572: 4 · 1 000 + 5 · 100 + 7 · 10 + 2 = 4 · (999 + 1) + 5 · (99 + 1) + 7 · (9 + 1) + 2 = (4 · 999 + 5 · 99 + 7 · 9) + (4 + 5 + 7 + 2).'),
      L('Birinchi qavs har doim 9 ga bo‘linadi. Ikkinchi qavs — aynan raqamlar yig‘indisi! Shuning uchun son 9 ga (yoki 3 ga) bo‘linishi faqat raqamlar yig‘indisiga bog‘liq. Bu isbot har qanday son uchun ishlaydi — qancha xonali bo‘lmasin.', 'Первая скобка всегда делится на 9. Вторая скобка — это и есть сумма цифр! Поэтому делимость числа на 9 (или на 3) зависит только от суммы цифр. Это доказательство годится для любого числа, сколько бы в нём ни было цифр.', 'The first bracket always divides by 9. The second bracket is exactly the digit sum! So whether the number divides by 9 (or 3) depends only on the digit sum. This proof works for any number, however many digits it has.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 87 345 ni tekshiramiz', 'Пошагово: проверяем 87 345', 'Step by step: checking 87 345'), list: [
      L('<b>Raqamlarni qo‘shamiz:</b> 8 + 7 + 3 + 4 + 5 = 27.', '<b>Складываем цифры:</b> 8 + 7 + 3 + 4 + 5 = 27.', '<b>Add the digits:</b> 8 + 7 + 3 + 4 + 5 = 27.'),
      L('<b>Yig‘indi katta bo‘lsa, yana qo‘shish mumkin:</b> 2 + 7 = 9.', '<b>Если сумма большая, можно сложить ещё раз:</b> 2 + 7 = 9.', '<b>If the sum is big, add again:</b> 2 + 7 = 9.'),
      L('<b>3 ga:</b> 27 : 3 = 9 — bo‘linadi. <b>9 ga:</b> 27 : 9 = 3 — bo‘linadi.', '<b>На 3:</b> 27 : 3 = 9 — делится. <b>На 9:</b> 27 : 9 = 3 — делится.', '<b>By 3:</b> 27 : 3 = 9 — yes. <b>By 9:</b> 27 : 9 = 3 — yes.'),
      L('<b>6 ga:</b> oxirgi raqam 5 — toq, 2 ga bo‘linmaydi, demak 6 ga ham <b>bo‘linmaydi</b>.', '<b>На 6:</b> последняя цифра 5 — нечётная, на 2 не делится, значит, и на 6 <b>не делится</b>.', '<b>By 6:</b> last digit 5 is odd, so not divisible by 2, so <b>not</b> by 6.'),
      L('Tekshiruv: 87 345 : 9 = 9 705. To‘g‘ri!', 'Проверка: 87 345 : 9 = 9 705. Верно!', 'Check: 87 345 : 9 = 9 705. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('123, 124, 125 dan qaysi biri 3 ga bo‘linadi?', 'Какое из чисел 123, 124, 125 делится на 3?', 'Which of 123, 124, 125 divides by 3?'), s: L('Raqamlar yig‘indilari: 6, 7, 8. Faqat 6 3 ga bo‘linadi. Javob: <b>123</b> (123 : 3 = 41).', 'Суммы цифр: 6, 7, 8. Только 6 делится на 3. Ответ: <b>123</b> (123 : 3 = 41).', 'Digit sums: 6, 7, 8. Only 6 divides by 3. Answer: <b>123</b> (123 : 3 = 41).') },
      { q: L('5 2*1 sonida * o‘rniga qanday raqam qo‘yilsa, son 9 ga bo‘linadi?', 'Какую цифру поставить вместо * в 5 2*1, чтобы число делилось на 9?', 'Which digit replaces * in 5 2*1 so the number divides by 9?'), s: L('5 + 2 + 1 = 8. 8 + * 9 ga bo‘linishi kerak: 9 yoki 18. * = 1 (yig‘indi 9) — boshqa raqam mos emas (* = 10 bo‘lolmaydi). Javob: <b>5 211</b>. Tekshiruv: 5 211 : 9 = 579.', '5 + 2 + 1 = 8. 8 + * должно делиться на 9: 9 или 18. * = 1 (сумма 9), другие цифры не подходят (* = 10 невозможно). Ответ: <b>5 211</b>. Проверка: 5 211 : 9 = 579.', '5 + 2 + 1 = 8. 8 + * must divide by 9: 9 or 18. * = 1 (sum 9); no other digit works (* = 10 is impossible). Answer: <b>5 211</b>. Check: 5 211 : 9 = 579.') },
      { q: L('2 316 6 ga bo‘linadimi?', 'Делится ли 2 316 на 6?', 'Does 2 316 divide by 6?'), s: L('Juft (6 bilan tugaydi) — 2 ga bo‘linadi. Raqamlar yig‘indisi 2 + 3 + 1 + 6 = 12 — 3 ga bo‘linadi. Demak, <b>6 ga bo‘linadi</b>: 2 316 : 6 = 386.', 'Чётное (оканчивается на 6) — делится на 2. Сумма цифр 2 + 3 + 1 + 6 = 12 — делится на 3. Значит, <b>делится на 6</b>: 2 316 : 6 = 386.', 'Even (ends in 6) — divides by 2. Digit sum 2 + 3 + 1 + 6 = 12 — divides by 3. So it <b>divides by 6</b>: 2 316 : 6 = 386.') },
      { q: L('3, 5, 7 raqamlaridan (har biri bir marta) 3 ga bo‘linadigan nechta uch xonali son tuzish mumkin?', 'Сколько трёхзначных чисел, делящихся на 3, можно составить из цифр 3, 5, 7 (каждая по разу)?', 'How many three-digit multiples of 3 can be made from 3, 5, 7 (each used once)?'), s: L('Raqamlar yig‘indisi har doim 3 + 5 + 7 = 15 — 3 ga bo‘linadi. Demak, hamma tartib mos: 357, 375, 537, 573, 735, 753 — <b>6 ta</b>.', 'Сумма цифр всегда 3 + 5 + 7 = 15 — делится на 3. Значит, подходит любой порядок: 357, 375, 537, 573, 735, 753 — <b>6 чисел</b>.', 'The digit sum is always 3 + 5 + 7 = 15, which divides by 3. So every order works: 357, 375, 537, 573, 735, 753 — <b>6 numbers</b>.') }
    ] },
    { kind: 'table', h: L('Barcha alomatlar bir joyda', 'Все признаки в одном месте', 'All the rules in one place'), table: { head: [L('Songa', 'На число', 'By'), L('Nimaga qaraymiz', 'На что смотрим', 'What to look at'), L('Misol', 'Пример', 'Example')], rows: [
      ['2', L('oxirgi raqam juft', 'последняя цифра чётная', 'last digit even'), '3 458'],
      ['3', L('raqamlar yig‘indisi : 3', 'сумма цифр : 3', 'digit sum : 3'), L('123 (6)', '123 (6)', '123 (6)')],
      ['4', L('oxirgi ikki raqam : 4', 'две последние цифры : 4', 'last two digits : 4'), L('7 904 (04)', '7 904 (04)', '7 904 (04)')],
      ['5', L('oxiri 0 yoki 5', 'на конце 0 или 5', 'ends in 0 or 5'), '35 715'],
      ['6', L(': 2 va : 3', ': 2 и : 3', ': 2 and : 3'), '2 316'],
      ['9', L('raqamlar yig‘indisi : 9', 'сумма цифр : 9', 'digit sum : 9'), L('4 572 (18)', '4 572 (18)', '4 572 (18)')],
      ['10', L('oxiri 0', 'на конце 0', 'ends in 0'), '12 340']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Oxirgi raqamga qarash.</b> «33 3 bilan tugaydi — 3 ga bo‘linadi, 13 ham» — xato. 3 va 9 uchun barcha raqamlar yig‘indisi kerak.', '<b>Смотреть на последнюю цифру.</b> «33 оканчивается на 3 — делится на 3, значит и 13» — ошибка. Для 3 и 9 нужна сумма всех цифр.', '<b>Looking at the last digit.</b> “33 ends in 3 so it divides by 3, so does 13” is wrong. For 3 and 9 you need the sum of all digits.'),
      L('<b>Xona qo‘shiluvchilarini qo‘shish.</b> 123 uchun 100 + 20 + 3 = 123 deb qo‘shish — bu sonning o‘zi. Raqamlarni qo‘shamiz: 1 + 2 + 3 = 6.', '<b>Складывать разрядные слагаемые.</b> Для 123 сложить 100 + 20 + 3 = 123 — это само число. Складываем цифры: 1 + 2 + 3 = 6.', '<b>Adding place values.</b> For 123, adding 100 + 20 + 3 = 123 just gives the number back. Add the digits: 1 + 2 + 3 = 6.'),
      L('<b>3 va 9 ni teng deb o‘ylash.</b> 3 ga bo‘linadigan son 9 ga ham bo‘linadi deyish xato: 6, 12, 15, 21 — 9 ga bo‘linmaydi.', '<b>Считать 3 и 9 одинаковыми.</b> Говорить, что делящееся на 3 делится и на 9, — ошибка: 6, 12, 15, 21 на 9 не делятся.', '<b>Treating 3 and 9 as the same.</b> Saying multiples of 3 are multiples of 9 is wrong: 6, 12, 15, 21 are not.'),
      L('<b>6 ga faqat 3 bo‘yicha tekshirish.</b> 15 ning raqamlar yig‘indisi 6, ammo 15 toq — 6 ga bo‘linmaydi. Juftlikni ham tekshiring!', '<b>Проверять на 6 только по 3.</b> У 15 сумма цифр 6, но 15 нечётное — на 6 не делится. Проверяй и чётность!', '<b>Checking 6 by 3 alone.</b> 15 has digit sum 6, but 15 is odd — not divisible by 6. Check evenness too!')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Uch kishiga bo‘lish.</b> Uch aka-uka 2 457 000 so‘mni teng bo‘lishmoqchi. Bo‘linadimi? 2 + 4 + 5 + 7 = 18 — 3 ga bo‘linadi. Demak, har biriga 819 000 so‘m tegadi va hech narsa ortmaydi.', '<b>Делим на троих.</b> Трое братьев хотят поровну поделить 2 457 000 сум. Делится ли? 2 + 4 + 5 + 7 = 18 — делится на 3. Каждому по 819 000 сум, ничего не останется.', '<b>Splitting three ways.</b> Three brothers want to share 2 457 000 sum equally. Does it divide? 2 + 4 + 5 + 7 = 18 — divisible by 3. Each gets 819 000 sum with nothing left over.'),
      L('<b>Xatolarni tekshirish.</b> Kassir yoki buxgalter katta hisobni «to‘qqizlik bilan tekshirish» orqali tezda nazorat qila oladi. Bu usul ko‘p xatolarni topadi (lekin hammasini emas: raqamlar o‘rni almashsa, sezmaydi).', '<b>Проверка ошибок.</b> Кассир или бухгалтер может быстро проверить большой расчёт «девяткой». Способ находит многие ошибки (но не все: перестановку цифр он не замечает).', '<b>Catching mistakes.</b> A cashier or accountant can quickly check a large calculation with the nines check. It catches many errors (but not all: it misses swapped digits).'),
      L('<b>Shtrix-kodlar va karta raqamlari.</b> Do‘kondagi shtrix-kodlar va bank karta raqamlarida oxirgi raqam «nazorat raqami» bo‘ladi — u boshqa raqamlardan maxsus yig‘indi orqali hisoblanadi. Agar bitta raqam noto‘g‘ri o‘qilsa, kassa buni darhol sezadi. Bu g‘oya raqamlar yig‘indisi alomatiga juda o‘xshaydi.', '<b>Штрихкоды и номера карт.</b> В штрихкодах и номерах банковских карт последняя цифра — «контрольная», её вычисляют из других цифр особой суммой. Если одна цифра считана неверно, касса сразу это заметит. Идея очень похожа на признак суммы цифр.', '<b>Barcodes and card numbers.</b> In barcodes and bank card numbers the last digit is a “check digit”, computed from the others by a special sum. If one digit is misread, the till notices at once. The idea is much like the digit-sum rule.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('<b>9 sehri:</b> istalgan sonni oling, uning raqamlarini aralashtirib yangi son tuzing va kattasidan kichigini ayiring. Natija har doim 9 ga bo‘linadi! 732 − 237 = 495, 4 + 9 + 5 = 18.', '<b>Магия девятки:</b> возьми любое число, переставь его цифры и вычти из большего меньшее. Результат всегда делится на 9! 732 − 237 = 495, 4 + 9 + 5 = 18.', '<b>Nine magic:</b> take any number, shuffle its digits to make a new one and subtract the smaller from the larger. The result always divides by 9! 732 − 237 = 495, 4 + 9 + 5 = 18.'),
      L('9 ko‘paytirish jadvalida raqamlar yig‘indisi doim 9: 18, 27, 36, 45, 54, 63, 72, 81 (1 + 8 = 9, 2 + 7 = 9 …).', 'В таблице умножения на 9 сумма цифр всегда 9: 18, 27, 36, 45, 54, 63, 72, 81 (1 + 8 = 9, 2 + 7 = 9 …).', 'In the 9 times table the digit sum is always 9: 18, 27, 36, 45, 54, 63, 72, 81 (1 + 8 = 9, 2 + 7 = 9 …).'),
      L('123 456 789 soni 9 ga bo‘linadi, chunki raqamlar yig‘indisi 45. 0 dan 9 gacha barcha raqamlardan tuzilgan har qanday son ham 9 ga bo‘linadi!', 'Число 123 456 789 делится на 9: сумма цифр 45. И любое число из всех цифр от 0 до 9 тоже делится на 9!', '123 456 789 divides by 9: its digit sum is 45. Any number using all digits 0 to 9 once also divides by 9!')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('7 *42 sonida * o‘rniga qaysi raqamlar qo‘yilsa, son 3 ga bo‘linadi?', 'Какие цифры можно поставить вместо * в 7 *42, чтобы число делилось на 3?', 'Which digits can replace * in 7 *42 so the number divides by 3?'),
      L('Eng kichik to‘rt xonali, 9 ga bo‘linadigan son qaysi?', 'Какое наименьшее четырёхзначное число делится на 9?', 'What is the smallest four-digit number divisible by 9?'),
      L('48 · 25 = 1 200 ni to‘qqizlik bilan tekshiring.', 'Проверь девяткой: 48 · 25 = 1 200.', 'Check 48 · 25 = 1 200 by nines.')
    ], after: [
      L('Javoblar: 1) 7 + 4 + 2 = 13, 13 + * = 15, 18 yoki 21: * = 2, 5, 8; 2) 1 008 (1 + 0 + 0 + 8 = 9); 3) 48 → 3, 25 → 7, 3 · 7 = 21 → 3; 1 200 → 3. Mos keldi.', 'Ответы: 1) 7 + 4 + 2 = 13, 13 + * = 15, 18 или 21: * = 2, 5, 8; 2) 1 008 (1 + 0 + 0 + 8 = 9); 3) 48 → 3, 25 → 7, 3 · 7 = 21 → 3; 1 200 → 3. Совпало.', 'Answers: 1) 7 + 4 + 2 = 13, 13 + * = 15, 18 or 21: * = 2, 5, 8; 2) 1 008 (1 + 0 + 0 + 8 = 9); 3) 48 → 3, 25 → 7, 3 · 7 = 21 → 3; 1 200 → 3. They match.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('3 ga: raqamlar yig‘indisi 3 ga bo‘linadi.', 'На 3: сумма цифр делится на 3.', 'By 3: the digit sum divides by 3.'),
      L('9 ga: raqamlar yig‘indisi 9 ga bo‘linadi.', 'На 9: сумма цифр делится на 9.', 'By 9: the digit sum divides by 9.'),
      L('6 ga: son juft va raqamlar yig‘indisi 3 ga bo‘linadi.', 'На 6: число чётное и сумма цифр делится на 3.', 'By 6: even, with a digit sum divisible by 3.'),
      L('Isbot: 10 = 9 + 1, 100 = 99 + 1, … shuning uchun son va raqamlar yig‘indisi 9 ga bir xil qoldiq beradi.', 'Доказательство: 10 = 9 + 1, 100 = 99 + 1, … поэтому число и его сумма цифр дают одинаковый остаток при делении на 9.', 'Proof: 10 = 9 + 1, 100 = 99 + 1, … so a number and its digit sum leave the same remainder on division by 9.'),
      L('«To‘qqizlik bilan tekshirish» — hisobdagi xatolarni topishning qadimiy usuli.', '«Проверка девяткой» — старинный способ найти ошибку в расчётах.', 'The check by nines is an ancient way to catch calculation errors.')
    ] }
  ] });

  // ---------- t12. Ikki xonali songa bo‘lish. Tanlash ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Bo‘linmani topish — topishmoq kabi', 'Найти частное — как разгадать загадку', 'Finding the quotient is like solving a riddle'), p: [
      L('Bir xonali songa bo‘lishda ko‘paytirish jadvalidan foydalanamiz: 56 : 7 = 8, chunki 7 · 8 = 56. Lekin 2 280 : 38 ni qanday topamiz? Jadvalda 38 yo‘q! Bu yerda yangi ko‘nikma kerak — bo‘linmani <b>tanlash</b>, ya’ni aqlli taxmin qilish va tekshirish.', 'При делении на однозначное число мы пользуемся таблицей умножения: 56 : 7 = 8, потому что 7 · 8 = 56. А как найти 2 280 : 38? В таблице нет 38! Здесь нужен новый навык — <b>подбор</b> частного, то есть умная догадка и проверка.', 'When dividing by a one-digit number we use the times table: 56 : 7 = 8 because 7 · 8 = 56. But how do we find 2 280 : 38? There is no 38 in the table! We need a new skill — <b>estimating</b> the quotient: a smart guess followed by a check.'),
      L('Bu xuddi «issiq-sovuq» o‘yiniga o‘xshaydi: avval yaxlitlab taxmin qilamiz, keyin ko‘paytirib tekshiramiz, ko‘p bo‘lsa — kamaytiramiz, kam bo‘lsa — oshiramiz. Bir-ikki urinishda to‘g‘ri javobni topamiz.', 'Это похоже на игру «горячо-холодно»: сначала прикидываем, округлив числа, потом проверяем умножением; если много — уменьшаем, мало — увеличиваем. За одну-две попытки находим ответ.', 'It is like a game of “hot and cold”: first round the numbers and guess, then check by multiplying; too big — go lower, too small — go higher. In one or two tries we find the answer.'),
      L('Bu mavzuda ikki xonali songa bo‘lishning burchak usulini, bo‘linma raqamini tanlash va natijani ko‘paytirish orqali tekshirishni o‘rganamiz.', 'В этой теме мы изучим деление уголком на двузначное число, подбор цифры частного и проверку умножением.', 'In this topic we learn long division by a two-digit number, estimating each quotient digit and checking by multiplication.')
    ] },
    { kind: 'def', h: L('Bo‘lish komponentlari', 'Компоненты деления', 'The parts of division'), p: [
      L('<b>Bo‘linuvchi : bo‘luvchi = bo‘linma</b>. 2 280 : 38 = 60 da 2 280 — bo‘linuvchi, 38 — bo‘luvchi, 60 — bo‘linma. Bo‘lish ko‘paytirishga teskari amal: bo‘linma · bo‘luvchi = bo‘linuvchi.', '<b>Делимое : делитель = частное</b>. В 2 280 : 38 = 60 число 2 280 — делимое, 38 — делитель, 60 — частное. Деление — действие, обратное умножению: частное · делитель = делимое.', '<b>Dividend : divisor = quotient</b>. In 2 280 : 38 = 60, 2 280 is the dividend, 38 the divisor and 60 the quotient. Division undoes multiplication: quotient · divisor = dividend.'),
      L('<b>To‘liqsiz bo‘linuvchi</b> — burchak usulida har bir qadamda bo‘lish uchun ajratiladigan son qismi. U bo‘luvchidan kichik bo‘lmasligi kerak. <b>Qoldiq</b> — bo‘lishdan keyin ortib qolgan son; u doim bo‘luvchidan kichik.', '<b>Неполное делимое</b> — часть числа, которую на каждом шаге деления уголком выделяют для деления. Оно не должно быть меньше делителя. <b>Остаток</b> — число, оставшееся после деления; он всегда меньше делителя.', 'A <b>partial dividend</b> is the part of the number taken at each step of long division. It must not be smaller than the divisor. The <b>remainder</b> is what is left over; it is always smaller than the divisor.'),
      L('<b>Tanlash</b> — bo‘linma raqamini yaxlitlangan sonlar yordamida taxmin qilib, keyin ko‘paytirib tekshirish.', '<b>Подбор</b> — угадывание цифры частного с помощью округлённых чисел и проверка умножением.', '<b>Estimating</b> means guessing a quotient digit with rounded numbers and then checking it by multiplication.')
    ] },
    { kind: 'history', h: L('Bo‘lish — eng qiyin amal', 'Деление — самое трудное действие', 'Division: the hardest operation'), p: [
      L('O‘rta asrlarda bo‘lish shunchalik qiyin hisoblanganki, Yevropada uni faqat universitetlarda o‘rgatishgan. «Bo‘lishni bilgan odam — olim» degan gap bor edi. Bunga sabab — Rim raqamlari: ular bilan bo‘lish deyarli imkonsiz edi.', 'В Средние века деление считалось таким трудным, что в Европе его изучали только в университетах. Говорили: «Кто умеет делить — тот учёный». Причина — римские цифры: делить с ними было почти невозможно.', 'In the Middle Ages division was considered so hard that in Europe it was taught only at universities. People said, “whoever can divide is a scholar”. The reason was Roman numerals: dividing with them was nearly impossible.'),
      L('Xorazmiy va boshqa Sharq olimlari hind raqamlari bilan bo‘lish usullarini ancha oldin tushuntirib bergan. Ular chang taxtada (qum sepilgan taxtacha) hisoblashgan: raqamlarni barmoq bilan yozib, kerak bo‘lsa o‘chirishgan. Bunday usulda bo‘linuvchining raqamlari ishlov berilgan sari o‘chirilib borgan.', 'Аль-Хорезми и другие восточные учёные гораздо раньше объяснили способы деления с индийскими цифрами. Они считали на пылевой доске (дощечке, посыпанной песком): писали цифры пальцем и стирали, когда нужно. Цифры делимого стирались по мере работы.', 'Al-Khwarizmi and other scholars of the East had explained ways to divide with Indian numerals much earlier. They calculated on a dust board (a tablet sprinkled with sand): they wrote digits with a finger and wiped them out as needed. The digits of the dividend were erased as the work went on.'),
      L('Bugungi «burchak» usuli XV asrda Italiyada shakllangan. 1491-yilda Filippo Kalandri kitobida u hozirgiga juda o‘xshash ko‘rinishda bosilgan. Shundan keyin bo‘lish oddiy maktab o‘quvchisi ham bajara oladigan amalga aylandi.', 'Сегодняшний способ «уголком» сложился в Италии в XV веке. В 1491 году в книге Филиппо Каландри он напечатан почти в современном виде. После этого деление стало действием, доступным обычному школьнику.', 'Today’s long-division layout took shape in Italy in the 15th century. In 1491 it was printed almost in its modern form in a book by Filippo Calandri. After that, division became something any schoolchild could do.')
    ] },
    { kind: 'rule', h: L('Tanlash qoidasi', 'Правило подбора', 'The estimating rule'), list: [
      L('<b>Bo‘luvchini yaxlitlang:</b> 38 ≈ 40, 23 ≈ 20, 67 ≈ 70. 5 dan kichik birlik — pastga, 5 va undan katta — yuqoriga.', '<b>Округли делитель:</b> 38 ≈ 40, 23 ≈ 20, 67 ≈ 70. Единицы меньше 5 — вниз, 5 и больше — вверх.', '<b>Round the divisor:</b> 38 ≈ 40, 23 ≈ 20, 67 ≈ 70. Ones below 5 round down, 5 or more round up.'),
      L('<b>Taxmin qiling:</b> to‘liqsiz bo‘linuvchini yaxlitlangan songa bo‘ling. 228 : 40 ≈ 5 yoki 6 (40 · 5 = 200, 40 · 6 = 240).', '<b>Прикинь:</b> раздели неполное делимое на округлённое число. 228 : 40 ≈ 5 или 6 (40 · 5 = 200, 40 · 6 = 240).', '<b>Guess:</b> divide the partial dividend by the rounded number. 228 : 40 ≈ 5 or 6 (40 · 5 = 200, 40 · 6 = 240).'),
      L('<b>Tekshiring:</b> haqiqiy bo‘luvchiga ko‘paytiring. 38 · 6 = 228 — aniq teng! Agar ko‘paytma to‘liqsiz bo‘linuvchidan katta chiqsa — raqamni 1 ga kamaytiring.', '<b>Проверь:</b> умножь на настоящий делитель. 38 · 6 = 228 — точно! Если произведение больше неполного делимого — уменьши цифру на 1.', '<b>Check:</b> multiply by the real divisor. 38 · 6 = 228 — exact! If the product is bigger than the partial dividend, lower the digit by 1.'),
      L('<b>Qoldiqni nazorat qiling:</b> ayirgandan keyingi qoldiq bo‘luvchidan kichik bo‘lishi shart. Katta bo‘lsa — raqamni 1 ga oshiring.', '<b>Следи за остатком:</b> остаток после вычитания обязан быть меньше делителя. Если больше — увеличь цифру на 1.', '<b>Watch the remainder:</b> after subtracting, it must be smaller than the divisor. If not, raise the digit by 1.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 2 280 : 38', 'Пошагово: 2 280 : 38', 'Step by step: 2 280 : 38'), list: [
      L('<b>1-to‘liqsiz bo‘linuvchi:</b> 2 < 38, 22 < 38, 228 ≥ 38. Demak, 228 ni olamiz. Bo‘linuvchida 228 dan keyin yana bitta raqam (0) bor, shuning uchun bo‘linmada <b>ikkita</b> raqam bo‘ladi.', '<b>1-е неполное делимое:</b> 2 < 38, 22 < 38, 228 ≥ 38. Берём 228. После 228 в делимом ещё одна цифра (0), поэтому в частном будет <b>две</b> цифры.', '<b>1st partial dividend:</b> 2 < 38, 22 < 38, 228 ≥ 38. Take 228. One more digit (0) follows, so the quotient will have <b>two</b> digits.'),
      L('<b>Tanlaymiz:</b> 38 ≈ 40, 228 : 40 ≈ 5. Sinab ko‘ramiz: 38 · 5 = 190, 228 − 190 = 38 — qoldiq bo‘luvchiga teng, demak 5 kam! 38 · 6 = 228. Raqam — <b>6</b>.', '<b>Подбираем:</b> 38 ≈ 40, 228 : 40 ≈ 5. Пробуем: 38 · 5 = 190, 228 − 190 = 38 — остаток равен делителю, значит 5 мало! 38 · 6 = 228. Цифра — <b>6</b>.', '<b>Estimate:</b> 38 ≈ 40, 228 : 40 ≈ 5. Try: 38 · 5 = 190, 228 − 190 = 38 — the remainder equals the divisor, so 5 is too small! 38 · 6 = 228. The digit is <b>6</b>.'),
      L('<b>Ayiramiz:</b> 228 − 228 = 0. Keyingi raqam 0 ni tushiramiz: 0. 0 : 38 = 0 — bo‘linmaga <b>0</b> yozamiz.', '<b>Вычитаем:</b> 228 − 228 = 0. Сносим следующую цифру 0: 0. 0 : 38 = 0 — пишем в частное <b>0</b>.', '<b>Subtract:</b> 228 − 228 = 0. Bring down the next digit 0: 0. 0 : 38 = 0 — write <b>0</b> in the quotient.'),
      L('<b>Javob:</b> 60. <b>Tekshiruv:</b> 38 · 60 = 2 280. To‘g‘ri!', '<b>Ответ:</b> 60. <b>Проверка:</b> 38 · 60 = 2 280. Верно!', '<b>Answer:</b> 60. <b>Check:</b> 38 · 60 = 2 280. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '8 400 : 12', s: L('Nollarni hisobga olib: 84 : 12 = 7 (12 · 7 = 84). Bo‘linuvchida 84 dan keyin ikkita nol — bo‘linmaga ham ikkita nol: <b>700</b>. Tekshiruv: 12 · 700 = 8 400.', 'С учётом нулей: 84 : 12 = 7 (12 · 7 = 84). После 84 в делимом два нуля — в частном тоже два нуля: <b>700</b>. Проверка: 12 · 700 = 8 400.', 'Using the zeros: 84 : 12 = 7 (12 · 7 = 84). Two zeros follow 84 in the dividend, so two zeros in the quotient: <b>700</b>. Check: 12 · 700 = 8 400.') },
      { q: '1 512 : 24', s: L('1-to‘liqsiz: 151. 24 ≈ 20, 151 : 20 ≈ 7. 24 · 7 = 168 > 151 — ko‘p! 24 · 6 = 144. 151 − 144 = 7. 2 ni tushiramiz: 72. 72 : 24 = 3. Javob: <b>63</b>. Tekshiruv: 24 · 63 = 1 512.', '1-е неполное: 151. 24 ≈ 20, 151 : 20 ≈ 7. 24 · 7 = 168 > 151 — много! 24 · 6 = 144. 151 − 144 = 7. Сносим 2: 72. 72 : 24 = 3. Ответ: <b>63</b>. Проверка: 24 · 63 = 1 512.', '1st partial: 151. 24 ≈ 20, 151 : 20 ≈ 7. 24 · 7 = 168 > 151 — too much! 24 · 6 = 144. 151 − 144 = 7. Bring down 2: 72. 72 : 24 = 3. Answer: <b>63</b>. Check: 24 · 63 = 1 512.') },
      { q: '4 897 : 59', s: L('1-to‘liqsiz: 489. 59 ≈ 60, 489 : 60 ≈ 8. 59 · 8 = 472. 489 − 472 = 17. 7 ni tushiramiz: 177. 177 : 60 ≈ 3, 59 · 3 = 177. Javob: <b>83</b>. Tekshiruv: 59 · 83 = 4 897.', '1-е неполное: 489. 59 ≈ 60, 489 : 60 ≈ 8. 59 · 8 = 472. 489 − 472 = 17. Сносим 7: 177. 177 : 60 ≈ 3, 59 · 3 = 177. Ответ: <b>83</b>. Проверка: 59 · 83 = 4 897.', '1st partial: 489. 59 ≈ 60, 489 : 60 ≈ 8. 59 · 8 = 472. 489 − 472 = 17. Bring down 7: 177. 177 : 60 ≈ 3, 59 · 3 = 177. Answer: <b>83</b>. Check: 59 · 83 = 4 897.') },
      { q: L('Jo‘mrakdan har daqiqada 18 l suv oqadi. 630 l suv necha daqiqada oqib chiqadi?', 'Из крана каждую минуту вытекает 18 л воды. За сколько минут вытечет 630 л?', 'A tap runs 18 l of water a minute. How many minutes for 630 l?'), s: L('630 : 18. 1-to‘liqsiz: 63. 63 : 20 ≈ 3, 18 · 3 = 54, 63 − 54 = 9. 0 ni tushiramiz: 90. 90 : 18 = 5. Javob: <b>35 daqiqa</b>. Tekshiruv: 18 · 35 = 630.', '630 : 18. 1-е неполное: 63. 63 : 20 ≈ 3, 18 · 3 = 54, 63 − 54 = 9. Сносим 0: 90. 90 : 18 = 5. Ответ: <b>35 минут</b>. Проверка: 18 · 35 = 630.', '630 : 18. 1st partial: 63. 63 : 20 ≈ 3, 18 · 3 = 54, 63 − 54 = 9. Bring down 0: 90. 90 : 18 = 5. Answer: <b>35 minutes</b>. Check: 18 · 35 = 630.') }
    ] },
    { kind: 'table', h: L('Taxmin va haqiqat', 'Прикидка и результат', 'Guess and result'), p: [
      L('Jadvalda taxminiy raqam qachon to‘g‘ri chiqib, qachon tuzatilishi kerakligi ko‘rsatilgan.', 'В таблице показано, когда прикидка сразу верна, а когда её нужно поправить.', 'The table shows when the guessed digit is right at once and when it needs fixing.')
    ], table: { head: [L('To‘liqsiz : bo‘luvchi', 'Неполное : делитель', 'Partial : divisor'), L('Taxmin', 'Прикидка', 'Guess'), L('Tekshiruv', 'Проверка', 'Check'), L('Raqam', 'Цифра', 'Digit')], rows: [
      ['228 : 38', '228 : 40 ≈ 5', L('38 · 5 = 190, qoldiq 38 — kam', '38 · 5 = 190, ост. 38 — мало', '38 · 5 = 190, rem. 38 — low'), '6'],
      ['151 : 24', '151 : 20 ≈ 7', L('24 · 7 = 168 — ko‘p', '24 · 7 = 168 — много', '24 · 7 = 168 — high'), '6'],
      ['489 : 59', '489 : 60 ≈ 8', L('59 · 8 = 472 — to‘g‘ri', '59 · 8 = 472 — верно', '59 · 8 = 472 — right'), '8'],
      ['92 : 23', '92 : 20 ≈ 4', L('23 · 4 = 92 — to‘g‘ri', '23 · 4 = 92 — верно', '23 · 4 = 92 — right'), '4']
    ] }, after: [
      L('Bo‘luvchini yuqoriga yaxlitlasak (38 → 40), taxmin ko‘pincha <b>kam</b> chiqadi; pastga yaxlitlasak (24 → 20) — <b>ko‘p</b> chiqadi. Buni bilsangiz, tuzatish oson.', 'Если округлили делитель вверх (38 → 40), прикидка часто выходит <b>меньше</b>; вниз (24 → 20) — <b>больше</b>. Зная это, легко поправить.', 'Rounding the divisor up (38 → 40) often makes the guess too <b>low</b>; rounding down (24 → 20) makes it too <b>high</b>. Knowing this makes fixing easy.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Bo‘linmadagi nolni yo‘qotish.</b> 2 280 : 38 = 6 deb javob berish. Tushirilgan raqam bo‘luvchidan kichik bo‘lsa, bo‘linmaga 0 yoziladi: 60.', '<b>Потерять нуль в частном.</b> Ответить 2 280 : 38 = 6. Если снесённое число меньше делителя, в частное пишем 0: 60.', '<b>Losing a zero in the quotient.</b> Answering 2 280 : 38 = 6. If the brought-down number is smaller than the divisor, write 0 in the quotient: 60.'),
      L('<b>Qoldiq bo‘luvchidan katta.</b> 151 − 24 · 5 = 31 qoldiq — 31 > 24, demak raqam kam tanlangan. Qoldiq doim bo‘luvchidan kichik!', '<b>Остаток больше делителя.</b> 151 − 24 · 5 = 31 — 31 > 24, значит, цифра подобрана мала. Остаток всегда меньше делителя!', '<b>Remainder bigger than the divisor.</b> 151 − 24 · 5 = 31 — 31 > 24, so the digit was too small. The remainder is always smaller than the divisor!'),
      L('<b>Bo‘linma raqamlari sonini noto‘g‘ri aniqlash.</b> Oldindan sanang: 1-to‘liqsiz bo‘linuvchidan keyin nechta raqam qolsa, bo‘linmada shuncha + 1 raqam bo‘ladi.', '<b>Неверно определить число цифр частного.</b> Считай заранее: сколько цифр осталось после 1-го неполного делимого, столько + 1 цифр будет в частном.', '<b>Misjudging the quotient’s length.</b> Count in advance: the digits left after the 1st partial dividend, plus 1, give the number of digits in the quotient.'),
      L('<b>Tekshirmaslik.</b> Har bir javobni ko‘paytirib tekshiring — bu 10 soniya oladi, ammo bahoni saqlaydi.', '<b>Не проверять.</b> Проверяй каждый ответ умножением — это 10 секунд, но они спасают оценку.', '<b>Not checking.</b> Check every answer by multiplying — it takes ten seconds and saves your mark.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Avtobusga joylashtirish.</b> 1 344 nafar sayyoh 42 o‘rinli avtobuslarda ketadi. Nechta avtobus kerak? 1 344 : 42 = 32 ta. Tashkilotchilar shunday hisob bilan transport buyurtma qiladi.', '<b>Рассадка по автобусам.</b> 1 344 туриста едут в 42-местных автобусах. Сколько нужно автобусов? 1 344 : 42 = 32. Организаторы заказывают транспорт по такому расчёту.', '<b>Seating on buses.</b> 1 344 tourists travel in 42-seat buses. How many buses? 1 344 : 42 = 32. Organisers book transport with this calculation.'),
      L('<b>Oylik maosh.</b> Yillik daromad 36 000 000 so‘m bo‘lsa, oyiga qancha? 36 000 000 : 12 = 3 000 000 so‘m.', '<b>Месячная зарплата.</b> Если годовой доход 36 000 000 сум, сколько в месяц? 36 000 000 : 12 = 3 000 000 сум.', '<b>Monthly pay.</b> If yearly income is 36 000 000 sum, what is it per month? 36 000 000 : 12 = 3 000 000 sum.'),
      L('<b>Sport musobaqasi.</b> 96 nafar sportchi 16 ta jamoaga teng bo‘linadi: 96 : 16 = 6 nafardan. Futbol turnirlarida guruhlar aynan shunday tuziladi.', '<b>Соревнования.</b> 96 спортсменов делят поровну на 16 команд: 96 : 16 = по 6. Так формируют группы на турнирах.', '<b>A competition.</b> 96 athletes are split equally into 16 teams: 96 : 16 = 6 each. Tournament groups are made this way.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Bo‘lish belgisi «÷» (obelus) ni 1659-yilda shveytsariyalik Yohann Ran ishlatgan. Biz esa Leybnits taklif qilgan «:» belgisidan foydalanamiz.', 'Знак деления «÷» (обелюс) в 1659 году использовал швейцарец Иоганн Ран. А мы пользуемся знаком «:», предложенным Лейбницем.', 'The division sign “÷” (obelus) was used in 1659 by the Swiss Johann Rahn. We use the “:” sign suggested by Leibniz.'),
      L('Kompyuter protsessorlarida bo‘lish ko‘paytirishdan bir necha barobar sekin ishlaydi — chunki ular ham bizga o‘xshab «tanlash» qadamlarini bajaradi.', 'В процессорах компьютеров деление выполняется в несколько раз медленнее умножения — ведь они тоже, как мы, делают шаги «подбора».', 'In computer processors division is several times slower than multiplication — because, like us, they carry out “estimating” steps.'),
      L('1 001 = 7 · 11 · 13. Shuning uchun abcabc ko‘rinishidagi har qanday son (masalan, 245 245) 7 ga, 11 ga va 13 ga bo‘linadi.', '1 001 = 7 · 11 · 13. Поэтому любое число вида abcabc (например, 245 245) делится на 7, 11 и 13.', '1 001 = 7 · 11 · 13. So any number of the form abcabc (e.g. 245 245) divides by 7, 11 and 13.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 2 976 : 48.', 'Вычисли: 2 976 : 48.', 'Work out: 2 976 : 48.'),
      L('Hisoblang: 7 225 : 85.', 'Вычисли: 7 225 : 85.', 'Work out: 7 225 : 85.'),
      L('Bir qutiga 24 ta tuxum sig‘adi. 1 080 ta tuxum uchun nechta quti kerak?', 'В коробку помещается 24 яйца. Сколько коробок нужно для 1 080 яиц?', 'A box holds 24 eggs. How many boxes are needed for 1 080 eggs?')
    ], after: [
      L('Javoblar: 1) 62 (48 · 62 = 2 976); 2) 85 (85 · 85 = 7 225); 3) 45 ta quti.', 'Ответы: 1) 62 (48 · 62 = 2 976); 2) 85 (85 · 85 = 7 225); 3) 45 коробок.', 'Answers: 1) 62 (48 · 62 = 2 976); 2) 85 (85 · 85 = 7 225); 3) 45 boxes.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Bo‘linuvchi : bo‘luvchi = bo‘linma; tekshiruv: bo‘linma · bo‘luvchi = bo‘linuvchi.', 'Делимое : делитель = частное; проверка: частное · делитель = делимое.', 'Dividend : divisor = quotient; check: quotient · divisor = dividend.'),
      L('Avval 1-to‘liqsiz bo‘linuvchini ajratib, bo‘linmadagi raqamlar sonini aniqlang.', 'Сначала выдели 1-е неполное делимое и определи число цифр частного.', 'First take the 1st partial dividend and work out how many digits the quotient has.'),
      L('Raqamni bo‘luvchini yaxlitlab tanlang va ko‘paytirib tekshiring.', 'Подбирай цифру, округлив делитель, и проверяй умножением.', 'Estimate each digit by rounding the divisor and check by multiplying.'),
      L('Ko‘paytma katta bo‘lsa — raqamni kamaytiring; qoldiq bo‘luvchidan katta bo‘lsa — oshiring.', 'Произведение больше — уменьши цифру; остаток больше делителя — увеличь.', 'Product too big — lower the digit; remainder too big — raise it.'),
      L('Tushirilgan son bo‘luvchidan kichik bo‘lsa, bo‘linmaga 0 yozing.', 'Если снесённое число меньше делителя — пиши в частное 0.', 'If the brought-down number is smaller than the divisor, write 0 in the quotient.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t13. Uch xonali songa bo‘lish ----------
  T.add(P, 't13', { sections: [
    { kind: 'intro', h: L('Katta bo‘luvchi — o‘sha usul', 'Делитель больше — способ тот же', 'Bigger divisor, same method'), p: [
      L('Ikki xonali songa bo‘lishni o‘rgandik: to‘liqsiz bo‘linuvchini ajratamiz, raqamni tanlaymiz, ko‘paytirib ayiramiz va keyingi raqamni tushiramiz. Yaxshi xabar: uch xonali songa bo‘lish ham <b>xuddi shu</b> qadamlardan iborat! Faqat sonlar biroz kattaroq va tanlash ko‘proq diqqat talab qiladi.', 'Мы научились делить на двузначное число: выделяем неполное делимое, подбираем цифру, умножаем, вычитаем и сносим следующую цифру. Хорошая новость: деление на трёхзначное число состоит из <b>тех же</b> шагов! Только числа немного больше, а подбор требует внимания.', 'We have learned to divide by a two-digit number: take a partial dividend, estimate a digit, multiply, subtract and bring down the next digit. Good news: dividing by a three-digit number uses <b>the same</b> steps! The numbers are just a bit bigger and estimating needs more care.'),
      L('Masalan, zavod 14 336 ta shisha idishni 256 tadan qutilarga joylashtirmoqchi. Nechta quti kerak? 14 336 : 256 — bu uch xonali songa bo‘lish. Javob 56 ekanini bu mavzu oxirida osongina topa olasiz.', 'Например, завод хочет упаковать 14 336 стеклянных банок по 256 штук в коробку. Сколько коробок нужно? 14 336 : 256 — это деление на трёхзначное число. К концу темы ты легко найдёшь ответ: 56.', 'For example, a factory wants to pack 14 336 glass jars in boxes of 256. How many boxes are needed? 14 336 : 256 is division by a three-digit number. By the end of this topic you will easily find the answer: 56.'),
      L('Bu mavzuda bo‘luvchini yuzliklarga yaxlitlab tanlash, yaxlit sonlarga bo‘lish va natijani tekshirishni o‘rganamiz.', 'В этой теме мы учимся подбирать цифру, округляя делитель до сотен, делить круглые числа и проверять ответ.', 'In this topic we learn to estimate by rounding the divisor to hundreds, to divide round numbers and to check the answer.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('Uch xonali songa bo‘lishda <b>1-to‘liqsiz bo‘linuvchi</b> kamida uch, ko‘pincha to‘rt xonali bo‘ladi. 14 336 : 256 da: 1 < 256, 14 < 256, 143 < 256, 1 433 ≥ 256. Demak, 1-to‘liqsiz bo‘linuvchi — 1 433.', 'При делении на трёхзначное число <b>1-е неполное делимое</b> — не меньше трёхзначного, часто четырёхзначное. В 14 336 : 256: 1 < 256, 14 < 256, 143 < 256, 1 433 ≥ 256. Значит, 1-е неполное делимое — 1 433.', 'When dividing by a three-digit number the <b>1st partial dividend</b> has at least three digits, often four. In 14 336 : 256: 1 < 256, 14 < 256, 143 < 256, 1 433 ≥ 256. So the 1st partial dividend is 1 433.'),
      L('<b>Bo‘linmadagi raqamlar soni</b> = 1-to‘liqsiz bo‘linuvchidan keyin qolgan raqamlar soni + 1. 1 433 dan keyin bitta raqam (6) qoldi, demak bo‘linma ikki xonali. Buni oldindan bilish xatodan saqlaydi.', '<b>Число цифр частного</b> = число цифр, оставшихся после 1-го неполного делимого, + 1. После 1 433 осталась одна цифра (6), значит, частное двузначное. Знать это заранее — защита от ошибок.', '<b>Digits in the quotient</b> = digits left after the 1st partial dividend + 1. After 1 433 one digit (6) is left, so the quotient has two digits. Knowing this in advance prevents mistakes.'),
      L('<b>Yaxlit yuzlikka yaxlitlash:</b> 256 ≈ 300 (56 > 50, yuqoriga), 214 ≈ 200 (14 < 50, pastga). Yaxlitlangan son bilan taxmin qilish oson: 1 433 : 300 ≈ 4 yoki 5.', '<b>Округление до сотен:</b> 256 ≈ 300 (56 > 50, вверх), 214 ≈ 200 (14 < 50, вниз). С округлённым числом прикидывать легко: 1 433 : 300 ≈ 4 или 5.', '<b>Rounding to hundreds:</b> 256 ≈ 300 (56 > 50, up), 214 ≈ 200 (14 < 50, down). Guessing with the rounded number is easy: 1 433 : 300 ≈ 4 or 5.')
    ] },
    { kind: 'history', h: L('Beruniy va ulkan hisoblar', 'Беруни и огромные вычисления', 'Biruni and huge calculations'), p: [
      L('<b>Abu Rayhon Beruniy</b> (973–1048) Xorazmning Kat shahrida tug‘ilgan. U astronomiya, geografiya, fizika va matematikada 150 dan ortiq asar yozgan. Beruniy Yer radiusini tog‘ cho‘qqisidan ufqqa qarab o‘lchash usulini o‘ylab topgan va natijasi hozirgi qiymatdan bir necha foizgina farq qilgan.', '<b>Абу Райхан Беруни</b> (973–1048) родился в городе Кят в Хорезме. Он написал более 150 трудов по астрономии, географии, физике и математике. Беруни придумал способ измерить радиус Земли, наблюдая горизонт с вершины горы, и его результат отличался от современного всего на несколько процентов.', '<b>Abu Rayhan Biruni</b> (973–1048) was born in the town of Kath in Khwarezm. He wrote more than 150 works on astronomy, geography, physics and mathematics. Biruni devised a way to measure the Earth’s radius by observing the horizon from a mountain top, and his result was only a few per cent off the modern value.'),
      L('Beruniy shaxmat taxtasi haqidagi mashhur masalani ham hisoblagan: birinchi katakka 1 ta bug‘doy, ikkinchisiga 2 ta, uchinchisiga 4 ta va hokazo, har gal ikki barobar. 64 katakdagi jami bug‘doy soni 20 xonali son bo‘ladi: 18 446 744 073 709 551 615! Beruniy bu sonni xatosiz topgan.', 'Беруни решил и знаменитую задачу о шахматной доске: на первую клетку 1 зерно, на вторую 2, на третью 4 и так далее, каждый раз вдвое больше. Всего зёрен на 64 клетках — 20-значное число: 18 446 744 073 709 551 615! Беруни нашёл его без ошибок.', 'Biruni also solved the famous chessboard problem: 1 grain on the first square, 2 on the second, 4 on the third and so on, doubling each time. The total on all 64 squares is a 20-digit number: 18 446 744 073 709 551 615! Biruni found it without a mistake.'),
      L('Bunday ishlarda katta sonlarni ko‘paytirish va bo‘lish asosiy vosita edi. Beruniy hisoblarida bo‘linmani tanlash va tekshirish usulini doimo qo‘llagan — xuddi siz hozir o‘rganayotganingiz kabi.', 'В таких работах умножение и деление больших чисел были главным инструментом. Беруни постоянно применял подбор частного и проверку — точно так, как ты учишься сейчас.', 'In such work, multiplying and dividing big numbers was the main tool. Biruni constantly used estimating and checking the quotient — just as you are learning now.')
    ] },
    { kind: 'rule', h: L('Qoida', 'Правило', 'The rule'), list: [
      L('<b>1.</b> 1-to‘liqsiz bo‘linuvchini ajrating va bo‘linmadagi raqamlar sonini aniqlang.', '<b>1.</b> Выдели 1-е неполное делимое и определи число цифр частного.', '<b>1.</b> Take the 1st partial dividend and find the number of quotient digits.'),
      L('<b>2.</b> Bo‘luvchini yuzliklarga yaxlitlang va raqamni taxmin qiling. Qulay usul: to‘liqsiz bo‘linuvchining yuzliklarini bo‘luvchining yuzliklariga bo‘ling (1 433 : 256 → 14 : 3 ≈ 4).', '<b>2.</b> Округли делитель до сотен и прикинь цифру. Удобно: сотни неполного делимого раздели на сотни делителя (1 433 : 256 → 14 : 3 ≈ 4).', '<b>2.</b> Round the divisor to hundreds and guess the digit. Handy: divide the hundreds of the partial dividend by the hundreds of the divisor (1 433 : 256 → 14 : 3 ≈ 4).'),
      L('<b>3.</b> Bo‘luvchini raqamga ko‘paytiring va ayiring. Qoldiq bo‘luvchidan kichik bo‘lishi shart.', '<b>3.</b> Умножь делитель на цифру и вычти. Остаток обязан быть меньше делителя.', '<b>3.</b> Multiply the divisor by the digit and subtract. The remainder must be smaller than the divisor.'),
      L('<b>4.</b> Keyingi raqamni tushiring va 2–3 qadamni takrorlang.', '<b>4.</b> Снеси следующую цифру и повтори шаги 2–3.', '<b>4.</b> Bring down the next digit and repeat steps 2–3.'),
      L('<b>5.</b> Ko‘paytirib tekshiring: bo‘linma · bo‘luvchi (+ qoldiq) = bo‘linuvchi.', '<b>5.</b> Проверь умножением: частное · делитель (+ остаток) = делимое.', '<b>5.</b> Check by multiplying: quotient · divisor (+ remainder) = dividend.')
    ], after: [
      L('<b>Yaxlit sonlar:</b> bo‘linuvchi va bo‘luvchidan bir xil miqdordagi nollarni olib tashlash mumkin: 2 400 : 200 = 24 : 2 = 12; 36 000 : 400 = 360 : 4 = 90.', '<b>Круглые числа:</b> у делимого и делителя можно отбросить одинаковое число нулей: 2 400 : 200 = 24 : 2 = 12; 36 000 : 400 = 360 : 4 = 90.', '<b>Round numbers:</b> you may drop the same number of zeros from the dividend and the divisor: 2 400 : 200 = 24 : 2 = 12; 36 000 : 400 = 360 : 4 = 90.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 14 336 : 256', 'Пошагово: 14 336 : 256', 'Step by step: 14 336 : 256'), list: [
      L('<b>1-to‘liqsiz:</b> 1 433. Undan keyin bitta raqam qoldi — bo‘linma <b>ikki xonali</b>.', '<b>1-е неполное:</b> 1 433. После него осталась одна цифра — частное <b>двузначное</b>.', '<b>1st partial:</b> 1 433. One digit is left — the quotient has <b>two digits</b>.'),
      L('<b>Tanlaymiz:</b> 256 ≈ 300, 1 433 : 300 ≈ 4. 256 · 4 = 1 024. 1 433 − 1 024 = 409 — bu 256 dan katta! Demak, 4 kam. 256 · 5 = 1 280. 1 433 − 1 280 = 153 < 256. Raqam — <b>5</b>.', '<b>Подбираем:</b> 256 ≈ 300, 1 433 : 300 ≈ 4. 256 · 4 = 1 024. 1 433 − 1 024 = 409 — больше 256! Значит, 4 мало. 256 · 5 = 1 280. 1 433 − 1 280 = 153 < 256. Цифра — <b>5</b>.', '<b>Estimate:</b> 256 ≈ 300, 1 433 : 300 ≈ 4. 256 · 4 = 1 024. 1 433 − 1 024 = 409 — bigger than 256! So 4 is too small. 256 · 5 = 1 280. 1 433 − 1 280 = 153 < 256. The digit is <b>5</b>.'),
      L('<b>Tushiramiz:</b> 6 ni tushiramiz — 1 536.', '<b>Сносим:</b> сносим 6 — 1 536.', '<b>Bring down:</b> bring down 6 — 1 536.'),
      L('<b>Tanlaymiz:</b> 1 536 : 300 ≈ 5, lekin 256 · 5 = 1 280, qoldiq 256 — teng, kam! 256 · 6 = 1 536. Qoldiq 0. Raqam — <b>6</b>.', '<b>Подбираем:</b> 1 536 : 300 ≈ 5, но 256 · 5 = 1 280, остаток 256 — равен делителю, мало! 256 · 6 = 1 536. Остаток 0. Цифра — <b>6</b>.', '<b>Estimate:</b> 1 536 : 300 ≈ 5, but 256 · 5 = 1 280 leaves 256 — equal to the divisor, too small! 256 · 6 = 1 536. Remainder 0. The digit is <b>6</b>.'),
      L('<b>Javob:</b> 56. <b>Tekshiruv:</b> 256 · 56 = 14 336. To‘g‘ri!', '<b>Ответ:</b> 56. <b>Проверка:</b> 256 · 56 = 14 336. Верно!', '<b>Answer:</b> 56. <b>Check:</b> 256 · 56 = 14 336. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '2 400 : 200', s: L('Ikkala sondan ikkita nolni olib tashlaymiz: 24 : 2 = <b>12</b>. Tekshiruv: 200 · 12 = 2 400.', 'Отбрасываем по два нуля: 24 : 2 = <b>12</b>. Проверка: 200 · 12 = 2 400.', 'Drop two zeros from each: 24 : 2 = <b>12</b>. Check: 200 · 12 = 2 400.') },
      { q: '8 772 : 172', s: L('1-to‘liqsiz: 877, bo‘linma ikki xonali. 172 ≈ 200, 877 : 200 ≈ 4; 172 · 4 = 688, 877 − 688 = 189 > 172 — kam. 172 · 5 = 860, qoldiq 17. 2 ni tushiramiz: 172. 172 : 172 = 1. Javob: <b>51</b>. Tekshiruv: 172 · 51 = 8 772.', '1-е неполное: 877, частное двузначное. 172 ≈ 200, 877 : 200 ≈ 4; 172 · 4 = 688, 877 − 688 = 189 > 172 — мало. 172 · 5 = 860, остаток 17. Сносим 2: 172. 172 : 172 = 1. Ответ: <b>51</b>. Проверка: 172 · 51 = 8 772.', '1st partial: 877, two-digit quotient. 172 ≈ 200, 877 : 200 ≈ 4; 172 · 4 = 688, 877 − 688 = 189 > 172 — too small. 172 · 5 = 860, remainder 17. Bring down 2: 172. 172 : 172 = 1. Answer: <b>51</b>. Check: 172 · 51 = 8 772.') },
      { q: '62 730 : 205', s: L('1-to‘liqsiz: 627, bo‘linma uch xonali. 627 : 200 ≈ 3, 205 · 3 = 615, qoldiq 12. 3 ni tushiramiz: 123 < 205 — bo‘linmaga <b>0</b>. 0 ni tushiramiz: 1 230. 1 230 : 200 ≈ 6, 205 · 6 = 1 230. Javob: <b>306</b>. Tekshiruv: 205 · 306 = 62 730.', '1-е неполное: 627, частное трёхзначное. 627 : 200 ≈ 3, 205 · 3 = 615, остаток 12. Сносим 3: 123 < 205 — в частное <b>0</b>. Сносим 0: 1 230. 1 230 : 200 ≈ 6, 205 · 6 = 1 230. Ответ: <b>306</b>. Проверка: 205 · 306 = 62 730.', '1st partial: 627, three-digit quotient. 627 : 200 ≈ 3, 205 · 3 = 615, remainder 12. Bring down 3: 123 < 205 — write <b>0</b>. Bring down 0: 1 230. 1 230 : 200 ≈ 6, 205 · 6 = 1 230. Answer: <b>306</b>. Check: 205 · 306 = 62 730.') },
      { q: L('Zavod 14 336 ta shisha bankani 256 tadan qutilarga joyladi. Nechta quti kerak bo‘ldi?', 'Завод упаковал 14 336 стеклянных банок по 256 в коробку. Сколько коробок понадобилось?', 'A factory packed 14 336 glass jars, 256 to a box. How many boxes were needed?'), s: L('14 336 : 256. Yuqoridagi bosqichlardagidek: 1 433 dan 5, 1 536 dan 6. Javob: <b>56 ta quti</b>. Tekshiruv: 256 · 56 = 14 336 — ortiqcha banka qolmadi.', '14 336 : 256. Как в шагах выше: из 1 433 — 5, из 1 536 — 6. Ответ: <b>56 коробок</b>. Проверка: 256 · 56 = 14 336 — лишних банок не осталось.', '14 336 : 256. As in the steps above: 5 from 1 433, 6 from 1 536. Answer: <b>56 boxes</b>. Check: 256 · 56 = 14 336 — no jars left over.') }
    ] },
    { kind: 'table', h: L('Yaxlit sonlarga bo‘lish', 'Деление круглых чисел', 'Dividing round numbers'), table: { head: [L('Misol', 'Пример', 'Example'), L('Nollarni olib tashlaymiz', 'Отбрасываем нули', 'Drop zeros'), L('Javob', 'Ответ', 'Answer')], rows: [
      ['2 400 : 200', '24 : 2', '12'],
      ['36 000 : 400', '360 : 4', '90'],
      ['48 000 : 600', '480 : 6', '80'],
      ['150 000 : 500', '1 500 : 5', '300'],
      ['72 000 : 900', '720 : 9', '80']
    ] }, after: [
      L('Nega bu mumkin? Bo‘linuvchi va bo‘luvchini bir xil songa (10, 100) bo‘lsak, bo‘linma o‘zgarmaydi. Bu bo‘lishning muhim xossasi: 2 400 : 200 = 240 : 20 = 24 : 2.', 'Почему так можно? Если делимое и делитель разделить на одно и то же число (10, 100), частное не изменится. Это важное свойство деления: 2 400 : 200 = 240 : 20 = 24 : 2.', 'Why is this allowed? Dividing both the dividend and the divisor by the same number (10, 100) does not change the quotient. This is a key property: 2 400 : 200 = 240 : 20 = 24 : 2.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>1-to‘liqsiz bo‘linuvchini kichik olish.</b> 14 336 : 256 da 143 ni olish — 143 < 256, bo‘lib bo‘lmaydi. Bo‘luvchidan kichik bo‘lmagan birinchi qismni oling: 1 433.', '<b>Взять слишком маленькое неполное делимое.</b> В 14 336 : 256 взять 143 — 143 < 256, делить нельзя. Бери первую часть, не меньшую делителя: 1 433.', '<b>Taking too small a partial dividend.</b> Taking 143 in 14 336 : 256 — 143 < 256, it will not divide. Take the first part not smaller than the divisor: 1 433.'),
      L('<b>O‘rtadagi nolni tashlab ketish.</b> 62 730 : 205 = 36 deyish. 123 < 205 bo‘lganda bo‘linmaga 0 yozish shart: 306.', '<b>Пропустить нуль в середине.</b> Сказать 62 730 : 205 = 36. Когда 123 < 205, в частное обязательно пишем 0: 306.', '<b>Skipping a middle zero.</b> Saying 62 730 : 205 = 36. When 123 < 205 you must write 0 in the quotient: 306.'),
      L('<b>Nollarni bir tomondan olib tashlash.</b> 2 400 : 200 da faqat bo‘linuvchidan nol olib tashlab, 24 : 200 qilish. Nollar <b>ikkalasidan teng</b> olib tashlanadi.', '<b>Отбрасывать нули только у одного числа.</b> В 2 400 : 200 убрать нули только у делимого: 24 : 200. Нули отбрасывают <b>у обоих поровну</b>.', '<b>Dropping zeros from one side only.</b> Turning 2 400 : 200 into 24 : 200. Zeros are dropped <b>equally from both</b>.'),
      L('<b>Qoldiqni tekshirmaslik.</b> 1 433 − 1 024 = 409 qoldiqni qabul qilish. 409 > 256 — raqam kam! Har doim qoldiqni bo‘luvchi bilan solishtiring.', '<b>Не проверять остаток.</b> Принять остаток 1 433 − 1 024 = 409. 409 > 256 — цифра мала! Всегда сравнивай остаток с делителем.', '<b>Not checking the remainder.</b> Accepting 1 433 − 1 024 = 409. 409 > 256 — the digit is too small! Always compare the remainder with the divisor.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Zavodda.</b> Konserva zavodi kuniga 36 000 ta banka chiqaradi va ularni 120 tadan qutiga joylaydi: 36 000 : 120 = 300 quti. Omborchi qancha joy kerakligini shu hisob bilan biladi.', '<b>На заводе.</b> Консервный завод выпускает 36 000 банок в день и упаковывает их по 120 в коробку: 36 000 : 120 = 300 коробок. Кладовщик по этому расчёту знает, сколько нужно места.', '<b>At a factory.</b> A cannery makes 36 000 jars a day and packs them 120 to a box: 36 000 : 120 = 300 boxes. The storekeeper knows how much space is needed from this.'),
      L('<b>Sayohatda.</b> Toshkentdan Xivagacha avtomobil yo‘li taxminan 1 000 km. Agar mashina 100 km ga 8 litr benzin sarflasa, jami 1 000 : 100 · 8 = 80 litr kerak.', '<b>В путешествии.</b> От Ташкента до Хивы по дороге около 1 000 км. Если машина тратит 8 литров на 100 км, нужно 1 000 : 100 · 8 = 80 литров.', '<b>Travelling.</b> The road from Tashkent to Khiva is about 1 000 km. If a car uses 8 litres per 100 km, it needs 1 000 : 100 · 8 = 80 litres.'),
      L('<b>Kutubxonada.</b> Kutubxonada 18 000 ta kitob bor, har bir javonga 150 ta sig‘adi. Javonlar soni: 18 000 : 150 = 120 ta.', '<b>В библиотеке.</b> В библиотеке 18 000 книг, на каждую полку помещается 150. Число полок: 18 000 : 150 = 120.', '<b>In a library.</b> A library has 18 000 books and each shelf holds 150. Shelves needed: 18 000 : 150 = 120.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Bir yilda 365 kun bor. 365 = 5 · 73 — ya’ni 365 ni faqat 1, 5, 73 va 365 ga qoldiqsiz bo‘lish mumkin. Shuning uchun yilni teng haftalarga bo‘lib bo‘lmaydi: 365 : 7 = 52 (qoldiq 1).', 'В году 365 дней. 365 = 5 · 73 — то есть 365 делится без остатка только на 1, 5, 73 и 365. Поэтому год нельзя разделить на целые недели: 365 : 7 = 52 (остаток 1).', 'A year has 365 days. 365 = 5 · 73, so it divides evenly only by 1, 5, 73 and 365. That is why a year is not a whole number of weeks: 365 : 7 = 52 remainder 1.'),
      L('Beruniy hisoblagan shaxmat bug‘doyini tashish uchun butun Yer yuzining ming yildan ortiq bug‘doy hosili kerak bo‘lardi!', 'Чтобы собрать всё зерно с шахматной доски Беруни, понадобился бы урожай пшеницы всей Земли более чем за тысячу лет!', 'Gathering all the grain from Biruni’s chessboard would take the whole world’s wheat harvest for more than a thousand years!'),
      L('1 000 000 : 1 001 ≈ 999. Shuning uchun 1 001 · 999 = 999 999 — bir milliondan bittagina kam!', '1 000 000 : 1 001 ≈ 999. И правда, 1 001 · 999 = 999 999 — всего на один меньше миллиона!', '1 000 000 : 1 001 ≈ 999. Indeed, 1 001 · 999 = 999 999 — just one short of a million!')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 9 728 : 128.', 'Вычисли: 9 728 : 128.', 'Work out: 9 728 : 128.'),
      L('Og‘zaki: 54 000 : 600 va 280 000 : 700.', 'Устно: 54 000 : 600 и 280 000 : 700.', 'Mentally: 54 000 : 600 and 280 000 : 700.'),
      L('Bir rulonda 150 m mato bor. 4 500 m mato nechta rulon?', 'В рулоне 150 м ткани. Сколько рулонов в 4 500 м?', 'A roll holds 150 m of cloth. How many rolls are 4 500 m?')
    ], after: [
      L('Javoblar: 1) 76 (128 · 76 = 9 728); 2) 90 va 400; 3) 30 ta rulon.', 'Ответы: 1) 76 (128 · 76 = 9 728); 2) 90 и 400; 3) 30 рулонов.', 'Answers: 1) 76 (128 · 76 = 9 728); 2) 90 and 400; 3) 30 rolls.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Uch xonali songa bo‘lish ham burchak usulida, xuddi ikki xonali kabi bajariladi.', 'Деление на трёхзначное число выполняется уголком так же, как на двузначное.', 'Dividing by a three-digit number uses long division just like a two-digit divisor.'),
      L('1-to‘liqsiz bo‘linuvchi bo‘luvchidan kichik bo‘lmasligi kerak.', '1-е неполное делимое не может быть меньше делителя.', 'The 1st partial dividend must not be smaller than the divisor.'),
      L('Raqamni bo‘luvchini yuzliklarga yaxlitlab tanlaymiz va tekshiramiz.', 'Цифру подбираем, округлив делитель до сотен, и проверяем.', 'Estimate each digit by rounding the divisor to hundreds, then check.'),
      L('Tushirilgan son bo‘luvchidan kichik bo‘lsa — bo‘linmaga 0.', 'Снесённое число меньше делителя — в частное 0.', 'Brought-down number smaller than the divisor — write 0.'),
      L('Yaxlit sonlarda ikkalasidan teng nollarni olib tashlaymiz.', 'У круглых чисел убираем у обоих одинаковое число нулей.', 'With round numbers, drop equal zeros from both.')
    ] }
  ] });

  // ---------- t14. Misol va masalalar: tenglamalar ----------
  T.add(P, 't14', { sections: [
    { kind: 'intro', h: L('Noma’lumni topamiz', 'Находим неизвестное', 'Finding the unknown'), p: [
      L('Men bir son o‘yladim. Undan 145 ni ayirib, natijani 5 ga bo‘ldim va 21 chiqdi. Qaysi sonni o‘yladim? Bu topishmoq aslida <b>tenglama</b>: (x − 145) : 5 = 21. Uni yechish uchun «orqaga» yuramiz: 21 ni 5 ga ko‘paytirib, 145 ni qo‘shamiz: 21 · 5 + 145 = 250. O‘ylangan son — 250!', 'Я задумал число. Вычел из него 145, результат разделил на 5 и получил 21. Какое число я задумал? Эта загадка на самом деле <b>уравнение</b>: (x − 145) : 5 = 21. Чтобы решить его, идём «назад»: 21 умножаем на 5 и прибавляем 145: 21 · 5 + 145 = 250. Задуманное число — 250!', 'I thought of a number. I subtracted 145, divided the result by 5 and got 21. What was my number? This riddle is really an <b>equation</b>: (x − 145) : 5 = 21. To solve it we walk “backwards”: multiply 21 by 5 and add 145: 21 · 5 + 145 = 250. The number was 250!'),
      L('Bu mavzuda biz o‘rgangan barcha amallarni — ko‘p xonali sonlarni ko‘paytirish va bo‘lishni — tenglamalar va murakkab masalalarda qo‘llaymiz. Masalalarni qismlarga bo‘lib, har birini alohida hisoblab, keyin taqqoslaymiz.', 'В этой теме мы применяем все изученные действия — умножение и деление многозначных чисел — в уравнениях и сложных задачах. Разбиваем задачу на части, считаем каждую отдельно, потом сравниваем.', 'In this topic we apply everything we have learned — multiplying and dividing large numbers — to equations and harder problems. We break a problem into parts, compute each one and then compare.'),
      L('Tenglama yechishni bilish — algebra olamiga birinchi qadam. Algebra esa yurtdoshimiz Xorazmiy nomi bilan chambarchas bog‘liq!', 'Умение решать уравнения — первый шаг в мир алгебры. А алгебра тесно связана с именем нашего земляка аль-Хорезми!', 'Solving equations is the first step into the world of algebra — and algebra is closely tied to the name of our countryman al-Khwarizmi!')
    ] },
    { kind: 'def', h: L('Tenglama va uning ildizi', 'Уравнение и его корень', 'An equation and its root'), p: [
      L('<b>Tenglama</b> — noma’lum son (odatda x harfi) qatnashgan tenglik: x · 25 = 1 000. <b>Tenglamaning ildizi</b> — x o‘rniga qo‘yganda to‘g‘ri tenglik hosil qiladigan son: x = 40, chunki 40 · 25 = 1 000. <b>Tenglamani yechish</b> — uning ildizini topish.', '<b>Уравнение</b> — равенство с неизвестным числом (обычно буква x): x · 25 = 1 000. <b>Корень уравнения</b> — число, при подстановке которого вместо x получается верное равенство: x = 40, потому что 40 · 25 = 1 000. <b>Решить уравнение</b> — найти его корень.', 'An <b>equation</b> is an equality with an unknown number (usually x): x · 25 = 1 000. The <b>root</b> of the equation is the number that makes it true when put in place of x: x = 40, because 40 · 25 = 1 000. To <b>solve</b> an equation is to find its root.')
    ], list: [
      L('Noma’lum <b>ko‘paytuvchi</b> = ko‘paytma : ma’lum ko‘paytuvchi.', 'Неизвестный <b>множитель</b> = произведение : известный множитель.', 'Unknown <b>factor</b> = product : known factor.'),
      L('Noma’lum <b>bo‘linuvchi</b> = bo‘linma · bo‘luvchi.', 'Неизвестное <b>делимое</b> = частное · делитель.', 'Unknown <b>dividend</b> = quotient · divisor.'),
      L('Noma’lum <b>bo‘luvchi</b> = bo‘linuvchi : bo‘linma.', 'Неизвестный <b>делитель</b> = делимое : частное.', 'Unknown <b>divisor</b> = dividend : quotient.'),
      L('Noma’lum <b>kamayuvchi</b> = ayriluvchi + ayirma; noma’lum <b>ayriluvchi</b> = kamayuvchi − ayirma; noma’lum <b>qo‘shiluvchi</b> = yig‘indi − ma’lum qo‘shiluvchi.', 'Неизвестное <b>уменьшаемое</b> = вычитаемое + разность; неизвестное <b>вычитаемое</b> = уменьшаемое − разность; неизвестное <b>слагаемое</b> = сумма − известное слагаемое.', 'Unknown <b>minuend</b> = subtrahend + difference; unknown <b>subtrahend</b> = minuend − difference; unknown <b>addend</b> = sum − known addend.')
    ] },
    { kind: 'history', h: L('Xorazmiy va «al-jabr»', 'Аль-Хорезми и «аль-джабр»', 'Al-Khwarizmi and “al-jabr”'), p: [
      L('Taxminan 820-yillarda Bag‘dodda Xorazmiy «Al-kitob al-muxtasar fi hisob al-jabr va-l-muqobala» («Tiklash va qarama-qarshi qo‘yish hisobi haqida qisqacha kitob») nomli asar yozgan. Bu kitobda tenglamalarni yechishning muntazam usullari birinchi marta tushuntirilgan.', 'Около 820-х годов в Багдаде аль-Хорезми написал труд «Краткая книга об исчислении аль-джабра и аль-мукабалы» («восполнения и противопоставления»). В этой книге впервые систематически объяснены способы решения уравнений.', 'Around the 820s in Baghdad, al-Khwarizmi wrote “The Compendious Book on Calculation by al-Jabr and al-Muqabala” (“restoring and balancing”). This book was the first to explain methods of solving equations systematically.'),
      L('Kitob nomidagi «al-jabr» so‘zi Yevropada «algebra» bo‘lib qoldi. Shunday qilib, matematikaning ikki muhim so‘zi — <b>algoritm</b> va <b>algebra</b> — Xorazmiy bilan bog‘liq. Bugun dunyoning barcha maktablarida tenglamalar uning g‘oyalari asosida yechiladi.', 'Слово «аль-джабр» из названия книги в Европе превратилось в «алгебру». Так два важнейших слова математики — <b>алгоритм</b> и <b>алгебра</b> — связаны с аль-Хорезми. Сегодня во всех школах мира уравнения решают на основе его идей.', 'The word “al-jabr” in the title became “algebra” in Europe. So two of the most important words in maths — <b>algorithm</b> and <b>algebra</b> — are tied to al-Khwarizmi. Today every school in the world solves equations using his ideas.'),
      L('Qizig‘i shundaki, Xorazmiy x harfidan foydalanmagan — u noma’lumni «shay’» (narsa) yoki «jizr» (ildiz) deb so‘z bilan yozgan. Harflarni noma’lum sifatida ishlatish XVI–XVII asrlarda fransuz olimlari Fransua Viet va Rene Dekart tufayli keng tarqalgan.', 'Интересно, что аль-Хорезми не пользовался буквой x — неизвестное он называл словами «шай» (вещь) или «джизр» (корень). Буквы для неизвестных распространились в XVI–XVII веках благодаря французским учёным Франсуа Виету и Рене Декарту.', 'Interestingly, al-Khwarizmi did not use the letter x — he called the unknown “shay’” (thing) or “jidhr” (root) in words. Letters for unknowns spread in the 16th–17th centuries thanks to the French scholars François Viète and René Descartes.')
    ] },
    { kind: 'rule', h: L('Murakkab tenglamani yechish qoidasi', 'Правило решения сложного уравнения', 'Rule for solving a compound equation'), p: [
      L('Murakkab tenglamada noma’lum qavs ichida yashiringan bo‘ladi: (x − 145) : 5 = 21. Uni yechish uchun <b>oxirgi bajarilgan amaldan</b> boshlaymiz — xuddi sovg‘a qutisini ochganday: avval tashqi qog‘oz, keyin ichki.', 'В сложном уравнении неизвестное спрятано в скобках: (x − 145) : 5 = 21. Решаем, начиная <b>с последнего выполненного действия</b> — как разворачиваем подарок: сначала внешнюю обёртку, потом внутреннюю.', 'In a compound equation the unknown hides inside brackets: (x − 145) : 5 = 21. We solve it starting from the <b>last operation performed</b> — like unwrapping a present: outer paper first, then the inner.')
    ], list: [
      L('<b>1.</b> Qaysi amal oxirgi bajarilgan? Bu yerda — bo‘lish. (x − 145) — noma’lum bo‘linuvchi.', '<b>1.</b> Какое действие выполнено последним? Здесь — деление. (x − 145) — неизвестное делимое.', '<b>1.</b> Which operation was done last? Here, division. (x − 145) is the unknown dividend.'),
      L('<b>2.</b> Bo‘linuvchini topamiz: x − 145 = 21 · 5 = 105.', '<b>2.</b> Находим делимое: x − 145 = 21 · 5 = 105.', '<b>2.</b> Find the dividend: x − 145 = 21 · 5 = 105.'),
      L('<b>3.</b> Endi oddiy tenglama: x — noma’lum kamayuvchi. x = 105 + 145 = 250.', '<b>3.</b> Теперь простое уравнение: x — неизвестное уменьшаемое. x = 105 + 145 = 250.', '<b>3.</b> Now a simple equation: x is the unknown minuend. x = 105 + 145 = 250.'),
      L('<b>4.</b> Tekshiramiz: (250 − 145) : 5 = 105 : 5 = 21. To‘g‘ri!', '<b>4.</b> Проверяем: (250 − 145) : 5 = 105 : 5 = 21. Верно!', '<b>4.</b> Check: (250 − 145) : 5 = 105 : 5 = 21. Correct!')
    ] },
    { kind: 'steps', h: L('Masalani taqqoslab yechish rejasi', 'План решения задачи на сравнение', 'Plan for a comparison problem'), list: [
      L('<b>1.</b> Masalada nechta «qism» borligini aniqlang (masalan, ikki oromgoh).', '<b>1.</b> Определи, сколько в задаче «частей» (например, два лагеря).', '<b>1.</b> Find how many “parts” the problem has (e.g. two camps).'),
      L('<b>2.</b> Har bir qism uchun ifoda tuzing va hisoblang.', '<b>2.</b> Для каждой части составь выражение и вычисли.', '<b>2.</b> Write and compute an expression for each part.'),
      L('<b>3.</b> Savolga qarang: «necha marta ko‘p» — bo‘lish, «nechta ko‘p» — ayirish, «jami» — qo‘shish.', '<b>3.</b> Посмотри на вопрос: «во сколько раз больше» — деление, «на сколько больше» — вычитание, «всего» — сложение.', '<b>3.</b> Look at the question: “how many times more” means division, “how many more” subtraction, “in all” addition.'),
      L('<b>4.</b> Javobni yozing va birliklarni ko‘rsating; mantiqiyligini tekshiring.', '<b>4.</b> Запиши ответ с единицами и проверь, разумен ли он.', '<b>4.</b> Write the answer with units and check it makes sense.')
    ], after: [
      L('Masalan: «Do‘konga 8 qutida 24 tadan olma sharbati va 6 qutida 12 tadan olcha sharbati keltirildi. Olma sharbati olcha sharbatidan necha marta ko‘p?» Ikki qism bor. Olma: 24 · 8 = 192 ta. Olcha: 12 · 6 = 72 ta. Savol «necha marta» — bo‘lamiz: 192 : 72 = 2 (qoldiq 48), ya’ni 2 martadan ko‘proq, lekin 3 marta emas. Agar savol «nechta ko‘p» bo‘lganda edi, javob 192 − 72 = 120 ta bo‘lardi. Savoldagi bitta so‘z butun yechimni o‘zgartiradi, shuning uchun uni diqqat bilan o‘qing.', 'Например: «В магазин привезли 8 коробок по 24 пакета яблочного сока и 6 коробок по 12 пакетов вишнёвого. Во сколько раз яблочного больше?» Две части. Яблочный: 24 · 8 = 192. Вишнёвый: 12 · 6 = 72. Вопрос «во сколько раз» — делим: 192 : 72 = 2 (остаток 48), то есть больше чем в 2 раза, но не в 3. Если бы спрашивали «на сколько больше», ответ был бы 192 − 72 = 120. Одно слово в вопросе меняет всё решение — читай внимательно.', 'For example: “A shop got 8 boxes of 24 apple juices and 6 boxes of 12 cherry juices. How many times more apple juice is there?” Two parts. Apple: 24 · 8 = 192. Cherry: 12 · 6 = 72. “How many times” means divide: 192 : 72 = 2 remainder 48 — more than twice, but not three times. Had it asked “how many more”, the answer would be 192 − 72 = 120. One word in the question changes the whole solution, so read carefully.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: 'x · 25 = 1 000', s: L('x — noma’lum ko‘paytuvchi. x = 1 000 : 25 = <b>40</b>. Tekshiruv: 40 · 25 = 1 000.', 'x — неизвестный множитель. x = 1 000 : 25 = <b>40</b>. Проверка: 40 · 25 = 1 000.', 'x is the unknown factor. x = 1 000 : 25 = <b>40</b>. Check: 40 · 25 = 1 000.') },
      { q: 'x : 36 = 48', s: L('x — noma’lum bo‘linuvchi. x = 48 · 36 = <b>1 728</b>. Tekshiruv: 1 728 : 36 = 48.', 'x — неизвестное делимое. x = 48 · 36 = <b>1 728</b>. Проверка: 1 728 : 36 = 48.', 'x is the unknown dividend. x = 48 · 36 = <b>1 728</b>. Check: 1 728 : 36 = 48.') },
      { q: '(x + 120) · 14 = 3 360', s: L('Oxirgi amal — ko‘paytirish. x + 120 = 3 360 : 14 = 240. x = 240 − 120 = <b>120</b>. Tekshiruv: (120 + 120) · 14 = 240 · 14 = 3 360.', 'Последнее действие — умножение. x + 120 = 3 360 : 14 = 240. x = 240 − 120 = <b>120</b>. Проверка: (120 + 120) · 14 = 240 · 14 = 3 360.', 'The last operation is multiplication. x + 120 = 3 360 : 14 = 240. x = 240 − 120 = <b>120</b>. Check: (120 + 120) · 14 = 240 · 14 = 3 360.') },
      { q: L('Birinchi oromgohga har birida 45 nafardan bola bo‘lgan 14 ta avtobus, ikkinchisiga har birida 36 nafardan 12 ta avtobus keldi. Birinchisiga necha nafar ko‘p bola keldi?', 'В первый лагерь приехали 14 автобусов по 45 детей, во второй — 12 автобусов по 36 детей. На сколько больше детей в первом лагере?', '14 buses with 45 children each came to the first camp and 12 buses with 36 each to the second. How many more children are in the first camp?'), s: L('1) 45 · 14 = 630. 2) 36 · 12 = 432. 3) 630 − 432 = 198. Javob: <b>198 nafar ko‘p</b>.', '1) 45 · 14 = 630. 2) 36 · 12 = 432. 3) 630 − 432 = 198. Ответ: <b>на 198 детей больше</b>.', '1) 45 · 14 = 630. 2) 36 · 12 = 432. 3) 630 − 432 = 198. Answer: <b>198 more children</b>.') }
    ] },
    { kind: 'table', h: L('Komponentlar jadvali', 'Таблица компонентов', 'Table of components'), p: [
      L('Har bir amal uchun noma’lumni qanday topishni eslab qolish uchun jadval.', 'Таблица-памятка: как найти неизвестное в каждом действии.', 'A memory table: how to find the unknown in each operation.')
    ], table: { head: [L('Tenglama', 'Уравнение', 'Equation'), L('x nima?', 'Что такое x?', 'What is x?'), L('Qanday topamiz', 'Как найти', 'How to find'), L('Javob', 'Ответ', 'Answer')], rows: [
      ['x + 350 = 1 200', L('qo‘shiluvchi', 'слагаемое', 'addend'), '1 200 − 350', '850'],
      ['x − 470 = 530', L('kamayuvchi', 'уменьшаемое', 'minuend'), '530 + 470', '1 000'],
      ['900 − x = 260', L('ayriluvchi', 'вычитаемое', 'subtrahend'), '900 − 260', '640'],
      ['x · 15 = 450', L('ko‘paytuvchi', 'множитель', 'factor'), '450 : 15', '30'],
      ['x : 24 = 15', L('bo‘linuvchi', 'делимое', 'dividend'), '15 · 24', '360'],
      ['720 : x = 48', L('bo‘luvchi', 'делитель', 'divisor'), '720 : 48', '15']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Teskari amalni noto‘g‘ri tanlash.</b> x : 36 = 48 da x = 48 : 36 deyish. Bo‘linuvchi topilganda <b>ko‘paytiramiz</b>: x = 48 · 36.', '<b>Неверно выбрать обратное действие.</b> В x : 36 = 48 сказать x = 48 : 36. Делимое находят <b>умножением</b>: x = 48 · 36.', '<b>Choosing the wrong inverse.</b> Saying x = 48 : 36 in x : 36 = 48. A dividend is found by <b>multiplying</b>: x = 48 · 36.'),
      L('<b>Ichki amaldan boshlash.</b> (x − 145) : 5 = 21 da avval 145 ni qo‘shish: x = 21 + 145 = 166, keyin 166 · 5. Xato! Avval tashqi amal — bo‘lish.', '<b>Начать с внутреннего действия.</b> В (x − 145) : 5 = 21 сначала прибавить 145: x = 21 + 145 = 166, потом 166 · 5. Ошибка! Сначала внешнее действие — деление.', '<b>Starting from the inside.</b> In (x − 145) : 5 = 21, adding 145 first: 21 + 145 = 166, then 166 · 5. Wrong! First the outer operation — division.'),
      L('<b>Noma’lum ayriluvchini noto‘g‘ri topish.</b> 900 − x = 260 da x = 900 + 260 deyish. Ayriluvchi = kamayuvchi − ayirma: 640.', '<b>Неверно найти вычитаемое.</b> В 900 − x = 260 сказать x = 900 + 260. Вычитаемое = уменьшаемое − разность: 640.', '<b>Finding the subtrahend wrongly.</b> Saying x = 900 + 260 in 900 − x = 260. Subtrahend = minuend − difference: 640.'),
      L('<b>«Nechta ko‘p» va «necha marta ko‘p»ni aralashtirish.</b> 630 va 210 uchun: nechta ko‘p — 420, necha marta ko‘p — 3 marta.', '<b>Путать «на сколько больше» и «во сколько раз больше».</b> Для 630 и 210: на сколько — 420, во сколько раз — в 3 раза.', '<b>Mixing “how many more” and “how many times more”.</b> For 630 and 210: 420 more, but 3 times as many.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Pul yig‘ish.</b> Velosiped 1 440 000 so‘m. Siz har oy bir xil miqdorda yig‘sangiz va 12 oyda yig‘ib bo‘lmoqchi bo‘lsangiz: x · 12 = 1 440 000, x = 120 000 so‘m oyiga.', '<b>Накопления.</b> Велосипед стоит 1 440 000 сум. Если копить каждый месяц одинаково и накопить за 12 месяцев: x · 12 = 1 440 000, x = 120 000 сум в месяц.', '<b>Saving up.</b> A bicycle costs 1 440 000 sum. To save the same amount each month for 12 months: x · 12 = 1 440 000, so x = 120 000 sum a month.'),
      L('<b>Oshxona.</b> Retseptda 4 kishilik palov uchun 600 g guruch kerak. 20 kishilik palov uchun: 600 : 4 · 20 = 3 000 g = 3 kg. Oshpazlar har kuni shunday «noma’lum»ni topishadi.', '<b>Кухня.</b> По рецепту на плов для 4 человек нужно 600 г риса. На 20 человек: 600 : 4 · 20 = 3 000 г = 3 кг. Повара каждый день находят такие «неизвестные».', '<b>In the kitchen.</b> A recipe for plov for 4 people needs 600 g of rice. For 20 people: 600 : 4 · 20 = 3 000 g = 3 kg. Cooks find such “unknowns” every day.'),
      L('<b>Sport.</b> Yuguruvchi 5 000 m ni har aylanasi 400 m bo‘lgan yo‘lakda yugurmoqda. Necha aylana? x · 400 = 5 000, x = 12 va yana 200 m (yarim aylana).', '<b>Спорт.</b> Бегун бежит 5 000 м по дорожке с кругом 400 м. Сколько кругов? x · 400 = 5 000, x = 12 и ещё 200 м (полкруга).', '<b>Sport.</b> A runner covers 5 000 m on a 400 m track. How many laps? x · 400 = 5 000, so 12 laps plus 200 m (half a lap).')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«=» tenglik belgisini 1557-yilda uelslik olim Robert Rekord o‘ylab topgan. U yozgan: «Ikki parallel chiziqdan tengroq narsa yo‘q».', 'Знак равенства «=» придумал в 1557 году валлийский учёный Роберт Рекорд. Он писал: «Нет ничего более равного, чем две параллельные линии».', 'The equals sign “=” was invented in 1557 by the Welsh scholar Robert Recorde. He wrote that nothing could be more equal than two parallel lines.'),
      L('Qadimgi Misrning Rind papirusida «aha» masalalari bor — noma’lumni topish masalalari. Masalan: «Bir son va uning yettidan biri birgalikda 19. Son qancha?»', 'В древнеегипетском папирусе Ринда есть задачи «аха» — на нахождение неизвестного. Например: «Число и его седьмая часть вместе дают 19. Каково число?»', 'The ancient Egyptian Rhind Papyrus has “aha” problems — finding an unknown. For example: “A number and its seventh together make 19. What is the number?”'),
      L('Xorazmiyning algebra kitobi 1145-yilda ingliz olimi Robert Chesterlik tomonidan lotin tiliga tarjima qilingan va Yevropa universitetlarida asrlar davomida o‘qitilgan.', 'Книгу аль-Хорезми по алгебре в 1145 году перевёл на латынь английский учёный Роберт Честерский, и её веками изучали в европейских университетах.', 'Al-Khwarizmi’s algebra book was translated into Latin in 1145 by the English scholar Robert of Chester and was studied in European universities for centuries.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Yeching: 4 800 : x = 32.', 'Реши: 4 800 : x = 32.', 'Solve: 4 800 : x = 32.'),
      L('Yeching: (x − 250) · 18 = 1 800.', 'Реши: (x − 250) · 18 = 1 800.', 'Solve: (x − 250) · 18 = 1 800.'),
      L('Men bir son o‘yladim, uni 24 ga ko‘paytirib, 100 ni qo‘shdim va 1 060 chiqdi. Qaysi son?', 'Я задумал число, умножил его на 24, прибавил 100 и получил 1 060. Какое число?', 'I thought of a number, multiplied it by 24, added 100 and got 1 060. What was it?')
    ], after: [
      L('Javoblar: 1) x = 4 800 : 32 = 150; 2) x − 250 = 100, x = 350; 3) x · 24 = 960, x = 40.', 'Ответы: 1) x = 4 800 : 32 = 150; 2) x − 250 = 100, x = 350; 3) x · 24 = 960, x = 40.', 'Answers: 1) x = 4 800 : 32 = 150; 2) x − 250 = 100, x = 350; 3) x · 24 = 960, x = 40.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Tenglama — noma’lum qatnashgan tenglik; ildiz — uni to‘g‘ri qiladigan son.', 'Уравнение — равенство с неизвестным; корень — число, делающее его верным.', 'An equation is an equality with an unknown; its root makes it true.'),
      L('Noma’lum komponentni teskari amal bilan topamiz.', 'Неизвестный компонент находим обратным действием.', 'Find the unknown part with the inverse operation.'),
      L('Murakkab tenglamani oxirgi amaldan boshlab, tashqaridan ichkariga yechamiz.', 'Сложное уравнение решаем с последнего действия, снаружи внутрь.', 'Solve a compound equation from the last operation, outside in.'),
      L('Har doim ildizni tenglamaga qo‘yib tekshiring.', 'Всегда проверяй корень подстановкой.', 'Always check the root by substituting it.'),
      L('«Algebra» so‘zi Xorazmiyning «al-jabr» kitobidan kelib chiqqan.', 'Слово «алгебра» — из книги аль-Хорезми «аль-джабр».', 'The word “algebra” comes from al-Khwarizmi’s book “al-jabr”.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t15. Xonalar va sinflar. Million ----------
  T.add(P, 't15', { sections: [
    { kind: 'intro', h: L('Bir million — bu qancha?', 'Миллион — это сколько?', 'How much is a million?'), p: [
      L('Siz 999 999 gacha bo‘lgan sonlarni bilasiz. Unga yana 1 qo‘shsak nima bo‘ladi? 999 999 + 1 = <b>1 000 000</b> — bir million! Bu yetti xonali eng kichik son. Million — shunchaki «katta son» emas, u butun bir yangi sinfning boshlanishi.', 'Ты знаешь числа до 999 999. А что будет, если прибавить ещё 1? 999 999 + 1 = <b>1 000 000</b> — миллион! Это самое маленькое семизначное число. Миллион — не просто «большое число», это начало целого нового класса.', 'You know the numbers up to 999 999. What happens if we add 1 more? 999 999 + 1 = <b>1 000 000</b> — one million! It is the smallest seven-digit number. A million is not just a “big number”: it starts a whole new period.'),
      L('Millionni tasavvur qilish qiyin. Keling, sinab ko‘ramiz. Agar har soniyada bittadan sanasangiz, millionga yetish uchun 11 kundan ko‘proq vaqt kerak — kechayu kunduz uxlamasdan! Bir million guruch donasi taxminan 20 kilogramm keladi. Bir million qadam — Toshkentdan Samarqandgacha bo‘lgan yo‘ldan ham uzunroq.', 'Миллион трудно представить. Давай попробуем. Если считать по числу в секунду, до миллиона понадобится больше 11 суток — днём и ночью без сна! Миллион рисовых зёрен весит около 20 килограммов. Миллион шагов — длиннее дороги от Ташкента до Самарканда.', 'A million is hard to picture. Let’s try. Counting one number per second, you would need more than 11 days to reach a million — day and night without sleep! A million grains of rice weigh about 20 kilograms. A million steps is longer than the road from Tashkent to Samarkand.'),
      L('Bu mavzuda million nima ekanini, sonlar qanday qilib uchta-uchta xonali <b>sinflarga</b> bo‘linishini va millionlar sinfini o‘rganamiz.', 'В этой теме мы узнаем, что такое миллион, как числа делятся на <b>классы</b> по три разряда, и познакомимся с классом миллионов.', 'In this topic we learn what a million is, how numbers are grouped into <b>periods</b> of three places, and meet the millions period.')
    ] },
    { kind: 'def', h: L('Xonalar va sinflar', 'Разряды и классы', 'Places and periods'), p: [
      L('<b>Million</b> — ming marta ming: 1 000 000 = 1 000 · 1 000. Uning yozuvida 1 va oltita nol bor. Million — 10 ta yuz ming, 100 ta o‘n ming, 1 000 ta ming.', '<b>Миллион</b> — тысяча тысяч: 1 000 000 = 1 000 · 1 000. В его записи 1 и шесть нулей. Миллион — это 10 сотен тысяч, 100 десятков тысяч, 1 000 тысяч.', 'A <b>million</b> is a thousand thousands: 1 000 000 = 1 000 · 1 000. It is written as 1 followed by six zeros. A million is 10 hundred-thousands, 100 ten-thousands, 1 000 thousands.'),
      L('Ko‘p xonali sonlarning xonalari o‘ngdan chapga uchtadan guruhlanadi. Har bir guruh <b>sinf</b> deyiladi. Har bir sinfda birliklar, o‘nliklar va yuzliklar bor.', 'Разряды многозначных чисел группируются справа налево по три. Каждая группа называется <b>классом</b>. В каждом классе есть единицы, десятки и сотни.', 'The places of large numbers are grouped in threes from right to left. Each group is called a <b>period</b>. Every period has ones, tens and hundreds.')
    ], list: [
      L('<b>1-sinf — birliklar sinfi:</b> birliklar, o‘nliklar, yuzliklar (1-, 2-, 3-xonalar).', '<b>1-й класс — класс единиц:</b> единицы, десятки, сотни (1-й, 2-й, 3-й разряды).', '<b>1st period — ones:</b> ones, tens, hundreds (places 1–3).'),
      L('<b>2-sinf — minglar sinfi:</b> minglar, o‘n minglar, yuz minglar (4-, 5-, 6-xonalar).', '<b>2-й класс — класс тысяч:</b> тысячи, десятки тысяч, сотни тысяч (4–6-й разряды).', '<b>2nd period — thousands:</b> thousands, ten-thousands, hundred-thousands (places 4–6).'),
      L('<b>3-sinf — millionlar sinfi:</b> millionlar, o‘n millionlar, yuz millionlar (7-, 8-, 9-xonalar).', '<b>3-й класс — класс миллионов:</b> миллионы, десятки миллионов, сотни миллионов (7–9-й разряды).', '<b>3rd period — millions:</b> millions, ten-millions, hundred-millions (places 7–9).')
    ], after: [
      L('25 304 019 sonida: millionlar sinfi — 25, minglar sinfi — 304, birliklar sinfi — 019. O‘qiladi: «yigirma besh million uch yuz to‘rt ming o‘n to‘qqiz».', 'В числе 25 304 019: класс миллионов — 25, класс тысяч — 304, класс единиц — 019. Читается: «двадцать пять миллионов триста четыре тысячи девятнадцать».', 'In 25 304 019: millions period 25, thousands period 304, ones period 019. It reads: “twenty-five million three hundred and four thousand and nineteen”.')
    ] },
    { kind: 'history', h: L('«Million» so‘zining tarixi', 'История слова «миллион»', 'The story of the word “million”'), p: [
      L('Qadimgi xalqlarda millionga alohida so‘z bo‘lmagan. Rimliklar eng ko‘p «ming» deyishgan, millionni esa «o‘n marta yuz ming» deb aytishgan. Yunonlarda eng katta nomli son — «miriada», ya’ni 10 000 edi.', 'У древних народов не было отдельного слова для миллиона. Римляне доходили до «тысячи», а миллион называли «десять раз по сто тысяч». У греков самым большим названным числом была «мириада» — 10 000.', 'Ancient peoples had no single word for a million. The Romans went up to “thousand” and called a million “ten times a hundred thousand”. For the Greeks the biggest named number was the “myriad” — 10 000.'),
      L('«Million» so‘zi XIII–XIV asrlarda Italiyada paydo bo‘lgan: «mille» — ming, «milione» — «katta ming». Mashhur sayyoh Marko Poloning kitobi Italiyada «Il Milione» deb nomlangan — balki u Sharq boyliklarini doim «millionlab» deb tasvirlagani uchundir. U Buyuk ipak yo‘lidagi yurtlar haqida hikoya qilgan.', 'Слово «миллион» появилось в Италии в XIII–XIV веках: «mille» — тысяча, «milione» — «большая тысяча». Книгу знаменитого путешественника Марко Поло в Италии называли «Il Milione» — возможно, потому что он всё время описывал богатства Востока «миллионами». Он рассказывал о землях на Великом шёлковом пути.', 'The word “million” appeared in Italy in the 13th–14th centuries: “mille” means thousand and “milione” a “big thousand”. The famous traveller Marco Polo’s book was known in Italy as “Il Milione” — perhaps because he kept describing the riches of the East in “millions”. He told of lands along the Great Silk Road.'),
      L('Xonalarni uchtadan sinflarga bo‘lish g‘oyasi Yevropada XV–XVI asrlarda keng tarqalgan. Rossiyada «million» so‘zi 1703-yilda Leontiy Magnitskiyning «Arifmetika» darsligi orqali ommalashgan. Bugun «million» so‘zi o‘zbek, rus, ingliz va boshqa ko‘plab tillarda deyarli bir xil eshitiladi.', 'Идея делить разряды на классы по три распространилась в Европе в XV–XVI веках. В России слово «миллион» стало известным благодаря «Арифметике» Леонтия Магницкого 1703 года. Сегодня «миллион» звучит почти одинаково на узбекском, русском, английском и многих других языках.', 'The idea of grouping places in threes spread in Europe in the 15th–16th centuries. In Russia the word “million” became widely known through Leonty Magnitsky’s “Arithmetic” of 1703. Today “million” sounds almost the same in Uzbek, Russian, English and many other languages.')
    ] },
    { kind: 'rule', h: L('Qoida: xona birliklari va ularning munosabatlari', 'Правило: разрядные единицы и их связь', 'Rule: place units and how they relate'), p: [
      L('Har bir xona birligi o‘zidan o‘ngdagi xona birligidan <b>10 marta</b> katta. Bu sanoq sistemamizning asosiy qonuni — o‘nli sistema.', 'Каждая разрядная единица в <b>10 раз</b> больше единицы соседнего справа разряда. Это главный закон нашей системы счисления — десятичной.', 'Every place unit is <b>10 times</b> bigger than the unit to its right. This is the main law of our decimal number system.')
    ], list: [
      L('1 o‘nlik = 10 birlik; 1 yuzlik = 10 o‘nlik = 100 birlik.', '1 десяток = 10 единиц; 1 сотня = 10 десятков = 100 единиц.', '1 ten = 10 ones; 1 hundred = 10 tens = 100 ones.'),
      L('1 ming = 10 yuzlik; 1 o‘n ming = 10 ming; 1 yuz ming = 10 o‘n ming.', '1 тысяча = 10 сотен; 1 десяток тысяч = 10 тысяч; 1 сотня тысяч = 10 десятков тысяч.', '1 thousand = 10 hundreds; 1 ten-thousand = 10 thousands; 1 hundred-thousand = 10 ten-thousands.'),
      L('1 million = 10 yuz ming = 1 000 ming.', '1 миллион = 10 сотен тысяч = 1 000 тысяч.', '1 million = 10 hundred-thousands = 1 000 thousands.'),
      L('1 milliard = 1 000 million = 1 000 000 000 (to‘qqizta nol).', '1 миллиард = 1 000 миллионов = 1 000 000 000 (девять нулей).', '1 billion = 1 000 million = 1 000 000 000 (nine zeros).')
    ], after: [
      L('Raqamning <b>qiymati</b> uning qaysi xonada turganiga bog‘liq. 3 555 555 sonida beshta 5 bor, lekin ularning qiymatlari har xil: 500 000, 50 000, 5 000, 500, 50 va 5.', '<b>Значение</b> цифры зависит от того, в каком разряде она стоит. В числе 3 555 555 шесть пятёрок, но значения у них разные: 500 000, 50 000, 5 000, 500, 50 и 5.', 'A digit’s <b>value</b> depends on its place. In 3 555 555 there are six 5s, but their values differ: 500 000, 50 000, 5 000, 500, 50 and 5.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 7 040 305 ni tahlil qilamiz', 'Пошагово: разбираем 7 040 305', 'Step by step: analysing 7 040 305'), list: [
      L('<b>Sinflarga ajratamiz</b> (o‘ngdan uchtadan): 7 | 040 | 305.', '<b>Делим на классы</b> (справа по три): 7 | 040 | 305.', '<b>Split into periods</b> (threes from the right): 7 | 040 | 305.'),
      L('<b>Millionlar sinfi:</b> 7 — yetti million.', '<b>Класс миллионов:</b> 7 — семь миллионов.', '<b>Millions period:</b> 7 — seven million.'),
      L('<b>Minglar sinfi:</b> 040 — qirq ming (yuz minglar xonasi bo‘sh).', '<b>Класс тысяч:</b> 040 — сорок тысяч (разряд сотен тысяч пуст).', '<b>Thousands period:</b> 040 — forty thousand (the hundred-thousands place is empty).'),
      L('<b>Birliklar sinfi:</b> 305 — uch yuz besh.', '<b>Класс единиц:</b> 305 — триста пять.', '<b>Ones period:</b> 305 — three hundred and five.'),
      L('<b>Xona qo‘shiluvchilari:</b> 7 000 000 + 40 000 + 300 + 5. Sonda jami 7 040 ta ming va 7 040 305 ta birlik bor.', '<b>Разрядные слагаемые:</b> 7 000 000 + 40 000 + 300 + 5. Всего в числе 7 040 тысяч и 7 040 305 единиц.', '<b>Expanded form:</b> 7 000 000 + 40 000 + 300 + 5. The number contains 7 040 whole thousands and 7 040 305 ones.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('999 999 dan keyingi va 1 000 000 dan oldingi sonlar qaysi?', 'Какое число идёт после 999 999 и какое перед 1 000 000?', 'Which number comes after 999 999, and which before 1 000 000?'), s: L('999 999 + 1 = <b>1 000 000</b>. 1 000 000 − 1 = <b>999 999</b>. Bu ikki son qo‘shni.', '999 999 + 1 = <b>1 000 000</b>. 1 000 000 − 1 = <b>999 999</b>. Это соседние числа.', '999 999 + 1 = <b>1 000 000</b>. 1 000 000 − 1 = <b>999 999</b>. They are neighbours.') },
      { q: L('3 685 214 sonida 6 raqamining qiymati qancha?', 'Каково значение цифры 6 в числе 3 685 214?', 'What is the value of the digit 6 in 3 685 214?'), s: L('Sinflar: 3 | 685 | 214. 6 — minglar sinfining yuzliklar xonasida, ya’ni yuz minglar xonasida. Qiymati: <b>600 000</b>.', 'Классы: 3 | 685 | 214. 6 стоит в разряде сотен класса тысяч, то есть сотен тысяч. Значение: <b>600 000</b>.', 'Periods: 3 | 685 | 214. The 6 is in the hundreds place of the thousands period — the hundred-thousands place. Value: <b>600 000</b>.') },
      { q: L('Raqamlar bilan yozing: o‘n ikki million besh ming yetti.', 'Запиши цифрами: двенадцать миллионов пять тысяч семь.', 'Write in digits: twelve million five thousand and seven.'), s: L('Millionlar — 12, minglar — 005, birliklar — 007. Javob: <b>12 005 007</b>. Bo‘sh xonalarga nol yozishni unutmang!', 'Миллионы — 12, тысячи — 005, единицы — 007. Ответ: <b>12 005 007</b>. Не забудь нули в пустых разрядах!', 'Millions 12, thousands 005, ones 007. Answer: <b>12 005 007</b>. Do not forget zeros in empty places!') },
      { q: L('Millionda nechta yuzlik bor?', 'Сколько сотен в миллионе?', 'How many hundreds are in a million?'), s: L('1 000 000 : 100 = <b>10 000</b>. Million — o‘n ming ta yuzlik.', '1 000 000 : 100 = <b>10 000</b>. Миллион — это десять тысяч сотен.', '1 000 000 : 100 = <b>10 000</b>. A million is ten thousand hundreds.') }
    ] },
    { kind: 'table', h: L('Sinflar va xonalar jadvali', 'Таблица классов и разрядов', 'Table of periods and places'), p: [
      L('Sonni jadvalga joylashtirsangiz, har bir raqamning o‘rni va qiymati aniq ko‘rinadi.', 'Если разместить число в таблице, место и значение каждой цифры видны сразу.', 'Put a number in the table and the place and value of every digit become clear.')
    ], table: { head: [L('Son', 'Число', 'Number'), L('Yuz mln', 'Сот. млн', 'H. mil.'), L('O‘n mln', 'Дес. млн', 'T. mil.'), L('Mln', 'Млн', 'Mil.'), L('Yuz ming', 'Сот. тыс.', 'H. th.'), L('O‘n ming', 'Дес. тыс.', 'T. th.'), L('Ming', 'Тыс.', 'Th.'), L('Yuz', 'Сот.', 'H.'), L('O‘n', 'Дес.', 'T.'), L('Bir', 'Ед.', 'O.')], rows: [
      ['1 000 000', '', '', '1', '0', '0', '0', '0', '0', '0'],
      ['25 304 019', '', '2', '5', '3', '0', '4', '0', '1', '9'],
      ['7 040 305', '', '', '7', '0', '4', '0', '3', '0', '5'],
      ['375 000 000', '3', '7', '5', '0', '0', '0', '0', '0', '0']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Sinflarni chapdan ajratish.</b> 2530419 ni 253 | 041 | 9 deb bo‘lish xato. Doim <b>o‘ngdan</b> uchtadan ajratamiz: 2 | 530 | 419.', '<b>Делить на классы слева.</b> Разбить 2530419 как 253 | 041 | 9 — ошибка. Всегда делим <b>справа</b> по три: 2 | 530 | 419.', '<b>Grouping from the left.</b> Splitting 2530419 as 253 | 041 | 9 is wrong. Always group in threes <b>from the right</b>: 2 | 530 | 419.'),
      L('<b>Sinf ichidagi nollarni tashlab ketish.</b> «Besh million yetti ming» ni 5 7 000 yoki 57 000 deb yozish. To‘g‘risi: 5 007 000 — minglar sinfi uchta raqamdan iborat: 007.', '<b>Пропускать нули внутри класса.</b> Записать «пять миллионов семь тысяч» как 57 000. Верно: 5 007 000 — в классе тысяч три цифры: 007.', '<b>Dropping zeros inside a period.</b> Writing “five million seven thousand” as 57 000. Correct: 5 007 000 — the thousands period has three digits: 007.'),
      L('<b>Nollar sonida adashish.</b> Millionda beshta yoki yettita nol yozish. Millionda aniq <b>oltita</b> nol: 1 000 000.', '<b>Ошибиться в числе нулей.</b> Написать в миллионе пять или семь нулей. В миллионе ровно <b>шесть</b> нулей: 1 000 000.', '<b>Miscounting zeros.</b> Writing five or seven zeros in a million. A million has exactly <b>six</b>: 1 000 000.'),
      L('<b>«Mingliklar soni» va «minglar xonasidagi raqam»ni aralashtirish.</b> 3 685 214 da minglar xonasida 5, lekin to‘liq minglar soni 3 685 ta.', '<b>Путать «количество тысяч» и «цифру разряда тысяч».</b> В 3 685 214 в разряде тысяч 5, а всего тысяч — 3 685.', '<b>Mixing “how many thousands” with “the thousands digit”.</b> In 3 685 214 the thousands digit is 5, but there are 3 685 whole thousands.')
    ] },
    { kind: 'life', h: L('Hayotda millionlar', 'Миллионы в жизни', 'Millions in life'), p: [
      L('<b>Aholi.</b> O‘zbekistonda 37 milliondan ortiq odam yashaydi. Toshkent aholisi taxminan 3 million. Bunday sonlarni statistiklar har yili hisoblab, maktablar va kasalxonalar qurishni rejalashtiradi.', '<b>Население.</b> В Узбекистане живёт более 37 миллионов человек. Население Ташкента — около 3 миллионов. Такие числа статистики пересчитывают каждый год, чтобы планировать школы и больницы.', '<b>Population.</b> More than 37 million people live in Uzbekistan. Tashkent has about 3 million. Statisticians recount such numbers every year to plan schools and hospitals.'),
      L('<b>Pul.</b> Avtomobil narxi 150 000 000 so‘m bo‘lishi mumkin — bu yuz ellik million. Uyni esa milliard so‘mlarda o‘lchashadi. Narxlarni to‘g‘ri o‘qiy olish — har bir kattaning muhim ko‘nikmasi.', '<b>Деньги.</b> Автомобиль может стоить 150 000 000 сум — сто пятьдесят миллионов. А дома оценивают миллиардами сумов. Правильно читать цены — важный навык каждого взрослого.', '<b>Money.</b> A car may cost 150 000 000 sum — a hundred and fifty million. Houses are priced in billions of sum. Reading prices correctly is an important adult skill.'),
      L('<b>Kosmos.</b> Yerdan Quyoshgacha taxminan 150 000 000 km. Yerdan Oygacha esa o‘rtacha 384 400 km — bu million kilometrdan ham kam!', '<b>Космос.</b> От Земли до Солнца около 150 000 000 км. А от Земли до Луны в среднем 384 400 км — это меньше миллиона километров!', '<b>Space.</b> The Sun is about 150 000 000 km from Earth. The Moon is on average 384 400 km away — less than a million kilometres!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Millionga qadar sanash uchun, kuniga 8 soatdan har soniyada bitta son aytsangiz, qariyb 35 kun kerak bo‘ladi.', 'Если считать по 8 часов в день, по числу в секунду, до миллиона понадобится почти 35 дней.', 'Counting one number a second for 8 hours a day, you would need almost 35 days to reach a million.'),
      L('Inson boshida o‘rtacha 100 000 ga yaqin soch tolasi bor. Million soch uchun 10 ta odam kerak!', 'На голове человека в среднем около 100 000 волос. На миллион волос понадобится 10 человек!', 'A human head has around 100 000 hairs on average. A million hairs would need 10 people!'),
      L('Bir million millimetr — atigi 1 kilometr! Bir million metr esa 1 000 km — Toshkentdan Nukusgacha bo‘lgan yo‘lga yaqin.', 'Миллион миллиметров — всего 1 километр! А миллион метров — 1 000 км, почти как дорога от Ташкента до Нукуса.', 'A million millimetres is just 1 kilometre! A million metres is 1 000 km — close to the road from Tashkent to Nukus.'),
      L('Milliondan keyingi katta sonlar: milliard (9 nol), trillion (12 nol), kvadrillion (15 nol). Har bir yangi nom oldingisidan 1 000 marta katta.', 'Большие числа после миллиона: миллиард (9 нулей), триллион (12 нулей), квадриллион (15 нулей). Каждое новое название в 1 000 раз больше предыдущего.', 'Big numbers after a million: billion (9 zeros), trillion (12 zeros), quadrillion (15 zeros). Each new name is 1 000 times the one before.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Millionda nechta o‘n ming bor?', 'Сколько десятков тысяч в миллионе?', 'How many ten-thousands are in a million?'),
      L('9 090 909 sonidagi 9 raqamlarining qiymatlarini yozing.', 'Запиши значения девяток в числе 9 090 909.', 'Write the values of the 9s in 9 090 909.'),
      L('Eng katta yetti xonali va eng kichik sakkiz xonali sonlarni yozing. Ular orasidagi farq qancha?', 'Запиши самое большое семизначное и самое маленькое восьмизначное числа. Какова их разность?', 'Write the largest seven-digit and the smallest eight-digit numbers. What is their difference?')
    ], after: [
      L('Javoblar: 1) 100 ta; 2) 9 000 000, 90 000, 900, 9; 3) 9 999 999 va 10 000 000, farqi 1.', 'Ответы: 1) 100; 2) 9 000 000, 90 000, 900, 9; 3) 9 999 999 и 10 000 000, разность 1.', 'Answers: 1) 100; 2) 9 000 000, 90 000, 900, 9; 3) 9 999 999 and 10 000 000, difference 1.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('1 000 000 = 1 000 · 1 000 — bir million, eng kichik yetti xonali son.', '1 000 000 = 1 000 · 1 000 — миллион, самое маленькое семизначное число.', '1 000 000 = 1 000 · 1 000 — one million, the smallest seven-digit number.'),
      L('Xonalar o‘ngdan uchtadan sinflarga bo‘linadi: birliklar, minglar, millionlar.', 'Разряды справа по три объединяются в классы: единицы, тысячи, миллионы.', 'Places group in threes from the right into periods: ones, thousands, millions.'),
      L('Har bir xona birligi o‘ngdagisidan 10 marta katta.', 'Каждая разрядная единица в 10 раз больше соседней справа.', 'Each place unit is 10 times the one to its right.'),
      L('Raqamning qiymati uning xonasiga bog‘liq.', 'Значение цифры зависит от её разряда.', 'A digit’s value depends on its place.'),
      L('Bo‘sh xonalarga va sinf ichiga nol yoziladi: 5 007 000.', 'В пустые разряды и внутри класса пишут нули: 5 007 000.', 'Empty places, even inside a period, get zeros: 5 007 000.'),
      L('«Million» so‘zi italyancha «katta ming» degan ma’noni bildiradi.', 'Слово «миллион» по-итальянски значит «большая тысяча».', 'The word “million” comes from Italian for “big thousand”.')
    ] }
  ] });

  // ---------- t16. Ko‘p xonali sonlarni o‘qish, yozish va taqqoslash ----------
  T.add(P, 't16', { sections: [
    { kind: 'intro', h: L('Katta sonlarni o‘qishni o‘rganamiz', 'Учимся читать большие числа', 'Learning to read big numbers'), p: [
      L('Gazetada shunday yozuv bor: «Viloyatda bu yil 3 045 007 tup daraxt ekildi». Buni qanday o‘qiymiz? «Uch million qirq besh ming yetti». Agar sinflarni bilsangiz, eng uzun sonni ham bir zumda o‘qiysiz. Bilmasangiz — raqamlar orasida adashib qolasiz.', 'В газете написано: «В области в этом году посадили 3 045 007 деревьев». Как это прочитать? «Три миллиона сорок пять тысяч семь». Если знаешь классы, прочитаешь даже самое длинное число мгновенно. Если нет — запутаешься в цифрах.', 'A newspaper says: “This year 3 045 007 trees were planted in the region.” How do we read that? “Three million forty-five thousand and seven.” If you know the periods, you can read even the longest number in a flash. If not, you get lost among the digits.'),
      L('Shuningdek, katta sonlarni <b>taqqoslash</b> ham muhim. Qaysi shaharda aholi ko‘p? Qaysi mashina qimmat? Qaysi sayyora uzoqroq? Bu savollarga javob berish uchun sonlarni tez va xatosiz solishtirishni bilish kerak.', 'Также важно уметь <b>сравнивать</b> большие числа. В каком городе больше жителей? Какая машина дороже? Какая планета дальше? Чтобы ответить, нужно быстро и без ошибок сравнивать числа.', 'Comparing big numbers matters too. Which city has more people? Which car is more expensive? Which planet is farther away? To answer, you need to compare numbers quickly and without mistakes.'),
      L('Bu mavzuda ko‘p xonali sonlarni o‘qish, so‘z bilan berilgan sonni raqamlar bilan yozish va ikki sonni taqqoslash qoidalarini o‘rganamiz.', 'В этой теме мы изучим правила чтения многозначных чисел, записи цифрами чисел, данных словами, и сравнения двух чисел.', 'In this topic we learn the rules for reading large numbers, writing numbers given in words as digits and comparing two numbers.')
    ] },
    { kind: 'def', h: L('O‘qish va taqqoslash atamalari', 'Термины чтения и сравнения', 'Terms for reading and comparing'), p: [
      L('Ko‘p xonali sonni o‘qish uchun uni <b>sinflarga</b> ajratib, har bir sinfni uch xonali son kabi o‘qiymiz va oxiriga sinf nomini qo‘shamiz: «… million», «… ming». Birliklar sinfining nomi aytilmaydi.', 'Чтобы прочитать многозначное число, делим его на <b>классы</b>, читаем каждый класс как трёхзначное число и добавляем название класса: «… миллионов», «… тысяч». Название класса единиц не произносят.', 'To read a large number, split it into <b>periods</b>, read each as a three-digit number and add the period name: “… million”, “… thousand”. The ones period name is not said.'),
      L('Agar biror sinfda faqat nollar bo‘lsa (masalan, 5 000 017 da minglar sinfi 000), u o‘qilmaydi: «besh million o‘n yetti».', 'Если в каком-то классе одни нули (например, в 5 000 017 класс тысяч — 000), он не читается: «пять миллионов семнадцать».', 'If a period is all zeros (e.g. the thousands period 000 in 5 000 017), it is not read: “five million and seventeen”.'),
      L('Taqqoslash belgilari: <b>&gt;</b> — katta, <b>&lt;</b> — kichik, <b>=</b> — teng. Belgining «ochiq og‘zi» doimo katta son tomonga qaraydi: 7 &gt; 3.', 'Знаки сравнения: <b>&gt;</b> — больше, <b>&lt;</b> — меньше, <b>=</b> — равно. «Открытый рот» знака всегда смотрит на большее число: 7 &gt; 3.', 'Comparison signs: <b>&gt;</b> greater than, <b>&lt;</b> less than, <b>=</b> equal. The “open mouth” of the sign always faces the bigger number: 7 &gt; 3.')
    ] },
    { kind: 'history', h: L('Sonlarni yozish tarixidan', 'Из истории записи чисел', 'From the history of writing numbers'), p: [
      L('Qadimgi Misrda million maxsus belgi bilan — qo‘llarini osmonga ko‘targan odam rasmi bilan yozilgan. Bu belgi «Heh» xudosini anglatgan va «son-sanoqsiz», «juda ko‘p» ma’nosini bergan. Misrliklar 1 000 000 dan katta sonni yozishga deyarli muhtoj bo‘lmagan.', 'В Древнем Египте миллион записывали особым знаком — фигурой человека с поднятыми к небу руками. Знак обозначал бога Хеха и означал «бесчисленно», «очень много». Числа больше 1 000 000 египтянам почти не требовались.', 'In Ancient Egypt a million was written with a special sign — a man raising his arms to the sky. The sign stood for the god Heh and meant “countless”, “a great many”. Egyptians hardly ever needed numbers bigger than 1 000 000.'),
      L('Qadimgi yunon olimi <b>Arximed</b> (miloddan avvalgi III asr) «Qum donalarini hisoblovchi» asarida butun koinotni to‘ldirish uchun qancha qum donasi kerakligini baholagan. Buning uchun u o‘sha davrda nomlanmagan juda katta sonlarni yozish tizimini o‘ylab topgan.', 'Древнегреческий учёный <b>Архимед</b> (III век до н. э.) в сочинении «Исчисление песчинок» оценил, сколько песчинок нужно, чтобы заполнить всю Вселенную. Для этого он придумал систему записи огромных чисел, у которых тогда не было названий.', 'The ancient Greek scholar <b>Archimedes</b> (3rd century BC), in “The Sand Reckoner”, estimated how many grains of sand would fill the whole universe. To do this he invented a way of writing enormous numbers that had no names at the time.'),
      L('Sinflar orasiga bo‘sh joy qoldirish odati keyinroq paydo bo‘lgan. Ba’zi mamlakatlarda vergul (1,000,000), boshqalarida nuqta (1.000.000) ishlatiladi. O‘zbekistonda va xalqaro ilmiy standartda kichik bo‘sh joy ishlatiladi: 1 000 000 — bu chalkashlikni oldini oladi.', 'Привычка оставлять пробел между классами появилась позже. В одних странах используют запятую (1,000,000), в других — точку (1.000.000). В Узбекистане и в международном научном стандарте ставят небольшой пробел: 1 000 000 — так нет путаницы.', 'Leaving a gap between periods came later. Some countries use commas (1,000,000), others dots (1.000.000). Uzbekistan and the international scientific standard use a small space: 1 000 000 — this avoids confusion.')
    ] },
    { kind: 'rule', h: L('Taqqoslash qoidasi', 'Правило сравнения', 'The comparison rule'), list: [
      L('<b>1.</b> Raqamlar sonini solishtiring. Qaysi sonda raqam ko‘p bo‘lsa, o‘sha katta: 1 000 000 (7 ta) &gt; 999 999 (6 ta).', '<b>1.</b> Сравни количество цифр. Где цифр больше, то число и больше: 1 000 000 (7 цифр) &gt; 999 999 (6 цифр).', '<b>1.</b> Compare the number of digits. More digits means bigger: 1 000 000 (7 digits) &gt; 999 999 (6 digits).'),
      L('<b>2.</b> Raqamlar soni teng bo‘lsa, chapdan, eng katta xonadan boshlab raqamlarni birma-bir solishtiring.', '<b>2.</b> Если цифр поровну, сравнивай цифры по одной слева, начиная со старшего разряда.', '<b>2.</b> If the digit counts are equal, compare digit by digit from the left, starting with the highest place.'),
      L('<b>3.</b> Birinchi farq qilgan raqam qaysi sonda katta bo‘lsa, o‘sha son katta. Keyingi raqamlar endi muhim emas: 3 405 007 &gt; 3 045 997, chunki 4 &gt; 0 yuz minglar xonasida.', '<b>3.</b> У какого числа первая отличающаяся цифра больше, то число и больше. Дальше цифры уже не важны: 3 405 007 &gt; 3 045 997, потому что 4 &gt; 0 в разряде сотен тысяч.', '<b>3.</b> Whichever number has the bigger digit at the first difference is bigger. Later digits no longer matter: 3 405 007 &gt; 3 045 997, because 4 &gt; 0 in the hundred-thousands place.'),
      L('<b>4.</b> Barcha raqamlar bir xil bo‘lsa — sonlar teng.', '<b>4.</b> Если все цифры совпали — числа равны.', '<b>4.</b> If all digits match, the numbers are equal.')
    ], after: [
      L('Nega bu qoida to‘g‘ri? Chunki har bir xona birligi o‘zidan o‘ngdagi barcha xonalardan ko‘ra «og‘irroq». Masalan, bitta yuz ming (100 000) o‘zidan keyingi barcha xonalardagi eng katta son — 99 999 dan ham katta. Shuning uchun yuqori xonada 1 ga ko‘p bo‘lsa, pastdagi raqamlar qanchalik katta bo‘lmasin, natijani o‘zgartira olmaydi. Xuddi pul kabi: bitta 100 000 so‘mlik banknot 9 ta 10 000 lik va 9 ta 1 000 lik banknotdan ham ko‘p pul. Taqqoslashda sonlarni bir-birining ostiga, xona ostiga xona qilib yozib olsangiz, farq qiladigan birinchi xonani topish ancha oson bo‘ladi.', 'Почему правило верно? Потому что каждая разрядная единица «тяжелее» всех разрядов справа вместе взятых. Например, одна сотня тысяч (100 000) больше, чем самое большое число из следующих разрядов — 99 999. Поэтому если в старшем разряде на 1 больше, младшие цифры, какими бы большими они ни были, результат не изменят. Как с деньгами: одна купюра в 100 000 сум — больше, чем 9 купюр по 10 000 и 9 по 1 000. При сравнении удобно записать числа друг под другом, разряд под разрядом, — так проще найти первый отличающийся разряд.', 'Why is the rule true? Because each place unit “outweighs” all the places to its right put together. For example, one hundred-thousand (100 000) is bigger than the largest number the lower places can hold — 99 999. So if a higher place is bigger by 1, the lower digits, however large, cannot change the result. It is like money: one 100 000-sum note is worth more than nine 10 000 notes and nine 1 000 notes. When comparing, write the numbers one under the other, place under place — then the first differing place is easy to spot.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: o‘qish va yozish', 'Пошагово: чтение и запись', 'Step by step: reading and writing'), list: [
      L('<b>O‘qish: 40 302 060.</b> Sinflar: 40 | 302 | 060. O‘qiymiz: «qirq million uch yuz ikki ming oltmish».', '<b>Чтение: 40 302 060.</b> Классы: 40 | 302 | 060. Читаем: «сорок миллионов триста две тысячи шестьдесят».', '<b>Reading 40 302 060.</b> Periods: 40 | 302 | 060. Read: “forty million three hundred and two thousand and sixty”.'),
      L('<b>Yozish: «sakkiz million to‘qqiz ming o‘n bir».</b> Avval sinflar uchun uchta «quti» chizamiz: _ | ___ | ___.', '<b>Запись: «восемь миллионов девять тысяч одиннадцать».</b> Сначала рисуем «коробки» для классов: _ | ___ | ___.', '<b>Writing “eight million nine thousand and eleven”.</b> First draw “boxes” for the periods: _ | ___ | ___.'),
      L('Millionlar qutisiga 8. Minglar qutisiga «to‘qqiz» — uch raqamli qilib: 009. Birliklar qutisiga «o‘n bir»: 011.', 'В коробку миллионов — 8. В коробку тысяч — «девять» тремя цифрами: 009. В коробку единиц — «одиннадцать»: 011.', 'Millions box: 8. Thousands box: “nine” as three digits: 009. Ones box: “eleven”: 011.'),
      L('Natija: <b>8 009 011</b>. Tekshiramiz: 7 ta raqam — million sinfidagi son uchun to‘g‘ri.', 'Итог: <b>8 009 011</b>. Проверяем: 7 цифр — верно для числа из класса миллионов.', 'Result: <b>8 009 011</b>. Check: 7 digits — right for a number in the millions.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Taqqoslang: 3 045 007 va 3 405 007.', 'Сравни: 3 045 007 и 3 405 007.', 'Compare: 3 045 007 and 3 405 007.'), s: L('Raqamlar soni teng (7 ta). Millionlar: 3 = 3. Yuz minglar: 0 &lt; 4. Javob: <b>3 045 007 &lt; 3 405 007</b>.', 'Цифр поровну (7). Миллионы: 3 = 3. Сотни тысяч: 0 &lt; 4. Ответ: <b>3 045 007 &lt; 3 405 007</b>.', 'Same number of digits (7). Millions: 3 = 3. Hundred-thousands: 0 &lt; 4. Answer: <b>3 045 007 &lt; 3 405 007</b>.') },
      { q: L('Taqqoslang: 999 999 va 1 000 000.', 'Сравни: 999 999 и 1 000 000.', 'Compare: 999 999 and 1 000 000.'), s: L('999 999 da 6 ta raqam, 1 000 000 da 7 ta. Raqami ko‘p son katta: <b>999 999 &lt; 1 000 000</b>. To‘qqizlar ko‘p bo‘lsa ham!', 'В 999 999 шесть цифр, в 1 000 000 — семь. Больше цифр — больше число: <b>999 999 &lt; 1 000 000</b>. Хоть девяток и много!', '999 999 has 6 digits, 1 000 000 has 7. More digits means bigger: <b>999 999 &lt; 1 000 000</b> — despite all those nines!') },
      { q: L('Kichigidan kattasiga tartiblang: 2 050 000, 2 500 000, 250 000, 2 005 000.', 'Расположи от меньшего к большему: 2 050 000, 2 500 000, 250 000, 2 005 000.', 'Order from smallest to largest: 2 050 000, 2 500 000, 250 000, 2 005 000.'), s: L('250 000 — 6 xonali, eng kichik. Qolganlari 7 xonali, yuz minglar: 0, 5, 0; o‘n minglar: 5 va 0. Javob: <b>250 000 &lt; 2 005 000 &lt; 2 050 000 &lt; 2 500 000</b>.', '250 000 — шестизначное, самое маленькое. Остальные семизначные, сотни тысяч: 0, 5, 0; десятки тысяч: 5 и 0. Ответ: <b>250 000 &lt; 2 005 000 &lt; 2 050 000 &lt; 2 500 000</b>.', '250 000 has six digits — smallest. The others have seven; hundred-thousands: 0, 5, 0; ten-thousands: 5 and 0. Answer: <b>250 000 &lt; 2 005 000 &lt; 2 050 000 &lt; 2 500 000</b>.') },
      { q: L('5 *82 314 &gt; 5 782 314. * o‘rniga qaysi raqamlar mos?', '5 *82 314 &gt; 5 782 314. Какие цифры подходят вместо *?', '5 *82 314 &gt; 5 782 314. Which digits can replace *?'), s: L('Faqat yuz minglar xonasi farq qiladi: * &gt; 7. Javob: <b>8 yoki 9</b>.', 'Отличается только разряд сотен тысяч: * &gt; 7. Ответ: <b>8 или 9</b>.', 'Only the hundred-thousands place differs: * &gt; 7. Answer: <b>8 or 9</b>.') }
    ] },
    { kind: 'table', h: L('O‘zbekiston shaharlari (taxminiy aholi)', 'Города Узбекистана (примерное население)', 'Cities of Uzbekistan (approximate population)'), p: [
      L('Ma’lumotlar yaxlitlangan va yildan yilga o‘zgaradi. Ularni taqqoslab, kattadan kichikka tartiblang.', 'Данные округлены и меняются из года в год. Сравни и расположи от большего к меньшему.', 'The figures are rounded and change year by year. Compare them and order from largest to smallest.')
    ], table: { head: [L('Shahar', 'Город', 'City'), L('Aholi', 'Население', 'Population'), L('O‘qilishi', 'Чтение', 'Read as')], rows: [
      [L('Toshkent', 'Ташкент', 'Tashkent'), '3 000 000', L('uch million', 'три миллиона', 'three million')],
      [L('Samarqand', 'Самарканд', 'Samarkand'), '570 000', L('besh yuz yetmish ming', 'пятьсот семьдесят тысяч', 'five hundred and seventy thousand')],
      [L('Namangan', 'Наманган', 'Namangan'), '660 000', L('olti yuz oltmish ming', 'шестьсот шестьдесят тысяч', 'six hundred and sixty thousand')],
      [L('Buxoro', 'Бухара', 'Bukhara'), '290 000', L('ikki yuz to‘qson ming', 'двести девяносто тысяч', 'two hundred and ninety thousand')]
    ] }, after: [
      L('Tartib: Toshkent &gt; Namangan &gt; Samarqand &gt; Buxoro. Toshkent — mamlakatdagi yagona «millioner» shahar.', 'Порядок: Ташкент &gt; Наманган &gt; Самарканд &gt; Бухара. Ташкент — единственный город-миллионник страны.', 'Order: Tashkent &gt; Namangan &gt; Samarkand &gt; Bukhara. Tashkent is the country’s only city with over a million people.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Birinchi raqamga qarab taqqoslash.</b> 95 000 &gt; 1 200 000 deyish, chunki 9 &gt; 1. Avval raqamlar sonini solishtiring: 5 &lt; 7, demak 95 000 kichik.', '<b>Сравнивать по первой цифре.</b> Сказать 95 000 &gt; 1 200 000, ведь 9 &gt; 1. Сначала сравни количество цифр: 5 &lt; 7, значит, 95 000 меньше.', '<b>Comparing by the first digit.</b> Saying 95 000 &gt; 1 200 000 because 9 &gt; 1. First compare digit counts: 5 &lt; 7, so 95 000 is smaller.'),
      L('<b>Nol sinfini o‘qish.</b> 5 000 017 ni «besh million nol ming o‘n yetti» deb o‘qish. Faqat nollardan iborat sinf o‘qilmaydi.', '<b>Читать нулевой класс.</b> Читать 5 000 017 как «пять миллионов ноль тысяч семнадцать». Класс из одних нулей не читают.', '<b>Reading a zero period.</b> Reading 5 000 017 as “five million zero thousand seventeen”. A period of zeros is not read.'),
      L('<b>Sinfni ikki raqam bilan yozish.</b> «Uch million qirq besh ming» ni 345 000 yoki 3 45 000 deb yozish. Minglar sinfi — uchta raqam: 3 045 000.', '<b>Записать класс двумя цифрами.</b> Записать «три миллиона сорок пять тысяч» как 345 000. В классе тысяч три цифры: 3 045 000.', '<b>Writing a period with two digits.</b> Writing “three million forty-five thousand” as 345 000. The thousands period has three digits: 3 045 000.'),
      L('<b>Belgini teskari qo‘yish.</b> &gt; va &lt; ni almashtirish. Eslab qoling: o‘tkir uchi kichik songa, ochiq tomoni katta songa qaraydi.', '<b>Перевернуть знак.</b> Путать &gt; и &lt;. Запомни: острый конец смотрит на меньшее число, открытая сторона — на большее.', '<b>Flipping the sign.</b> Mixing up &gt; and &lt;. Remember: the point faces the smaller number, the open side the bigger one.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Xarid qilishda.</b> Bir do‘konda televizor 4 590 000 so‘m, boshqasida 4 950 000 so‘m. Qaysi arzon? Millionlar teng (4), yuz minglar: 5 &lt; 9 — birinchi do‘kon arzonroq, 360 000 so‘m tejaysiz.', '<b>При покупке.</b> В одном магазине телевизор стоит 4 590 000 сум, в другом — 4 950 000. Где дешевле? Миллионы равны (4), сотни тысяч: 5 &lt; 9 — в первом дешевле, экономия 360 000 сум.', '<b>Shopping.</b> A TV costs 4 590 000 sum in one shop and 4 950 000 in another. Which is cheaper? Millions equal (4), hundred-thousands 5 &lt; 9 — the first shop, saving 360 000 sum.'),
      L('<b>Bank va telefon.</b> Bank ilovasida hisob raqami, telefon raqamlari ham ko‘p xonali. Ularni sinflarga bo‘lib o‘qish xatolarni kamaytiradi: +998 90 123 45 67.', '<b>Банк и телефон.</b> Номера счетов в банковском приложении и номера телефонов тоже многозначные. Читать их группами — меньше ошибок: +998 90 123 45 67.', '<b>Banks and phones.</b> Account numbers in a banking app and phone numbers are long too. Reading them in groups reduces mistakes: +998 90 123 45 67.'),
      L('<b>Geografiya.</b> Daryolar uzunligi, tog‘lar balandligi, mamlakatlar maydoni — hammasi taqqoslanadi. Amudaryo (2 540 km) Sirdaryodan (2 212 km) uzunroq — lekin turli manbalar biroz farqli sonlarni beradi, shuning uchun manbaga e’tibor bering.', '<b>География.</b> Длины рек, высоты гор, площади стран — всё сравнивают. Амударья (2 540 км) длиннее Сырдарьи (2 212 км) — но разные источники дают немного разные числа, поэтому обращай внимание на источник.', '<b>Geography.</b> River lengths, mountain heights and country areas are all compared. The Amu Darya (2 540 km) is longer than the Syr Darya (2 212 km) — though sources give slightly different figures, so always note the source.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Ingliz tilida «billion» bugun 1 000 000 000 (milliard), lekin ilgari Britaniyada u 1 000 000 000 000 ni bildirgan. 1974-yilda Britaniya rasman Amerika ma’nosiga o‘tgan.', 'В английском «billion» сегодня — 1 000 000 000 (миллиард), но раньше в Британии так называли 1 000 000 000 000. В 1974 году Британия официально перешла на американское значение.', 'In English, “billion” today means 1 000 000 000, but in Britain it used to mean 1 000 000 000 000. In 1974 Britain officially switched to the American meaning.'),
      L('Yer sayyorasida 8 milliarddan ortiq odam yashaydi — bu 8 000 dan ortiq million!', 'На Земле живёт больше 8 миллиардов человек — это больше 8 000 миллионов!', 'More than 8 billion people live on Earth — that is over 8 000 million!'),
      L('Eng katta pul banknoti: 1946-yilda Vengriyada 100 kvintillion (1 dan keyin 20 ta nol) pengolik banknot chiqarilgan — inflyatsiya tufayli.', 'Самая «большая» банкнота: в 1946 году в Венгрии выпустили купюру в 100 квинтиллионов (1 и 20 нулей) пенгё — из-за инфляции.', 'The “biggest” banknote: in 1946 Hungary issued a 100 quintillion (1 followed by 20 zeros) pengő note because of inflation.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('O‘qing: 60 006 600.', 'Прочитай: 60 006 600.', 'Read: 60 006 600.'),
      L('Raqamlar bilan yozing: «bir yuz bir million bir ming bir».', 'Запиши цифрами: «сто один миллион одна тысяча один».', 'Write in digits: “one hundred and one million one thousand and one”.'),
      L('Belgi qo‘ying: 7 008 900 ◻ 7 080 090.', 'Поставь знак: 7 008 900 ◻ 7 080 090.', 'Put the sign: 7 008 900 ◻ 7 080 090.')
    ], after: [
      L('Javoblar: 1) oltmish million olti ming olti yuz; 2) 101 001 001; 3) &lt; (o‘n minglar xonasida 0 &lt; 8).', 'Ответы: 1) шестьдесят миллионов шесть тысяч шестьсот; 2) 101 001 001; 3) &lt; (в разряде десятков тысяч 0 &lt; 8).', 'Answers: 1) sixty million six thousand six hundred; 2) 101 001 001; 3) &lt; (ten-thousands place: 0 &lt; 8).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Sonni o‘ngdan uchtadan sinflarga ajratib, chapdan o‘qiymiz.', 'Делим число справа на классы по три и читаем слева.', 'Split into periods of three from the right; read from the left.'),
      L('Faqat nollardan iborat sinf o‘qilmaydi; birliklar sinfining nomi aytilmaydi.', 'Класс из одних нулей не читают; название класса единиц не произносят.', 'A zero period is not read; the ones period name is not said.'),
      L('Yozishda har bir sinf uchta raqamdan iborat (birinchisidan tashqari).', 'При записи в каждом классе три цифры (кроме первого).', 'When writing, every period has three digits (except the first).'),
      L('Taqqoslash: avval raqamlar soni, keyin chapdan raqamlar.', 'Сравнение: сначала количество цифр, потом цифры слева.', 'Comparing: first the digit count, then digits from the left.'),
      L('Birinchi farq qilgan raqam javobni hal qiladi.', 'Первая отличающаяся цифра решает ответ.', 'The first differing digit decides.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t17. Ko‘p xonali sonlarni qo‘shish va ayirish ----------
  T.add(P, 't17', { sections: [
    { kind: 'intro', h: L('Millionlar bilan hisoblaymiz', 'Считаем с миллионами', 'Calculating with millions'), p: [
      L('Viloyatda birinchi yili 450 000 tup, ikkinchi yili 550 000 tup daraxt ekildi. Jami nechta? 450 000 + 550 000 = 1 000 000 — roppa-rosa bir million! Ko‘p xonali sonlarni qo‘shish va ayirish 3-sinfda o‘rgangan ustun usulining davomi, faqat endi sonlar uzunroq.', 'В области в первый год посадили 450 000 деревьев, во второй — 550 000. Сколько всего? 450 000 + 550 000 = 1 000 000 — ровно миллион! Сложение и вычитание многозначных чисел — продолжение столбика из 3 класса, только числа теперь длиннее.', 'In the first year 450 000 trees were planted in the region, in the second 550 000. How many in all? 450 000 + 550 000 = 1 000 000 — exactly one million! Adding and subtracting large numbers continues the column method from Grade 3; the numbers are just longer.'),
      L('Uzun sonlarda xato qilish oson: bitta raqamni noto‘g‘ri xonaga yozsangiz, javob minglab yoki millionlab farq qiladi. Shuning uchun bu mavzuda biz tartibli yozishga, o‘tkazish va qarz olishni to‘g‘ri bajarishga va javobni tekshirishga alohida e’tibor beramiz.', 'В длинных числах легко ошибиться: одна цифра не в том разряде — и ответ отличается на тысячи или миллионы. Поэтому в этой теме мы особенно следим за аккуратной записью, правильным переносом и заёмом и проверкой ответа.', 'With long numbers mistakes are easy: one digit in the wrong place and the answer is off by thousands or millions. So in this topic we pay special attention to neat writing, correct carrying and borrowing, and checking the answer.'),
      L('Ayniqsa qiyin holat — ko‘p nolli sondan ayirish, masalan 1 000 000 − 1. Uni ham oson yechishni o‘rganamiz.', 'Особенно трудный случай — вычитание из числа с множеством нулей, например 1 000 000 − 1. Научимся решать и такое легко.', 'The trickiest case is subtracting from a number full of zeros, like 1 000 000 − 1. We will learn to do that easily too.')
    ] },
    { kind: 'def', h: L('Qo‘shish va ayirish komponentlari', 'Компоненты сложения и вычитания', 'Parts of addition and subtraction'), p: [
      L('<b>Qo‘shiluvchi + qo‘shiluvchi = yig‘indi</b>. <b>Kamayuvchi − ayriluvchi = ayirma</b>. Qo‘shish va ayirish o‘zaro teskari amallar: agar 450 000 + 550 000 = 1 000 000 bo‘lsa, 1 000 000 − 550 000 = 450 000.', '<b>Слагаемое + слагаемое = сумма</b>. <b>Уменьшаемое − вычитаемое = разность</b>. Сложение и вычитание — взаимно обратные действия: если 450 000 + 550 000 = 1 000 000, то 1 000 000 − 550 000 = 450 000.', '<b>Addend + addend = sum</b>. <b>Minuend − subtrahend = difference</b>. Addition and subtraction undo each other: if 450 000 + 550 000 = 1 000 000, then 1 000 000 − 550 000 = 450 000.'),
      L('<b>O‘tkazish</b> — qo‘shishda xonadagi yig‘indi 10 dan oshganda, bitta birlikni keyingi (chapdagi) xonaga o‘tkazish. <b>Qarz olish</b> — ayirishda yuqoridagi raqam kichik bo‘lsa, chapdagi xonadan 1 ni olib, uni 10 ta kichik birlikka aylantirish.', '<b>Перенос</b> — при сложении, если сумма в разряде больше 9, одну единицу переносим в следующий (левый) разряд. <b>Заём</b> — при вычитании, если верхняя цифра меньше, берём 1 у левого разряда и превращаем её в 10 единиц меньшего разряда.', 'A <b>carry</b> happens in addition when a column sum passes 9: one unit moves to the next (left) place. A <b>borrow</b> happens in subtraction when the top digit is smaller: take 1 from the left place and turn it into 10 units of the smaller place.'),
      L('Qo‘shishning xossalari: o‘rin almashtirish (a + b = b + a) va guruhlash ((a + b) + c = a + (b + c)). Ular og‘zaki hisobni osonlashtiradi: 370 000 + 245 000 + 630 000 = (370 000 + 630 000) + 245 000 = 1 245 000.', 'Свойства сложения: переместительное (a + b = b + a) и сочетательное ((a + b) + c = a + (b + c)). Они облегчают устный счёт: 370 000 + 245 000 + 630 000 = (370 000 + 630 000) + 245 000 = 1 245 000.', 'Properties of addition: commutative (a + b = b + a) and associative ((a + b) + c = a + (b + c)). They make mental maths easier: 370 000 + 245 000 + 630 000 = (370 000 + 630 000) + 245 000 = 1 245 000.')
    ] },
    { kind: 'history', h: L('Cho‘tdan kompyutergacha', 'От счётов до компьютера', 'From the abacus to the computer'), p: [
      L('Bir necha asr davomida savdogarlar katta sonlarni <b>cho‘t</b> (abak) yordamida qo‘shishgan. Cho‘tning har bir simi — bitta xona, unda 10 ta tosh. Simda 10 ta tosh to‘lsa, ularni qaytarib, keyingi simga bitta tosh surishgan — bu aynan «o‘tkazish»! O‘zbekiston bozorlarida cho‘tni XX asr oxirigacha ham ko‘rish mumkin edi.', 'Много веков купцы складывали большие числа на <b>счётах</b> (абаке). Каждая проволока счётов — один разряд, на ней 10 костяшек. Когда набиралось 10, их сбрасывали и на следующей проволоке откладывали одну — это и есть «перенос»! На базарах Узбекистана счёты можно было увидеть до конца XX века.', 'For centuries merchants added big numbers on an <b>abacus</b>. Each wire is one place with 10 beads. When 10 beads were reached, they were pushed back and one bead was moved on the next wire — that is exactly a “carry”! Abacuses could still be seen in Uzbek markets until the end of the 20th century.'),
      L('1642-yilda 19 yoshli fransuz Blez Paskal otasiga soliq hisobida yordam berish uchun birinchi mexanik qo‘shish mashinasini yasagan. Unda tishli g‘ildiraklar 9 dan 0 ga o‘tganda, qo‘shni g‘ildirakni bir pog‘ona burardi — o‘tkazishni mashina o‘zi bajarardi.', 'В 1642 году 19-летний француз Блез Паскаль, чтобы помочь отцу с налоговыми расчётами, построил первую механическую суммирующую машину. В ней зубчатое колесо, переходя с 9 на 0, поворачивало соседнее на один шаг — перенос машина делала сама.', 'In 1642 the 19-year-old Frenchman Blaise Pascal built the first mechanical adding machine to help his father with tax sums. When a gear wheel went from 9 to 0, it turned its neighbour one step — the machine did the carrying itself.'),
      L('Bugungi kompyuterlar soniyasiga milliardlab qo‘shishni bajaradi, lekin ichkarida ular ham xuddi shu «o‘tkazish» qoidasini ishlatadi — faqat ikkilik sanoq sistemasida.', 'Сегодня компьютеры выполняют миллиарды сложений в секунду, но внутри они пользуются тем же правилом «переноса» — только в двоичной системе.', 'Today’s computers do billions of additions a second, but inside they use the same carrying rule — only in the binary system.')
    ] },
    { kind: 'rule', h: L('Qoida', 'Правило', 'The rule'), list: [
      L('Sonlarni ustunga <b>o‘ng tomondan tekislab</b> yozing: birliklar ostida birliklar, minglar ostida minglar, millionlar ostida millionlar.', 'Записывай числа столбиком, <b>выравнивая по правому краю</b>: единицы под единицами, тысячи под тысячами, миллионы под миллионами.', 'Write the numbers in a column <b>aligned on the right</b>: ones under ones, thousands under thousands, millions under millions.'),
      L('Hisobni <b>o‘ngdan chapga</b>, birliklardan boshlang.', 'Считай <b>справа налево</b>, начиная с единиц.', 'Work <b>right to left</b>, starting with the ones.'),
      L('Qo‘shishda 9 dan oshsa — o‘tkazing; ayirishda yetmasa — qarz oling.', 'При сложении больше 9 — переноси; при вычитании не хватает — занимай.', 'In addition, past 9 — carry; in subtraction, too small — borrow.'),
      L('Nol bo‘lgan xonadan qarz olib bo‘lmaydi — keyingi nol bo‘lmagan xonagacha boring; o‘tib ketilgan nollar 9 ga aylanadi.', 'У нулевого разряда занять нельзя — идём до ближайшего ненулевого разряда; пройденные нули превращаются в 9.', 'You cannot borrow from a zero — go left to the nearest non-zero place; the zeros passed over become 9s.'),
      L('Javobni teskari amal bilan tekshiring.', 'Проверяй ответ обратным действием.', 'Check the answer with the inverse operation.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 1 000 000 − 254 368', 'Пошагово: 1 000 000 − 254 368', 'Step by step: 1 000 000 − 254 368'), list: [
      L('<b>Birliklar:</b> 0 dan 8 ni ayirib bo‘lmaydi. Chapda faqat nollar — eng yaqin nol bo‘lmagan raqam milliondagi 1. Undan qarz olamiz.', '<b>Единицы:</b> из 0 не вычесть 8. Слева одни нули — ближайшая ненулевая цифра — 1 миллионов. Занимаем у неё.', '<b>Ones:</b> cannot take 8 from 0. Only zeros to the left — the nearest non-zero digit is the 1 in the millions. Borrow from it.'),
      L('<b>Qarz zanjiri:</b> 1 million → 10 yuz ming. Bittasini olib, 9 qoladi; shu tarzda har bir oraliq nol 9 ga aylanadi, birliklar esa 10 bo‘ladi. Endi kamayuvchi go‘yo 0 | 999 | 99(10).', '<b>Цепочка займов:</b> 1 миллион → 10 сотен тысяч. Берём одну, остаётся 9; так каждый промежуточный нуль становится 9, а единиц становится 10. Теперь уменьшаемое как бы 0 | 999 | 99(10).', '<b>Chain of borrows:</b> 1 million → 10 hundred-thousands. Take one, 9 remain; in this way every zero in between becomes 9 and the ones become 10. Now the minuend is in effect 0 | 999 | 99(10).'),
      L('<b>Ayiramiz:</b> 10 − 8 = 2; 9 − 6 = 3; 9 − 3 = 6; 9 − 4 = 5; 9 − 5 = 4; 9 − 2 = 7. Javob: <b>745 632</b>.', '<b>Вычитаем:</b> 10 − 8 = 2; 9 − 6 = 3; 9 − 3 = 6; 9 − 4 = 5; 9 − 5 = 4; 9 − 2 = 7. Ответ: <b>745 632</b>.', '<b>Subtract:</b> 10 − 8 = 2; 9 − 6 = 3; 9 − 3 = 6; 9 − 4 = 5; 9 − 5 = 4; 9 − 2 = 7. Answer: <b>745 632</b>.'),
      L('<b>Tez yo‘l:</b> 1 000 000 − 254 368 = (999 999 − 254 368) + 1 = 745 631 + 1 = 745 632. 999 999 dan ayirishda hech qachon qarz kerak emas!', '<b>Быстрый путь:</b> 1 000 000 − 254 368 = (999 999 − 254 368) + 1 = 745 631 + 1 = 745 632. При вычитании из 999 999 заём не нужен никогда!', '<b>Shortcut:</b> 1 000 000 − 254 368 = (999 999 − 254 368) + 1 = 745 631 + 1 = 745 632. Subtracting from 999 999 never needs a borrow!'),
      L('<b>Tekshiruv:</b> 745 632 + 254 368 = 1 000 000. To‘g‘ri!', '<b>Проверка:</b> 745 632 + 254 368 = 1 000 000. Верно!', '<b>Check:</b> 745 632 + 254 368 = 1 000 000. Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '367 485 + 248 936', s: L('5 + 6 = 11 (1, o‘tkaz 1); 8 + 3 + 1 = 12 (2, o‘tkaz 1); 4 + 9 + 1 = 14 (4, o‘tkaz 1); 7 + 8 + 1 = 16 (6, o‘tkaz 1); 6 + 4 + 1 = 11 (1, o‘tkaz 1); 3 + 2 + 1 = 6. Javob: <b>616 421</b>.', '5 + 6 = 11 (1, перенос 1); 8 + 3 + 1 = 12 (2, перенос 1); 4 + 9 + 1 = 14 (4, перенос 1); 7 + 8 + 1 = 16 (6, перенос 1); 6 + 4 + 1 = 11 (1, перенос 1); 3 + 2 + 1 = 6. Ответ: <b>616 421</b>.', '5 + 6 = 11 (1, carry 1); 8 + 3 + 1 = 12 (2, carry 1); 4 + 9 + 1 = 14 (4, carry 1); 7 + 8 + 1 = 16 (6, carry 1); 6 + 4 + 1 = 11 (1, carry 1); 3 + 2 + 1 = 6. Answer: <b>616 421</b>.') },
      { q: '5 030 400 − 2 816 750', s: L('Birliklar: 0 − 0 = 0. O‘nliklar: 0 − 5 — qarz (yuzliklar 4 → 3): 10 − 5 = 5. Yuzliklar: 3 − 7 — qarz (minglar 0, o‘n minglar 3 → 2, minglar 9): 13 − 7 = 6. Minglar: 9 − 6 = 3. O‘n minglar: 2 − 1 = 1. Yuz minglar: 0 − 8 — qarz (millionlar 5 → 4): 10 − 8 = 2. Millionlar: 4 − 2 = 2. Javob: <b>2 213 650</b>.', 'Единицы: 0 − 0 = 0. Десятки: 0 − 5 — заём (сотни 4 → 3): 10 − 5 = 5. Сотни: 3 − 7 — заём (тысячи 0, десятки тысяч 3 → 2, тысячи 9): 13 − 7 = 6. Тысячи: 9 − 6 = 3. Десятки тысяч: 2 − 1 = 1. Сотни тысяч: 0 − 8 — заём (миллионы 5 → 4): 10 − 8 = 2. Миллионы: 4 − 2 = 2. Ответ: <b>2 213 650</b>.', 'Ones: 0 − 0 = 0. Tens: 0 − 5 — borrow (hundreds 4 → 3): 10 − 5 = 5. Hundreds: 3 − 7 — borrow (thousands 0, so ten-thousands 3 → 2, thousands 9): 13 − 7 = 6. Thousands: 9 − 6 = 3. Ten-thousands: 2 − 1 = 1. Hundred-thousands: 0 − 8 — borrow (millions 5 → 4): 10 − 8 = 2. Millions: 4 − 2 = 2. Answer: <b>2 213 650</b>.') },
      { q: '450 000 + 550 000', s: L('Ming larda hisoblaymiz: 450 + 550 = 1 000 ming = <b>1 000 000</b>.', 'Считаем в тысячах: 450 + 550 = 1 000 тысяч = <b>1 000 000</b>.', 'Count in thousands: 450 + 550 = 1 000 thousand = <b>1 000 000</b>.') },
      { q: L('Kutubxonada 1 250 000 ta kitob bor edi. 86 500 tasi eskirgani uchun hisobdan chiqarildi, 124 000 ta yangi kitob keldi. Endi nechta kitob?', 'В библиотеке было 1 250 000 книг. 86 500 списали как устаревшие, поступило 124 000 новых. Сколько книг теперь?', 'A library had 1 250 000 books. 86 500 worn-out books were removed and 124 000 new ones arrived. How many books now?'), s: L('1 250 000 − 86 500 = 1 163 500. 1 163 500 + 124 000 = <b>1 287 500 ta</b>. Boshqa yo‘l: 124 000 − 86 500 = 37 500 ga ko‘paydi; 1 250 000 + 37 500 = 1 287 500.', '1 250 000 − 86 500 = 1 163 500. 1 163 500 + 124 000 = <b>1 287 500 книг</b>. Другой путь: книг стало больше на 124 000 − 86 500 = 37 500; 1 250 000 + 37 500 = 1 287 500.', '1 250 000 − 86 500 = 1 163 500. 1 163 500 + 124 000 = <b>1 287 500 books</b>. Another way: the stock grew by 124 000 − 86 500 = 37 500; 1 250 000 + 37 500 = 1 287 500.') }
    ] },
    { kind: 'table', h: L('Og‘zaki hisob uchun qulay juftlar', 'Удобные пары для устного счёта', 'Handy pairs for mental maths'), p: [
      L('Yig‘indisi yaxlit son bo‘ladigan juftlarni topsangiz, hisob tezlashadi.', 'Найди пары с круглой суммой — и счёт пойдёт быстрее.', 'Find pairs with a round sum and the work speeds up.')
    ], table: { head: [L('Juft', 'Пара', 'Pair'), L('Yig‘indi', 'Сумма', 'Sum')], rows: [
      ['450 000 + 550 000', '1 000 000'],
      ['375 000 + 625 000', '1 000 000'],
      ['999 999 + 1', '1 000 000'],
      ['1 000 000 − 1', '999 999'],
      ['1 000 000 − 100 000', '900 000'],
      ['2 500 000 + 7 500 000', '10 000 000']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Chapdan tekislash.</b> 1 250 000 va 86 500 ni chap chetdan tekislab yozish. Uzunligi har xil sonlarda bu juda xavfli — doim o‘ngdan tekislang.', '<b>Выравнивание слева.</b> Записать 1 250 000 и 86 500, выравнивая по левому краю. Для чисел разной длины это очень опасно — всегда выравнивай справа.', '<b>Aligning on the left.</b> Writing 1 250 000 and 86 500 lined up on the left. With numbers of different lengths that is very risky — always align on the right.'),
      L('<b>Nollardan qarz olishda adashish.</b> 1 000 000 − 1 ni 900 000 deb yozish. Har bir o‘tilgan nol 9 ga aylanadi: 999 999.', '<b>Ошибка при займе через нули.</b> Записать 1 000 000 − 1 = 900 000. Каждый пройденный нуль становится 9: 999 999.', '<b>Slipping when borrowing across zeros.</b> Writing 1 000 000 − 1 = 900 000. Every zero passed becomes 9: 999 999.'),
      L('<b>Oxirgi o‘tkazmani yo‘qotish.</b> 600 000 + 500 000 da 1 ni yozmay, 100 000 deb qoldirish. To‘g‘risi: 1 100 000.', '<b>Потерять последний перенос.</b> В 600 000 + 500 000 не записать 1 и оставить 100 000. Верно: 1 100 000.', '<b>Losing the final carry.</b> Leaving 600 000 + 500 000 as 100 000 without the leading 1. Correct: 1 100 000.'),
      L('<b>Kamaytirilgan raqamni unutish.</b> Qarz bergandan keyin chapdagi raqam 1 ga kamayadi. 5 030 400 − 2 816 750 da millionlar 5 emas, 4 bo‘lib qoladi.', '<b>Забыть уменьшенную цифру.</b> После заёма левая цифра уменьшается на 1. В 5 030 400 − 2 816 750 миллионов остаётся не 5, а 4.', '<b>Forgetting the reduced digit.</b> After lending, the left digit drops by 1. In 5 030 400 − 2 816 750 the millions become 4, not 5.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Oila byudjeti.</b> Oylik daromad 8 500 000 so‘m. Uy-joy uchun 1 200 000, oziq-ovqatga 3 750 000, transportga 640 000 so‘m sarflandi. Qolgan pul: 8 500 000 − (1 200 000 + 3 750 000 + 640 000) = 8 500 000 − 5 590 000 = 2 910 000 so‘m.', '<b>Семейный бюджет.</b> Месячный доход 8 500 000 сум. На жильё ушло 1 200 000, на еду 3 750 000, на транспорт 640 000. Осталось: 8 500 000 − (1 200 000 + 3 750 000 + 640 000) = 8 500 000 − 5 590 000 = 2 910 000 сум.', '<b>Family budget.</b> Monthly income is 8 500 000 sum. Housing took 1 200 000, food 3 750 000, transport 640 000. Left: 8 500 000 − (1 200 000 + 3 750 000 + 640 000) = 8 500 000 − 5 590 000 = 2 910 000 sum.'),
      L('<b>Turizm.</b> O‘zbekistonga bir yili 6 600 000 sayyoh, keyingi yili 8 200 000 sayyoh kelgan bo‘lsa, o‘sish 8 200 000 − 6 600 000 = 1 600 000 kishi. Bunday hisoblar mehmonxona va aeroportlarni rejalashtirishda kerak.', '<b>Туризм.</b> Если за один год в Узбекистан приехали 6 600 000 туристов, а за следующий 8 200 000, рост — 8 200 000 − 6 600 000 = 1 600 000 человек. Такие расчёты нужны для планирования гостиниц и аэропортов.', '<b>Tourism.</b> If 6 600 000 tourists came to Uzbekistan one year and 8 200 000 the next, the growth was 8 200 000 − 6 600 000 = 1 600 000 people. Such sums help plan hotels and airports.'),
      L('<b>Masofalar.</b> Yerdan Marsgacha masofa o‘zgarib turadi: eng yaqin holatda taxminan 55 000 000 km, eng uzoqda 400 000 000 km atrofida. Farq: 345 000 000 km!', '<b>Расстояния.</b> Расстояние от Земли до Марса меняется: в ближайшей точке около 55 000 000 км, в дальней — около 400 000 000 км. Разница: 345 000 000 км!', '<b>Distances.</b> The distance from Earth to Mars changes: about 55 000 000 km at its closest and around 400 000 000 km at its farthest. Difference: 345 000 000 km!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Yosh Karl Gauss (1777–1855) maktabda 1 dan 100 gacha sonlarning yig‘indisini bir necha soniyada topgan: 1 + 100, 2 + 99, … — 50 ta juft, har biri 101. Jami: 5 050.', 'Юный Карл Гаусс (1777–1855) в школе за несколько секунд нашёл сумму чисел от 1 до 100: 1 + 100, 2 + 99, … — 50 пар по 101. Всего 5 050.', 'Young Carl Gauss (1777–1855) found the sum of 1 to 100 in seconds at school: 1 + 100, 2 + 99, … — 50 pairs of 101. Total: 5 050.'),
      L('123 456 789 + 987 654 321 = 1 111 111 110 — deyarli hammasi birlar!', '123 456 789 + 987 654 321 = 1 111 111 110 — почти одни единицы!', '123 456 789 + 987 654 321 = 1 111 111 110 — almost all ones!'),
      L('Paskal mashinasining bir nechta nusxasi bugungacha saqlangan va muzeylarda ko‘rsatiladi.', 'Несколько экземпляров машины Паскаля сохранились до наших дней и выставляются в музеях.', 'Several of Pascal’s machines survive and are displayed in museums.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 2 000 000 − 1 234 567.', 'Вычисли: 2 000 000 − 1 234 567.', 'Work out: 2 000 000 − 1 234 567.'),
      L('Qulay usulda: 280 000 + 395 000 + 720 000 + 605 000.', 'Удобным способом: 280 000 + 395 000 + 720 000 + 605 000.', 'The handy way: 280 000 + 395 000 + 720 000 + 605 000.'),
      L('Qaysi son 1 000 000 dan 37 tadan kam?', 'Какое число на 37 меньше 1 000 000?', 'Which number is 37 less than 1 000 000?')
    ], after: [
      L('Javoblar: 1) 765 433; 2) (280 000 + 720 000) + (395 000 + 605 000) = 2 000 000; 3) 999 963.', 'Ответы: 1) 765 433; 2) (280 000 + 720 000) + (395 000 + 605 000) = 2 000 000; 3) 999 963.', 'Answers: 1) 765 433; 2) (280 000 + 720 000) + (395 000 + 605 000) = 2 000 000; 3) 999 963.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Sonlarni o‘ngdan tekislab, xona ostiga xona yozamiz.', 'Пишем числа с выравниванием справа, разряд под разрядом.', 'Align on the right, place under place.'),
      L('Hisob o‘ngdan chapga: o‘tkazish va qarz olish.', 'Считаем справа налево: перенос и заём.', 'Work right to left, carrying and borrowing.'),
      L('Nollardan qarz olganda o‘tilgan nollar 9 ga aylanadi.', 'При заёме через нули пройденные нули становятся девятками.', 'Borrowing across zeros turns them into 9s.'),
      L('1 000 000 − a = (999 999 − a) + 1 — qarzsiz tez yo‘l.', '1 000 000 − a = (999 999 − a) + 1 — быстрый путь без заёмов.', '1 000 000 − a = (999 999 − a) + 1 — the borrow-free shortcut.'),
      L('O‘rin almashtirish va guruhlash og‘zaki hisobni tezlashtiradi.', 'Переместительное и сочетательное свойства ускоряют устный счёт.', 'Commutative and associative properties speed up mental maths.'),
      L('Har doim teskari amal bilan tekshiring.', 'Всегда проверяй обратным действием.', 'Always check with the inverse operation.')
    ] }
  ] });

  // ---------- t18. Ko‘p xonali sonlarni ko‘paytirish va bo‘lish ----------
  T.add(P, 't18', { sections: [
    { kind: 'intro', h: L('Nollar — yordamchi do‘stlar', 'Нули — друзья-помощники', 'Zeros are helpful friends'), p: [
      L('Sayohat narxi bir kishi uchun 1 500 000 so‘m. 4 kishilik oila qancha to‘laydi? 36 000 so‘mni 4 kishiga teng bo‘lsa, har biriga qancha? Bunday katta sonlar bilan hisoblash qo‘rqinchli ko‘rinadi, lekin aslida juda oson — agar nollar bilan to‘g‘ri ishlashni bilsangiz.', 'Поездка стоит 1 500 000 сум на человека. Сколько заплатит семья из 4 человек? Если 36 000 сум поделить на 4 человек, сколько каждому? Считать с такими большими числами кажется страшно, но на самом деле очень легко — если умеешь обращаться с нулями.', 'A trip costs 1 500 000 sum per person. How much does a family of 4 pay? If 36 000 sum is shared by 4 people, how much each? Calculating with such big numbers looks scary, but it is actually easy — if you know how to handle zeros.'),
      L('Sir oddiy: 36 000 — bu 36 ta ming. 36 ta mingni 4 ga bo‘lsak, 9 ta ming chiqadi: 9 000. Biz katta sonni «mingliklar», «yuzliklar» kabi yirik birliklarda hisoblaymiz va jadvaldagi oddiy misolga keltiramiz.', 'Секрет прост: 36 000 — это 36 тысяч. 36 тысяч разделить на 4 — получим 9 тысяч: 9 000. Мы считаем большое число в крупных единицах — «тысячах», «сотнях» — и сводим к простому табличному примеру.', 'The secret is simple: 36 000 is 36 thousands. 36 thousands divided by 4 is 9 thousands: 9 000. We count the big number in large units — “thousands”, “hundreds” — and reduce it to a simple times-table fact.'),
      L('Bu mavzuda yaxlit sonlarni ko‘paytirish va bo‘lish, ko‘p xonali sonni bir xonali songa bo‘lish va masalalarni yechishni mustahkamlaymiz.', 'В этой теме закрепляем умножение и деление круглых чисел, деление многозначного числа на однозначное и решение задач.', 'In this topic we consolidate multiplying and dividing round numbers, dividing a large number by a one-digit number and solving problems.')
    ] },
    { kind: 'def', h: L('Yirik birliklarda hisoblash', 'Счёт крупными единицами', 'Counting in large units'), p: [
      L('Har qanday yaxlit sonni «necha ta yirik birlik» deb o‘qish mumkin: 36 000 = 36 ming; 4 200 = 42 yuz; 1 500 000 = 15 yuz ming yoki 1 500 ming. Bu bizga nollarni vaqtincha «chetga qo‘yish» imkonini beradi.', 'Любое круглое число можно прочитать как «столько-то крупных единиц»: 36 000 = 36 тысяч; 4 200 = 42 сотни; 1 500 000 = 15 сотен тысяч или 1 500 тысяч. Это позволяет временно «отложить» нули.', 'Any round number can be read as “so many large units”: 36 000 = 36 thousand; 4 200 = 42 hundred; 1 500 000 = 15 hundred-thousand or 1 500 thousand. This lets us set the zeros aside for a while.')
    ], list: [
      L('<b>Ko‘paytirish:</b> nolsiz qismlarni ko‘paytiramiz, keyin ikkala ko‘paytuvchidagi barcha nollarni qo‘shamiz: 50 · 140 = 5 · 14 · 100 = 7 000.', '<b>Умножение:</b> умножаем части без нулей, потом приписываем все нули обоих множителей: 50 · 140 = 5 · 14 · 100 = 7 000.', '<b>Multiplying:</b> multiply the parts without zeros, then append all the zeros of both factors: 50 · 140 = 5 · 14 · 100 = 7 000.'),
      L('<b>Bo‘lish (bir xonali songa):</b> bo‘linuvchini yirik birliklarda o‘qib bo‘lamiz: 36 000 : 4 = 36 ming : 4 = 9 ming.', '<b>Деление (на однозначное):</b> читаем делимое крупными единицами и делим: 36 000 : 4 = 36 тысяч : 4 = 9 тысяч.', '<b>Dividing by one digit:</b> read the dividend in large units and divide: 36 000 : 4 = 36 thousand : 4 = 9 thousand.'),
      L('<b>Bo‘lish (yaxlit songa):</b> ikkalasidan bir xil miqdorda nol olib tashlaymiz: 480 000 : 600 = 4 800 : 6 = 800.', '<b>Деление (на круглое число):</b> убираем у обоих поровну нулей: 480 000 : 600 = 4 800 : 6 = 800.', '<b>Dividing by a round number:</b> remove the same number of zeros from both: 480 000 : 600 = 4 800 : 6 = 800.')
    ] },
    { kind: 'history', h: L('Katta sonlar va savdo yo‘llari', 'Большие числа и торговые пути', 'Big numbers and trade routes'), p: [
      L('Buyuk ipak yo‘li bo‘ylab Samarqand, Buxoro, Xiva orqali minglab karvonlar o‘tgan. Savdogarlar tovar, pul va masofani hisoblashlari kerak edi: 300 tuya, har birida 150 kg yuk — jami 45 000 kg. Bunday hisoblar hind-arab raqamlari bilan juda tezlashgan.', 'По Великому шёлковому пути через Самарканд, Бухару, Хиву проходили тысячи караванов. Купцам нужно было считать товар, деньги и расстояния: 300 верблюдов по 150 кг груза — всего 45 000 кг. С индийско-арабскими цифрами такие расчёты сильно ускорились.', 'Thousands of caravans travelled the Great Silk Road through Samarkand, Bukhara and Khiva. Merchants had to count goods, money and distances: 300 camels with 150 kg each — 45 000 kg in all. Hindu-Arabic numerals made such sums much faster.'),
      L('Xorazmiy o‘z kitoblarida meros taqsimlash, savdo va o‘lchov masalalarini ham yechgan. U bu kitobni aynan odamlarning kundalik ehtiyojlari uchun yozganini ta’kidlagan: tijorat, yer o‘lchash, meros bo‘lish.', 'Аль-Хорезми в своих книгах решал и задачи о разделе наследства, торговле и измерениях. Он подчёркивал, что писал книгу именно для повседневных нужд людей: торговли, землемерия, раздела наследства.', 'In his books al-Khwarizmi also solved problems about inheritance, trade and measurement. He stressed that he wrote for people’s everyday needs: commerce, surveying land and dividing inheritances.'),
      L('Ulug‘bek davrida Samarqandda tanga zarb qilinib, katta miqdordagi pullar hisobi yuritilgan. Hisobchilar millionlab dirhamni ko‘paytirib va bo‘lib, xatoni «to‘qqizlik bilan tekshirish» orqali nazorat qilishgan.', 'Во времена Улугбека в Самарканде чеканили монеты и вели счёт крупным суммам. Счётчики умножали и делили миллионы дирхамов, проверяя ошибки «девяткой».', 'In Ulugh Beg’s time coins were minted in Samarkand and large sums were accounted for. Clerks multiplied and divided millions of dirhams, checking for errors with the check by nines.')
    ] },
    { kind: 'rule', h: L('Ko‘p xonali sonni bir xonali songa bo‘lish', 'Деление многозначного числа на однозначное', 'Dividing a large number by one digit'), list: [
      L('<b>1.</b> 1-to‘liqsiz bo‘linuvchini ajrating va bo‘linmadagi raqamlar sonini aniqlang.', '<b>1.</b> Выдели 1-е неполное делимое и определи число цифр частного.', '<b>1.</b> Take the 1st partial dividend and find the number of quotient digits.'),
      L('<b>2.</b> Jadval yordamida raqamni toping, ko‘paytiring va ayiring.', '<b>2.</b> По таблице найди цифру, умножь и вычти.', '<b>2.</b> Find the digit from the times table, multiply and subtract.'),
      L('<b>3.</b> Keyingi raqamni tushiring. U bo‘luvchidan kichik bo‘lsa — bo‘linmaga 0 yozing va yana bitta raqam tushiring.', '<b>3.</b> Снеси следующую цифру. Если число меньше делителя — пиши в частное 0 и сноси ещё одну цифру.', '<b>3.</b> Bring down the next digit. If it is smaller than the divisor, write 0 in the quotient and bring down another digit.'),
      L('<b>4.</b> Bo‘linuvchining barcha raqamlari tugaguncha takrorlang. Ko‘paytirib tekshiring.', '<b>4.</b> Повторяй, пока не кончатся цифры делимого. Проверь умножением.', '<b>4.</b> Repeat until the dividend’s digits run out. Check by multiplying.')
    ], after: [
      L('Nega bo‘linmadagi raqamlar sonini oldindan aniqlash shunchalik muhim? Chunki u «xavfsizlik kamari» vazifasini bajaradi. Agar siz bo‘linma 6 xonali bo‘lishini bilsangiz-u, javobingizda faqat 3 ta raqam chiqsa, demak qayerdadir nolni tushirib qoldirgansiz. Bu oddiy tekshiruv bir soniya oladi, lekin eng ko‘p uchraydigan xatoni ushlab qoladi. Shuningdek, javobni taxminan baholash ham foydali: 4 836 024 : 6 — bu 4 800 000 : 6 = 800 000 ga yaqin bo‘lishi kerak.', 'Почему так важно заранее знать число цифр частного? Это «ремень безопасности». Если ты знаешь, что частное шестизначное, а в ответе всего 3 цифры, значит, где-то потерян нуль. Такая проверка занимает секунду, но ловит самую частую ошибку. Полезна и прикидка: 4 836 024 : 6 должно быть около 4 800 000 : 6 = 800 000.', 'Why is it so important to know the number of quotient digits in advance? It is a “seat belt”. If you know the quotient has six digits but your answer has only three, a zero has been lost somewhere. The check takes a second but catches the most common mistake. An estimate helps too: 4 836 024 : 6 should be close to 4 800 000 : 6 = 800 000.'),
      L('Masalan, 4 836 024 : 6. 1-to‘liqsiz — 48, bo‘linma 6 xonali. 48 : 6 = 8; 3 &lt; 6 — 0; 36 : 6 = 6; 0 : 6 = 0; 2 &lt; 6 — 0; 24 : 6 = 4. Javob: 806 004. Tekshiruv: 806 004 · 6 = 4 836 024.', 'Например, 4 836 024 : 6. 1-е неполное — 48, в частном 6 цифр. 48 : 6 = 8; 3 &lt; 6 — 0; 36 : 6 = 6; 0 : 6 = 0; 2 &lt; 6 — 0; 24 : 6 = 4. Ответ: 806 004. Проверка: 806 004 · 6 = 4 836 024.', 'E.g. 4 836 024 : 6. The 1st partial dividend is 48, so the quotient has 6 digits. 48 : 6 = 8; 3 &lt; 6 — 0; 36 : 6 = 6; 0 : 6 = 0; 2 &lt; 6 — 0; 24 : 6 = 4. Answer: 806 004. Check: 806 004 · 6 = 4 836 024.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: 50 · 140 va 36 000 : 4', 'Пошагово: 50 · 140 и 36 000 : 4', 'Step by step: 50 · 140 and 36 000 : 4'), list: [
      L('<b>50 · 140.</b> Nollarni chetga: 5 va 14. 5 · 14 = 70.', '<b>50 · 140.</b> Откладываем нули: 5 и 14. 5 · 14 = 70.', '<b>50 · 140.</b> Set zeros aside: 5 and 14. 5 · 14 = 70.'),
      L('Chetga qo‘yilgan nollar: 50 da bitta, 140 da bitta — jami ikkita. 70 ga ikkita nol: <b>7 000</b>.', 'Отложенных нулей: в 50 один, в 140 один — всего два. К 70 приписываем два нуля: <b>7 000</b>.', 'Zeros set aside: one in 50, one in 140 — two in all. Append two zeros to 70: <b>7 000</b>.'),
      L('<b>36 000 : 4.</b> 36 000 ni «36 ming» deb o‘qiymiz. 36 : 4 = 9.', '<b>36 000 : 4.</b> Читаем 36 000 как «36 тысяч». 36 : 4 = 9.', '<b>36 000 : 4.</b> Read 36 000 as “36 thousand”. 36 : 4 = 9.'),
      L('Demak, 9 ming: <b>9 000</b>. Tekshiruv: 9 000 · 4 = 36 000.', 'Значит, 9 тысяч: <b>9 000</b>. Проверка: 9 000 · 4 = 36 000.', 'So 9 thousand: <b>9 000</b>. Check: 9 000 · 4 = 36 000.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: '1 500 000 · 4', s: L('15 yuz ming · 4 = 60 yuz ming = <b>6 000 000</b>. Bu — 4 kishilik oila uchun sayohat narxi.', '15 сотен тысяч · 4 = 60 сотен тысяч = <b>6 000 000</b>. Это цена поездки для семьи из 4 человек.', '15 hundred-thousands · 4 = 60 hundred-thousands = <b>6 000 000</b>. That is the trip price for a family of 4.') },
      { q: '480 000 : 600', s: L('Ikkalasidan ikkitadan nol olib tashlaymiz: 4 800 : 6. 48 yuz : 6 = 8 yuz = <b>800</b>.', 'Убираем по два нуля: 4 800 : 6. 48 сотен : 6 = 8 сотен = <b>800</b>.', 'Remove two zeros from each: 4 800 : 6. 48 hundred : 6 = 8 hundred = <b>800</b>.') },
      { q: '2 450 000 : 7', s: L('245 o‘n ming : 7 = 35 o‘n ming = <b>350 000</b>. Tekshiruv: 350 000 · 7 = 2 450 000.', '245 десятков тысяч : 7 = 35 десятков тысяч = <b>350 000</b>. Проверка: 350 000 · 7 = 2 450 000.', '245 ten-thousands : 7 = 35 ten-thousands = <b>350 000</b>. Check: 350 000 · 7 = 2 450 000.') },
      { q: L('Zavod 6 kunda 1 260 000 ta g‘isht ishlab chiqardi. Shu sur’atda 15 kunda nechta g‘isht chiqaradi?', 'Завод за 6 дней выпустил 1 260 000 кирпичей. Сколько он выпустит за 15 дней при той же скорости?', 'A factory made 1 260 000 bricks in 6 days. How many will it make in 15 days at the same rate?'), s: L('1) Bir kunda: 1 260 000 : 6 = 210 000 ta. 2) 15 kunda: 210 000 · 15 = 3 150 000 ta. Javob: <b>3 150 000 ta g‘isht</b>.', '1) За день: 1 260 000 : 6 = 210 000. 2) За 15 дней: 210 000 · 15 = 3 150 000. Ответ: <b>3 150 000 кирпичей</b>.', '1) Per day: 1 260 000 : 6 = 210 000. 2) In 15 days: 210 000 · 15 = 3 150 000. Answer: <b>3 150 000 bricks</b>.') }
    ] },
    { kind: 'table', h: L('Yirik birliklar bilan hisob', 'Счёт крупными единицами', 'Working in large units'), table: { head: [L('Misol', 'Пример', 'Example'), L('Yirik birliklarda', 'В крупных единицах', 'In large units'), L('Javob', 'Ответ', 'Answer')], rows: [
      ['36 000 : 4', L('36 ming : 4', '36 тыс. : 4', '36 thousand : 4'), '9 000'],
      ['4 200 · 30', L('42 yuz · 3 o‘n', '42 сотни · 3 десятка', '42 hundred · 3 tens'), '126 000'],
      ['720 000 : 9', L('72 o‘n ming : 9', '72 дес. тыс. : 9', '72 ten-thousand : 9'), '80 000'],
      ['250 · 4 000', L('25 o‘n · 4 ming', '25 дес. · 4 тыс.', '25 tens · 4 thousand'), '1 000 000'],
      ['5 600 000 : 8', L('56 yuz ming : 8', '56 сот. тыс. : 8', '56 hundred-thousand : 8'), '700 000']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Nollarni yo‘qotish.</b> 36 000 : 4 = 9 yoki 900 deyish. Bo‘linuvchida «ming» bor edi — javob ham «ming»da: 9 000. Ko‘paytirib tekshirish bu xatoni darhol ochadi.', '<b>Потерять нули.</b> Сказать 36 000 : 4 = 9 или 900. В делимом были «тысячи» — и ответ в тысячах: 9 000. Проверка умножением сразу выдаст ошибку.', '<b>Losing zeros.</b> Saying 36 000 : 4 = 9 or 900. The dividend was in “thousands”, so the answer is too: 9 000. A multiplication check reveals the slip at once.'),
      L('<b>Yashirin nolni unutish.</b> 50 · 140 da 5 · 14 = 70 dagi nolni hisobga olmay, 700 deyish. 70 ga yana ikkita nol: 7 000.', '<b>Забыть скрытый нуль.</b> В 50 · 140 не учесть нуль в 5 · 14 = 70 и сказать 700. К 70 ещё два нуля: 7 000.', '<b>Forgetting a hidden zero.</b> In 50 · 140, ignoring the zero in 5 · 14 = 70 and saying 700. Two more zeros go on 70: 7 000.'),
      L('<b>Bo‘linmadagi nollarni tashlab ketish.</b> 4 836 024 : 6 = 864 deyish. Har safar tushirilgan son bo‘luvchidan kichik bo‘lsa, 0 yoziladi: 806 004.', '<b>Пропустить нули в частном.</b> Сказать 4 836 024 : 6 = 864. Каждый раз, когда снесённое число меньше делителя, пишем 0: 806 004.', '<b>Dropping zeros in the quotient.</b> Saying 4 836 024 : 6 = 864. Each time the brought-down number is smaller than the divisor, write 0: 806 004.'),
      L('<b>Nollarni bir tomondan olib tashlash.</b> 480 000 : 600 da 48 : 600 qilish. Nollar ikkalasidan teng olinadi.', '<b>Убрать нули только у одного.</b> В 480 000 : 600 сделать 48 : 600. Нули убирают у обоих поровну.', '<b>Removing zeros from one side.</b> Turning 480 000 : 600 into 48 : 600. Zeros come off both equally.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this needed in life?'), p: [
      L('<b>Sayohat.</b> Ko‘lga sayohat bir kishi uchun 1 200 000 so‘m. 5 kishilik oila: 1 200 000 · 5 = 6 000 000 so‘m. Agar oila 10 oy davomida teng yig‘sa, oyiga 6 000 000 : 10 = 600 000 so‘m kerak.', '<b>Путешествие.</b> Поездка на озеро — 1 200 000 сум на человека. Семья из 5: 1 200 000 · 5 = 6 000 000 сум. Если копить поровну 10 месяцев, нужно 6 000 000 : 10 = 600 000 сум в месяц.', '<b>A trip.</b> A lake trip costs 1 200 000 sum per person. A family of 5: 1 200 000 · 5 = 6 000 000 sum. Saving equally over 10 months needs 6 000 000 : 10 = 600 000 sum a month.'),
      L('<b>Qishloq xo‘jaligi.</b> 1 gektar bog‘dan 25 000 kg olma olindi. 40 gektardan: 25 000 · 40 = 1 000 000 kg — bir million kilogramm, ya’ni 1 000 tonna!', '<b>Сельское хозяйство.</b> С 1 гектара сада собрали 25 000 кг яблок. С 40 гектаров: 25 000 · 40 = 1 000 000 кг — миллион килограммов, то есть 1 000 тонн!', '<b>Farming.</b> 1 hectare of orchard gave 25 000 kg of apples. 40 hectares: 25 000 · 40 = 1 000 000 kg — a million kilograms, that is 1 000 tonnes!'),
      L('<b>Elektr energiyasi.</b> Bitta uy oyiga 300 kVt·soat ishlatadi. 2 000 xonadonli mahalla: 300 · 2 000 = 600 000 kVt·soat. Energetiklar stansiyalarni shu hisob bilan rejalashtiradi.', '<b>Электроэнергия.</b> Один дом расходует 300 кВт·ч в месяц. Махалля из 2 000 домов: 300 · 2 000 = 600 000 кВт·ч. Энергетики планируют станции по такому расчёту.', '<b>Electricity.</b> One home uses 300 kWh a month. A neighbourhood of 2 000 homes: 300 · 2 000 = 600 000 kWh. Power engineers plan stations with this calculation.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Inson yuragi bir yilda taxminan 40 000 000 marta uradi: 110 000 (bir sutkada) · 365 ≈ 40 150 000.', 'Сердце человека за год бьётся около 40 000 000 раз: 110 000 (за сутки) · 365 ≈ 40 150 000.', 'A human heart beats about 40 000 000 times a year: 110 000 (per day) · 365 ≈ 40 150 000.'),
      L('1 000 · 1 000 = 1 000 000. Million — tomoni 1 000 katak bo‘lgan kvadratdagi kataklar soni. Agar har bir katak 1 sm bo‘lsa, bunday varaq 10 m × 10 m bo‘lardi — sinf xonasidan ham katta!', '1 000 · 1 000 = 1 000 000. Миллион — это число клеток в квадрате со стороной 1 000 клеток. Если клетка 1 см, такой лист был бы 10 м × 10 м — больше классной комнаты!', '1 000 · 1 000 = 1 000 000. A million is the number of squares in a 1 000-by-1 000 grid. With 1 cm squares the sheet would be 10 m × 10 m — bigger than a classroom!'),
      L('Asalari 1 kg asal yig‘ish uchun gullarga milliondan ortiq marta qo‘nadi, butun bir oila esa minglab kilometr uchadi.', 'Чтобы собрать 1 кг мёда, пчёлы садятся на цветы больше миллиона раз и пролетают тысячи километров.', 'To collect 1 kg of honey, bees land on flowers more than a million times and fly thousands of kilometres.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Hisoblang: 70 · 9 000 va 630 000 : 90.', 'Вычисли: 70 · 9 000 и 630 000 : 90.', 'Work out: 70 · 9 000 and 630 000 : 90.'),
      L('Hisoblang: 3 024 018 : 6.', 'Вычисли: 3 024 018 : 6.', 'Work out: 3 024 018 : 6.'),
      L('8 ta bir xil kompyuter 36 000 000 so‘m turadi. 3 ta shunday kompyuter qancha?', '8 одинаковых компьютеров стоят 36 000 000 сум. Сколько стоят 3 таких компьютера?', '8 identical computers cost 36 000 000 sum. How much do 3 of them cost?')
    ], after: [
      L('Javoblar: 1) 630 000 va 7 000; 2) 504 003; 3) 36 000 000 : 8 = 4 500 000, · 3 = 13 500 000 so‘m.', 'Ответы: 1) 630 000 и 7 000; 2) 504 003; 3) 36 000 000 : 8 = 4 500 000, · 3 = 13 500 000 сум.', 'Answers: 1) 630 000 and 7 000; 2) 504 003; 3) 36 000 000 : 8 = 4 500 000, · 3 = 13 500 000 sum.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Yaxlit sonlarni yirik birliklarda o‘qiymiz: 36 000 = 36 ming.', 'Круглые числа читаем крупными единицами: 36 000 = 36 тысяч.', 'Read round numbers in large units: 36 000 = 36 thousand.'),
      L('Ko‘paytirishda nollarni chetga olib, oxirida hammasini qo‘shamiz.', 'При умножении откладываем нули и в конце приписываем все.', 'In multiplication, set zeros aside and append them all at the end.'),
      L('Yaxlit songa bo‘lishda ikkalasidan teng nol olib tashlaymiz.', 'При делении на круглое число убираем у обоих поровну нулей.', 'Dividing by a round number, remove equal zeros from both.'),
      L('Bir xonali songa bo‘lishda bo‘linmadagi nollarni unutmang.', 'При делении на однозначное не забывай нули в частном.', 'Dividing by one digit, do not forget zeros in the quotient.'),
      L('Har bir javobni teskari amal bilan tekshiring.', 'Проверяй каждый ответ обратным действием.', 'Check every answer with the inverse operation.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '4-1';

  // ---------- t19. Misol va masalalar. Mantiqiy topshiriqlar ----------
  T.add(P, 't19', { sections: [
    { kind: 'intro', h: L('Detektiv bo‘lamiz', 'Становимся детективами', 'Becoming detectives'), p: [
      L('Qutida 50 tadan ko‘p bo‘lmagan konfet bor. Ularni 2, 3 yoki 4 nafar bolaga teng bo‘lish mumkin, lekin 5 nafarga bo‘lganda 3 ta ortib qoladi. Qutida nechta konfet? Bu masalada hech qanday murakkab amal yo‘q — faqat <b>mantiq</b>: shartlarni birma-bir tekshirib, mos kelmaydiganlarini chiqarib tashlaymiz. Xuddi detektiv kabi!', 'В коробке не больше 50 конфет. Их можно поровну разделить на 2, 3 или 4 детей, а при делении на 5 остаётся 3. Сколько конфет в коробке? В этой задаче нет сложных действий — только <b>логика</b>: проверяем условия по очереди и отбрасываем неподходящие варианты. Как детектив!', 'A box holds at most 50 sweets. They can be shared equally among 2, 3 or 4 children, but among 5 there are 3 left over. How many sweets are in the box? There is no hard arithmetic here — only <b>logic</b>: test the conditions one by one and rule out what does not fit. Just like a detective!'),
      L('Mantiqiy masalalar bu yil o‘rgangan hamma narsani birlashtiradi: bo‘luvchilar va karralilar, bo‘linish alomatlari, katta sonlar, amallar tartibi. Ular fikrlashni o‘stiradi va matematikaning eng qiziqarli qismi hisoblanadi.', 'Логические задачи объединяют всё, что мы изучили в этом году: делители и кратные, признаки делимости, большие числа, порядок действий. Они развивают мышление и считаются самой интересной частью математики.', 'Logic puzzles bring together everything we learned this year: divisors and multiples, divisibility rules, big numbers and the order of operations. They grow your thinking and are often the most fun part of maths.'),
      L('Bu mavzuda shartlarni tekshirish usulini, jadval va chizma bilan fikrlashni, sehrli kvadratlarni va «har biri har biri bilan» masalalarini o‘rganamiz.', 'В этой теме мы изучим проверку условий, рассуждения с таблицей и рисунком, магические квадраты и задачи «каждый с каждым».', 'In this topic we learn to test conditions, reason with tables and drawings, and explore magic squares and “everyone with everyone” problems.')
    ] },
    { kind: 'def', h: L('Mantiqiy masala nima?', 'Что такое логическая задача?', 'What is a logic puzzle?'), p: [
      L('<b>Mantiqiy masala</b> — javobni hisob-kitobdan ko‘ra ko‘proq <b>fikrlash</b> orqali topiladigan masala. Unda bir nechta <b>shart</b> beriladi va ularning hammasini bir vaqtda qanoatlantiradigan javob izlanadi.', '<b>Логическая задача</b> — задача, ответ на которую находят скорее <b>рассуждением</b>, чем вычислением. В ней дано несколько <b>условий</b>, и ищется ответ, удовлетворяющий им всем сразу.', 'A <b>logic puzzle</b> is a problem solved more by <b>reasoning</b> than by calculation. It gives several <b>conditions</b>, and we look for the answer that satisfies all of them at once.')
    ], list: [
      L('<b>Shart</b> — masaladagi talab: «2 ga bo‘linadi», «50 dan oshmaydi», «Azizdan yuqorida yashaydi».', '<b>Условие</b> — требование задачи: «делится на 2», «не больше 50», «живёт выше Азиза».', 'A <b>condition</b> is a requirement: “divisible by 2”, “at most 50”, “lives above Aziz”.'),
      L('<b>Variantlarni saralash</b> — barcha mumkin bo‘lgan javoblarni yozib, shartlarga mos kelmaydiganlarini chiqarib tashlash.', '<b>Перебор вариантов</b> — выписать все возможные ответы и вычеркнуть те, что не подходят под условия.', '<b>Trying the cases</b> — list every possible answer and cross out those that break a condition.'),
      L('<b>Qarama-qarshilik</b> — agar faraz boshqa shart bilan to‘qnashsa, demak faraz noto‘g‘ri.', '<b>Противоречие</b> — если предположение спорит с другим условием, значит, предположение неверно.', 'A <b>contradiction</b> — if an assumption clashes with another condition, the assumption is false.'),
      L('<b>Sehrli kvadrat</b> — kataklardagi sonlar har bir qator, ustun va diagonal bo‘yicha bir xil yig‘indi beradigan kvadrat.', '<b>Магический квадрат</b> — квадрат, в котором суммы чисел по каждой строке, столбцу и диагонали одинаковы.', 'A <b>magic square</b> is a grid where every row, column and diagonal adds up to the same sum.')
    ] },
    { kind: 'history', h: L('Topishmoq va jumboqlar tarixi', 'История головоломок', 'A history of puzzles'), p: [
      L('Eng qadimgi sehrli kvadrat — Xitoyning «Lo Shu» kvadrati. Rivoyatga ko‘ra, uni toshbaqa kosasidagi naqshdan ko‘rishgan. Unda 1 dan 9 gacha sonlar shunday joylashganki, har bir qator, ustun va diagonal yig‘indisi 15 ga teng.', 'Самый древний магический квадрат — китайский «Ло Шу». По легенде, его увидели в узоре на панцире черепахи. В нём числа от 1 до 9 расставлены так, что сумма по каждой строке, столбцу и диагонали равна 15.', 'The oldest magic square is China’s “Lo Shu”. Legend says it was seen in the pattern on a turtle’s shell. It places the numbers 1 to 9 so that every row, column and diagonal adds up to 15.'),
      L('O‘rta asr Sharq olimlari sehrli kvadratlarni chuqur o‘rganishgan. X asrda Abul-Vafo Buzjoniy va boshqa olimlar katta sehrli kvadratlarni tuzish usullarini yozib qoldirishgan. Ular bunday kvadratlarni bezak va hatto tumor sifatida ham ishlatishgan. 1514-yilda nemis rassomi Albrext Dyurer o‘zining mashhur gravyurasiga 4 × 4 sehrli kvadratni chizgan — yig‘indisi 34.', 'Средневековые восточные учёные глубоко изучали магические квадраты. В X веке Абу-ль-Вафа аль-Бузджани и другие описали способы составлять большие магические квадраты. Их использовали в украшениях и даже как обереги. В 1514 году немецкий художник Альбрехт Дюрер изобразил на своей знаменитой гравюре магический квадрат 4 × 4 — с суммой 34.', 'Medieval scholars of the East studied magic squares deeply. In the 10th century Abu al-Wafa al-Buzjani and others described methods for building large magic squares. They were used in decoration and even as charms. In 1514 the German artist Albrecht Dürer put a 4 × 4 magic square with sum 34 into his famous engraving.'),
      L('Taxminan 800-yilda ingliz olimi Alkuin «Yoshlarning aqlini charxlash uchun masalalar» to‘plamini tuzgan. Unda bo‘ri, echki va karam masalasi bor: dehqon ularni qayiqda daryodan o‘tkazishi kerak, lekin qayiqqa faqat bittasi sig‘adi, bo‘ri echkini, echki esa karamni yeb qo‘yishi mumkin. Bu masala hozir ham butun dunyoda yechiladi!', 'Около 800 года английский учёный Алкуин составил сборник «Задачи для изощрения ума юношей». В нём есть задача о волке, козе и капусте: крестьянин должен перевезти их через реку, но в лодку помещается лишь один груз, а волк может съесть козу, коза — капусту. Эту задачу решают по всему миру до сих пор!', 'Around 800 the English scholar Alcuin compiled “Problems to Sharpen the Young”. It includes the wolf, goat and cabbage puzzle: a farmer must ferry them across a river, but the boat carries only one at a time, and the wolf would eat the goat, the goat the cabbage. People all over the world still solve it today!')
    ] },
    { kind: 'rule', h: L('Mantiqiy masalani yechish qoidalari', 'Правила решения логической задачи', 'Rules for solving a logic puzzle'), list: [
      L('<b>1. Barcha shartlarni yozib oling.</b> Har birini alohida qatorga raqamlab yozing — birortasi ham e’tibordan chetda qolmasin.', '<b>1. Выпиши все условия.</b> Каждое — отдельной строкой с номером, чтобы ни одно не потерялось.', '<b>1. Write down all the conditions.</b> Number each on its own line so none is missed.'),
      L('<b>2. Eng «kuchli» shartdan boshlang.</b> Variantlarni eng ko‘p qisqartiradigan shartni birinchi qo‘llang. Konfet masalasida bu «2, 3 va 4 ga bo‘linadi» — demak son 12 ga karrali.', '<b>2. Начни с самого «сильного» условия.</b> Первым применяй то, что сильнее всего сокращает варианты. В задаче о конфетах это «делится на 2, 3 и 4» — значит, число кратно 12.', '<b>2. Start with the “strongest” condition.</b> Apply first the one that cuts the options most. In the sweets puzzle it is “divides by 2, 3 and 4” — so the number is a multiple of 12.'),
      L('<b>3. Variantlarni ro‘yxatga oling va saralang.</b> 50 gacha 12 ga karralilar: 12, 24, 36, 48.', '<b>3. Выпиши варианты и проверь их.</b> Кратные 12 до 50: 12, 24, 36, 48.', '<b>3. List the cases and test them.</b> Multiples of 12 up to 50: 12, 24, 36, 48.'),
      L('<b>4. Qolgan shartlar bilan tekshiring.</b> 5 ga bo‘lganda qoldiq 3: 12 → 2, 24 → 4, 36 → 1, 48 → 3. Faqat <b>48</b> mos!', '<b>4. Проверь остальными условиями.</b> Остаток 3 при делении на 5: 12 → 2, 24 → 4, 36 → 1, 48 → 3. Подходит только <b>48</b>!', '<b>4. Test with the remaining conditions.</b> Remainder 3 on division by 5: 12 → 2, 24 → 4, 36 → 1, 48 → 3. Only <b>48</b> fits!'),
      L('<b>5. Javobni barcha shartlar bilan qayta tekshiring.</b> 48 : 2 = 24, 48 : 3 = 16, 48 : 4 = 12, 48 = 5 · 9 + 3, 48 ≤ 50. Hammasi bajarildi.', '<b>5. Перепроверь ответ всеми условиями.</b> 48 : 2 = 24, 48 : 3 = 16, 48 : 4 = 12, 48 = 5 · 9 + 3, 48 ≤ 50. Всё выполнено.', '<b>5. Re-check the answer against every condition.</b> 48 : 2 = 24, 48 : 3 = 16, 48 : 4 = 12, 48 = 5 · 9 + 3, 48 ≤ 50. All satisfied.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich: qavatlar jumbog‘i', 'Пошагово: головоломка об этажах', 'Step by step: the floors puzzle'), p: [
      L('To‘rt do‘st — Doniyor, Jasur, Aziz va Kamron — bir uyning 2-, 3-, 4- va 5-qavatlarida yashaydi (har qavatda bittadan). Doniyor 2-qavatda, Jasur 5-qavatda. Aziz Doniyordan yuqorida, Kamron esa Azizdan pastda yashaydi. Aziz qaysi qavatda?', 'Четыре друга — Дониёр, Жасур, Азиз и Камрон — живут на 2, 3, 4 и 5 этажах одного дома (по одному на этаже). Дониёр на 2-м, Жасур на 5-м. Азиз живёт выше Дониёра, а Камрон ниже Азиза. На каком этаже Азиз?', 'Four friends — Doniyor, Jasur, Aziz and Kamron — live on floors 2, 3, 4 and 5 of one building (one per floor). Doniyor is on 2, Jasur on 5. Aziz lives above Doniyor, and Kamron below Aziz. Which floor is Aziz on?')
    ], list: [
      L('Doniyor — 2, Jasur — 5. Aziz va Kamron uchun bo‘sh: 3 va 4.', 'Дониёр — 2, Жасур — 5. Для Азиза и Камрона свободны 3 и 4.', 'Doniyor 2, Jasur 5. Floors 3 and 4 are left for Aziz and Kamron.'),
      L('Faraz qilaylik, Aziz 3-qavatda. Unda Kamron 4-qavatda — lekin u Azizdan <b>pastda</b> bo‘lishi kerak edi. Qarama-qarshilik!', 'Предположим, Азиз на 3-м. Тогда Камрон на 4-м — но он должен быть <b>ниже</b> Азиза. Противоречие!', 'Suppose Aziz is on 3. Then Kamron is on 4 — but he must be <b>below</b> Aziz. Contradiction!'),
      L('Demak, Aziz — <b>4-qavatda</b>, Kamron — 3-qavatda. Tekshiramiz: 4 &gt; 2 (Doniyordan yuqori), 3 &lt; 4 (Kamron pastda). To‘g‘ri!', 'Значит, Азиз — <b>на 4-м</b>, Камрон — на 3-м. Проверяем: 4 &gt; 2 (выше Дониёра), 3 &lt; 4 (Камрон ниже). Верно!', 'So Aziz is on <b>floor 4</b> and Kamron on 3. Check: 4 &gt; 2 (above Doniyor), 3 &lt; 4 (Kamron below). Correct!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('4 ta do‘st uchrashib, har biri har biri bilan bir martadan qo‘l berib ko‘rishdi. Nechta qo‘l berish bo‘ldi?', '4 друга встретились, и каждый пожал руку каждому один раз. Сколько было рукопожатий?', '4 friends met and each shook hands with each other once. How many handshakes?'), s: L('Har biri 3 kishi bilan ko‘rishadi: 4 · 3 = 12. Lekin har bir qo‘l berishda ikki kishi qatnashadi, shuning uchun har biri ikki marta sanaldi: 12 : 2 = <b>6</b>. Ro‘yxat: AB, AC, AD, BC, BD, CD.', 'Каждый жмёт руку троим: 4 · 3 = 12. Но в каждом рукопожатии участвуют двое, и каждое посчитано дважды: 12 : 2 = <b>6</b>. Список: АБ, АВ, АГ, БВ, БГ, ВГ.', 'Each shakes hands with 3 people: 4 · 3 = 12. But each handshake involves two people, so it was counted twice: 12 : 2 = <b>6</b>. List: AB, AC, AD, BC, BD, CD.') },
      { q: L('Ketma-ket uchta juft sonning yig‘indisi 24. O‘rtadagisi qaysi?', 'Сумма трёх последовательных чётных чисел равна 24. Каково среднее?', 'Three consecutive even numbers add to 24. What is the middle one?'), s: L('O‘rtadagi son chetkilarning «o‘rtachasi»: chapdagisi 2 ga kam, o‘ngdagisi 2 ga ko‘p, ular bir-birini muvozanatlaydi. Shuning uchun o‘rtadagisi 24 : 3 = <b>8</b>. Sonlar: 6, 8, 10. Tekshiruv: 6 + 8 + 10 = 24.', 'Среднее число — «середина»: левое на 2 меньше, правое на 2 больше, они уравновешивают друг друга. Поэтому среднее = 24 : 3 = <b>8</b>. Числа: 6, 8, 10. Проверка: 6 + 8 + 10 = 24.', 'The middle number balances the others: the left is 2 less, the right 2 more. So the middle is 24 : 3 = <b>8</b>. The numbers are 6, 8, 10. Check: 6 + 8 + 10 = 24.') },
      { q: L('2, 3 va 5 ga bo‘linadigan eng kichik natural son qaysi?', 'Какое наименьшее натуральное число делится на 2, 3 и 5?', 'What is the smallest whole number divisible by 2, 3 and 5?'), s: L('2 va 5 ga bo‘linsa — oxiri 0. 3 ga bo‘linsa — raqamlar yig‘indisi 3 ga karrali. 10 (1) — yo‘q, 20 (2) — yo‘q, 30 (3) — ha! Javob: <b>30</b> = 2 · 3 · 5.', 'Делится на 2 и 5 — оканчивается на 0. На 3 — сумма цифр кратна 3. 10 (1) — нет, 20 (2) — нет, 30 (3) — да! Ответ: <b>30</b> = 2 · 3 · 5.', 'Divisible by 2 and 5 — ends in 0. By 3 — digit sum a multiple of 3. 10 (1) no, 20 (2) no, 30 (3) yes! Answer: <b>30</b> = 2 · 3 · 5.') },
      { q: L('Soat 3 ni ko‘rsatganda strelkalar orasidagi burchak necha gradus?', 'Какой угол между стрелками часов в 3 часа?', 'What angle do the clock hands make at 3 o’clock?'), s: L('Siferblatda 12 ta bo‘lak, to‘liq aylana 360°. Bir bo‘lak: 360 : 12 = 30°. Soat 3 da strelkalar orasida 3 bo‘lak: 3 · 30 = <b>90°</b> — to‘g‘ri burchak.', 'На циферблате 12 делений, полный круг 360°. Одно деление: 360 : 12 = 30°. В 3 часа между стрелками 3 деления: 3 · 30 = <b>90°</b> — прямой угол.', 'A clock face has 12 parts and a full turn is 360°. One part: 360 : 12 = 30°. At 3 o’clock there are 3 parts between the hands: 3 · 30 = <b>90°</b> — a right angle.') }
    ] },
    { kind: 'table', h: L('Sehrli kvadrat 3 × 3', 'Магический квадрат 3 × 3', 'A 3 × 3 magic square'), p: [
      L('Bu — Lo Shu kvadrati. Har bir qator, ustun va ikkala diagonal yig‘indisi 15. Tekshirib ko‘ring!', 'Это квадрат Ло Шу. Сумма каждой строки, столбца и обеих диагоналей — 15. Проверь!', 'This is the Lo Shu square. Every row, column and both diagonals add to 15. Check it!')
    ], table: { head: ['', L('1-ustun', '1-й столбец', 'Col 1'), L('2-ustun', '2-й столбец', 'Col 2'), L('3-ustun', '3-й столбец', 'Col 3')], rows: [
      [L('1-qator', '1-я строка', 'Row 1'), '4', '9', '2'],
      [L('2-qator', '2-я строка', 'Row 2'), '3', '5', '7'],
      [L('3-qator', '3-я строка', 'Row 3'), '8', '1', '6']
    ] }, after: [
      L('Nega yig‘indi aynan 15? 1 dan 9 gacha sonlar yig‘indisi 45. Uchta qator teng bo‘lishi uchun har biri 45 : 3 = 15 bo‘lishi kerak. Markazda doim 5 turadi — o‘rtadagi son. Har bir juft qarama-qarshi son (4 va 6, 9 va 1, 2 va 8, 3 va 7) yig‘indisi 10.', 'Почему сумма именно 15? Сумма чисел от 1 до 9 — 45. Чтобы три строки были равны, каждая должна быть 45 : 3 = 15. В центре всегда 5 — среднее число. Каждая пара противоположных чисел (4 и 6, 9 и 1, 2 и 8, 3 и 7) в сумме даёт 10.', 'Why exactly 15? The numbers 1 to 9 add to 45. For three equal rows, each must be 45 : 3 = 15. The centre is always 5 — the middle number. Each pair of opposite numbers (4 and 6, 9 and 1, 2 and 8, 3 and 7) adds to 10.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Birinchi mos kelganini javob deb olish.</b> Konfet masalasida 12 ni tanlash — u 2, 3, 4 ga bo‘linadi, lekin 5 ga bo‘lganda 2 qoladi, 3 emas. Har doim <b>barcha</b> shartlarni tekshiring.', '<b>Взять первое подходящее.</b> В задаче о конфетах выбрать 12 — оно делится на 2, 3, 4, но при делении на 5 даёт остаток 2, а не 3. Всегда проверяй <b>все</b> условия.', '<b>Taking the first fit.</b> Choosing 12 in the sweets puzzle — it divides by 2, 3, 4, but leaves 2 on division by 5, not 3. Always check <b>every</b> condition.'),
      L('<b>Ikki marta sanash.</b> Qo‘l berish masalasida 4 · 3 = 12 ni javob deyish. AB va BA — bitta qo‘l berish, shuning uchun 2 ga bo‘lamiz.', '<b>Двойной счёт.</b> В задаче о рукопожатиях ответить 4 · 3 = 12. АБ и БА — одно рукопожатие, поэтому делим на 2.', '<b>Double counting.</b> Answering 4 · 3 = 12 for the handshakes. AB and BA are one handshake, so divide by 2.'),
      L('<b>Shartni o‘zgartirib o‘qish.</b> «Azizdan pastda» ni «Azizning ostidagi qavatda» deb tushunish. «Pastda» — istalgan pastroq qavat, albatta qo‘shni emas.', '<b>Читать условие по-своему.</b> Понять «ниже Азиза» как «прямо под Азизом». «Ниже» — на любом более низком этаже, не обязательно соседнем.', '<b>Reading a condition wrongly.</b> Taking “below Aziz” to mean “directly under Aziz”. “Below” means any lower floor, not necessarily the next one.'),
      L('<b>Variantlarni tartibsiz saralash.</b> Tasodifiy sonlarni sinash — biror variant tushib qolishi mumkin. Variantlarni tartib bilan, kichigidan kattasiga yozing.', '<b>Беспорядочный перебор.</b> Пробовать случайные числа — можно пропустить вариант. Выписывай варианты по порядку, от меньшего к большему.', '<b>Testing cases at random.</b> Trying random numbers can miss a case. List the cases in order, smallest to largest.')
    ] },
    { kind: 'life', h: L('Hayotda mantiq', 'Логика в жизни', 'Logic in life'), p: [
      L('<b>Jadval tuzish.</b> Maktabda dars jadvalini tuzish — ulkan mantiqiy masala: bir o‘qituvchi bir vaqtda ikki sinfda bo‘la olmaydi, sport zali bitta, har sinfda kuniga 5–6 dars. Bunday masalalarni bugun kompyuter dasturlari yechadi, lekin ular ham aynan siz o‘rgangan usul — shartlarni tekshirish va variantlarni saralash bilan ishlaydi.', '<b>Составление расписания.</b> Составить школьное расписание — огромная логическая задача: учитель не может быть в двух классах сразу, спортзал один, в каждом классе 5–6 уроков в день. Сегодня такие задачи решают программы, но и они работают тем же способом — проверкой условий и перебором вариантов.', '<b>Making timetables.</b> Building a school timetable is a huge logic puzzle: a teacher cannot be in two classes at once, there is one gym, each class has 5–6 lessons a day. Today computer programs solve such problems, but they work exactly the way you learned — checking conditions and trying cases.'),
      L('<b>Turnirlar.</b> 8 ta jamoa «har biri har biri bilan» bir martadan o‘ynasa, nechta o‘yin bo‘ladi? 8 · 7 : 2 = 28. Tashkilotchilar stadion va hakamlar sonini shunday hisoblaydi.', '<b>Турниры.</b> Если 8 команд играют «каждая с каждой» по разу, сколько будет игр? 8 · 7 : 2 = 28. Так организаторы считают число стадионов и судей.', '<b>Tournaments.</b> If 8 teams each play each other once, how many games? 8 · 7 : 2 = 28. Organisers count stadiums and referees this way.'),
      L('<b>Sudoku va shaxmat.</b> Sudoku — sehrli kvadratning qarindoshi, unda har bir qator, ustun va kichik kvadratda 1 dan 9 gacha raqamlar bir martadan uchraydi. Shaxmat esa «agar men shunday yursam, raqib nima qiladi?» degan mantiqiy fikrlashga asoslangan.', '<b>Судоку и шахматы.</b> Судоку — родственник магического квадрата: в каждой строке, столбце и малом квадрате цифры от 1 до 9 встречаются по разу. Шахматы же построены на логике «если я пойду так, что сделает соперник?».', '<b>Sudoku and chess.</b> Sudoku is a cousin of the magic square: each row, column and small box holds the digits 1 to 9 once. Chess is built on the logic of “if I move here, what will my opponent do?”.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Dyurer sehrli kvadratining pastki qatoridagi o‘rtadagi ikki son — 15 va 14 — gravyura yaratilgan yilni ko‘rsatadi: 1514!', 'В магическом квадрате Дюрера два средних числа нижней строки — 15 и 14 — показывают год создания гравюры: 1514!', 'In Dürer’s magic square the two middle numbers of the bottom row — 15 and 14 — give the year of the engraving: 1514!'),
      L('Sinfda 30 o‘quvchi har biri har biri bilan bir martadan qo‘l berib ko‘rishsa, 30 · 29 : 2 = 435 ta qo‘l berish bo‘ladi!', 'Если 30 учеников класса пожмут руки каждый каждому, будет 30 · 29 : 2 = 435 рукопожатий!', 'If 30 pupils in a class all shake hands with each other, that is 30 · 29 : 2 = 435 handshakes!'),
      L('Bo‘ri, echki va karam masalasi 7 ta suzish bilan yechiladi: avval echkini olib o‘tish kerak — boshqa birinchi qadam bilan yechib bo‘lmaydi.', 'Задача о волке, козе и капусте решается за 7 переправ: первой надо перевезти козу — с другим первым ходом не решить.', 'The wolf, goat and cabbage puzzle takes 7 crossings: the goat must go first — no other first move works.'),
      L('1 dan 100 gacha barcha sonlarning yig‘indisi 5 050, 1 dan 1 000 gacha esa 500 500.', 'Сумма всех чисел от 1 до 100 — 5 050, а от 1 до 1 000 — 500 500.', 'The sum of all numbers from 1 to 100 is 5 050, and from 1 to 1 000 it is 500 500.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('45 ning nechta bo‘luvchisi bor?', 'Сколько делителей у числа 45?', 'How many divisors does 45 have?'),
      L('1 000 000 dan oldingi son qaysi? Uning raqamlar yig‘indisi qancha va u 9 ga bo‘linadimi?', 'Какое число перед 1 000 000? Какова его сумма цифр и делится ли оно на 9?', 'Which number comes before 1 000 000? What is its digit sum, and does it divide by 9?'),
      L('5 ta jamoa «har biri har biri bilan» bir martadan o‘ynadi. Nechta o‘yin bo‘ldi?', '5 команд сыграли «каждая с каждой» по разу. Сколько было игр?', '5 teams each played each other once. How many games?')
    ], after: [
      L('Javoblar: 1) 1, 3, 5, 9, 15, 45 — 6 ta; 2) 999 999, yig‘indisi 54 — ha, 9 ga bo‘linadi (999 999 : 9 = 111 111); 3) 5 · 4 : 2 = 10 ta o‘yin.', 'Ответы: 1) 1, 3, 5, 9, 15, 45 — 6; 2) 999 999, сумма цифр 54 — да, делится на 9 (999 999 : 9 = 111 111); 3) 5 · 4 : 2 = 10 игр.', 'Answers: 1) 1, 3, 5, 9, 15, 45 — 6; 2) 999 999, digit sum 54 — yes, it divides by 9 (999 999 : 9 = 111 111); 3) 5 · 4 : 2 = 10 games.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Mantiqiy masalada barcha shartlarni yozib, eng kuchlisidan boshlaymiz.', 'В логической задаче выписываем все условия и начинаем с самого сильного.', 'In a logic puzzle, write all conditions and start with the strongest.'),
      L('Variantlarni tartib bilan saralab, mos kelmaydiganlarini chiqarib tashlaymiz.', 'Перебираем варианты по порядку и вычёркиваем неподходящие.', 'Try the cases in order and cross out those that fail.'),
      L('Farazdan qarama-qarshilik kelib chiqsa — faraz noto‘g‘ri.', 'Если из предположения следует противоречие — оно неверно.', 'If an assumption leads to a contradiction, it is false.'),
      L('«Har biri har biri bilan»: n · (n − 1) : 2.', '«Каждый с каждым»: n · (n − 1) : 2.', '“Everyone with everyone”: n · (n − 1) : 2.'),
      L('3 × 3 sehrli kvadratda yig‘indi 15, markazda 5.', 'В магическом квадрате 3 × 3 сумма 15, в центре 5.', 'In a 3 × 3 magic square the sum is 15 and the centre is 5.'),
      L('Javobni har doim barcha shartlar bilan qayta tekshiring.', 'Всегда перепроверяй ответ всеми условиями.', 'Always re-check the answer against every condition.')
    ] }
  ] });
})(this);
